    /* ========================================================================
     * PHASE 3 PUBLIC WEBSITE MODULES:
     * 1. PBDekRotator — Dynamic Asia/Bangkok Year-Based Cohort Calculation
     *    ("Welcome, DEK70 / DEK71 / DEK72" in 2026 -> DEK71/72/73 in 2027),
     *    Fixed-Width Animated Slot, Pause/Play Control, Visibility Pause/Rollover,
     *    and prefers-reduced-motion Static Fallback ("Welcome, DEK70, DEK71 & DEK72").
     * 2. Public Section Navigation, Instructor Portrait Hydration & Password Toggle.
     * ======================================================================== */

    var PBDekRotator = (function () {
      var ROTATION_INTERVAL_MS = 2600;
      var activeIndex = 0;
      var intervalId = null;
      var userPaused = false;
      var forcedReducedMotion = null;
      var forcedTestYear = null;
      var currentDekState = {
        bangkokYear: 2026,
        mode: 'AUTO_YEAR',
        baseDekNumber: 70,
        cohorts: ['DEK70', 'DEK71', 'DEK72'],
        staticGreetingText: 'Welcome, DEK70, DEK71 & DEK72',
        ariaLabelText: 'Welcome, DEK70, DEK71, and DEK72'
      };

      function getCurrentBangkokYear() {
        if (forcedTestYear && !isNaN(Number(forcedTestYear))) {
          return Math.floor(Number(forcedTestYear));
        }
        try {
          if (typeof Intl !== 'undefined' && typeof Intl.DateTimeFormat === 'function') {
            var fmt = new Intl.DateTimeFormat('en-US', {
              timeZone: 'Asia/Bangkok',
              year: 'numeric'
            });
            var yr = parseInt(fmt.format(new Date()), 10);
            if (!isNaN(yr) && yr >= 2020 && yr <= 2100) {
              return yr;
            }
          }
        } catch (ignoreIntlErr) {}
        return 2026;
      }

      /**
       * Pure calculation of the 3 active Thai entrance cohorts (DEKxx) for any
       * Asia/Bangkok calendar year:
       * - 2026 -> ["DEK70", "DEK71", "DEK72"]
       * - 2027 -> ["DEK71", "DEK72", "DEK73"]
       * - 2028 -> ["DEK72", "DEK73", "DEK74"]
       */
      function calculateDekCohorts(bangkokYear, opt_override) {
        var yr = Number(bangkokYear);
        if (!yr || isNaN(yr) || yr < 2020 || yr > 2100) {
          yr = getCurrentBangkokYear();
        } else {
          yr = Math.floor(yr);
        }
        var ov = opt_override && typeof opt_override === 'object' ? opt_override : {};
        var mode = ov.mode === 'MANUAL_OVERRIDE' ? 'MANUAL_OVERRIDE' : 'AUTO_YEAR';
        var manualBase = Number(ov.baseDekNumber);
        var firstDek =
          mode === 'MANUAL_OVERRIDE' && !isNaN(manualBase) && manualBase >= 60 && manualBase <= 150
            ? Math.floor(manualBase)
            : 70 + (yr - 2026);

        var cohorts = [
          'DEK' + String(firstDek),
          'DEK' + String(firstDek + 1),
          'DEK' + String(firstDek + 2)
        ];

        return {
          bangkokYear: yr,
          mode: mode,
          baseDekNumber: firstDek,
          cohorts: cohorts,
          staticGreetingText:
            'Welcome, ' + cohorts[0] + ', ' + cohorts[1] + ' & ' + cohorts[2],
          ariaLabelText:
            'Welcome, ' + cohorts[0] + ', ' + cohorts[1] + ', and ' + cohorts[2]
        };
      }

      function isReducedMotionActive() {
        if (forcedReducedMotion !== null) {
          return Boolean(forcedReducedMotion);
        }
        return false;
      }

      var slotSlideTimeoutId = null;

      function extractDekNumStr(cohortLabel) {
        return String(cohortLabel || 'DEK70').replace(/^DEK/i, '');
      }

      function syncDualDekSlotWindowsStatic() {
        var cohorts =
          (currentDekState && Array.isArray(currentDekState.cohorts) && currentDekState.cohorts) ||
          ['DEK70', 'DEK71', 'DEK72'];
        var currNum = extractDekNumStr(cohorts[activeIndex] || 'DEK70');
        var nextNum = extractDekNumStr(cohorts[(activeIndex + 1) % 3] || 'DEK71');

        var win1 = document.getElementById('dek-slot-window-1');
        var win2 = document.getElementById('dek-slot-window-2');
        if (win1) win1.classList.remove('is-sliding');
        if (win2) win2.classList.remove('is-sliding');

        var c1 = document.getElementById('dek-curr-1');
        var n1 = document.getElementById('dek-next-1');
        var c2 = document.getElementById('dek-curr-2');
        var n2 = document.getElementById('dek-next-2');
        if (c1) c1.textContent = currNum;
        if (n1) n1.textContent = nextNum;
        if (c2) c2.textContent = currNum;
        if (n2) n2.textContent = nextNum;
      }

      function animateDualDekSlotWindows(prevIdx, newActiveIdx) {
        if (isReducedMotionActive() || userPaused) {
          syncDualDekSlotWindowsStatic();
          return;
        }
        var cohorts =
          (currentDekState && Array.isArray(currentDekState.cohorts) && currentDekState.cohorts) ||
          ['DEK70', 'DEK71', 'DEK72'];
        var prevNum = extractDekNumStr(cohorts[prevIdx] || 'DEK70');
        var currNum = extractDekNumStr(cohorts[newActiveIdx] || 'DEK71');
        var followingNum = extractDekNumStr(cohorts[(newActiveIdx + 1) % 3] || 'DEK72');

        var win1 = document.getElementById('dek-slot-window-1');
        var win2 = document.getElementById('dek-slot-window-2');
        var c1 = document.getElementById('dek-curr-1');
        var n1 = document.getElementById('dek-next-1');
        var c2 = document.getElementById('dek-curr-2');
        var n2 = document.getElementById('dek-next-2');

        if (!win1 && !win2) return;
        if (slotSlideTimeoutId) {
          clearTimeout(slotSlideTimeoutId);
          slotSlideTimeoutId = null;
        }

        if (win1) win1.classList.remove('is-sliding');
        if (win2) win2.classList.remove('is-sliding');
        if (c1) c1.textContent = prevNum;
        if (n1) n1.textContent = currNum;
        if (c2) c2.textContent = prevNum;
        if (n2) n2.textContent = currNum;

        if (win1) void win1.offsetWidth;
        if (win1) win1.classList.add('is-sliding');
        if (win2) win2.classList.add('is-sliding');

        slotSlideTimeoutId = setTimeout(function () {
          if (win1) win1.classList.remove('is-sliding');
          if (win2) win2.classList.remove('is-sliding');
          if (c1) c1.textContent = currNum;
          if (n1) n1.textContent = followingNum;
          if (c2) c2.textContent = currNum;
          if (n2) n2.textContent = followingNum;
          slotSlideTimeoutId = null;
        }, 500);
        if (slotSlideTimeoutId && typeof slotSlideTimeoutId.unref === 'function') {
          slotSlideTimeoutId.unref();
        }
      }

      function syncItemClasses(opt_animateSlots, opt_prevIndex) {
        for (var i = 0; i < 3; i++) {
          var itemEl = document.getElementById('landing-dek-item-' + String(i));
          if (!itemEl) continue;
          itemEl.classList.remove('is-active', 'is-prev', 'is-next');
          if (i === activeIndex) {
            itemEl.classList.add('is-active');
          } else if (i === (activeIndex + 2) % 3) {
            itemEl.classList.add('is-prev');
          } else {
            itemEl.classList.add('is-next');
          }
        }
        if (opt_animateSlots && typeof opt_prevIndex === 'number') {
          animateDualDekSlotWindows(opt_prevIndex, activeIndex);
        } else {
          syncDualDekSlotWindowsStatic();
        }
      }

      function syncToggleButtonUi() {
        var bar = document.getElementById('landing-dek-rotator-bar');
        var btn = document.getElementById('btn-dek-rotator-toggle');
        var lbl = document.getElementById('label-dek-rotator-toggle');
        var reduced = isReducedMotionActive();
        var effectivePaused = Boolean(userPaused || reduced);

        if (bar) {
          bar.classList.toggle('is-paused', Boolean(userPaused));
          bar.classList.toggle('is-reduced-motion', Boolean(reduced));
        }
        if (btn) {
          btn.setAttribute('aria-pressed', effectivePaused ? 'true' : 'false');
          btn.setAttribute(
            'aria-label',
            effectivePaused ? 'Resume cohort animation' : 'Pause cohort animation'
          );
          var existingSvg = typeof btn.querySelector === 'function' ? btn.querySelector('svg') : null;
          var newSvg = PBIcons.create(effectivePaused ? 'play' : 'pause', 'pb-icon-sm');
          newSvg.id = 'icon-dek-rotator-pause';
          if (existingSvg && existingSvg.parentNode === btn) {
            btn.replaceChild(newSvg, existingSvg);
          }
        }
        if (lbl) {
          lbl.textContent = effectivePaused ? 'Play' : 'Pause';
        }
      }

      function renderCohortsToDom(dekBundle) {
        if (!dekBundle || !Array.isArray(dekBundle.cohorts)) return;
        currentDekState = dekBundle;
        for (var i = 0; i < 3; i++) {
          var itemEl = document.getElementById('landing-dek-item-' + String(i));
          if (itemEl && dekBundle.cohorts[i]) {
            itemEl.textContent = String(dekBundle.cohorts[i]);
          }
        }
        var staticEl = document.getElementById('landing-dek-static-fallback');
        if (staticEl) {
          staticEl.textContent =
            dekBundle.staticGreetingText ||
            'Welcome, ' +
              dekBundle.cohorts[0] +
              ', ' +
              dekBundle.cohorts[1] +
              ' & ' +
              dekBundle.cohorts[2];
        }
        var regionEl = document.getElementById('landing-dek-greeting-region');
        if (regionEl) {
          regionEl.setAttribute(
            'aria-label',
            dekBundle.ariaLabelText ||
              'Welcome, ' +
                dekBundle.cohorts[0] +
                ', ' +
                dekBundle.cohorts[1] +
                ', and ' +
                dekBundle.cohorts[2]
          );
        }
        syncItemClasses();
        syncToggleButtonUi();
      }

      function stopIntervalTimer() {
        if (intervalId) {
          clearInterval(intervalId);
          intervalId = null;
        }
      }

      function stepOnce() {
        var prevIdx = activeIndex;
        activeIndex = (activeIndex + 1) % 3;
        syncItemClasses(true, prevIdx);
        return currentDekState.cohorts[activeIndex];
      }

      function startIntervalTimerIfEligible() {
        stopIntervalTimer();
        if (userPaused || isReducedMotionActive()) {
          syncToggleButtonUi();
          return;
        }
        if (typeof document !== 'undefined' && document.visibilityState === 'hidden') {
          return;
        }
        intervalId = setInterval(function () {
          stepOnce();
        }, ROTATION_INTERVAL_MS);
        if (intervalId && typeof intervalId.unref === 'function') {
          intervalId.unref();
        }
        syncToggleButtonUi();
      }

      function pause() {
        userPaused = true;
        stopIntervalTimer();
        syncToggleButtonUi();
      }

      function resume() {
        userPaused = false;
        startIntervalTimerIfEligible();
      }

      function togglePause() {
        if (userPaused) {
          resume();
        } else {
          pause();
        }
        return userPaused;
      }

      function setYearForTesting(year, opt_override) {
        forcedTestYear = year ? Math.floor(Number(year)) : null;
        var computed = calculateDekCohorts(
          forcedTestYear || getCurrentBangkokYear(),
          opt_override
        );
        activeIndex = 0;
        renderCohortsToDom(computed);
        return computed;
      }

      function setReducedMotionForTesting(flag) {
        forcedReducedMotion = flag === null || flag === undefined ? null : Boolean(flag);
        if (forcedReducedMotion) {
          stopIntervalTimer();
        } else if (!userPaused) {
          startIntervalTimerIfEligible();
        }
        syncToggleButtonUi();
        return isReducedMotionActive();
      }

      function init(opt_serverDekConfig) {
        var initialState =
          opt_serverDekConfig && Array.isArray(opt_serverDekConfig.cohorts)
            ? opt_serverDekConfig
            : calculateDekCohorts(getCurrentBangkokYear());
        userPaused = false;
        activeIndex = 0;
        renderCohortsToDom(initialState);
        startIntervalTimerIfEligible();
      }

      return Object.freeze({
        calculateDekCohorts: calculateDekCohorts,
        getCurrentBangkokYear: getCurrentBangkokYear,
        init: init,
        stepOnce: stepOnce,
        pause: pause,
        resume: resume,
        togglePause: togglePause,
        setYearForTesting: setYearForTesting,
        setReducedMotionForTesting: setReducedMotionForTesting,
        getState: function () {
          return {
            bangkokYear: currentDekState.bangkokYear,
            mode: currentDekState.mode,
            baseDekNumber: currentDekState.baseDekNumber,
            cohorts: currentDekState.cohorts.slice(),
            activeIndex: activeIndex,
            activeCohort: currentDekState.cohorts[activeIndex],
            userPaused: userPaused,
            reducedMotion: isReducedMotionActive(),
            staticGreetingText: currentDekState.staticGreetingText,
            ariaLabelText: currentDekState.ariaLabelText
          };
        }
      });
    })();

    var PBHeroCardDeck = (function () {
      var AUTO_SHUFFLE_INTERVAL_MS = 4000;
      var CYCLE_OUT_DURATION_MS = 300;
      var cardPositions = [0, 1, 2];
      var isShuffling = false;
      var hoverOrFocusPaused = false;
      var autoTimerId = null;

      function getCardNodes() {
        return [
          document.getElementById('hero-shuffle-card-0'),
          document.getElementById('hero-shuffle-card-1'),
          document.getElementById('hero-shuffle-card-2')
        ];
      }

      function syncIgGalleryIndicators(activeZeroIdx) {
        var idx = Number(activeZeroIdx || 0);
        if (idx < 0 || idx > 2 || isNaN(idx)) idx = 0;
        var counterEl = document.getElementById('landing-hero-ig-counter');
        if (counterEl) {
          counterEl.textContent = String(idx + 1) + ' / 3';
        }
        if (typeof document !== 'undefined' && typeof document.querySelectorAll === 'function') {
          var dots = document.querySelectorAll('[data-hero-ig-dot]');
          for (var d = 0; d < dots.length; d++) {
            var dotIdx = Number(dots[d].getAttribute('data-hero-ig-dot') || 0);
            dots[d].classList.toggle('is-active', dotIdx === idx);
          }
        }
      }

      function updateShuffleStatusIndicator() {
        var statusEl = document.getElementById('landing-hero-shuffle-status');
        var cards = getCardNodes();
        var frontIdx = cardPositions.indexOf(0);
        if (frontIdx === -1) frontIdx = 0;
        syncIgGalleryIndicators(frontIdx);
        var frontCard = cards[frontIdx];
        var title =
          (frontCard && frontCard.getAttribute('data-card-title')) ||
          'Intracellular Vesicle Transport';
        if (statusEl) {
          clearChildren(statusEl);
          var dot = document.createElement('span');
          dot.className = 'pb-hero-shuffle-dot';
          dot.setAttribute('aria-hidden', 'true');
          var txt = document.createElement('span');
          txt.textContent =
            'Showing ' + String(frontIdx + 1) + ' of 3: ' + title;
          statusEl.appendChild(dot);
          statusEl.appendChild(txt);
        }
      }

      function applyCardPositionClasses() {
        var cards = getCardNodes();
        for (var i = 0; i < cards.length; i++) {
          var c = cards[i];
          if (!c) continue;
          c.classList.remove('card-pos-0', 'card-pos-1', 'card-pos-2', 'cycle-out');
          c.classList.add('card-pos-' + String(cardPositions[i]));
        }
        updateShuffleStatusIndicator();
      }

      function shuffleNext() {
        if (isShuffling) return false;
        var cards = getCardNodes();
        if (!cards[0] || !cards[1] || !cards[2]) return false;

        var reduced =
          PBDekRotator &&
          typeof PBDekRotator.getState === 'function' &&
          PBDekRotator.getState().reducedMotion;

        if (reduced) {
          cardPositions = cardPositions.map(function (pos) {
            return (pos + 2) % 3;
          });
          applyCardPositionClasses();
          return true;
        }

        isShuffling = true;
        var frontCardIdx = cardPositions.indexOf(0);
        if (frontCardIdx === -1) frontCardIdx = 0;
        var frontCard = cards[frontCardIdx];
        if (frontCard) {
          frontCard.classList.add('cycle-out');
        }

        setTimeout(function () {
          cardPositions = cardPositions.map(function (pos) {
            return (pos + 2) % 3;
          });
          applyCardPositionClasses();
          setTimeout(function () {
            isShuffling = false;
          }, 300);
        }, CYCLE_OUT_DURATION_MS);
        return true;
      }

      function stopAutoShuffle() {
        if (autoTimerId) {
          clearInterval(autoTimerId);
          autoTimerId = null;
        }
      }

      function startAutoShuffleIfEligible() {
        stopAutoShuffle();
        var reduced =
          PBDekRotator &&
          typeof PBDekRotator.getState === 'function' &&
          PBDekRotator.getState().reducedMotion;
        if (reduced || hoverOrFocusPaused) return;
        if (typeof document !== 'undefined' && document.visibilityState === 'hidden') {
          return;
        }
        autoTimerId = setInterval(function () {
          if (!hoverOrFocusPaused) {
            shuffleNext();
          }
        }, AUTO_SHUFFLE_INTERVAL_MS);
        if (autoTimerId && typeof autoTimerId.unref === 'function') {
          autoTimerId.unref();
        }
      }

      function init() {
        applyCardPositionClasses();
        startAutoShuffleIfEligible();
      }

      return Object.freeze({
        init: init,
        shuffleNext: shuffleNext,
        stopAutoShuffle: stopAutoShuffle,
        startAutoShuffleIfEligible: startAutoShuffleIfEligible,
        setHoverOrFocusPaused: function (paused) {
          hoverOrFocusPaused = Boolean(paused);
          if (hoverOrFocusPaused) {
            stopAutoShuffle();
          } else {
            startAutoShuffleIfEligible();
          }
        },
        getState: function () {
          return {
            cardPositions: cardPositions.slice(),
            frontCardIndex: cardPositions.indexOf(0),
            isShuffling: isShuffling,
            hoverOrFocusPaused: hoverOrFocusPaused
          };
        }
      });
    })();

    /**
     * Phase 3: Applies the optional instructor portrait image or falls back cleanly
     * to the academic crest silhouette if no portrait is configured or if loading fails.
     */
    function resolvePublicDriveImgSrcPhase3(dto) {
      if (!dto || dto.available !== true) return '';
      if (typeof dto.dataUri === 'string' && /^data:image\/(png|jpeg|webp|gif);base64,/i.test(dto.dataUri)) {
        return dto.dataUri;
      }
      if (typeof dto.imageUrl === 'string' && /^https:\/\/[^\s]+$/i.test(dto.imageUrl)) {
        return dto.imageUrl;
      }
      if (dto.driveFileId && typeof window.getGoogleDriveImageUrl === 'function') {
        return window.getGoogleDriveImageUrl(dto.driveFileId);
      }
      return '';
    }

    function applyInstructorPortraitPhase3(portraitDto) {
      var imgEl = document.getElementById('landing-instructor-portrait-img');
      var fallbackEl = document.getElementById('landing-instructor-portrait-fallback');
      if (!imgEl || !fallbackEl) return;

      var resolvedSrc = resolvePublicDriveImgSrcPhase3(portraitDto);
      if (!resolvedSrc) {
        imgEl.removeAttribute('src');
        imgEl.classList.add('hidden');
        fallbackEl.classList.remove('hidden');
        return;
      }

      var fallbackTried = false;
      imgEl.onerror = function () {
        if (!fallbackTried && portraitDto && portraitDto.driveFileId && window.PB_DRIVE && window.PB_DRIVE.isConfigured()) {
          fallbackTried = true;
          window.PB_DRIVE.downloadDriveFileBlobAuthorized(portraitDto.driveFileId)
            .then(function (dl) {
              imgEl.src = URL.createObjectURL(dl.blob);
            })
            .catch(function () {
              imgEl.removeAttribute('src');
              imgEl.classList.add('hidden');
              fallbackEl.classList.remove('hidden');
            });
          return;
        }
        imgEl.removeAttribute('src');
        imgEl.classList.add('hidden');
        fallbackEl.classList.remove('hidden');
      };
      imgEl.onload = function () {
        imgEl.classList.remove('hidden');
        fallbackEl.classList.add('hidden');
      };
      imgEl.referrerPolicy = 'no-referrer';
      imgEl.alt = (portraitDto && portraitDto.altText) || 'Pattanabhumi Biology Instructor portrait';
      imgEl.src = resolvedSrc;
      imgEl.classList.remove('hidden');
      fallbackEl.classList.add('hidden');
    }

    function applySingleHeroShuffleCardSlotPhase8(slotNumber, cardDto) {
      var idx0 = Number(slotNumber) - 1;
      if (isNaN(idx0) || idx0 < 0 || idx0 > 2) return;
      var imgEl = document.getElementById('hero-shuffle-card-img-' + String(idx0));
      var svgEl = document.getElementById('hero-shuffle-card-svg-' + String(idx0));
      if (!imgEl) return;

      var resolvedSrc = resolvePublicDriveImgSrcPhase3(cardDto);
      if (!resolvedSrc) {
        imgEl.removeAttribute('src');
        imgEl.classList.add('hidden');
        imgEl.classList.remove('is-sharp');
        if (svgEl) svgEl.classList.remove('hidden');
        return;
      }

      var fallbackTried = false;
      imgEl.classList.remove('is-sharp');
      imgEl.referrerPolicy = 'no-referrer';
      imgEl.onerror = function () {
        if (!fallbackTried && cardDto && cardDto.driveFileId && window.PB_DRIVE && window.PB_DRIVE.isConfigured()) {
          fallbackTried = true;
          window.PB_DRIVE.downloadDriveFileBlobAuthorized(cardDto.driveFileId)
            .then(function (dl) {
              imgEl.src = URL.createObjectURL(dl.blob);
            })
            .catch(function () {
              imgEl.removeAttribute('src');
              imgEl.classList.add('hidden');
              if (svgEl) svgEl.classList.remove('hidden');
            });
          return;
        }
        imgEl.removeAttribute('src');
        imgEl.classList.add('hidden');
        if (svgEl) svgEl.classList.remove('hidden');
      };
      imgEl.onload = function () {
        imgEl.classList.remove('hidden');
        imgEl.classList.add('is-sharp');
        if (svgEl) svgEl.classList.add('hidden');
      };
      imgEl.src = resolvedSrc;
      imgEl.classList.remove('hidden');
      if (svgEl) svgEl.classList.add('hidden');
      if (imgEl.complete) {
        imgEl.classList.add('is-sharp');
      }
    }

    function applyHeroShuffleCardsPhase8(cardsArray) {
      if (!Array.isArray(cardsArray)) return;
      for (var i = 1; i <= 3; i++) {
        var found = null;
        for (var j = 0; j < cardsArray.length; j++) {
          if (cardsArray[j] && Number(cardsArray[j].slotIndex) === i) {
            found = cardsArray[j];
            break;
          }
        }
        applySingleHeroShuffleCardSlotPhase8(i, found || cardsArray[i - 1] || null);
      }
    }

    /**
     * Phase 3: Hydrates the Public Website sections with server bootstrap data
     * (`dekConfig`, `publicContent`, `instructorPortrait`).
     */
    function applyPublicWebsiteContentPhase3(bootstrapData) {
      var d = bootstrapData && typeof bootstrapData === 'object' ? bootstrapData : {};
      var pub = d.publicContent && typeof d.publicContent === 'object' ? d.publicContent : {};
      var dekCfg =
        d.dekConfig ||
        pub.dek ||
        PBDekRotator.calculateDekCohorts(d.bangkokYear || 2026);
      PBDekRotator.init(dekCfg);
      applyInstructorPortraitPhase3(d.instructorPortrait || null);
      if (Array.isArray(d.heroShuffleCards)) {
        applyHeroShuffleCardsPhase8(d.heroShuffleCards);
      }

      if (pub.hero && typeof pub.hero === 'object') {
        if (pub.hero.eyebrow) {
          var cleanEyebrow = String(pub.hero.eyebrow)
            .replace(/\s*(?:—|--|-|\u2014)\s*Asia\/Bangkok\s*\(UTC\+7\)/gi, '')
            .trim();
          setText('landing-hero-eyebrow', cleanEyebrow || pub.hero.eyebrow);
        }
        if (pub.hero.lead) {
          setText('landing-hero-lead', pub.hero.lead);
        }
      }
      if (pub.aboutUs && typeof pub.aboutUs === 'object') {
        if (pub.aboutUs.subtitle) {
          setText('landing-about-subtitle', pub.aboutUs.subtitle);
        }
        if (Array.isArray(pub.aboutUs.paragraphs)) {
          if (pub.aboutUs.paragraphs[0]) {
            setText('landing-about-p1', pub.aboutUs.paragraphs[0]);
          }
          if (pub.aboutUs.paragraphs[1]) {
            setText('landing-about-p2', pub.aboutUs.paragraphs[1]);
          }
          if (pub.aboutUs.paragraphs[2]) {
            setText('landing-about-p3', pub.aboutUs.paragraphs[2]);
          }
        }
      }
      if (pub.instructorProfile && typeof pub.instructorProfile === 'object') {
        if (pub.instructorProfile.headlineBadge) {
          setText('landing-instructor-headline-text', pub.instructorProfile.headlineBadge);
        }
        if (pub.instructorProfile.education) {
          setText('landing-instructor-education', pub.instructorProfile.education);
        }
        if (pub.instructorProfile.teachingExperience) {
          setText('landing-instructor-experience', pub.instructorProfile.teachingExperience);
        }
        if (
          Array.isArray(pub.instructorProfile.awards) &&
          pub.instructorProfile.awards.length > 0
        ) {
          var awardsListEl = document.getElementById('landing-instructor-awards-list');
          if (awardsListEl) {
            clearChildren(awardsListEl);
            for (var a = 0; a < pub.instructorProfile.awards.length; a++) {
              var awardText = String(pub.instructorProfile.awards[a] || '').trim();
              if (!awardText) continue;
              var li = document.createElement('li');
              li.className = 'pb-instructor-award-item';
              var iconSpan = document.createElement('span');
              iconSpan.className = 'pb-instructor-award-icon';
              iconSpan.setAttribute('aria-hidden', 'true');
              iconSpan.appendChild(PBIcons.create('award', 'pb-icon-sm'));
              var txtSpan = document.createElement('span');
              txtSpan.textContent = awardText;
              li.appendChild(iconSpan);
              li.appendChild(txtSpan);
              awardsListEl.appendChild(li);
            }
          }
        }
      }
    }

    /**
     * Phase 3: Smoothly scrolls to a section on the Public Website (`#view-landing`),
     * automatically switching back from `#view-contact` if needed and respecting
     * `prefers-reduced-motion: reduce`.
     */
    function scrollToPublicSectionPhase3(sectionId) {
      if (!sectionId) return;
      setMobileMenuOpen(false);
      if (currentActiveViewName !== 'landing') {
        showSectionView('landing');
      }
      var targetEl = document.getElementById(sectionId);
      if (!targetEl) return;
      var allNavLinks = document.querySelectorAll('.nav-link, .mobile-nav-link');
      for (var nIdx = 0; nIdx < allNavLinks.length; nIdx++) {
        var nl = allNavLinks[nIdx];
        var matchesSec = nl.getAttribute('data-scroll-section') === sectionId;
        nl.classList.toggle('is-active', matchesSec);
        if (matchesSec) {
          nl.setAttribute('aria-current', 'location');
        } else {
          nl.removeAttribute('aria-current');
        }
      }
      var badgeEl = document.getElementById('floating-toc-active-label');
      if (badgeEl) {
        var secMap = {
          'landing-section-hero': 'Home',
          'landing-section-benefits': 'Benefits',
          'landing-section-how-to-login': 'How to Log In',
          'landing-why-pattanabhumi-pillars': 'Why Us',
          'landing-section-about': 'About Us',
          'landing-section-instructor': 'Instructor',
          'landing-section-contact-cta': 'Contact'
        };
        if (secMap[sectionId]) {
          badgeEl.textContent = secMap[sectionId];
        }
      }
      var reduceMotion = false;
      try {
        if (typeof window.matchMedia === 'function') {
          reduceMotion = Boolean(
            window.matchMedia('(prefers-reduced-motion: reduce)').matches
          );
        }
      } catch (ignoreErr) {}
      if (typeof targetEl.scrollIntoView === 'function') {
        try {
          targetEl.scrollIntoView({
            behavior: reduceMotion ? 'auto' : 'smooth',
            block: 'start'
          });
        } catch (scrollErr) {
          targetEl.scrollIntoView();
        }
      }
    }

    /**
     * Phase 3: Toggles or resets the password visibility inside `#modal-login`.
     */
    function setLoginPasswordVisibilityPhase3(showPlain) {
      var pwdInp = document.getElementById('input-login-password');
      var toggleBtn = document.getElementById('btn-toggle-login-password-visibility');
      var toggleLbl = document.getElementById('label-login-password-toggle');
      if (!pwdInp) return false;
      var reveal = Boolean(showPlain);
      pwdInp.setAttribute('type', reveal ? 'text' : 'password');
      if (toggleBtn) {
        toggleBtn.setAttribute('aria-pressed', reveal ? 'true' : 'false');
        toggleBtn.setAttribute(
          'aria-label',
          reveal ? 'Hide password' : 'Show password'
        );
        var oldIcon = toggleBtn.querySelector('svg');
        var newIcon = PBIcons.create(reveal ? 'eye-off' : 'eye', 'pb-icon-sm');
        newIcon.id = 'icon-login-password-eye';
        if (oldIcon && oldIcon.parentNode === toggleBtn) {
          toggleBtn.replaceChild(newIcon, oldIcon);
        }
      }
      if (toggleLbl) {
        toggleLbl.textContent = reveal ? 'Hide' : 'Show';
      }
      return reveal;
    }

    var DEFAULT_EMBEDDED_LOGO_DATA_URL =
      'assets/logo.webp';

