    /**
     * Self-healing DOM helper: ensures that every logo `<img>` slot exists next to its
     * corresponding `PB` fallback badge, even if an older HTML template was open.
     */
    function ensureLogoImgSlotsExist() {
      for (var i = 0; i < LOGO_SLOT_PAIRS.length; i++) {
        var slot = LOGO_SLOT_PAIRS[i];
        var badgeEl = document.getElementById(slot.badgeId);
        var imgEl = document.getElementById(slot.imgId);
        if (!imgEl && badgeEl && badgeEl.parentNode) {
          imgEl = document.createElement('img');
          imgEl.id = slot.imgId;
          imgEl.className = slot.className || 'brand-logo-img hidden';
          imgEl.setAttribute('alt', 'Pattanabhumi Biology logo');
          imgEl.setAttribute('style', slot.inlineStyle || '');
          badgeEl.parentNode.insertBefore(imgEl, badgeEl);
        } else if (imgEl && slot.inlineStyle && !imgEl.getAttribute('style')) {
          imgEl.setAttribute('style', slot.inlineStyle);
        }
      }
    }

    function readCachedLogoState() {
      if (inMemoryLogoCache && inMemoryLogoCache.cacheKey && inMemoryLogoCache.dataUrl) {
        return inMemoryLogoCache;
      }
      try {
        if (typeof window !== 'undefined' && window.sessionStorage) {
          var raw = window.sessionStorage.getItem(SESSION_STORAGE_KEY_LOGO_CACHE);
          if (raw) {
            var parsed = JSON.parse(raw);
            if (parsed && parsed.cacheKey && parsed.dataUrl) {
              inMemoryLogoCache = parsed;
              return parsed;
            }
          }
        }
      } catch (ignoreReadErr) {}
      return null;
    }

    function writeCachedLogoState(cacheObj) {
      inMemoryLogoCache = cacheObj || null;
      try {
        if (typeof window !== 'undefined' && window.sessionStorage) {
          if (cacheObj && cacheObj.cacheKey && cacheObj.dataUrl) {
            window.sessionStorage.setItem(
              SESSION_STORAGE_KEY_LOGO_CACHE,
              JSON.stringify(cacheObj)
            );
          } else {
            window.sessionStorage.removeItem(SESSION_STORAGE_KEY_LOGO_CACHE);
          }
        }
      } catch (ignoreWriteErr) {}
    }

    /**
     * Updates all 6 consistent logo slots (Landing Header, Mobile Navigation Header,
     * Landing Hero, Login Modal, Student Portal Header, and Administrator Dashboard Header).
     * Shows the PB fallback badge while loading or if an admin override explicitly fails,
     * and supports both dynamic Drive base64 payloads and the embedded default conversion
     * of `LOGO01.psd` (`12EKzWLkKL9XEdZVrJBzGNERdAd7BFi--`).
     */
    function applySchoolLogoBranding(logoPayload, fallbackText) {
      ensureLogoImgSlotsExist();
      var fbText = fallbackText || 'PB';
      var altText =
        (logoPayload && logoPayload.altText) || 'Pattanabhumi Biology logo';

      for (var i = 0; i < LOGO_SLOT_PAIRS.length; i++) {
        setText(LOGO_SLOT_PAIRS[i].badgeId, fbText);
      }

      var resolvedDataUrl = '';
      var cached = readCachedLogoState();

      if (logoPayload && logoPayload.available === true) {
        if (
          logoPayload.unchanged === true &&
          cached &&
          cached.cacheKey === logoPayload.cacheKey &&
          cached.dataUrl
        ) {
          resolvedDataUrl = cached.dataUrl;
        } else if (
          typeof logoPayload.dataBase64 === 'string' &&
          logoPayload.dataBase64.length > 0 &&
          typeof logoPayload.mimeType === 'string' &&
          /^image\/(png|jpeg|webp|gif)$/i.test(logoPayload.mimeType)
        ) {
          resolvedDataUrl =
            'data:' +
            logoPayload.mimeType.toLowerCase() +
            ';base64,' +
            logoPayload.dataBase64;
          writeCachedLogoState({
            cacheKey: logoPayload.cacheKey || 'logo_active',
            mimeType: logoPayload.mimeType.toLowerCase(),
            dataUrl: resolvedDataUrl,
            altText: altText
          });
        } else if (typeof logoPayload.imageUrl === 'string' && /^https:\/\/[^\s]+$/i.test(logoPayload.imageUrl)) {
          resolvedDataUrl = logoPayload.imageUrl;
          writeCachedLogoState({
            cacheKey: logoPayload.cacheKey || 'logo_active',
            mimeType: (logoPayload.mimeType || 'image/png').toLowerCase(),
            dataUrl: resolvedDataUrl,
            altText: altText
          });
        } else if (logoPayload.driveFileId && typeof window.getGoogleDriveImageUrl === 'function') {
          resolvedDataUrl = window.getGoogleDriveImageUrl(logoPayload.driveFileId);
        }
      } else if (
        (!logoPayload || logoPayload.sourceType !== 'ADMIN_OVERRIDE') &&
        typeof DEFAULT_EMBEDDED_LOGO_DATA_URL === 'string' &&
        DEFAULT_EMBEDDED_LOGO_DATA_URL.length > 0
      ) {
        /* When no custom admin override is failing, use the built-in converted WebP of LOGO01.psd */
        resolvedDataUrl = DEFAULT_EMBEDDED_LOGO_DATA_URL;
      } else {
        writeCachedLogoState(null);
      }

      for (var j = 0; j < LOGO_SLOT_PAIRS.length; j++) {
        (function (slot) {
          var imgEl = document.getElementById(slot.imgId);
          var badgeEl = document.getElementById(slot.badgeId);
          if (!imgEl || !badgeEl) {
            return;
          }
          imgEl.setAttribute('alt', altText);
          imgEl.referrerPolicy = 'no-referrer';
          if (imgEl.dataset) {
            delete imgEl.dataset.pbDriveFallbackTried;
          }

          if (!resolvedDataUrl) {
            imgEl.classList.add('hidden');
            imgEl.removeAttribute('src');
            badgeEl.classList.remove('hidden');
            return;
          }

          imgEl.onload = function () {
            imgEl.classList.remove('hidden');
            badgeEl.classList.add('hidden');
          };
          imgEl.onerror = function () {
            if (
              logoPayload &&
              logoPayload.driveFileId &&
              imgEl.dataset &&
              imgEl.dataset.pbDriveFallbackTried !== '1' &&
              window.PB_DRIVE &&
              typeof window.PB_DRIVE.downloadDriveFileBlobAuthorized === 'function'
            ) {
              imgEl.dataset.pbDriveFallbackTried = '1';
              window.PB_DRIVE.downloadDriveFileBlobAuthorized(logoPayload.driveFileId)
                .then(function (dl) {
                  if (dl && dl.blob && dl.blob.size > 0) {
                    imgEl.src = URL.createObjectURL(dl.blob);
                    return;
                  }
                  imgEl.classList.add('hidden');
                  badgeEl.classList.remove('hidden');
                })
                .catch(function () {
                  imgEl.classList.add('hidden');
                  badgeEl.classList.remove('hidden');
                });
              return;
            }
            imgEl.classList.add('hidden');
            badgeEl.classList.remove('hidden');
          };

          if (imgEl.getAttribute('src') !== resolvedDataUrl) {
            imgEl.setAttribute('src', resolvedDataUrl);
            imgEl.classList.remove('hidden');
            badgeEl.classList.add('hidden');
          } else {
            imgEl.classList.remove('hidden');
            badgeEl.classList.add('hidden');
          }
        })(LOGO_SLOT_PAIRS[j]);
      }
    }

    function isLocalStorageAvailable() {
      try {
        if (typeof window === 'undefined' || !window.localStorage) {
          return false;
        }
        var probeKey = '__pb_storage_probe__';
        window.localStorage.setItem(probeKey, '1');
        var readBack = window.localStorage.getItem(probeKey);
        window.localStorage.removeItem(probeKey);
        return readBack === '1';
      } catch (err) {
        return false;
      }
    }

    /**
     * Tests whether first-party non-sensitive `document.cookie` writes are supported
     * inside the Google Apps Script HTML Service sandboxed iframe, and returns a
     * structured status object describing the active preference storage mechanism.
     *
     * Security Policy:
     * - Never stores passwords, banking details, profile data, or login bearer tokens in cookies.
     * - Never claims to issue HttpOnly cookies.
     * - Falls back to localStorage (`pb_ui_storage_notice_ack_v1`) and then in-memory state.
     *
     * @param {boolean=} opt_setAcknowledged True to persist the non-sensitive `1` flag.
     * @return {{ cookieSupported: boolean, localStorageSupported: boolean, acknowledged: boolean, mechanismUsed: string, statusSummary: string }}
     */
    function testAndManageNonSensitiveNoticeCookie(opt_setAcknowledged) {
      var cookieSupported = false;
      var cookieHasAck = false;

      try {
        if (typeof document !== 'undefined' && typeof document.cookie === 'string') {
          var probeCookie = '__pb_cookie_probe__=1; Max-Age=60; SameSite=Lax; Path=/';
          document.cookie = probeCookie;
          cookieSupported =
            document.cookie.indexOf('__pb_cookie_probe__=1') !== -1;
          if (cookieSupported) {
            document.cookie =
              '__pb_cookie_probe__=; Max-Age=0; SameSite=Lax; Path=/';
          }
          if (opt_setAcknowledged === true && cookieSupported) {
            document.cookie =
              COOKIE_NAME_NOTICE_PREF +
              '=1; Max-Age=2592000; SameSite=Lax; Path=/';
          }
          cookieHasAck =
            document.cookie.indexOf(COOKIE_NAME_NOTICE_PREF + '=1') !== -1;
        }
      } catch (cookieErr) {
        cookieSupported = false;
      }

      var lsSupported = isLocalStorageAvailable();
      var lsHasAck = false;
      if (lsSupported) {
        try {
          if (opt_setAcknowledged === true) {
            window.localStorage.setItem(STORAGE_KEY_NOTICE_PREF, '1');
          }
          lsHasAck =
            window.localStorage.getItem(STORAGE_KEY_NOTICE_PREF) === '1';
        } catch (lsErr) {
          lsHasAck = false;
        }
      }

      if (opt_setAcknowledged === true) {
        inMemoryNoticePrefAck = true;
      }

      var acknowledged = cookieHasAck || lsHasAck || inMemoryNoticePrefAck;
      var mechanismUsed = cookieSupported
        ? 'DOCUMENT_COOKIE (' + COOKIE_NAME_NOTICE_PREF + '=1)'
        : lsSupported
        ? 'LOCAL_STORAGE_FALLBACK (' + STORAGE_KEY_NOTICE_PREF + '=1)'
        : 'IN_MEMORY_FALLBACK (iframe blocked cookies & localStorage)';

      var statusSummary = cookieSupported
        ? 'HTML Service Iframe Cookie Test: Non-sensitive preference cookie (' +
          COOKIE_NAME_NOTICE_PREF +
          ') is writable in this browser (' +
          (acknowledged ? 'Saved' : 'Ready') +
          '). Custom HttpOnly cookies are unavailable in HtmlService.'
        : lsSupported
        ? 'HTML Service Iframe Cookie Test: Browser blocks document.cookie inside this sandboxed iframe; using documented localStorage fallback (' +
          STORAGE_KEY_NOTICE_PREF +
          ': ' +
          (acknowledged ? 'Saved' : 'Ready') +
          ').'
        : 'HTML Service Iframe Cookie Test: Browser blocks both document.cookie and localStorage in this iframe; using documented in-memory fallback (' +
          (acknowledged ? 'Saved for this visit' : 'Ready') +
          ').';

      setText('cookie-storage-status-text', statusSummary);
      var badge = document.getElementById('cookie-storage-test-badge');
      if (badge) {
        badge.textContent = acknowledged
          ? 'Storage Notice Acknowledged (' +
            (cookieSupported ? 'Cookie' : lsSupported ? 'localStorage Fallback' : 'Memory Fallback') +
            ')'
          : 'Essential Storage Only';
      }

      return {
        cookieSupported: cookieSupported,
        localStorageSupported: lsSupported,
        acknowledged: acknowledged,
        mechanismUsed: mechanismUsed,
        statusSummary: statusSummary
      };
    }

    /**
     * Reads any previously saved bearer token from localStorage (Remember me)
     * or sessionStorage (current browser tab across F5 refreshes).
     */
    function readPersistedTokenIfAvailable() {
      try {
        if (isLocalStorageAvailable()) {
          var raw = window.localStorage.getItem(STORAGE_KEY_SESSION_TOKEN);
          if (typeof raw === 'string' && /^[0-9a-f]{64}$/i.test(raw.trim())) {
            return raw.trim().toLowerCase();
          }
        }
        if (typeof window !== 'undefined' && window.sessionStorage) {
          var sRaw = window.sessionStorage.getItem(STORAGE_KEY_SESSION_TOKEN);
          if (typeof sRaw === 'string' && /^[0-9a-f]{64}$/i.test(sRaw.trim())) {
            return sRaw.trim().toLowerCase();
          }
        }
      } catch (err) {
        return null;
      }
      return null;
    }

    /**
     * Stores the bearer token in memory and either:
     * - `localStorage` if `rememberMe === true` (7-day persistent login)
     * - `sessionStorage` if `rememberMe === false` (tab-scoped, survives F5 reload, clears on tab close).
     */
    function storeSessionCredential(rawToken, rememberMe) {
      var cleanTok = typeof rawToken === 'string' ? rawToken.trim() : '';
      inMemorySessionToken = cleanTok || null;
      window.__PB_SESSION_TOKEN__ = inMemorySessionToken;
      var warningBanner = document.getElementById('remember-me-storage-warning');

      if (!rememberMe) {
        if (isLocalStorageAvailable()) {
          try {
            window.localStorage.removeItem(STORAGE_KEY_SESSION_TOKEN);
          } catch (ignoreErr) {}
        }
        var savedToSessionTab = false;
        try {
          if (typeof window !== 'undefined' && window.sessionStorage && cleanTok) {
            window.sessionStorage.setItem(STORAGE_KEY_SESSION_TOKEN, cleanTok);
            savedToSessionTab = true;
          }
        } catch (ignoreSesErr) {}
        currentStorageMode = savedToSessionTab
          ? 'SESSION_STORAGE (Cleared on tab close, preserved on refresh)'
          : 'IN_MEMORY_ONLY (Cleared on tab close/refresh)';
        if (warningBanner) {
          warningBanner.classList.add('hidden');
        }
        return {
          persistedToLocalStorage: false,
          fallbackWarningMessage: ''
        };
      }

      try {
        if (typeof window !== 'undefined' && window.sessionStorage) {
          window.sessionStorage.removeItem(STORAGE_KEY_SESSION_TOKEN);
        }
      } catch (ignoreSesRmErr) {}

      if (isLocalStorageAvailable()) {
        try {
          window.localStorage.setItem(STORAGE_KEY_SESSION_TOKEN, rawToken);
          currentStorageMode = 'LOCAL_STORAGE_REMEMBER_ME (7-day bearer token)';
          if (warningBanner) {
            warningBanner.classList.add('hidden');
          }
          return {
            persistedToLocalStorage: true,
            fallbackWarningMessage: ''
          };
        } catch (writeErr) {}
      }

      currentStorageMode =
        'IN_MEMORY_FALLBACK (Browser blocked iframe localStorage; login lasts for this visit only)';
      var msg =
        'You selected "Remember me", but your browser blocks persistent storage inside sandboxed iframes. Your session is active in memory for this visit only.';
      if (warningBanner) {
        setText('remember-me-storage-warning-text', msg);
        warningBanner.classList.remove('hidden');
      }
      return {
        persistedToLocalStorage: false,
        fallbackWarningMessage: msg
      };
    }

    /**
     * Clears both in-memory and localStorage session credentials.
     */
    function isCurrentSessionAdminUser() {
      return Boolean(
        currentSessionMeta &&
          currentSessionMeta.user &&
          String(currentSessionMeta.user.role || '').toUpperCase() === 'ADMIN'
      );
    }

    function showTransitionLoadingView(headingText, subtitleText) {
      if (headingText) setText('loading-heading-text', headingText);
      if (subtitleText) setText('loading-subtitle-text', subtitleText);
      showSectionView('loading');
    }

    function resetAllPortalSessionState(opt_reason) {
      currentStudentCourseFromAdminPreview = false;
      isExamStudioModeActive = false;
      if (typeof PBEnhancedSelect === 'object' && PBEnhancedSelect) {
        PBEnhancedSelect.closeActive(true, false);
      }
      if (typeof exitAdminExamsStudioMode === 'function') {
        exitAdminExamsStudioMode(true, { targetAdminTab: 'settings', skipDataLoad: true });
      }
      studentCourseDetailCacheById = {};
      if (typeof clearRpcReadCache === 'function') clearRpcReadCache();
      if (typeof PBObjectUrlManager === 'object' && PBObjectUrlManager && typeof PBObjectUrlManager.clearPersistentCache === 'function') {
        PBObjectUrlManager.clearPersistentCache();
      }
      if (typeof currentAdminExamsListPhase3 !== 'undefined') currentAdminExamsListPhase3 = [];
      if (typeof currentStudentCourseExamsCatalogPhase3 !== 'undefined') currentStudentCourseExamsCatalogPhase3 = [];
      if (typeof currentQBankQuestionsPhase2 !== 'undefined') currentQBankQuestionsPhase2 = [];
      if (typeof currentQBankStimuliCachePhase2 !== 'undefined') currentQBankStimuliCachePhase2 = [];
      if (typeof currentAdminCoursesList !== 'undefined') currentAdminCoursesList = [];
      currentStudentCourseDetailBundle = null;
      currentStudentCourseId = '';
      currentSelectedCourseDetail = null;
      currentSelectedInstructionExamPhase3 = null;
      currentExamWorkspaceQuestionIndexPhase5 = 0;
      if (typeof formsBuilderQuestionCards !== 'undefined') formsBuilderQuestionCards = [];
      if (typeof window !== 'undefined') {
        window.__PB_ACTIVE_RICH_EDITOR__ = null;
      }

      if (window.PBExamAutosaveEngine && typeof window.PBExamAutosaveEngine.reset === 'function') {
        window.PBExamAutosaveEngine.reset();
      }
      if (
        typeof window.PBExamIntegrityGuard === 'object' &&
        window.PBExamIntegrityGuard &&
        typeof window.PBExamIntegrityGuard.detach === 'function'
      ) {
        try {
          window.PBExamIntegrityGuard.detach();
        } catch (ignoreDetachErr) {}
      }
      if (typeof PBAdminActionModal === 'object' && PBAdminActionModal) {
        PBAdminActionModal.close();
      }
      var modalIdsToClose = [
        'modal-student-exam-instructions',
        'modal-exam-submit-readiness',
        'modal-exam-submission-receipt',
        'modal-student-exam-result',
        'modal-recording-detail',
        'modal-privacy-gate',
        'modal-report-unavailability',
        'modal-release-notes'
      ];
      for (var m = 0; m < modalIdsToClose.length; m++) {
        if (typeof closeModalDialog === 'function') {
          closeModalDialog(modalIdsToClose[m]);
        }
      }
      if (typeof closeFormsExamBuilderToCatalog === 'function') {
        closeFormsExamBuilderToCatalog();
      }
      var domIdsToClear = [
        'student-course-exams-grid',
        'admin-exams-list-tbody',
        'admin-qbank-table-tbody',
        'admin-exam-assignments-tbody',
        'exam-inst-sections-tbody',
        'exam-inst-rules-list'
      ];
      for (var d = 0; d < domIdsToClear.length; d++) {
        var el = document.getElementById(domIdsToClear[d]);
        if (el) {
          while (el.firstChild) el.removeChild(el.firstChild);
        }
      }
    }

    function clearClientSessionCredential() {
      inMemorySessionToken = null;
      window.__PB_SESSION_TOKEN__ = null;
      currentSessionMeta = null;
      currentStorageMode = 'NONE';
      if (isLocalStorageAvailable()) {
        try {
          window.localStorage.removeItem(STORAGE_KEY_SESSION_TOKEN);
        } catch (ignoreErr) {}
      }
      try {
        if (typeof window !== 'undefined' && window.sessionStorage) {
          window.sessionStorage.removeItem(STORAGE_KEY_SESSION_TOKEN);
        }
      } catch (ignoreSesClearErr) {}
      resetAllPortalSessionState('CREDENTIAL_CLEARED');
    }

    /**
     * Estimates the UTF-8 byte length of a JSON-serializable payload in the browser.
     */
    function estimateJsonBytes(obj) {
      var str = JSON.stringify(obj === undefined ? {} : obj) || '';
      if (typeof TextEncoder !== 'undefined') {
        return new TextEncoder().encode(str).length;
      }
      return unescape(encodeURIComponent(str)).length;
    }

    /**
     * Displays an inline status or error banner inside the Login Modal (#login-inline-alert).
     */
    function setLoginInlineAlert(variant, opt_title, opt_message) {
      var box = document.getElementById('login-inline-alert');
      if (!box) {
        return;
      }
      if (variant === 'hidden') {
        box.classList.add('hidden');
        return;
      }
      box.className = 'banner banner-' + (variant || 'danger');
      var tTitle = opt_title || 'Sign In Notice';
      var tMsg = opt_message || '';
      setText('login-inline-alert-title', tTitle);
      setText('login-inline-alert-message', tMsg);
      box.classList.remove('hidden');
      if (typeof PBNotify === 'object' && PBNotify && typeof PBNotify.toast === 'function') {
        PBNotify.toast(variant || 'danger', tTitle, tMsg);
      }
    }

    /**
     * Displays an inline status or error banner inside the Privacy Gate Modal (#privacy-gate-inline-alert).
     */
    function setPrivacyGateInlineAlert(variant, opt_title, opt_message) {
      var box = document.getElementById('privacy-gate-inline-alert');
      if (!box) {
        return;
      }
      if (variant === 'hidden') {
        box.classList.add('hidden');
        return;
      }
      box.className = 'banner banner-' + (variant || 'danger');
      setText(
        'privacy-gate-inline-alert-title',
        opt_title || 'Privacy Notice Acknowledgment'
      );
      setText('privacy-gate-inline-alert-message', opt_message || '');
      box.classList.remove('hidden');
      if (typeof PBNotify === 'object' && PBNotify && typeof PBNotify.toast === 'function') {
        PBNotify.toast(variant || 'danger', opt_title || 'Privacy Notice Acknowledgment', opt_message || '');
      }
    }

    /**
     * Displays a server or transport error in the dismissible UI banner (#rpc-error-banner).
     */
    function showUiErrorBanner(err) {
      var banner = document.getElementById('rpc-error-banner');
      if (!banner) {
        return;
      }
      var code = err && err.code ? String(err.code) : 'ERR_UNKNOWN';
      var message =
        err && err.message
          ? String(err.message)
          : 'An unexpected error occurred while communicating with the server.';
      var reqId = err && err.requestId ? String(err.requestId) : 'N/A';
      var action = err && err.action ? String(err.action) : 'unknown';

      setText('rpc-error-banner-title', 'Request Failed (' + code + ')');
      setText('rpc-error-banner-message', message);

      var fieldErrorKeys =
        err && err.fieldErrors && typeof err.fieldErrors === 'object'
          ? Object.keys(err.fieldErrors)
          : [];
      var metaText = 'Action: ' + action + ' | Correlation ID: ' + reqId;
      if (fieldErrorKeys.length > 0) {
        metaText += ' | Fields: ' + JSON.stringify(err.fieldErrors);
      }
      setText('rpc-error-banner-meta', metaText);

      banner.classList.remove('hidden');
      if (typeof PBNotify === 'object' && PBNotify && typeof PBNotify.toast === 'function') {
        PBNotify.toast('danger', 'Request Failed (' + code + ')', message);
      }
    }

    /**
     * Hides the UI server error banner.
     */
    function hideUiErrorBanner() {
      var banner = document.getElementById('rpc-error-banner');
      if (banner) {
        banner.classList.add('hidden');
      }
    }

    /**
     * Returns all keyboard-focusable elements inside a container element.
     */
    function getFocusableElements(container) {
      if (!container || typeof container.querySelectorAll !== 'function') {
        return [];
      }
      var nodes = container.querySelectorAll(
        'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
      );
      var result = [];
      for (var i = 0; i < nodes.length; i++) {
        var el = nodes[i];
        if (!el.classList.contains('hidden') && el.offsetParent !== null) {
          result.push(el);
        } else if (!el.classList.contains('hidden')) {
          result.push(el);
        }
      }
      return result;
    }

    /**
     * Opens an accessible modal dialog (`modal-login` or `modal-privacy-gate`),
     * records the previously focused element, and moves focus into the dialog.
     *
     * @param {string} modalId DOM ID of the `.modal-backdrop` element.
     * @param {string=} opt_initialFocusId Optional element ID inside the modal to focus first.
     */
    /**
     * Self-healing DOM guard:
     * - Removes any legacy Step 4 `#view-login` card so its `#form-login` / `#input-login-*` IDs
     *   never collide with Step 5's `#modal-login`.
     * - Injects `#modal-login` and `#modal-privacy-gate` if they are missing from the DOM.
     */
    function ensureStep5ModalsExist() {
      var legacyLoginCard = document.getElementById('view-login');
      if (legacyLoginCard && legacyLoginCard.parentNode) {
        legacyLoginCard.parentNode.removeChild(legacyLoginCard);
      }
    }

    function setLoginModalPaneMode(mode) {
      var isRecovery = mode === 'recovery';
      var signinPane = document.getElementById('login-view-signin-pane');
      var recoveryPane = document.getElementById('login-view-recovery-pane');
      var titleEl = document.getElementById('login-modal-title');
      var descEl = document.getElementById('login-modal-desc');
      var chipEl = document.querySelector('#modal-login .pb-auth-ref-status-chip');
      if (signinPane) {
        signinPane.classList.toggle('hidden', isRecovery);
      }
      if (recoveryPane) {
        recoveryPane.classList.toggle('hidden', !isRecovery);
      }
      if (titleEl) {
        titleEl.textContent = isRecovery ? 'Forgot Password?' : 'Welcome Back!';
      }
      if (descEl) {
        descEl.textContent = isRecovery
          ? 'Enter your username or email and connect with Pattanabhumi Biology support to reset your credentials.'
          : 'Sign in to access smart, personalized biology study plans, recorded lessons, and class schedules.';
      }
      if (chipEl) {
        chipEl.textContent = isRecovery ? 'Account Recovery' : 'Secure Portal Sign-In';
      }
    }

    function openModalDialog(modalId, opt_initialFocusId) {
      ensureStep5ModalsExist();
      if (modalId === 'modal-login') {
        setLoginModalPaneMode('signin');
      }
      var modalEl = document.getElementById(modalId);
      if (!modalEl) {
        return;
      }
      if (!activeModalId && document.activeElement) {
        lastFocusedBeforeModal = document.activeElement;
      }
      activeModalId = modalId;
      modalEl.classList.remove('hidden');
      modalEl.setAttribute('aria-hidden', 'false');
      if (document.body && document.body.classList) {
        document.body.classList.add('pb-modal-open');
      }

      var targetFocus = opt_initialFocusId
        ? document.getElementById(opt_initialFocusId)
        : null;
      if (!targetFocus) {
        var focusables = getFocusableElements(modalEl);
        targetFocus = focusables.length > 0 ? focusables[0] : null;
      }
      if (targetFocus && typeof targetFocus.focus === 'function') {
        setTimeout(function () {
          targetFocus.focus();
        }, 10);
      }
    }

    /**
     * Closes an accessible modal dialog and restores focus to the trigger control.
     *
     * @param {string} modalId DOM ID of the `.modal-backdrop` element.
     */
    var pbPdfViewerReturnModalId = null;

    function isSecondaryOverlayModalId(modalId) {
      return (
        modalId === 'modal-pb-pdf-viewer' ||
        modalId === 'modal-pb-image-zoom' ||
        modalId === 'modal-pb-table-editor'
      );
    }

    function closeModalDialog(modalId) {
      var modalEl = document.getElementById(modalId);
      if (!modalEl) {
        return;
      }
      if (typeof PBEnhancedSelect === 'object' && PBEnhancedSelect) {
        PBEnhancedSelect.closeActive(true, false);
      }
      if (modalId === 'modal-recording-detail' && typeof unmountRecordingYouTubePlayer === 'function') {
        unmountRecordingYouTubePlayer();
      }
      if (modalId === 'modal-pb-pdf-viewer') {
        var pdfViewerIframe = document.getElementById('iframe-pb-pdf-viewer');
        if (pdfViewerIframe) {
          pdfViewerIframe.src = 'about:blank';
        }
      }
      if (modalId === 'modal-pb-image-zoom') {
        var zoomImg = document.getElementById('img-pb-image-zoom-target');
        if (zoomImg) {
          zoomImg.removeAttribute('src');
        }
      }
      unloadEmbeddedPdfFramesInElement(modalEl);
      modalEl.classList.add('hidden');
      modalEl.setAttribute('aria-hidden', 'true');

      if (activeModalId === modalId) {
        activeModalId = null;
      }
      if (isSecondaryOverlayModalId(modalId) && pbPdfViewerReturnModalId) {
        var prevModalEl = document.getElementById(pbPdfViewerReturnModalId);
        if (prevModalEl && !prevModalEl.classList.contains('hidden')) {
          activeModalId = pbPdfViewerReturnModalId;
        }
        pbPdfViewerReturnModalId = null;
      }
      if (!activeModalId && document.body && document.body.classList) {
        document.body.classList.remove('pb-modal-open');
      }
      if (
        !activeModalId &&
        lastFocusedBeforeModal &&
        typeof lastFocusedBeforeModal.focus === 'function'
      ) {
        try {
          lastFocusedBeforeModal.focus();
        } catch (ignoreFocusErr) {}
        lastFocusedBeforeModal = null;
      }
    }

    /**
     * Switches visible top-level section view (`loading`, `fatal`, `landing`, `profile`,
     * `payments`, `calendar`, `admin`, `contact`) and updates `aria-current="page"` on
     * navigation buttons.
     */

    /* ========================================================================
     * FLOATING QUICK-JUMP TABLE OF CONTENTS (TOC) MODULE (PBFloatingToc)
     * Provides a collapsible floating TOC menu (#pb-floating-toc-dock) and
     * in-page quick-jump pill navigation for Student, Admin, and Public views.
     * ======================================================================== */
    /* ========================================================================
     * ADMIN DASHBOARD MODAL CARD CONTROLLER (PBAdminActionModal)
     * Opens stacked Admin Dashboard editor cards/forms as centered/sheet modal
     * cards on demand so administrators never have to scroll through long
     * vertically stacked forms.
     * ======================================================================== */
    var PBAdminActionModal = (function () {
      var activeModalId = '';

      function ensureModalHeader(cardEl, titleText) {
        if (!cardEl) return;
        var hdr = null;
        for (var i = 0; i < cardEl.children.length; i++) {
          if (
            cardEl.children[i].classList &&
            cardEl.children[i].classList.contains('pb-admin-modal-sticky-bar')
          ) {
            hdr = cardEl.children[i];
            break;
          }
        }
        if (!hdr) {
          hdr = document.createElement('div');
          hdr.className = 'pb-admin-modal-sticky-bar';

          var titleSpan = document.createElement('span');
          titleSpan.className = 'pb-admin-modal-sticky-title';
          titleSpan.textContent = titleText || 'Admin Action';

          var closeBtn = document.createElement('button');
          closeBtn.type = 'button';
          closeBtn.className = 'pb-admin-modal-close-btn';
          closeBtn.setAttribute('aria-label', 'Close modal card');
          closeBtn.textContent = 'Close';
          closeBtn.addEventListener('click', function (evt) {
            evt.preventDefault();
            evt.stopPropagation();
            close();
          });

          hdr.appendChild(titleSpan);
          hdr.appendChild(closeBtn);
          if (cardEl.firstChild) {
            cardEl.insertBefore(hdr, cardEl.firstChild);
          } else {
            cardEl.appendChild(hdr);
          }
        } else {
          for (var j = 0; j < hdr.children.length; j++) {
            if (
              hdr.children[j].classList &&
              hdr.children[j].classList.contains('pb-admin-modal-sticky-title') &&
              titleText
            ) {
              hdr.children[j].textContent = titleText;
            }
          }
        }
      }

      function open(targetId, opt_title) {
        if (!targetId) return false;
        var el = document.getElementById(targetId);
        if (!el) return false;
        if (activeModalId && activeModalId !== targetId) {
          var prev = document.getElementById(activeModalId);
          if (prev) {
            prev.classList.remove('is-modal-open');
          }
        }
        /* Ensure parent admin tabpanel is visible so fixed modal child is never hidden by a display:none tabpanel */
        var parentNode = el.parentNode;
        while (parentNode && parentNode !== document.body) {
          if (
            parentNode.getAttribute &&
            parentNode.getAttribute('role') === 'tabpanel' &&
            parentNode.id &&
            parentNode.id.indexOf('admin-panel-') === 0 &&
            parentNode.classList &&
            parentNode.classList.contains('hidden')
          ) {
            var tabKey = parentNode.id.replace('admin-panel-', '');
            if (typeof switchAdminSubTab === 'function') {
              switchAdminSubTab(tabKey, false, false);
            } else {
              parentNode.classList.remove('hidden');
            }
            break;
          }
          parentNode = parentNode.parentNode;
        }
        if (targetId === 'admin-factory-reset-card') {
          var resetEmailInp = document.getElementById('input-admin-factory-reset-email');
          if (resetEmailInp) {
            var notifInp = document.getElementById('input-admin-notification-email');
            var contactInp = document.getElementById('input-admin-contact-email');
            var sessionEmail =
              currentSessionMeta && currentSessionMeta.user && currentSessionMeta.user.email
                ? String(currentSessionMeta.user.email).trim()
                : '';
            var lockedEmail =
              sessionEmail ||
              (resetEmailInp.value && resetEmailInp.value.trim()) ||
              (notifInp && notifInp.value.trim()) ||
              (contactInp && contactInp.value.trim()) ||
              '';
            resetEmailInp.value = lockedEmail;
            resetEmailInp.readOnly = true;
            resetEmailInp.disabled = true;
            resetEmailInp.setAttribute('aria-readonly', 'true');
          }
          if (typeof loadFactoryResetPreviewCounts === 'function') {
            loadFactoryResetPreviewCounts();
          }
        }
        activeModalId = targetId;
        ensureModalHeader(el, opt_title || 'Admin Editor');
        el.classList.add('pb-admin-modal-target');
        el.classList.remove('hidden');
        el.classList.add('is-modal-open');
        var backdrop = document.getElementById('pb-admin-action-modal-backdrop');
        if (backdrop) {
          backdrop.classList.remove('hidden');
          backdrop.setAttribute('aria-hidden', 'false');
        }
        if (document.body && document.body.classList) {
          document.body.classList.add('pb-admin-modal-lock');
        }
        try {
          el.scrollTop = 0;
        } catch (ignoreScrollErr) {}
        return true;
      }

      function close() {
        if (activeModalId) {
          var el = document.getElementById(activeModalId);
          if (el) {
            if (activeModalId === 'admin-question-preview-card') {
              clearChildren('qbank-preview-body-container');
            } else {
              unloadEmbeddedPdfFramesInElement(el);
            }
            el.classList.remove('is-modal-open');
            if (activeModalId === 'admin-unavail-detail-drawer') {
              el.classList.add('hidden');
            }
          }
          activeModalId = '';
        }
        var backdrop = document.getElementById('pb-admin-action-modal-backdrop');
        if (backdrop) {
          backdrop.classList.add('hidden');
          backdrop.setAttribute('aria-hidden', 'true');
        }
        if (document.body && document.body.classList) {
          document.body.classList.remove('pb-admin-modal-lock');
        }
      }

      return Object.freeze({
        open: open,
        close: close,
        getActiveId: function () {
          return activeModalId;
        }
      });
    })();

    var PBConfirmModal = (function () {
      var bound = false;
      var activeResolver = null;
      var activeOnConfirm = null;
      var inFlight = false;

      function getEls() {
        return {
          backdrop: document.getElementById('modal-admin-confirm-action'),
          badge: document.getElementById('confirm-action-modal-badge'),
          title: document.getElementById('confirm-action-modal-title'),
          icon: document.getElementById('confirm-action-modal-icon'),
          hiBox: document.getElementById('confirm-action-highlight-box'),
          hiLbl: document.getElementById('confirm-action-highlight-label'),
          hiVal: document.getElementById('confirm-action-highlight-value'),
          msg: document.getElementById('confirm-action-modal-message'),
          err: document.getElementById('confirm-action-modal-error'),
          closeBtn: document.getElementById('btn-confirm-action-close'),
          cancelBtn: document.getElementById('btn-confirm-action-cancel'),
          submitBtn: document.getElementById('btn-confirm-action-submit')
        };
      }

      function close(didConfirm) {
        if (inFlight && !didConfirm) return;
        var els = getEls();
        if (els.backdrop) {
          els.backdrop.classList.add('hidden');
          els.backdrop.setAttribute('aria-hidden', 'true');
        }
        inFlight = false;
        if (els.cancelBtn) els.cancelBtn.disabled = false;
        if (els.submitBtn) els.submitBtn.disabled = false;
        if (els.closeBtn) els.closeBtn.disabled = false;
        var res = activeResolver;
        activeResolver = null;
        activeOnConfirm = null;
        if (typeof res === 'function') res(Boolean(didConfirm));
      }

      function ensureBound() {
        if (bound) return;
        var els = getEls();
        if (!els.backdrop) return;
        bound = true;
        if (els.closeBtn) {
          els.closeBtn.addEventListener('click', function () {
            close(false);
          });
        }
        if (els.cancelBtn) {
          els.cancelBtn.addEventListener('click', function () {
            close(false);
          });
        }
        els.backdrop.addEventListener('click', function (evt) {
          if (evt.target === els.backdrop) close(false);
        });
        document.addEventListener('keydown', function (evt) {
          if (evt.key === 'Escape' && els.backdrop && !els.backdrop.classList.contains('hidden')) {
            close(false);
          }
        });
        if (els.submitBtn) {
          els.submitBtn.addEventListener('click', function () {
            if (inFlight) return;
            var handler = activeOnConfirm;
            if (typeof handler !== 'function') {
              close(true);
              return;
            }
            inFlight = true;
            var origText = els.submitBtn.textContent || 'Confirm';
            if (els.err) els.err.textContent = '';
            els.submitBtn.disabled = true;
            els.submitBtn.textContent = els.submitBtn.getAttribute('data-loading-label') || 'Deleting...';
            if (els.cancelBtn) els.cancelBtn.disabled = true;
            if (els.closeBtn) els.closeBtn.disabled = true;
            Promise.resolve()
              .then(function () {
                return handler();
              })
              .then(function () {
                inFlight = false;
                els.submitBtn.textContent = origText;
                close(true);
              })
              .catch(function (err) {
                inFlight = false;
                els.submitBtn.disabled = false;
                els.submitBtn.textContent = origText;
                if (els.cancelBtn) els.cancelBtn.disabled = false;
                if (els.closeBtn) els.closeBtn.disabled = false;
                if (els.err) {
                  els.err.textContent = (err && err.message) || 'Action failed. Please try again.';
                }
              });
          });
        }
      }

      function run(opts) {
        opts = opts && typeof opts === 'object' ? opts : {};
        if (window.__PB_AUTO_CONFIRM_DELETE__ === true) {
          return typeof opts.onConfirm === 'function' ? Promise.resolve(opts.onConfirm()) : Promise.resolve(true);
        }
        ensureBound();
        var els = getEls();
        if (!els.backdrop) {
          return typeof opts.onConfirm === 'function' ? Promise.resolve(opts.onConfirm()) : Promise.resolve(true);
        }
        activeOnConfirm = typeof opts.onConfirm === 'function' ? opts.onConfirm : null;
        if (els.badge) {
          els.badge.textContent = opts.badgeText || 'Confirm Permanent Action';
          els.badge.className = opts.isWarning ? 'badge badge-incomplete' : 'badge badge-danger';
        }
        if (els.icon) {
          els.icon.classList.toggle('is-warning', Boolean(opts.isWarning));
        }
        if (els.title) els.title.textContent = opts.title || 'Confirm Action';
        if (els.msg) els.msg.textContent = opts.message || '';
        if (els.err) els.err.textContent = '';
        if (els.hiBox && els.hiLbl && els.hiVal) {
          if (opts.targetDetail) {
            els.hiLbl.textContent = opts.targetLabel || 'Target Item';
            els.hiVal.textContent = opts.targetDetail;
            els.hiBox.classList.remove('hidden');
          } else {
            els.hiBox.classList.add('hidden');
          }
        }
        if (els.submitBtn) {
          els.submitBtn.textContent = opts.confirmText || 'Delete Permanently';
          els.submitBtn.setAttribute('data-loading-label', opts.loadingText || 'Deleting...');
          var usePrimaryBtn = opts.confirmVariant === 'primary';
          els.submitBtn.classList.toggle('btn-danger', !usePrimaryBtn);
          els.submitBtn.classList.toggle('btn-primary', usePrimaryBtn);
          els.submitBtn.disabled = false;
        }
        if (els.cancelBtn) els.cancelBtn.disabled = false;
        if (els.closeBtn) els.closeBtn.disabled = false;
        els.backdrop.classList.remove('hidden');
        els.backdrop.setAttribute('aria-hidden', 'false');
        if (els.cancelBtn) els.cancelBtn.focus();
        return new Promise(function (resolve) {
          activeResolver = resolve;
        });
      }

      return Object.freeze({ run: run, close: close });
    })();

