      var lineConfigured = /^https:\/\/[^\s]+$/i.test(effectiveLineUrl);

      var rawPhone = typeof contact.phone === 'string' ? contact.phone.trim() : '';
      var effectivePhone = rawPhone || defaultPhone;
      var phoneDigits = effectivePhone.replace(/[^0-9+]/g, '') || '0966821528';
      var phoneConfigured = Boolean(phoneDigits);

      var fbConfigured =
        Boolean(contact.facebookConfigured) &&
        typeof contact.facebookUrl === 'string' &&
        /^https:\/\/[^\s]+$/i.test(contact.facebookUrl.trim());

      var rawEmail = typeof contact.email === 'string' ? contact.email.trim() : '';
      var effectiveEmail =
        /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(rawEmail) &&
        rawEmail.toLowerCase().indexOf('placeholder') === -1 &&
        rawEmail.toLowerCase().indexOf('example.com') === -1
