    /**
     * Invokes the single backend RPC entry point (rpcDispatch) via google.script.run.
     */
    var activeGasTransportCount = 0;
    var MAX_CONCURRENT_GAS_TRANSPORT = 6;
    var pendingGasTransportQueue = [];
    var RPC_SHORT_READ_CACHE_ = {};
    var RPC_SHORT_READ_TTL_MS_ = 10000;

    function clearRpcReadCache() {
      RPC_SHORT_READ_CACHE_ = {};
      studentCourseDetailCacheById = {};
    }

    function isShortCacheableReadAction(actionName) {
      return /^(public\.getBootstrap|student\.(getCourses|getCourseDetail)|exams\.list|admin\.(exams|courses|questions)\.list|calendar\.list)$/i.test(
        String(actionName || '').trim()
      );
    }

    function pumpGasTransportQueue() {
      while (activeGasTransportCount < MAX_CONCURRENT_GAS_TRANSPORT && pendingGasTransportQueue.length > 0) {
        var nextJob = pendingGasTransportQueue.shift();
        activeGasTransportCount += 1;
        try {
          nextJob();
        } catch (err) {
          activeGasTransportCount = Math.max(0, activeGasTransportCount - 1);
        }
      }
    }

    function enqueueGasTransportCall(jobFn) {
      pendingGasTransportQueue.push(jobFn);
      pumpGasTransportQueue();
    }

    function releaseGasTransportSlot() {
      activeGasTransportCount = Math.max(0, activeGasTransportCount - 1);
      pumpGasTransportQueue();
    }

    function isReadOnlyCoalesceableRpcAction(actionName) {
      var act = String(actionName || '').trim();
      if (act === 'system.ping') return false;
      return /^(public\.getBootstrap|auth\.get|file\.getContent|student\.(get|list)|admin\.(get|list)|admin\.(exams|questions|attempts|integrity|results|grading)\.(list|get|inspect|preview|analytics)|exams\.(list|get)|payment\.get|calendar\.(get|list)|unavailability\.list|portal\.(listAnnouncements|getReleaseAckStatus))/i.test(
        act
      );
    }

    function rpcCallEnvelope(action, opt_payload, opt_options) {
      var options =
        opt_options && typeof opt_options === 'object' ? opt_options : {};
      var safeAction = typeof action === 'string' ? action.trim() : '';
      var isReadOnlyAction = isReadOnlyCoalesceableRpcAction(safeAction);
      var payloadSig = '';
      if (isReadOnlyAction && opt_payload && typeof opt_payload === 'object') {
        try {
          payloadSig = ':' + JSON.stringify(opt_payload).slice(0, 180);
        } catch (ignoreSigErr) {}
      }
      var dedupeKey =
        typeof options.dedupeKey === 'string' && options.dedupeKey.length > 0
          ? options.dedupeKey
          : 'action:' + safeAction + payloadSig;

      /* Coalesce identical in-flight read-only requests so admin.getCourseEditorDetail and list/get calls never fail with ERR_DUPLICATE_IN_FLIGHT */
      if (isReadOnlyAction && !options.allowConcurrent && inFlightPromises[dedupeKey]) {
        return inFlightPromises[dedupeKey];
      }

      if (isShortCacheableReadAction(safeAction) && !options.forceRefresh && RPC_SHORT_READ_CACHE_[dedupeKey]) {
        var cachedRpcHit = RPC_SHORT_READ_CACHE_[dedupeKey];
        if (cachedRpcHit && Date.now() - cachedRpcHit.cachedAt < RPC_SHORT_READ_TTL_MS_) {
          return Promise.resolve(cachedRpcHit.envelope);
        }
        delete RPC_SHORT_READ_CACHE_[dedupeKey];
      }

      var requestId = nextRequestId();

      var reqPromise = new Promise(function (resolve, reject) {
        function failWith(errorObj) {
          errorObj.action = safeAction;
          errorObj.requestId = errorObj.requestId || requestId;
          errorObj.autoRetried = false;

          if (errorObj.code === 'ERR_ACCOUNT_INTEGRITY_LOCKED') {
            clearClientSessionCredential();
            applySessionAndRouteState(null, 'INVALID_OR_EXPIRED');
            if (typeof openAccountIntegrityLockedModalPhaseC === 'function') {
              openAccountIntegrityLockedModalPhaseC({
                fieldErrors: errorObj.fieldErrors || {}
              });
            }
          }

          /* If session expired or was revoked on a protected call, clear local state and return to Login (unless user is actively logging out) */
          if (
            (errorObj.code === 'ERR_AUTH_REQUIRED' ||
              errorObj.code === 'ERR_ACCOUNT_SUSPENDED') &&
            safeAction !== 'auth.login' &&
            !options.keepSessionOnAuthError
          ) {
            if (isLogoutInProgress || !currentSessionMeta || !currentSessionMeta.user) {
              errorObj.suppressedDuringLogout = true;
            } else {
              var feObj = errorObj.fieldErrors && typeof errorObj.fieldErrors === 'object' ? errorObj.fieldErrors : {};
              var isSuperseded = Boolean(
                feObj.sessionSuperseded ||
                  feObj.revokeReason === 'NEW_DEVICE_LOGIN' ||
                  String(errorObj.message || '').indexOf('another device') !== -1
              );
              clearClientSessionCredential();
              applySessionAndRouteState(
                null,
                isSuperseded ? 'SESSION_SUPERSEDED' : 'INVALID_OR_EXPIRED',
                isSuperseded ? errorObj.message : ''
              );
              if (options.silent || isSuperseded) {
                errorObj.suppressedDuringLogout = true;
              }
            }
          }

          /* If backend reports ERR_PRIVACY_ACK_REQUIRED (e.g. notice version changed), open Privacy Gate */
          if (
            errorObj.code === 'ERR_PRIVACY_ACK_REQUIRED' &&
            currentSessionMeta &&
            currentSessionMeta.user
          ) {
            var newVer =
              errorObj.fieldErrors &&
              errorObj.fieldErrors.requiredPrivacyNoticeVersion
                ? errorObj.fieldErrors.requiredPrivacyNoticeVersion
                : null;
            if (newVer) {
              currentSessionMeta.user.requiredPrivacyNoticeVersion = newVer;
            }
            currentSessionMeta.user.requiresPrivacyAck = true;
            currentSessionMeta.user.privacyGateReason = 'NOTICE_UPDATE_GATE';
            openPrivacyNoticeGateForUser(currentSessionMeta.user);
          }

          if (!options.suppressErrorBanner) {
            showUiErrorBanner(errorObj);
          }
          reject(errorObj);
        }

        if (!options.allowConcurrent && inFlightLocks[dedupeKey] === true) {
          failWith({
            code: 'ERR_DUPLICATE_IN_FLIGHT',
            message:
              'A request for "' +
              safeAction +
              '" is already in progress. Please wait for it to finish.',
            fieldErrors: {}
          });
          return;
        }

        var payloadToSend = opt_payload === undefined ? {} : opt_payload;
        var byteLimit =
          safeAction === 'payment.uploadReceipt' ||
          safeAction === 'admin.uploadFile'
            ? MAX_UPLOAD_REQUEST_BYTES
            : MAX_STANDARD_REQUEST_BYTES;

        var estimatedBytes = 0;
        try {
          estimatedBytes = estimateJsonBytes(payloadToSend);
        } catch (serErr) {
          failWith({
            code: 'ERR_VALIDATION_FAILED',
            message: 'Request payload could not be serialized to JSON.',
            fieldErrors: {}
          });
          return;
        }

        if (estimatedBytes > byteLimit) {
          failWith({
            code: 'ERR_PAYLOAD_TOO_LARGE',
            message:
              'Request payload (' +
              estimatedBytes +
              ' bytes) exceeds the client maximum (' +
              byteLimit +
              ' bytes).',
            fieldErrors: {}
          });
          return;
        }

        if (
          typeof google === 'undefined' ||
          !google.script ||
          !google.script.run ||
          typeof google.script.run.withSuccessHandler !== 'function'
        ) {
          failWith({
            code: 'ERR_APPS_SCRIPT_BRIDGE_UNAVAILABLE',
            message:
              'The google.script.run bridge is unavailable. Ensure you opened this page via the Google Apps Script Web App deployment URL.',
            fieldErrors: {}
          });
          return;
        }

        inFlightLocks[dedupeKey] = true;

        var activeTok =
          inMemorySessionToken || window.__PB_SESSION_TOKEN__ || null;
        var tokenToUse =
          options.sessionTokenOverride !== undefined
            ? options.sessionTokenOverride
            : activeTok;

        var envelope = {
          action: safeAction,
          requestId: requestId,
          sessionToken: tokenToUse,
          authToken: tokenToUse,
          payload: payloadToSend
        };

        function dispatchViaGasBridge(isRetryAttempt) {
          enqueueGasTransportCall(function () {
            google.script.run
              .withSuccessHandler(function (response) {
                releaseGasTransportSlot();
                delete inFlightLocks[dedupeKey];
                delete inFlightPromises[dedupeKey];

                if (!response || typeof response !== 'object') {
                  failWith({
                    code: 'ERR_EMPTY_RPC_RESPONSE',
                    message:
                      'The server returned an empty or malformed response envelope.',
                    fieldErrors: {}
                  });
                  return;
                }

                var echoedReqId = response.requestId || requestId;
                if (response.ok !== true) {
                  var errObj = response.error || {};
                  failWith({
                    code: errObj.code || 'ERR_RPC_REJECTED',
                    message: errObj.message || 'The server rejected the request.',
                    fieldErrors: errObj.fieldErrors || {},
                    requestId: echoedReqId,
                    serverTimeUtc: response.serverTimeUtc || null
                  });
                  return;
                }

                var successEnvelope = {
                  ok: true,
                  action: response.action || safeAction,
                  requestId: echoedReqId,
                  serverTimeUtc: response.serverTimeUtc || null,
                  data: response.data || {}
                };
                if (!isReadOnlyAction) {
                  clearRpcReadCache();
                } else if (isShortCacheableReadAction(safeAction)) {
                  RPC_SHORT_READ_CACHE_[dedupeKey] = {
                    cachedAt: Date.now(),
                    envelope: successEnvelope
                  };
                }
                resolve(successEnvelope);
              })
              .withFailureHandler(function (nativeError) {
                releaseGasTransportSlot();

                var isFinancial =
                  Object.prototype.hasOwnProperty.call(
                    FINANCIAL_MUTATION_ACTIONS,
                    safeAction
                  ) && FINANCIAL_MUTATION_ACTIONS[safeAction] === true;

                if (!isFinancial && !isRetryAttempt && safeAction !== 'system.ping') {
                  setTimeout(function () {
                    dispatchViaGasBridge(true);
                  }, 320);
                  return;
                }

                delete inFlightLocks[dedupeKey];
                delete inFlightPromises[dedupeKey];

                var rawMsg =
                  nativeError && nativeError.message
                    ? String(nativeError.message)
                    : String(nativeError || 'Unknown Apps Script transport failure.');

                failWith({
                  code: 'ERR_TRANSPORT_FAILURE',
                  message: isFinancial
                    ? 'Network/transport error during financial operation ("' +
                      safeAction +
                      '"). To prevent duplicate charges, the request was not automatically retried. Please refresh status before trying again. Details: ' +
                      rawMsg
                    : 'Communication with Google Apps Script failed: ' + rawMsg,
                  fieldErrors: {}
                });
              })
              .rpcDispatch(envelope);
          });
        }
        dispatchViaGasBridge(false);
      });
      if (isReadOnlyAction && inFlightLocks[dedupeKey]) {
        inFlightPromises[dedupeKey] = reqPromise;
      }
      return reqPromise;
    }

    /**
     * Convenience wrapper that resolves directly with `response.data`.
     */
    function rpcCall(action, opt_payload, opt_options) {
      return rpcCallEnvelope(action, opt_payload, opt_options).then(function (
        envelope
      ) {
        return envelope.data;
      });
    }

    /**
     * Binds an async click handler to a button, automatically disabling the button
     * while the Promise is in flight.
     */
    /**
     * Wraps an asynchronous action triggered by `btnEl` and displays an inline
     * loading spinner on `btnEl` plus a localized throbber overlay on `areaEl`.
     */
    function withButtonAndAreaLoading(btnEl, areaEl, asyncFn) {
      if (btnEl) {
        if (btnEl.getAttribute('aria-busy') === 'true') {
          return Promise.resolve();
        }
        btnEl.disabled = true;
        btnEl.setAttribute('aria-busy', 'true');
        btnEl.classList.add('is-btn-loading');
      }
      if (areaEl && areaEl.classList) {
        areaEl.classList.add('pb-area-loading-busy');
        areaEl.setAttribute('aria-busy', 'true');
      }
      return Promise.resolve()
        .then(function () {
          return asyncFn();
        })
        .then(
          function (res) {
            if (btnEl) {
              btnEl.disabled = false;
              btnEl.removeAttribute('aria-busy');
              btnEl.classList.remove('is-btn-loading');
            }
            if (areaEl && areaEl.classList) {
              areaEl.classList.remove('pb-area-loading-busy');
              areaEl.removeAttribute('aria-busy');
            }
            return res;
          },
          function (err) {
            if (btnEl) {
              btnEl.disabled = false;
              btnEl.removeAttribute('aria-busy');
              btnEl.classList.remove('is-btn-loading');
            }
            if (areaEl && areaEl.classList) {
              areaEl.classList.remove('pb-area-loading-busy');
              areaEl.removeAttribute('aria-busy');
            }
            throw err;
          }
        );
    }

    /**
     * Renders animated skeleton shimmer rows into a `<tbody>` while table data is loading.
     */
    function renderTableSkeletonRows(tbodyId, colCount, opt_rowCount) {
      var tbody = document.getElementById(tbodyId);
      if (!tbody) return;
      clearChildren(tbody);
      var rows = opt_rowCount || 3;
      var tr = document.createElement('tr');
      var td = document.createElement('td');
      td.colSpan = colCount || 6;
      var wrap = document.createElement('div');
      wrap.className = 'pb-table-skeleton-stack';
      wrap.setAttribute('aria-hidden', 'true');
      for (var i = 0; i < rows; i++) {
        var line = document.createElement('div');
        line.className = 'pb-skeleton-line';
        line.style.width = (100 - i * 5) + '%';
        line.style.height = '40px';
        line.style.borderRadius = '10px';
        wrap.appendChild(line);
      }
      td.appendChild(wrap);
      tr.appendChild(td);
      tbody.appendChild(tr);
    }

    /**
     * Renders animated section & card skeleton blocks inside `#admin-course-sections-list` while loading.
     */
    function renderSectionsWorkspaceSkeleton() {
      var listEl = document.getElementById('admin-course-sections-list');
      if (!listEl) return;
      clearChildren(listEl);
      for (var i = 0; i < 3; i++) {
        var box = document.createElement('div');
        box.className = 'course-section-box pb-section-skeleton-card';
        box.setAttribute('aria-hidden', 'true');

        var topRow = document.createElement('div');
        topRow.style.display = 'flex';
        topRow.style.justifyContent = 'space-between';
        topRow.style.flexWrap = 'wrap';
        topRow.style.gap = '10px';

        var leftCol = document.createElement('div');
        leftCol.style.flex = '1';
        leftCol.style.minWidth = '180px';
        var bLine = document.createElement('div');
        bLine.className = 'pb-skeleton-line';
        bLine.style.width = '130px';
        bLine.style.height = '20px';
        bLine.style.borderRadius = '999px';
        bLine.style.marginBottom = '8px';
        var tLine = document.createElement('div');
        tLine.className = 'pb-skeleton-line';
        tLine.style.width = '65%';
        tLine.style.height = '22px';
        leftCol.appendChild(bLine);
        leftCol.appendChild(tLine);

        var rightPills = document.createElement('div');
        rightPills.style.display = 'flex';
        rightPills.style.gap = '6px';
        rightPills.style.flexWrap = 'wrap';
        for (var p = 0; p < 4; p++) {
          var pill = document.createElement('div');
          pill.className = 'pb-skeleton-line';
          pill.style.width = '92px';
          pill.style.height = '34px';
          pill.style.borderRadius = '999px';
          rightPills.appendChild(pill);
        }

        topRow.appendChild(leftCol);
        topRow.appendChild(rightPills);
        box.appendChild(topRow);
        listEl.appendChild(box);
      }
    }

    function bindActionButton(buttonId, asyncHandlerFn) {
      var btn = document.getElementById(buttonId);
      if (!btn) {
        return;
      }
      var isRunning = false;
      btn.addEventListener('click', function (evt) {
        if (isRunning || btn.disabled) {
          evt.preventDefault();
          return;
        }
        isRunning = true;
        btn.disabled = true;
        btn.setAttribute('aria-busy', 'true');
        btn.classList.add('is-btn-loading');

        Promise.resolve()
          .then(function () {
            return asyncHandlerFn(evt);
          })
          .catch(function () {})
          .then(function () {
            isRunning = false;
            btn.disabled = false;
            btn.removeAttribute('aria-busy');
            btn.classList.remove('is-btn-loading');
          });
      });
    }

    /**
     * Renders diagnostic test results in the Developer Verification Drawer.
     */
    function renderDiagnosticResult(title, details) {
      setText('rpc-test-result-heading', title);
      setText('rpc-test-result-json', JSON.stringify(details, null, 2));
    }

    /**
     * Displays the Fatal Error view with diagnostic details.
     */
    function renderFatalError(err) {
      var code = err && err.code ? err.code : 'ERR_UNKNOWN';
      var message =
        err && err.message
          ? err.message
          : 'An unexpected error prevented the application shell from initializing.';

      setText('fatal-error-code', code);
      setText('fatal-error-detail', message);
      showSectionView('fatal');
    }

    /**
     * Initializes the application shell:
     * - Shows the neutral `#view-loading` state during session restoration so private
     *   content is never flashed and a signed-out landing page is never falsely shown.
     * - Restores any valid `localStorage` Remember-me session via `public.getBootstrap`.
     * - Routes authenticated users to Privacy Gate (if required), My Profile (`STUDENT`),
     *   or Admin Dashboard (`ADMIN`), and unauthenticated visitors to Landing Page.
     */
    var startupWatchdogTimer = null;

    var BOOTSTRAP_SESSION_CACHE_KEY = 'pb_lms_bootstrap_cache_v1';
    var BOOTSTRAP_CACHE_MAX_AGE_MS_ = 300000;
    var pbLastVersionCheckAtMs_ = 0;

    function getDeclaredBuildVersion() {
      try {
        var meta = document.querySelector('meta[name="pb-build-version"]');
        return meta ? String(meta.getAttribute('content') || '').trim() : '';
      } catch (ignoreMetaErr) {
        return '';
      }
    }

    function clearStaleSiteCachesForNewVersion() {
      try {
        if (typeof sessionStorage !== 'undefined' && sessionStorage) {
          sessionStorage.removeItem(BOOTSTRAP_SESSION_CACHE_KEY);
        }
      } catch (e1) {}
      try {
        if (typeof localStorage !== 'undefined' && localStorage) {
          localStorage.removeItem(BOOTSTRAP_SESSION_CACHE_KEY);
          if (typeof SESSION_STORAGE_KEY_LOGO_CACHE === 'string') {
            localStorage.removeItem(SESSION_STORAGE_KEY_LOGO_CACHE);
          }
        }
      } catch (e2) {}
      if (typeof clearRpcReadCache === 'function') clearRpcReadCache();
    }

    function pbCheckDeploymentFreshness() {
      try {
        if (typeof window === 'undefined' || !window.location || !/^https?:$/i.test(String(window.location.protocol || ''))) {
          return;
        }
        if (/script\.google(usercontent)?\.com$/i.test(String(window.location.hostname || ''))) {
          return;
        }
        var declared = getDeclaredBuildVersion();
        if (!declared || declared === 'dev') return;
        var now = Date.now();
        if (pbLastVersionCheckAtMs_ && now - pbLastVersionCheckAtMs_ < 60000) return;
        pbLastVersionCheckAtMs_ = now;
        if (typeof window.fetch !== 'function') return;

        window
          .fetch('version.json?_=' + String(now), { cache: 'no-store' })
          .then(function (res) {
            return res && res.ok ? res.json() : null;
          })
          .then(function (manifest) {
            var liveVer = manifest && manifest.version ? String(manifest.version).trim() : '';
            if (typeof PBReleaseNotesManager === 'object' && PBReleaseNotesManager && typeof PBReleaseNotesManager.setManifestMeta === 'function') {
              PBReleaseNotesManager.setManifestMeta(manifest || null);
            }
            if (!liveVer || liveVer === declared) return;
            clearStaleSiteCachesForNewVersion();

            var activeExamView = document.getElementById('view-exam-workspace');
            var inExam = activeExamView && !activeExamView.classList.contains('hidden');
            var fbWorkspaceEl = document.getElementById('pb-forms-builder-workspace');
            var inFormBuilder = fbWorkspaceEl && !fbWorkspaceEl.classList.contains('hidden') && !document.getElementById('view-admin')?.classList.contains('hidden');
            var hasOpenEditorModal = Boolean(
              document.querySelector('.pb-modal-overlay.is-open, .modal-backdrop.is-open, dialog[open]')
            );
            var hasDirtyAdmin = Boolean(typeof hasUnsavedCourseChanges !== 'undefined' && hasUnsavedCourseChanges);
            if (inExam || inFormBuilder || hasOpenEditorModal || hasDirtyAdmin) {
              if (typeof PBNotify === 'object' && PBNotify && typeof PBNotify.toast === 'function') {
                PBNotify.toast(
                  'info',
                  'New Version Published',
                  'A newer build of Pattanabhumi Biology is available. Save your work and refresh when ready.',
                  { durationMs: 8000 }
                );
              }
              return;
            }
            var reloadedFor = '';
            try {
              reloadedFor = sessionStorage.getItem('pb_auto_reloaded_ver') || '';
              if (reloadedFor === liveVer) return;
              sessionStorage.setItem('pb_auto_reloaded_ver', liveVer);
              sessionStorage.setItem('pb_post_update_reload_from', declared);
              if (inMemorySessionToken && window.sessionStorage && !readPersistedTokenIfAvailable()) {
                window.sessionStorage.setItem(STORAGE_KEY_SESSION_TOKEN, inMemorySessionToken);
              }
            } catch (eStore) {
              return;
            }
            var pageUrl = String(window.location.href || '').split('#')[0];
            window
              .fetch(pageUrl, { cache: 'reload' })
              .catch(function () {})
              .then(function () {
                window.location.reload();
              });
          })
          .catch(function () {});
      } catch (ignoreFreshErr) {}
    }

    if (typeof document !== 'undefined' && document.addEventListener) {
      document.addEventListener('visibilitychange', function () {
        if (document.visibilityState === 'visible') {
          pbCheckDeploymentFreshness();
        }
      });
    }

    function isBootstrapCacheEntryFresh(parsed) {
      if (!parsed || typeof parsed !== 'object') return false;
      var declared = getDeclaredBuildVersion();
      if (declared && declared !== 'dev' && parsed.buildVersion !== declared) {
        return false;
      }
      if (parsed.cachedAt && Date.now() - Number(parsed.cachedAt) > BOOTSTRAP_CACHE_MAX_AGE_MS_) {
        return false;
      }
      return true;
    }

    function readCachedBootstrapData() {
      try {
        if (typeof sessionStorage !== 'undefined' && sessionStorage) {
          var raw = sessionStorage.getItem(BOOTSTRAP_SESSION_CACHE_KEY);
          if (raw) {
            var parsed = JSON.parse(raw);
            if (isBootstrapCacheEntryFresh(parsed)) {
              return parsed;
            }
            sessionStorage.removeItem(BOOTSTRAP_SESSION_CACHE_KEY);
          }
        }
      } catch (ignoreReadBootErr) {}
      try {
        if (typeof localStorage !== 'undefined' && localStorage) {
          var rawLocal = localStorage.getItem(BOOTSTRAP_SESSION_CACHE_KEY);
          if (rawLocal) {
            var parsedLocal = JSON.parse(rawLocal);
            if (isBootstrapCacheEntryFresh(parsedLocal)) {
              return parsedLocal;
            }
            localStorage.removeItem(BOOTSTRAP_SESSION_CACHE_KEY);
          }
        }
      } catch (ignoreReadLocalBootErr) {}
      return null;
    }

    function writeCachedBootstrapData(bootstrapData) {
      try {
        if (bootstrapData && typeof bootstrapData === 'object') {
          var slim = {
            buildVersion: getDeclaredBuildVersion() || 'dev',
            cachedAt: Date.now(),
            schoolName: bootstrapData.schoolName || 'Pattanabhumi Biology',
            logoText: bootstrapData.logoText || 'PB',
            contact: bootstrapData.contact || {},
            bangkokYear: bootstrapData.bangkokYear || 2026,
            dekConfig: bootstrapData.dekConfig || null,
            publicContent: bootstrapData.publicContent || null
          };
          var serialized = JSON.stringify(slim);
          if (typeof sessionStorage !== 'undefined' && sessionStorage) {
            sessionStorage.setItem(BOOTSTRAP_SESSION_CACHE_KEY, serialized);
          }
          if (typeof localStorage !== 'undefined' && localStorage) {
            localStorage.setItem(BOOTSTRAP_SESSION_CACHE_KEY, serialized);
          }
        }
      } catch (ignoreWriteBootErr) {}
    }

    function initializeShell() {
      hideUiErrorBanner();
      pbCheckDeploymentFreshness();

      if (startupWatchdogTimer) {
        clearTimeout(startupWatchdogTimer);
        startupWatchdogTimer = null;
      }
      startupWatchdogTimer = setTimeout(function () {
        if (currentActiveViewName === 'loading') {
          syncHeaderNavigation(null);
          showSectionView('landing');
          showUiErrorBanner({
            code: 'ERR_BOOTSTRAP_TIMEOUT',
            action: 'public.getBootstrap',
            requestId: 'startup_watchdog',
            message:
              'Initial server bootstrap took longer than 10 seconds. Showing the Landing Page in fallback mode — you can click Log in or retry your connection.'
          });
        }
      }, 10000);

      try {
        ensureStep5ModalsExist();
      } catch (ignoreModalInitErr) {}
      var candidateToken =
        inMemorySessionToken || window.__PB_SESSION_TOKEN__ || null;
      var hadPersistedToken = false;
      if (!candidateToken) {
        var persisted = readPersistedTokenIfAvailable();
        if (persisted) {
          candidateToken = persisted;
          inMemorySessionToken = persisted;
          window.__PB_SESSION_TOKEN__ = persisted;
          hadPersistedToken = true;
          var hasLsTok = false;
          try {
            hasLsTok = Boolean(window.localStorage && window.localStorage.getItem(STORAGE_KEY_SESSION_TOKEN));
          } catch (_eLsCheck) {}
          currentStorageMode = hasLsTok
            ? 'LOCAL_STORAGE_REMEMBER_ME (Resumed from browser localStorage)'
            : 'SESSION_STORAGE_CURRENT_TAB (Resumed cleanly on refresh)';
        }
      }

      var existingLogoCache = readCachedLogoState();

      /* Fast-path initial paint: If no session token exists to restore, show the Landing Page immediately (0ms delay) */
      if (!candidateToken) {
        var cachedBoot = readCachedBootstrapData();
        if (cachedBoot) {
          applyPublicWebsiteContentPhase3(cachedBoot);
          updateContactChannelsUi(cachedBoot.contact || {});
        } else {
          PBDekRotator.init();
        }
        if (existingLogoCache && existingLogoCache.publicLogo) {
          applySchoolLogoBranding(existingLogoCache.publicLogo, 'PB');
        }
        syncHeaderNavigation(null);
        showSectionView('landing');
      } else {
        showSectionView('loading');
      }

      return rpcCall(
        'public.getBootstrap',
        {
          existingSessionToken: candidateToken || '',
          sessionToken: candidateToken || '',
          authToken: candidateToken || '',
          cachedLogoKey: existingLogoCache ? existingLogoCache.cacheKey : ''
        },
        { suppressErrorBanner: true }
      )
        .then(function (bootstrapData) {
          if (startupWatchdogTimer) {
            clearTimeout(startupWatchdogTimer);
            startupWatchdogTimer = null;
          }
          currentBootstrapData = bootstrapData || {};
          writeCachedBootstrapData(currentBootstrapData);

          var schoolName =
            bootstrapData.schoolName || 'Pattanabhumi Biology';
          setText('header-school-name', schoolName);
          setText('mobile-drawer-school-name', schoolName);
          setText('landing-hero-title', schoolName);
          setText('footer-school-name', schoolName);

          var logoText = bootstrapData.logoText || 'PB';
          applySchoolLogoBranding(bootstrapData.logo || null, logoText);

          /* Update Contact channels & Forgot Password LINE fallback */
          updateContactChannelsUi(bootstrapData.contact || {});

          /* Phase 3: Hydrate DEK70/71/72 cohort rotator & Instructor Portrait */
          applyPublicWebsiteContentPhase3(bootstrapData);

          /* Test HTML Service cookie & fallback status */
          testAndManageNonSensitiveNoticeCookie(false);

          /* Show warning inside Login Modal if Users sheet has 0 accounts */
          var noAdminBanner = document.getElementById('login-no-admin-warning');
          if (noAdminBanner) {
            var hasUsers =
              bootstrapData.hasAnyUserAccount !== undefined
                ? Boolean(bootstrapData.hasAnyUserAccount)
                : true;
            noAdminBanner.classList.toggle('hidden', hasUsers);
          }

          /* Warn if localStorage is blocked inside sandboxed iframe */
          if (!isLocalStorageAvailable()) {
            var warnEl = document.getElementById('remember-me-storage-warning');
            if (warnEl) {
              warnEl.classList.remove('hidden');
            }
          }

          if (bootstrapData.session && bootstrapData.session.user) {
            var postUpdPrev = '';
            try {
              postUpdPrev = sessionStorage.getItem('pb_post_update_reload_from') || '';
              if (postUpdPrev) sessionStorage.removeItem('pb_post_update_reload_from');
            } catch (_eUpdFlag) {}
            if (postUpdPrev && typeof clearRpcReadCache === 'function') {
              clearRpcReadCache();
            }
            applySessionAndRouteState(bootstrapData.session, 'RESTORED');
            if (postUpdPrev && typeof PBNotify === 'object' && PBNotify && typeof PBNotify.toast === 'function') {
              PBNotify.toast(
                'success',
                'Portal Updated & Session Restored',
                'Loaded latest build (' + (getDeclaredBuildVersion() || 'latest') + ') and automatically restored your session.'
              );
            }
            if (typeof PBPortalEnhancements === 'object' && PBPortalEnhancements && typeof PBPortalEnhancements.onAuthStateUpdated === 'function') {
              PBPortalEnhancements.onAuthStateUpdated(bootstrapData.session.user, 'RESTORED');
            }
          } else {
            var restoreOutcome =
              bootstrapData.sessionRestoreReason === 'NEW_DEVICE_LOGIN'
                ? 'SESSION_SUPERSEDED'
                : hadPersistedToken || bootstrapData.sessionRestoreStatus === 'INVALID_OR_EXPIRED'
                ? 'INVALID_OR_EXPIRED'
                : 'NO_TOKEN';
            var restoreMsg = bootstrapData.sessionRestoreMessage || '';
            clearClientSessionCredential();
            applySessionAndRouteState(null, restoreOutcome, restoreMsg);
          }
        })
        .catch(function (err) {
          if (startupWatchdogTimer) {
            clearTimeout(startupWatchdogTimer);
            startupWatchdogTimer = null;
          }
          console.error('Shell initialization error:', err);
          /* Fall back to interactive Landing Page + banner instead of trapping user if non-fatal */
          syncHeaderNavigation(null);
          showSectionView('landing');
          showUiErrorBanner({
            code: (err && err.code) || 'ERR_BOOTSTRAP_FAILED',
            action: 'public.getBootstrap',
            requestId: (err && err.requestId) || 'bootstrap_err',
            message:
              'Bootstrap warning: ' +
              String((err && err.message) || err || 'Could not reach server.') +
              ' Showing Landing Page so you can still navigate and test.'
          });
        });
    }

    /**
     * Handles Login Modal form submission (`#form-login`).
     */
    var clientLoginFailureCountsByUsername = {};

    function openAccountLockedPopupModal(username, opt_lockoutMessage) {
      var userLbl = document.getElementById('account-locked-username-label');
      if (userLbl) {
        userLbl.textContent = String(username || 'your account');
      }
      var lockModal = document.getElementById('modal-account-locked');
      if (lockModal) {
        lockModal.classList.remove('hidden');
        syncAllModalAccessibilityAndScrollLock();
        var closeBtn = document.getElementById('btn-close-account-locked-modal');
        if (closeBtn && typeof closeBtn.focus === 'function') {
          setTimeout(function () {
            closeBtn.focus();
          }, 20);
        }
      }
      if (typeof PBNotify === 'object' && PBNotify && typeof PBNotify.toast === 'function') {
        PBNotify.toast(
          'danger',
          'Account Locked — Contact Support',
          opt_lockoutMessage ||
            'Too many failed password attempts (> 5). Please contact support (Tel.0966821528 / LINE: poowadatch / pattanabhumi.biology@gmail.com) to unlock your account.'
        );
      }
    }

    function closeAccountLockedPopupModal() {
      var lockModal = document.getElementById('modal-account-locked');
      if (lockModal) {
        lockModal.classList.add('hidden');
        syncAllModalAccessibilityAndScrollLock();
      }
    }

