    function setBtnVectorIcon(btn, iconName, labelText, opt_tooltip) {
      if (!btn) return;
      btn.classList.add('pb-vec-icon-btn');
      if (opt_tooltip) {
        btn.title = String(opt_tooltip);
        btn.setAttribute('aria-label', String(opt_tooltip));
      } else if (labelText) {
        btn.title = String(labelText);
      }
      var svgInner = PB_VECTOR_ICON_PATHS[iconName] || PB_VECTOR_ICON_PATHS.edit;
      var safeLabel = String(labelText || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
      btn.innerHTML =
        '<svg class="pb-icon pb-icon-sm" viewBox="0 0 24 24" aria-hidden="true">' +
        svgInner +
        '</svg>' +
        (safeLabel ? '<span>' + safeLabel + '</span>' : '');
    }

    function setLoginModalSkeletonState(isActive, opt_statusText, opt_badgeText, opt_stageNum) {
      var skelEl = document.getElementById('login-modal-skeleton-screen');
      var formEl = document.getElementById('form-login');
      var statusEl = document.getElementById('login-skeleton-status-text');
      var badgeEl = document.getElementById('login-skeleton-step-badge');
      var orbEl = document.getElementById('login-modal-orb');
      var orbIdle = document.getElementById('login-orb-icon-idle');
      var orbSucc = document.getElementById('login-orb-icon-success');
      var step1 = document.getElementById('login-anim-step-1');
      var step2 = document.getElementById('login-anim-step-2');
      var step3 = document.getElementById('login-anim-step-3');
      var progFill = document.getElementById('login-anim-progress-fill');
      var stage = Number(opt_stageNum) || 1;

      if (skelEl) {
        skelEl.classList.toggle('hidden', !isActive);
      }
      if (formEl) {
        formEl.classList.toggle('is-authenticating', Boolean(isActive));
      }
      if (orbEl) {
        orbEl.classList.toggle('is-authenticating', Boolean(isActive && stage < 3));
        orbEl.classList.toggle('is-login-success', Boolean(isActive && stage >= 3));
      }
      if (orbIdle && orbSucc) {
        var showSuccess = Boolean(isActive && stage >= 3);
        orbIdle.classList.toggle('hidden', showSuccess);
        orbSucc.classList.toggle('hidden', !showSuccess);
      }
      if (step1) {
        step1.classList.toggle('is-active', Boolean(isActive && stage === 1));
        step1.classList.toggle('is-done', Boolean(isActive && stage > 1));
      }
      if (step2) {
        step2.classList.toggle('is-active', Boolean(isActive && stage === 2));
        step2.classList.toggle('is-done', Boolean(isActive && stage > 2));
      }
      if (step3) {
        step3.classList.toggle('is-active', Boolean(isActive && stage === 3));
        step3.classList.toggle('is-done', Boolean(isActive && stage >= 3));
      }
      if (progFill) {
        progFill.style.width = !isActive ? '0%' : stage === 1 ? '38%' : stage === 2 ? '78%' : '100%';
      }
      if (statusEl && opt_statusText) {
        statusEl.textContent = String(opt_statusText);
      }
      if (badgeEl && opt_badgeText) {
        badgeEl.textContent = String(opt_badgeText);
      }
    }

    function handleLoginFormSubmit(evt) {
      if (evt && typeof evt.preventDefault === 'function') {
        evt.preventDefault();
      }
      hideUiErrorBanner();

      var usernameInput = document.getElementById('input-login-username');
      var passwordInput = document.getElementById('input-login-password');
      var rememberInput = document.getElementById('input-login-remember');
      var submitBtn = document.getElementById('btn-login-submit');

      var username = usernameInput ? usernameInput.value.trim() : '';
      var password = passwordInput ? passwordInput.value : '';
      var rememberMe = Boolean(rememberInput && rememberInput.checked);

      PBNotify.clearFieldError('input-login-username');
      PBNotify.clearFieldError('input-login-password');

      if (!username || !password) {
        if (!username) {
          PBNotify.setFieldError(
            'input-login-username',
            'Please enter your assigned username.'
          );
        }
        if (!password) {
          PBNotify.setFieldError(
            'input-login-password',
            'Please enter your password.'
          );
        }
        setLoginInlineAlert('hidden');
        if (!username && usernameInput) {
          usernameInput.focus();
        } else if (!password && passwordInput) {
          passwordInput.focus();
        }
        return Promise.resolve();
      }
      setLoginPasswordVisibilityPhase3(false);

      var submitBtnLbl = document.getElementById('label-login-submit-btn');
      if (submitBtn) {
        submitBtn.disabled = true;
        if (submitBtnLbl) {
          submitBtnLbl.textContent = 'Signing in...';
        } else {
          submitBtn.textContent = 'Signing in...';
        }
        submitBtn.setAttribute('aria-busy', 'true');
      }

      setLoginModalSkeletonState(
        true,
        'Verifying your credentials & securing session...',
        'Step 1 of 3',
        1
      );
      setLoginInlineAlert('hidden');

      return rpcCallEnvelope(
        'auth.login',
        {
          username: username,
          password: password,
          rememberMe: rememberMe
        },
        { suppressErrorBanner: true }
      )
        .then(function (envelope) {
          if (username) {
            clientLoginFailureCountsByUsername[username.toLowerCase()] = 0;
          }
          if (passwordInput) {
            passwordInput.value = '';
          }
          setLoginModalSkeletonState(
            true,
            'Credentials verified! Unlocking your workspace...',
            'Step 2 of 3',
            2
          );
          setLoginInlineAlert('hidden');

          var loginData = envelope.data || {};
          var issuedToken =
            loginData.sessionToken || loginData.authToken || '';
          var storageOutcome = storeSessionCredential(
            issuedToken,
            Boolean(loginData.rememberMe)
          );

          var sessionSummary = {
            sessionId: loginData.sessionId,
            expiresAtUtc: loginData.expiresAtUtc,
            expiresAtBangkok: loginData.expiresAtBangkok,
            rememberMe: loginData.rememberMe,
            user: loginData.user
          };

          return new Promise(function (resolve) {
            setTimeout(function () {
              setLoginModalSkeletonState(
                true,
                'Welcome back! Entering learning portal...',
                'Verified',
                3
              );
              setTimeout(function () {
                if (typeof closeModalDialog === 'function') {
                  closeModalDialog('modal-login');
                }
                resetAllPortalSessionState('FRESH_LOGIN_SWITCH');
                var roleTitle =
                  loginData.user && String(loginData.user.role || '').toUpperCase() === 'ADMIN'
                    ? 'Administrator'
                    : 'Student';
                showTransitionLoadingView(
                  'Verifying Account & Loading Portal…',
                  'Initializing your authorized ' + roleTitle + ' workspace…'
                );
                setTimeout(function () {
                  applySessionAndRouteState(sessionSummary, 'FRESH_LOGIN');
                  if (typeof PBPortalEnhancements === 'object' && PBPortalEnhancements && typeof PBPortalEnhancements.onAuthStateUpdated === 'function') {
                    PBPortalEnhancements.onAuthStateUpdated(loginData.user, 'FRESH_LOGIN');
                  }
                  renderDiagnosticResult(
                    'PASS: Login succeeded for ' +
                      loginData.user.username +
                      ' (' +
                      loginData.user.role +
                      ') | Requires Privacy Ack: ' +
                      String(Boolean(loginData.user.requiresPrivacyAck)),
                    {
                      sessionId: loginData.sessionId,
                      expiresAtBangkok: loginData.expiresAtBangkok,
                      storageMode: currentStorageMode,
                      persistedToLocalStorage: storageOutcome.persistedToLocalStorage,
                      user: loginData.user
                    }
                  );
                  resolve();
                }, 160);
              }, 160);
            }, 120);
          });
        })
        .catch(function (err) {
          var dlg = document.querySelector('#modal-login .pb-login-modal-dialog');
          if (dlg) {
            dlg.classList.remove('is-login-error-shake');
            void dlg.offsetWidth;
            dlg.classList.add('is-login-error-shake');
            setTimeout(function () {
              dlg.classList.remove('is-login-error-shake');
            }, 520);
          }
          var code = err && err.code ? String(err.code) : 'ERR_LOGIN_FAILED';
          var msg =
            err && err.message
              ? String(err.message)
              : 'Sign-in could not be completed.';
          var usrKey = String(username || 'account').toLowerCase();
          if (code === 'ERR_INVALID_CREDENTIALS') {
            clientLoginFailureCountsByUsername[usrKey] =
              Number(clientLoginFailureCountsByUsername[usrKey] || 0) + 1;
          }
          var serverFailCount =
            err && err.fieldErrors && err.fieldErrors.failureCount
              ? Number(err.fieldErrors.failureCount)
              : Number(clientLoginFailureCountsByUsername[usrKey] || 0);
          var isLockedOut =
            code === 'ERR_RATE_LIMITED' ||
            code === 'ERR_ACCOUNT_SUSPENDED' ||
            Boolean(err && err.fieldErrors && err.fieldErrors.accountLocked === 'true') ||
            serverFailCount > 5;

          if (code === 'ERR_ACCOUNT_INTEGRITY_LOCKED') {
            setLoginInlineAlert(
              'danger',
              'Account temporarily locked',
              'Your account has been locked after repeated examination invalidations. Please contact Pattanabhumi Biology for review.'
            );
            if (typeof openAccountIntegrityLockedModalPhaseC === 'function') {
              openAccountIntegrityLockedModalPhaseC({
                username: username,
                password: password,
                fieldErrors: (err && err.fieldErrors) || {}
              });
            }
          } else if (isLockedOut) {
            var lockMsg =
              'Your account has been locked because an incorrect password was entered more than 5 times. Please contact Pattanabhumi Biology support (Phone: Tel.0966821528 | LINE ID: poowadatch | Email: pattanabhumi.biology@gmail.com) to unlock your account.';
            setLoginInlineAlert('danger', 'Account Locked — Contact Support', lockMsg);
            openAccountLockedPopupModal(username, lockMsg);
          } else {
            var remAttempts = Math.max(0, 5 - serverFailCount);
            var extraNote =
              code === 'ERR_INVALID_CREDENTIALS' && serverFailCount > 0
                ? ' (Attempt ' +
                  String(serverFailCount) +
                  ' of 5 — ' +
                  String(remAttempts) +
                  ' attempt(s) remaining before account lockout.)'
                : '';
            setLoginInlineAlert('danger', 'Sign-In Failed', msg + extraNote);
          }
          renderDiagnosticResult('Login rejected (' + code + ')', err);
        })
        .then(function () {
          setLoginModalSkeletonState(false);
          if (submitBtn) {
            submitBtn.disabled = false;
            if (submitBtnLbl) {
              submitBtnLbl.textContent = 'Sign In to Portal';
            } else {
              submitBtn.textContent = 'Sign In to Portal';
            }
            submitBtn.removeAttribute('aria-busy');
          }
        });
    }

    /**
     * Handles Privacy Notice Gate form submission (`#form-privacy-gate`).
     */
    function handlePrivacyGateSubmit(evt) {
      if (evt && typeof evt.preventDefault === 'function') {
        evt.preventDefault();
      }
      hideUiErrorBanner();

      var ackCheckbox = document.getElementById('input-privacy-ack-required');
      var mktCheckbox = document.getElementById(
        'input-privacy-marketing-optin'
      );
      var submitBtn = document.getElementById('btn-privacy-ack-submit');

      var isAcked = Boolean(ackCheckbox && ackCheckbox.checked);
      var marketingOptIn = Boolean(mktCheckbox && mktCheckbox.checked);

      if (!isAcked) {
        setPrivacyGateInlineAlert(
          'danger',
          'Privacy Notice Acknowledgment Required',
          'Please check the required box confirming that you have read and acknowledge the Privacy Notice. (The marketing email checkbox is optional and does not need to be checked.)'
        );
        if (ackCheckbox) {
          ackCheckbox.focus();
        }
        return Promise.resolve();
      }

      var noticeVersion =
        (currentSessionMeta &&
          currentSessionMeta.user &&
          currentSessionMeta.user.requiredPrivacyNoticeVersion) ||
        (currentBootstrapData && currentBootstrapData.privacyNoticeVersion) ||
        '2026-10-v1';

      if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.textContent = 'Recording Acknowledgment...';
        submitBtn.setAttribute('aria-busy', 'true');
      }

      setPrivacyGateInlineAlert(
        'warning',
        'Saving Privacy Choice...',
        'Recording Privacy Notice version "' +
          noticeVersion +
          '" and server timestamp in PrivacyChoices...'
      );

      return rpcCallEnvelope(
        'privacy.acknowledge',
        {
          noticeVersion: noticeVersion,
          acknowledged: true,
          marketingOptIn: marketingOptIn
        },
        { suppressErrorBanner: true }
      )
        .then(function (envelope) {
          var resData = envelope.data;
          setPrivacyGateInlineAlert('hidden');

          if (currentSessionMeta && resData.user) {
            currentSessionMeta.user = resData.user;
          }

          applySessionAndRouteState(currentSessionMeta, 'PRIVACY_ACKNOWLEDGED');
          if (typeof PBPortalEnhancements === 'object' && PBPortalEnhancements && typeof PBPortalEnhancements.onAuthStateUpdated === 'function') {
            PBPortalEnhancements.onAuthStateUpdated(currentSessionMeta && currentSessionMeta.user, 'PRIVACY_ACKNOWLEDGED');
          }

          renderDiagnosticResult(
            'PASS: Privacy Notice (' +
              resData.noticeVersion +
              ') acknowledged [' +
              resData.actionSource +
              '] | Marketing Opt-In: ' +
              String(resData.marketingOptIn),
            resData
          );
        })
        .catch(function (err) {
          var code = err && err.code ? String(err.code) : 'ERR_PRIVACY_FAILED';
          var msg =
            err && err.message
              ? String(err.message)
              : 'Could not save privacy acknowledgment.';
          setPrivacyGateInlineAlert('danger', 'Error (' + code + ')', msg);
        })
        .then(function () {
          if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = 'Acknowledge & Continue to Portal';
            submitBtn.removeAttribute('aria-busy');
          }
        });
    }

    /**
     * Handles saving the optional Marketing Email preference from My Profile (`#btn-save-marketing-pref`).
     */
    function handleSaveProfileMarketingPref() {
      hideUiErrorBanner();
      var mktCheckbox = document.getElementById('input-profile-marketing-optin');
      var marketingOptIn = Boolean(mktCheckbox && mktCheckbox.checked);
      setText('profile-marketing-status', 'Saving preference to server...');

      return rpcCallEnvelope('privacy.updateMarketing', {
        marketingOptIn: marketingOptIn
      })
        .then(function (envelope) {
          var resData = envelope.data;
          if (currentSessionMeta && resData.user) {
            currentSessionMeta.user = resData.user;
            populateProfileView(currentSessionMeta);
          }
          setText(
            'profile-marketing-status',
            'Saved (' +
              (resData.marketingOptIn ? 'Opted In' : 'Opted Out') +
              ') at ' +
              (resData.recordedAtBangkok || resData.recordedAtUtc)
          );
          renderDiagnosticResult(
            'PASS: Marketing email preference updated (' +
              String(resData.marketingOptIn) +
              ')',
            resData
          );
        })
        .catch(function (err) {
          setText(
            'profile-marketing-status',
            'Failed to save: ' + String(err.message || err.code)
          );
        });
    }

    /**
     * Handles Logout button click: revokes the server session record in `Sessions`,
     * clears local credentials, closes any open modal, and returns to the Landing Page (`#view-landing`).
     */
    var isLogoutInProgress = false;

    function setLogoutSpinnerState(isActive, opt_stage) {
      var overlayEl = document.getElementById('pb-logout-loading-overlay');
      var cardEl = document.getElementById('pb-logout-loading-card');
      var chipEl = document.getElementById('pb-logout-step-chip');
      var textEl = document.getElementById('pb-logout-loading-text');
      var subEl = document.getElementById('pb-logout-loading-subtitle');
      var progEl = document.getElementById('pb-logout-progress-fill');
      var lockIcon = document.getElementById('pb-logout-icon-lock');
      var checkIcon = document.getElementById('pb-logout-icon-check');
      var isComplete = opt_stage === 'COMPLETE';

      if (cardEl) {
        cardEl.classList.toggle('is-logout-complete', isComplete);
      }
      if (chipEl) {
        chipEl.textContent = isComplete ? 'Session Cleared' : 'Securing Account';
      }
      if (textEl) {
        textEl.textContent = isComplete ? 'Signed Out Safely' : 'Signing Out Safely...';
      }
      if (subEl) {
        subEl.textContent = isComplete
          ? 'Your session token has been revoked. Returning to home page...'
          : 'Revoking active session token and locking your workspace...';
      }
      if (progEl) {
        progEl.style.width = !isActive ? '0%' : isComplete ? '100%' : '68%';
      }
      if (lockIcon && checkIcon) {
        lockIcon.classList.toggle('hidden', isComplete);
        checkIcon.classList.toggle('hidden', !isComplete);
      }
      if (overlayEl) {
        overlayEl.classList.toggle('hidden', !isActive);
        overlayEl.setAttribute('aria-hidden', isActive ? 'false' : 'true');
      }
      var logoutBtnIds = [
        { id: 'btn-header-logout', defaultLabel: 'Log out' },
        { id: 'btn-mobile-logout', defaultLabel: 'Log out' },
        { id: 'btn-privacy-decline-logout', defaultLabel: 'Decline & Log Out' }
      ];
      for (var i = 0; i < logoutBtnIds.length; i++) {
        var btn = document.getElementById(logoutBtnIds[i].id);
        if (btn) {
          btn.disabled = Boolean(isActive);
          var lblSpan = btn.querySelector('.pb-logout-btn-label');
          if (isActive) {
            btn.setAttribute('aria-busy', 'true');
            btn.classList.add('is-logging-out');
            if (lblSpan) {
              lblSpan.textContent = 'Signing out...';
            } else {
              btn.textContent = 'Logging out...';
            }
          } else {
            btn.removeAttribute('aria-busy');
            btn.classList.remove('is-logging-out');
            if (lblSpan) {
              lblSpan.textContent = logoutBtnIds[i].defaultLabel;
            } else {
              btn.textContent = logoutBtnIds[i].defaultLabel;
            }
          }
        }
      }
    }

    function handleLogoutClick() {
      isLogoutInProgress = true;
      hideUiErrorBanner();
      setAdminScoresAlertPhase6('hidden');
      if (typeof PBNotify === 'object' && PBNotify && typeof PBNotify.clearAllToasts === 'function') {
        PBNotify.clearAllToasts();
      }
      resetAllPortalSessionState('LOGOUT_START');
      setLogoutSpinnerState(true, 'REVOKING');
      showTransitionLoadingView(
        'Signing Out…',
        'Revoking your session and clearing local workspace data…'
      );

      return rpcCallEnvelope(
        'auth.logout',
        {},
        { keepSessionOnAuthError: true, suppressErrorBanner: true }
      )
        .then(function (envelope) {
          setLogoutSpinnerState(true, 'COMPLETE');
          return new Promise(function (resolve) {
            setTimeout(function () {
              setLogoutSpinnerState(false);
              clearClientSessionCredential();
              applySessionAndRouteState(null, 'LOGGED_OUT');
              if (typeof PBPortalEnhancements === 'object' && PBPortalEnhancements && typeof PBPortalEnhancements.onAuthStateUpdated === 'function') {
                PBPortalEnhancements.onAuthStateUpdated(null, 'LOGGED_OUT');
              }
              if (typeof PBNotify === 'object' && PBNotify && typeof PBNotify.clearAllToasts === 'function') {
                PBNotify.clearAllToasts();
              }
              isLogoutInProgress = false;
              renderDiagnosticResult(
                'PASS: Logout succeeded - backend session revoked and returned to Landing Page',
                envelope
              );
              resolve();
            }, 300);
          });
        })
        .catch(function (err) {
          setLogoutSpinnerState(false);
          clearClientSessionCredential();
          applySessionAndRouteState(null, 'LOGGED_OUT');
          if (typeof PBPortalEnhancements === 'object' && PBPortalEnhancements && typeof PBPortalEnhancements.onAuthStateUpdated === 'function') {
            PBPortalEnhancements.onAuthStateUpdated(null, 'LOGGED_OUT');
          }
          if (typeof PBNotify === 'object' && PBNotify && typeof PBNotify.clearAllToasts === 'function') {
            PBNotify.clearAllToasts();
          }
          isLogoutInProgress = false;
          showUiErrorBanner({
            code: err.code || 'ERR_LOGOUT_SERVER_WARNING',
            action: 'auth.logout',
            requestId: err.requestId || 'N/A',
            message:
              'Your local browser session was cleared and you have been returned to the Landing Page, but the server revocation call returned: ' +
              String(err.message || err.code)
          });
        });
    }

    /**
     * Handles Navigation view switching (`landing`, `profile`, `payments`, `calendar`, `admin`, `contact`).
     * Enforces client-side role and privacy-gate checks in addition to mandatory backend guards.
     */
    function handleNavigateToView(targetView) {
      if (!confirmDiscardUnsavedChangesIfNeeded('navigating to "' + targetView + '"')) {
        return;
      }
      hideUiErrorBanner();

      if (targetView === 'contact') {
        showSectionView('contact');
        return;
      }

      if (!currentSessionMeta || !currentSessionMeta.user) {
        if (targetView === 'landing') {
          showSectionView('landing');
        } else {
          if (typeof PBPortalRouter === 'object' && PBPortalRouter) {
            PBPortalRouter.setPendingHash(targetView);
          }
          openModalDialog('modal-login', 'input-login-username');
          setLoginInlineAlert(
            'warning',
            'Authentication Required',
            'Please log in to access "' + targetView + '".'
          );
        }
        return;
      }

      var usr = currentSessionMeta.user;
      if (usr.requiresPrivacyAck) {
        openPrivacyNoticeGateForUser(usr);
        return;
      }

      if (targetView === 'admin-exams') {
        if (usr.role !== 'ADMIN') {
          showUiErrorBanner({
            code: 'ERR_FORBIDDEN_ROLE',
            action: 'ui.navigateAdminExams',
            requestId: 'ui_guard',
            message:
              'Access denied: Exams & Quizzes Studio is restricted to administrator accounts.'
          });
          return;
        }
        showSectionView('admin');
        if (typeof enterAdminExamsStudioMode === 'function') {
          enterAdminExamsStudioMode('builder');
        }
        return;
      }

      if (targetView === 'admin') {
        if (usr.role !== 'ADMIN') {
          showUiErrorBanner({
            code: 'ERR_FORBIDDEN_ROLE',
            action: 'ui.navigateAdmin',
            requestId: 'ui_guard',
            message:
              'Access denied: Admin Dashboard is restricted to administrator accounts.'
          });
          return;
        }
        if (typeof exitAdminExamsStudioMode === 'function') {
          exitAdminExamsStudioMode(true);
        }
        showSectionView('admin');
        refreshAdminDashboardSummary();
        return;
      }

      if (targetView === 'profile') {
        populateProfileView(currentSessionMeta);
        showSectionView('profile');
        return;
      }

      if (targetView === 'payments') {
        showSectionView('payments');
        if (usr.role === 'ADMIN') {
          setPaymentsViewRoleMode(true, false);
          loadAdminInvoicesStep10();
        } else {
          setPaymentsViewRoleMode(false, false);
          loadStudentPaymentSummaryStep11({ autoSwitchStepper: true });
        }
        return;
      }

      if (targetView === 'calendar') {
        showSectionView('calendar');
        loadClassCalendarMonthStep13();
        return;
      }

      /* Default fallback: Admin -> admin, Student -> profile */
      showSectionView(usr.role === 'ADMIN' ? 'admin' : 'profile');
    }

