    /**
     * Binds all navigation, modal focus management, login, privacy gate, profile, admin,
     * contact, and diagnostic event listeners.
     */

    /* ========================================================================
     * STEP 7: STRUCTURED RICH-TEXT ENGINE (pb-richtext-v1), SAFE DOM RENDERER,
     * COURSE / SECTION / CARD / ASSESSMENT CMS & STUDENT COURSE DETAIL VIEW
     * ======================================================================== */

    var hasUnsavedCourseChanges = false;
    var currentAdminCoursesList = [];
    var currentAdminAssessmentsList = [];
    var currentSelectedCourseDetail = null;
    var currentStudentCourseId = '';
    var currentStudentCourseFromAdminPreview = false;

    var richTextEditorsRegistry = {};

    function setCourseEditorDirtyState(isDirty, opt_reasonLabel) {
      hasUnsavedCourseChanges = Boolean(isDirty);
      var badge = document.getElementById('admin-course-dirty-badge');
      if (badge) {
        if (hasUnsavedCourseChanges) {
          badge.className = 'badge badge-incomplete';
          badge.textContent =
            'Unsaved Changes' +
            (opt_reasonLabel ? ' (' + opt_reasonLabel + ')' : ' — Save Before Leaving');
        } else {
          badge.className = 'badge badge-ok';
          badge.textContent = 'Saved (No Unsaved Course/Card Edits)';
        }
      }
    }

    function confirmDiscardUnsavedChangesIfNeeded(actionLabel) {
      if (!hasUnsavedCourseChanges) {
        return true;
      }
      if (window.__PB_TEST_BLOCK_UNSAVED_NAV__ === true) {
        showUiErrorBanner({
          code: 'ERR_UNSAVED_CHANGES_GUARD',
          action: 'ui.unsavedNavigationGuard',
          requestId: 'ui_dirty_guard',
          message:
            'Navigation paused because you have unsaved edits while ' +
            (actionLabel || 'changing views') +
            '. Save your changes or confirm discard.'
        });
        return false;
      }
      if (typeof window.confirm === 'function' && window.__PB_AUTO_CONFIRM_UNSAVED__ === false) {
        var confirmed = window.confirm(
          'You have unsaved changes in the Course / Card / Assessment editor while ' +
            (actionLabel || 'leaving this view') +
            '. Discard unsaved changes and continue?'
        );
        if (confirmed) {
          setCourseEditorDirtyState(false);
        }
        return confirmed;
      }
      setCourseEditorDirtyState(false);
      return true;
    }

    function createDefaultEmptyRichTextDoc() {
      return {
        schemaVersion: 'pb-richtext-v1',
        blocks: [
          {
            type: 'paragraph',
            spans: [{ text: '' }]
          }
        ]
      };
    }

    function extractPlainTextFromRichTextDoc(doc) {
      if (doc === null || doc === undefined) return '';
      if (typeof doc === 'string') {
        var trimmedStr = doc.trim();
        if (trimmedStr.charAt(0) === '{') {
          try {
            var parsedStr = JSON.parse(trimmedStr);
            if (parsedStr && Array.isArray(parsedStr.blocks)) {
              return extractPlainTextFromRichTextDoc(parsedStr);
            }
          } catch (ignoreParseErr) {}
        }
        return doc;
      }
      if (typeof doc !== 'object') return '';
      if (typeof doc.plainText === 'string' && !Array.isArray(doc.blocks)) {
        return doc.plainText;
      }
      var blocks = Array.isArray(doc.blocks) ? doc.blocks : [];
      var lines = [];
      for (var b = 0; b < blocks.length; b++) {
        var blk = blocks[b];
        if (!blk || typeof blk !== 'object') continue;
        if (blk.type === 'bullet_list' || blk.type === 'ordered_list') {
          var items = Array.isArray(blk.items) ? blk.items : [];
          for (var it = 0; it < items.length; it++) {
            var itemSpans = Array.isArray(items[it].spans) ? items[it].spans : [];
            var itemTxt = '';
            for (var s = 0; s < itemSpans.length; s++) {
              itemTxt += itemSpans[s] && itemSpans[s].text ? String(itemSpans[s].text) : '';
            }
            lines.push(itemTxt);
          }
        } else if (blk.type === 'image_attachment' && blk.fileId) {
          lines.push('[Image: ' + (blk.caption || blk.altText || blk.fileId) + ']');
        } else if (blk.type === 'pdf_attachment' && blk.fileId) {
          lines.push('[PDF: ' + (blk.title || blk.fileId) + ']');
        } else if (blk.type === 'table' && Array.isArray(blk.rows)) {
          var tblParts = [];
          if (blk.caption) tblParts.push('[Table: ' + blk.caption + ']');
          if (Array.isArray(blk.headers)) {
            for (var hi = 0; hi < blk.headers.length; hi++) {
              if (blk.headers[hi]) tblParts.push(String(blk.headers[hi]));
            }
          }
          for (var ri = 0; ri < blk.rows.length; ri++) {
            if (Array.isArray(blk.rows[ri])) {
              for (var ci = 0; ci < blk.rows[ri].length; ci++) {
                if (blk.rows[ri][ci]) tblParts.push(String(blk.rows[ri][ci]));
              }
            }
          }
          lines.push(tblParts.length > 0 ? tblParts.join(' ') : '[Table]');
        } else if (Array.isArray(blk.spans)) {
          var pTxt = '';
          for (var ps = 0; ps < blk.spans.length; ps++) {
            pTxt += blk.spans[ps] && blk.spans[ps].text ? String(blk.spans[ps].text) : '';
          }
          lines.push(pTxt);
        }
      }
      return lines.join('\n');
    }

    function stripInternalMediaMarkerTags(rawText) {
      var s = String(rawText || '');
      s = s.replace(/\[(?:Image|PDF|Table):[^\]]*(?:\]|\.{3}|$)/gi, ' ');
      s = s.replace(/\[(?:Image|PDF|Table)\]/gi, ' ');
      return s.replace(/\s+/g, ' ').trim();
    }

    function extractCleanTextFromRichTextDoc(doc) {
      if (doc === null || doc === undefined) return '';
      if (typeof doc === 'string') {
        var trimmed = doc.trim();
        if (trimmed.charAt(0) === '{') {
          try {
            var parsed = JSON.parse(trimmed);
            if (parsed && Array.isArray(parsed.blocks)) {
              return extractCleanTextFromRichTextDoc(parsed);
            }
          } catch (ignoreErr) {}
        }
        return stripInternalMediaMarkerTags(trimmed);
      }
      if (typeof doc !== 'object') return '';
      if (typeof doc.plainText === 'string' && !Array.isArray(doc.blocks)) {
        return stripInternalMediaMarkerTags(doc.plainText);
      }
      var blocks = Array.isArray(doc.blocks) ? doc.blocks : [];
      var lines = [];
      for (var b = 0; b < blocks.length; b++) {
        var blk = blocks[b];
        if (!blk || typeof blk !== 'object') continue;
        if (blk.type === 'bullet_list' || blk.type === 'ordered_list') {
          var items = Array.isArray(blk.items) ? blk.items : [];
          for (var it = 0; it < items.length; it++) {
            var itemSpans = Array.isArray(items[it].spans) ? items[it].spans : [];
            var itemTxt = '';
            for (var s = 0; s < itemSpans.length; s++) {
              itemTxt += itemSpans[s] && itemSpans[s].text ? String(itemSpans[s].text) : '';
            }
            if (itemTxt.trim()) lines.push(itemTxt.trim());
          }
        } else if (Array.isArray(blk.spans)) {
          var pTxt = '';
          for (var ps = 0; ps < blk.spans.length; ps++) {
            pTxt += blk.spans[ps] && blk.spans[ps].text ? String(blk.spans[ps].text) : '';
          }
          if (pTxt.trim()) lines.push(pTxt.trim());
        }
      }
      return lines.join('\n').trim();
    }

    function richTextDocHasAnyContent(doc) {
      if (extractCleanTextFromRichTextDoc(doc).trim().length > 0) return true;
      return extractPlainTextFromRichTextDoc(doc).trim().length > 0;
    }

    function extractMediaSummaryFromQuestion(q, opt_doc) {
      var counts = { images: 0, pdfs: 0, tables: 0 };
      var doc = opt_doc && typeof opt_doc === 'object' ? opt_doc : (q && q.stemRichText);
      if (doc && typeof doc === 'object' && Array.isArray(doc.blocks)) {
        for (var i = 0; i < doc.blocks.length; i++) {
          var b = doc.blocks[i];
          if (!b) continue;
          if (b.type === 'image_attachment' && b.fileId) counts.images++;
          else if (b.type === 'pdf_attachment' && b.fileId) {
            var bt = String(b.title || '').trim();
            if (bt.indexOf('[PB_EXAM_PAPER_PDF]') !== 0 && bt.indexOf('[PB_ANSWER_SHEET_PDF:') !== 0) {
              counts.pdfs++;
            }
          } else if (b.type === 'table') {
            counts.tables++;
          }
        }
      }
      if (q) {
        var extraImgs = Array.isArray(q.imageFileIds)
          ? q.imageFileIds.length
          : (q.imageFileId ? String(q.imageFileId).split(',').filter(Boolean).length : 0);
        if (extraImgs > counts.images) counts.images = extraImgs;
        var rawCombined = String((q.title || '') + ' ' + (q.stemPlainText || ''));
        if (counts.images === 0 && /\[Image:/i.test(rawCombined)) counts.images = 1;
        if (counts.pdfs === 0 && /\[PDF:/i.test(rawCombined)) counts.pdfs = 1;
        if (counts.tables === 0 && /\[Table:/i.test(rawCombined)) counts.tables = 1;
      }
      return counts;
    }

    function buildCleanQuestionTableSummary(q) {
      var rawTitle = stripInternalMediaMarkerTags(q && q.title);
      var rawStem = stripInternalMediaMarkerTags(
        (q && q.stemPlainText) ||
          (q && q.stemRichText ? extractCleanTextFromRichTextDoc(q.stemRichText) : '')
      );
      var cleanTitle = rawTitle || rawStem || 'Diagram / Rich Media Question';
      if (cleanTitle.length > 96) {
        var cut = cleanTitle.slice(0, 96);
        var lastSp = cut.lastIndexOf(' ');
        if (lastSp > 45) cut = cut.slice(0, lastSp);
        cleanTitle = cut.trim() + '…';
      }
      var cleanDesc = '';
      if (rawStem) {
        var normTitle = rawTitle.replace(/[…]+$/, '').trim().toLowerCase();
        var normStem = rawStem.trim().toLowerCase();
        if (!rawTitle) {
          cleanDesc = rawStem.length > 96 ? rawStem : '';
        } else if (normStem !== normTitle && normTitle.indexOf(normStem) !== 0) {
          cleanDesc = normStem.indexOf(normTitle) === 0 && rawStem.length <= cleanTitle.length + 12 ? '' : rawStem;
        }
      }
      var counts = extractMediaSummaryFromQuestion(q);
      var mediaBadges = [];
      if (counts.images > 0) {
        mediaBadges.push({
          icon: 'image',
          label: counts.images > 1 ? counts.images + ' Diagrams' : 'Diagram',
          className: 'pb-table-media-pill'
        });
      }
      if (counts.pdfs > 0) {
        mediaBadges.push({
          icon: 'file-pdf',
          label: counts.pdfs > 1 ? counts.pdfs + ' PDFs' : 'PDF',
          className: 'pb-table-media-pill'
        });
      }
      if (counts.tables > 0) {
        mediaBadges.push({
          icon: 'table',
          label: counts.tables > 1 ? counts.tables + ' Tables' : 'Table',
          className: 'pb-table-media-pill'
        });
      }
      return {
        title: cleanTitle,
        description: cleanDesc,
        mediaBadges: mediaBadges
      };
    }

    function plainTextToRichTextDocSafe(rawText) {
      var str = rawText === null || rawText === undefined ? '' : String(rawText);
      var rawLines = str.replace(/\r\n/g, '\n').split('\n');
      var blocks = [];
      for (var i = 0; i < rawLines.length; i++) {
        blocks.push({
          type: 'paragraph',
          spans: [{ text: rawLines[i] }]
        });
      }
      if (blocks.length === 0) {
        return createDefaultEmptyRichTextDoc();
      }
      return {
        schemaVersion: 'pb-richtext-v1',
        blocks: blocks
      };
    }

    function cloneRichTextDocSafe(doc) {
      if (typeof doc === 'string') {
        var s = doc.trim();
        if (s.charAt(0) === '{') {
          try {
            var jsonParsed = JSON.parse(s);
            if (jsonParsed && jsonParsed.schemaVersion === 'pb-richtext-v1' && Array.isArray(jsonParsed.blocks) && jsonParsed.blocks.length > 0) {
              return jsonParsed;
            }
          } catch (ignoreJsonStrErr) {}
        }
        return plainTextToRichTextDocSafe(doc);
      }
      if (!doc || typeof doc !== 'object' || !Array.isArray(doc.blocks)) {
        return createDefaultEmptyRichTextDoc();
      }
      try {
        var parsed = JSON.parse(JSON.stringify(doc));
        if (parsed.schemaVersion !== 'pb-richtext-v1' || !Array.isArray(parsed.blocks) || parsed.blocks.length === 0) {
          return createDefaultEmptyRichTextDoc();
        }
        return parsed;
      } catch (e) {
        return createDefaultEmptyRichTextDoc();
      }
    }

    function isSafeRichTextHref(rawUrl) {
      if (!rawUrl || typeof rawUrl !== 'string') {
        return false;
      }
      var trimmed = rawUrl.trim();
      if (/^https:\/\/[A-Za-z0-9.-]+(?::\d+)?(?:\/[^\s]*)?$/i.test(trimmed)) {
        return true;
      }
      if (/^mailto:[^\s@]+@[^\s@]+\.[^\s@]+$/i.test(trimmed)) {
        return true;
      }
      return false;
    }

    /**
     * Renders a validated `pb-richtext-v1` document into `containerEl` using ONLY
     * `document.createElement` and `textContent` (zero `innerHTML` injection).
     */

    /* ========================================================================
     * STEP 8: PBObjectUrlManager — Temporary Blob / Object URL Lifecycle Manager
     * - Converts authorized Base64 file payloads from file.getContent into
     *   temporary in-memory Blob object URLs (URL.createObjectURL).
     * - Automatically tracks and revokes object URLs (URL.revokeObjectURL) on
     *   view navigation, modal close, course switch, and logout.
     * - Provides a graceful fallback when Blob or URL.createObjectURL is
     *   restricted by an embedded webview or test harness.
     * - Strictly prevents blob: or data: URLs from ever being persisted as
     *   database references.
     * ======================================================================== */
    var PBObjectUrlManager = (function () {
      var managedEntries = {};
      var inFlightFilePromises = {};
      var simulateBlobBlocked = false;
      var totalCreatedCount = 0;
      var totalRevokedCount = 0;
      var IDB_NAME = 'ppb_portal_blob_cache_v1';
      var IDB_STORE = 'files';
      var idbPromise = null;

      function getCurrentUserCacheScope() {
        var uid =
          currentSessionMeta && currentSessionMeta.user
            ? currentSessionMeta.user.userId || currentSessionMeta.user.user_id || ''
            : '';
        return uid || 'anon';
      }

      function openBlobCacheDb() {
        if (simulateBlobBlocked || typeof window.indexedDB === 'undefined') {
          return Promise.resolve(null);
        }
        if (idbPromise) return idbPromise;
        idbPromise = new Promise(function (resolve) {
          try {
            var req = window.indexedDB.open(IDB_NAME, 1);
            req.onupgradeneeded = function (evt) {
              var db = evt.target.result;
              if (db && !db.objectStoreNames.contains(IDB_STORE)) {
                db.createObjectStore(IDB_STORE, { keyPath: 'storageKey' });
              }
            };
            req.onsuccess = function () {
              resolve(req.result || null);
            };
            req.onerror = function () {
              resolve(null);
            };
            req.onblocked = function () {
              resolve(null);
            };
          } catch (ignoreDbErr) {
            resolve(null);
          }
        });
        return idbPromise;
      }

      function idbGetCachedEntry(storageKey) {
        return openBlobCacheDb().then(function (db) {
          if (!db) return null;
          return new Promise(function (resolve) {
            try {
              var tx = db.transaction(IDB_STORE, 'readonly');
              var req = tx.objectStore(IDB_STORE).get(storageKey);
              req.onsuccess = function () {
                resolve(req.result || null);
              };
              req.onerror = function () {
                resolve(null);
              };
            } catch (e) {
              resolve(null);
            }
          });
        });
      }

      function idbPutCachedBlob(storageKey, blob, mimeType, originalFilename, sizeBytes) {
        if (!blob || blob.size > 15 * 1024 * 1024) return;
        openBlobCacheDb().then(function (db) {
          if (!db) return;
          try {
            var tx = db.transaction(IDB_STORE, 'readwrite');
            tx.objectStore(IDB_STORE).put({
              storageKey: storageKey,
              blob: blob,
              mimeType: mimeType,
              originalFilename: originalFilename,
              sizeBytes: sizeBytes,
              cachedAt: Date.now()
            });
          } catch (ignorePutErr) {}
        });
      }

      function clearPersistentCache() {
        openBlobCacheDb().then(function (db) {
          if (!db) return;
          try {
            var tx = db.transaction(IDB_STORE, 'readwrite');
            tx.objectStore(IDB_STORE).clear();
          } catch (ignoreClearErr) {}
        });
      }

      function decodeBase64ToUint8Array(base64Str) {
        var cleaned = String(base64Str || '').trim();
        if (!cleaned || cleaned.indexOf('__PB_DIRECT_BLOB__:') === 0) {
          return new Uint8Array(0);
        }
        var commaIdx = cleaned.indexOf(',');
        if (cleaned.slice(0, 5).toLowerCase() === 'data:' && commaIdx !== -1) {
          cleaned = cleaned.slice(commaIdx + 1).trim();
        }
        cleaned = cleaned.replace(/\s+/g, '');
        var binaryStr = window.atob(cleaned);
        var len = binaryStr.length;
        var bytes = new Uint8Array(len);
        for (var i = 0; i < len; i++) {
          bytes[i] = binaryStr.charCodeAt(i);
        }
        return bytes;
      }

      function revokeByKey(cacheKey) {
        var key = String(cacheKey || '');
        if (!key || !managedEntries[key]) {
          return false;
        }
        var entry = managedEntries[key];
        delete managedEntries[key];
        if (
          entry &&
          entry.objectUrl &&
          !entry.isFallbackDataUri &&
          !entry.isDirectDriveUrl &&
          /^blob:/i.test(String(entry.objectUrl)) &&
          window.URL &&
          typeof window.URL.revokeObjectURL === 'function'
        ) {
          try {
            window.URL.revokeObjectURL(entry.objectUrl);
            totalRevokedCount++;
          } catch (ignoreRevokeErr) {}
        }
        return true;
      }

      function revokeAll(reason) {
        if (typeof closeInAppPdfViewerModal === 'function') {
          var activePdfModal = document.getElementById('modal-pb-pdf-viewer');
          if (activePdfModal && !activePdfModal.classList.contains('hidden')) {
            closeInAppPdfViewerModal();
          }
        }
        var keys = Object.keys(managedEntries);
        var count = 0;
        for (var i = 0; i < keys.length; i++) {
          if (revokeByKey(keys[i])) {
            count++;
          }
        }
        return {
          revokedCount: count,
          reason: reason || 'MANUAL_OR_NAVIGATION',
          activeRemaining: Object.keys(managedEntries).length,
          totalCreatedCount: totalCreatedCount,
          totalRevokedCount: totalRevokedCount
        };
      }

      function createFromBase64(dataBase64, mimeType, opt_cacheKey, opt_filename) {
        var safeMime = String(mimeType || 'application/octet-stream').trim();
        var key = String(
          opt_cacheKey || 'tmp_' + String(new Date().getTime()) + '_' + String(totalCreatedCount + 1)
        );

        if (managedEntries[key]) {
          revokeByKey(key);
        }

        var bytes = decodeBase64ToUint8Array(dataBase64);
        var canUseBlobUrl =
          !simulateBlobBlocked &&
          typeof window.Blob === 'function' &&
          typeof window.URL !== 'undefined' &&
          window.URL &&
          typeof window.URL.createObjectURL === 'function';

        if (canUseBlobUrl) {
          try {
            var blob = new Blob([bytes], { type: safeMime });
            var objUrl = window.URL.createObjectURL(blob);
            totalCreatedCount++;
            managedEntries[key] = {
              cacheKey: key,
              objectUrl: objUrl,
              mimeType: safeMime,
              sizeBytes: bytes.length,
              originalFilename: opt_filename || 'attachment',
              isFallbackDataUri: false,
              mechanism: 'BLOB_OBJECT_URL'
            };
            return managedEntries[key];
          } catch (blobErr) {
            /* Fall through to fallback when browser blocks Blob/createObjectURL */
          }
        }

        /* Graceful fallback when Blob or URL.createObjectURL is unavailable/blocked */
        var cleanB64 = String(dataBase64 || '').replace(/\s+/g, '');
        var fallbackUri = 'data:' + safeMime + ';base64,' + cleanB64;
        managedEntries[key] = {
          cacheKey: key,
          objectUrl: fallbackUri,
          mimeType: safeMime,
          sizeBytes: bytes.length,
          originalFilename: opt_filename || 'attachment',
          isFallbackDataUri: true,
          mechanism: 'DATA_URI_FALLBACK_BLOB_BLOCKED'
        };
        return managedEntries[key];
      }

      function createFromBlob(blob, mimeType, opt_cacheKey, opt_filename, opt_sizeBytes) {
        var safeMime = String(mimeType || (blob && blob.type) || 'application/octet-stream').trim();
        var key = String(
          opt_cacheKey || 'tmp_' + String(new Date().getTime()) + '_' + String(totalCreatedCount + 1)
        );
        if (managedEntries[key]) {
          revokeByKey(key);
        }
        var objUrl = window.URL.createObjectURL(blob);
        totalCreatedCount++;
        managedEntries[key] = {
          cacheKey: key,
          objectUrl: objUrl,
          mimeType: safeMime,
          sizeBytes: Number(opt_sizeBytes || (blob && blob.size) || 0),
          originalFilename: opt_filename || 'attachment',
          isFallbackDataUri: false,
          mechanism: 'INDEXEDDB_BLOB_OBJECT_URL'
        };
        return managedEntries[key];
      }

      function fetchAndCreateObjectUrl(fileId, opt_courseId, opt_fetchOptions) {
        var cleanFileId = String(fileId || '').trim();
        if (!/^fil_[a-z0-9_-]{4,64}$/i.test(cleanFileId)) {
          return Promise.reject({
            code: 'ERR_FORBIDDEN_RESOURCE',
            message:
              'Only application file IDs (fil_...) can be loaded through PBObjectUrlManager.'
          });
        }
        var courseId = String(opt_courseId || '').trim();
        var cacheKey = cleanFileId + (courseId ? ':' + courseId : '');
        var idbKey = getCurrentUserCacheScope() + '|' + cacheKey;
        var fOpts = opt_fetchOptions && typeof opt_fetchOptions === 'object' ? opt_fetchOptions : {};

        if (managedEntries[cacheKey]) {
          return Promise.resolve(managedEntries[cacheKey]);
        }
        if (inFlightFilePromises[cacheKey]) {
          return inFlightFilePromises[cacheKey];
        }

        var promise = idbGetCachedEntry(idbKey)
          .then(function (idbRec) {
            if (
              idbRec &&
              idbRec.blob &&
              !simulateBlobBlocked &&
              typeof window.URL !== 'undefined' &&
              window.URL &&
              typeof window.URL.createObjectURL === 'function'
            ) {
              try {
                return createFromBlob(
                  idbRec.blob,
                  idbRec.mimeType,
                  cacheKey,
                  idbRec.originalFilename,
                  idbRec.sizeBytes
                );
              } catch (ignoreRestoreErr) {}
            }
            return rpcCallEnvelope(
              'file.getContent',
              {
                fileId: cleanFileId,
                courseId: courseId
              },
              { suppressErrorBanner: true }
            ).then(function (envelope) {
              var d = envelope.data || {};
              if (!d.dataBase64 && d.driveFileId) {
                var mimeStr = String(d.mimeType || 'application/octet-stream').trim();
                var directImgUrl =
                  d.directImageUrl ||
                  (typeof window.getGoogleDriveImageUrl === 'function'
                    ? window.getGoogleDriveImageUrl(d.driveFileId)
                    : '');
                if (/^image\//i.test(mimeStr) && directImgUrl) {
                  totalCreatedCount++;
                  managedEntries[cacheKey] = {
                    cacheKey: cacheKey,
                    objectUrl: directImgUrl,
                    directImageUrl: directImgUrl,
                    driveFileId: d.driveFileId,
                    mimeType: mimeStr,
                    sizeBytes: Number(d.sizeBytes || 0),
                    originalFilename: d.originalFilename || 'image.png',
                    isFallbackDataUri: false,
                    isDirectDriveUrl: true,
                    idbKey: idbKey,
                    mechanism: 'DRIVE_DIRECT_IMAGE_URL'
                  };
                  return managedEntries[cacheKey];
                }
                if (window.PB_DRIVE && typeof window.PB_DRIVE.downloadDriveFileBlobAuthorized === 'function') {
                  return window.PB_DRIVE.downloadDriveFileBlobAuthorized(d.driveFileId).then(function (dl) {
                    var effMime = mimeStr || dl.mimeType || 'application/octet-stream';
                    var effName = d.originalFilename || 'attachment';
                    var blobEntry = createFromBlob(
                      dl.blob,
                      effMime,
                      cacheKey,
                      effName,
                      dl.sizeBytes || d.sizeBytes || 0
                    );
                    blobEntry.driveFileId = d.driveFileId;
                    idbPutCachedBlob(idbKey, dl.blob, effMime, effName, dl.sizeBytes || (dl.blob && dl.blob.size) || 0);
                    return blobEntry;
                  });
                }
              }
              var created = createFromBase64(
                d.dataBase64,
                d.mimeType,
                cacheKey,
                d.originalFilename
              );
              if (
                !created.isFallbackDataUri &&
                typeof window.Blob === 'function'
              ) {
                try {
                  var bytes = decodeBase64ToUint8Array(d.dataBase64);
                  var blobCopy = new window.Blob([bytes], {
                    type: d.mimeType || 'application/octet-stream'
                  });
                  idbPutCachedBlob(
                    idbKey,
                    blobCopy,
                    d.mimeType || 'application/octet-stream',
                    d.originalFilename || 'attachment',
                    bytes.length
                  );
                } catch (ignorePersistErr) {}
              }
              return created;
            });
          })
          .then(
            function (entry) {
              delete inFlightFilePromises[cacheKey];
              return entry;
            },
            function (err) {
              delete inFlightFilePromises[cacheKey];
              var errMsg = String((err && err.message) || '');
              var isEnrollmentDenied =
                errMsg.indexOf('ACTIVE enrollment') !== -1 ||
                errMsg.indexOf('course is not published') !== -1;
              if (
                !fOpts.skipRevokeCheck &&
                isEnrollmentDenied &&
                err &&
                err.code === 'ERR_FORBIDDEN_RESOURCE' &&
                currentActiveViewName === 'courseDetail' &&
                courseId &&
                courseId === currentStudentCourseId
              ) {
                handleCourseAccessRevokedWhileOpen(err);
              }
              throw err;
            }
          );

        inFlightFilePromises[cacheKey] = promise;
        return promise;
      }

      function prefetchFiles(itemsList) {
        if (!Array.isArray(itemsList) || itemsList.length === 0) return;
        var queue = itemsList.slice(0, 6);
        var idx = 0;
        function pumpNext() {
          if (idx >= queue.length) return;
          var item = queue[idx++];
          if (!item || !item.fileId) {
            pumpNext();
            return;
          }
          fetchAndCreateObjectUrl(item.fileId, item.courseId || '', { skipRevokeCheck: true })
            .catch(function () {})
            .then(function () {
              setTimeout(pumpNext, 120);
            });
        }
        setTimeout(pumpNext, 250);
      }

      /**
       * Seeds in-memory + IndexedDB blob caches immediately after an upload so
       * subsequent preview/open clicks resolve without a duplicate file.getContent RPC.
       */
      function seedCacheFromBase64(fileId, dataBase64, mimeType, originalFilename, opt_courseId, opt_blob) {
        var cleanFileId = String(fileId || '').trim();
        if (!/^fil_[a-z0-9_-]{4,64}$/i.test(cleanFileId) || (!dataBase64 && !opt_blob)) {
          return null;
        }
        var courseId = String(opt_courseId || '').trim();
        var cacheKey = cleanFileId + (courseId ? ':' + courseId : '');
        var idbKey = getCurrentUserCacheScope() + '|' + cacheKey;
        var safeMime = String(mimeType || 'application/pdf').trim();
        var safeName = String(originalFilename || 'document.pdf').trim();
        if (opt_blob && typeof window.Blob === 'function' && opt_blob instanceof window.Blob) {
          var argCreated = createFromBlob(opt_blob, safeMime, cacheKey, safeName, opt_blob.size);
          idbPutCachedBlob(idbKey, opt_blob, safeMime, safeName, opt_blob.size);
          return argCreated;
        }
        if (window.PB_DRIVE && typeof window.PB_DRIVE.peekPendingBlob === 'function') {
          var directBlob = window.PB_DRIVE.peekPendingBlob(dataBase64);
          if (directBlob) {
            var directCreated = createFromBlob(directBlob, safeMime, cacheKey, safeName, directBlob.size);
            idbPutCachedBlob(idbKey, directBlob, safeMime, safeName, directBlob.size);
            return directCreated;
          }
        }
        if (String(dataBase64 || '').trim().indexOf('__PB_DIRECT_BLOB__:') === 0) {
          return null;
        }
        var created = createFromBase64(dataBase64, safeMime, cacheKey, safeName);
        if (!created.isFallbackDataUri && typeof window.Blob === 'function') {
          try {
            var bytes = decodeBase64ToUint8Array(dataBase64);
            var blobCopy = new window.Blob([bytes], { type: safeMime });
            idbPutCachedBlob(idbKey, blobCopy, safeMime, safeName, bytes.length);
          } catch (ignoreSeedPersistErr) {}
        }
        return created;
      }

      function attachDriveImageFallback(imgEl, entry, opt_onErrorFinal) {
        if (!imgEl) return;
        imgEl.referrerPolicy = 'no-referrer';
        var triedAuthorized = false;
        imgEl.onerror = function () {
          if (
            !triedAuthorized &&
            entry &&
            entry.isDirectDriveUrl &&
            entry.driveFileId &&
            window.PB_DRIVE &&
            typeof window.PB_DRIVE.downloadDriveFileBlobAuthorized === 'function'
          ) {
            triedAuthorized = true;
            window.PB_DRIVE.downloadDriveFileBlobAuthorized(entry.driveFileId)
              .then(function (dl) {
                var recovered = createFromBlob(
                  dl.blob,
                  entry.mimeType || dl.mimeType || 'image/png',
                  entry.cacheKey,
                  entry.originalFilename,
                  dl.sizeBytes || (dl.blob && dl.blob.size) || 0
                );
                if (entry.idbKey) {
                  idbPutCachedBlob(entry.idbKey, dl.blob, recovered.mimeType, recovered.originalFilename, recovered.sizeBytes);
                }
                imgEl.src = recovered.objectUrl;
              })
              .catch(function (dlErr) {
                if (typeof opt_onErrorFinal === 'function') opt_onErrorFinal(dlErr);
              });
            return;
          }
          if (typeof opt_onErrorFinal === 'function') opt_onErrorFinal();
        };
      }

      function triggerAuthorizedDownload(fileId, opt_courseId, opt_openInNewTab) {
        return fetchAndCreateObjectUrl(fileId, opt_courseId, { skipRevokeCheck: true }).then(function (entry) {
          if (
            !opt_openInNewTab &&
            entry.isDirectDriveUrl &&
            entry.driveFileId &&
            window.PB_DRIVE &&
            typeof window.PB_DRIVE.downloadDriveFileBlobAuthorized === 'function'
          ) {
            return window.PB_DRIVE.downloadDriveFileBlobAuthorized(entry.driveFileId).then(function (dl) {
              var blobEntry = createFromBlob(
                dl.blob,
                entry.mimeType || dl.mimeType,
                entry.cacheKey,
                entry.originalFilename,
                dl.sizeBytes
              );
              var dlA = document.createElement('a');
              dlA.href = blobEntry.objectUrl;
              dlA.rel = 'noopener noreferrer';
              dlA.download = blobEntry.originalFilename || 'attachment';
              dlA.style.display = 'none';
              document.body.appendChild(dlA);
              dlA.click();
              setTimeout(function () {
                if (dlA.parentNode) dlA.parentNode.removeChild(dlA);
              }, 250);
              return blobEntry;
            });
          }
          if (opt_openInNewTab) {
            var openedWin = null;
            try {
              openedWin = window.open(entry.objectUrl, '_blank', 'noopener,noreferrer');
            } catch (ignorePopErr) {
              openedWin = null;
            }
            if (openedWin) {
              return entry;
            }
            var mimeLower = String(entry.mimeType || '').toLowerCase();
            if (
              (mimeLower === 'application/pdf' || /\.pdf$/i.test(String(entry.originalFilename || ''))) &&
              typeof openInAppPdfViewerModal === 'function'
            ) {
              openInAppPdfViewerModal(entry);
              return entry;
            }
          }
          var a = document.createElement('a');
          a.href = entry.objectUrl;
          a.rel = 'noopener noreferrer';
          if (opt_openInNewTab) {
            a.target = '_blank';
          } else {
            a.download = entry.originalFilename || 'document.pdf';
          }
          a.style.display = 'none';
          document.body.appendChild(a);
          a.click();
          setTimeout(function () {
            if (a.parentNode) {
              a.parentNode.removeChild(a);
            }
          }, 250);
          return entry;
        });
      }

      return Object.freeze({
        createFromBase64: createFromBase64,
        createFromBlob: createFromBlob,
        seedCacheFromBase64: seedCacheFromBase64,
        attachDriveImageFallback: attachDriveImageFallback,
        fetchAndCreateObjectUrl: fetchAndCreateObjectUrl,
        triggerAuthorizedDownload: triggerAuthorizedDownload,
        prefetchFiles: prefetchFiles,
        clearPersistentCache: clearPersistentCache,
        revokeByKey: revokeByKey,
        revokeAll: revokeAll,
        setSimulateBlobBlocked: function (flag) {
          simulateBlobBlocked = Boolean(flag);
        },
        getStats: function () {
          return {
            activeCount: Object.keys(managedEntries).length,
            totalCreatedCount: totalCreatedCount,
            totalRevokedCount: totalRevokedCount,
            simulateBlobBlocked: simulateBlobBlocked
          };
        }
      });
    })();

    /**
     * Reads a browser File object into a Base64 string after enforcing the 2 MB
     * (2,097,152 bytes) application file size limit on the client.
     */
    function readBrowserFileAsBase64Step8(fileObj, opt_anchorIdOrEl) {
      return new Promise(function (resolve, reject) {
        if (!fileObj) {
          reject({
            code: 'ERR_VALIDATION_FAILED',
            message: 'Please select a file to upload first.'
          });
          return;
        }
        var maxBytes = 209715200;
        if (fileObj.size === 0) {
          reject({
            code: 'ERR_FILE_INVALID',
            message: 'Selected file is empty (0 bytes).'
          });
          return;
        }
        if (fileObj.size > maxBytes) {
          reject({
            code: 'ERR_FILE_TOO_LARGE',
            message:
              'Selected file "' +
              fileObj.name +
              '" (' +
              fileObj.size +
              ' bytes) exceeds the 200 MB (209,715,200 bytes) application upload limit.'
          });
          return;
        }
        if (opt_anchorIdOrEl) {
          PBUploadProgress.updateStage1Determinate(opt_anchorIdOrEl, 10, fileObj.name);
        }

        function arrayBufferToBase64Fast(buffer) {
          var bytes = new Uint8Array(buffer);
          var chunkSize = 0x8000;
          var parts = [];
          for (var i = 0; i < bytes.length; i += chunkSize) {
            parts.push(String.fromCharCode.apply(null, bytes.subarray(i, i + chunkSize)));
          }
          return window.btoa(parts.join(''));
        }

        function maybeOptimizeUploadImage(srcFile) {
          var mime = String((srcFile && srcFile.type) || '').toLowerCase();
          var isOptimizableImage =
            (mime === 'image/jpeg' || mime === 'image/png' || mime === 'image/webp') &&
            srcFile.size > 614400 &&
            typeof document !== 'undefined' &&
            typeof window.createImageBitmap === 'function';
          if (!isOptimizableImage) {
            return Promise.resolve(srcFile);
          }
          return window
            .createImageBitmap(srcFile)
            .then(function (bmp) {
              try {
                var maxDim = 1920;
                var w = bmp.width || 0;
                var h = bmp.height || 0;
                if (!w || !h || (w <= maxDim && h <= maxDim && srcFile.size <= 1500000)) {
                  if (typeof bmp.close === 'function') bmp.close();
                  return srcFile;
                }
                var scale = Math.min(1, maxDim / Math.max(w, h));
                var targetW = Math.max(1, Math.round(w * scale));
                var targetH = Math.max(1, Math.round(h * scale));
                var canvas = document.createElement('canvas');
                canvas.width = targetW;
                canvas.height = targetH;
                var ctx = canvas.getContext('2d');
                if (!ctx || typeof canvas.toBlob !== 'function') {
                  if (typeof bmp.close === 'function') bmp.close();
                  return srcFile;
                }
                ctx.drawImage(bmp, 0, 0, targetW, targetH);
                if (typeof bmp.close === 'function') bmp.close();
                var quality = mime === 'image/png' ? undefined : 0.86;
                return new Promise(function (resBlob) {
                  canvas.toBlob(
                    function (outBlob) {
                      if (outBlob && outBlob.type === mime && outBlob.size > 0 && outBlob.size < srcFile.size) {
                        resBlob(outBlob);
                      } else {
                        resBlob(srcFile);
                      }
                    },
                    mime,
                    quality
                  );
                });
              } catch (ignoreOptErr) {
                return srcFile;
              }
            })
            .catch(function () {
              return srcFile;
            });
        }

        if (
          window.PB_API &&
          window.PB_API.mode === 'SUPABASE_DIRECT_DRIVE' &&
          window.PB_DRIVE &&
          typeof window.PB_DRIVE.compressImageWithCanvas === 'function'
        ) {
          window.PB_DRIVE.compressImageWithCanvas(fileObj, { maxWidth: 1280, quality: 0.8 })
            .then(function (prep) {
              if (opt_anchorIdOrEl) {
                PBUploadProgress.updateStage1Determinate(opt_anchorIdOrEl, 100, prep.originalFilename);
                PBUploadProgress.updateStage2Indeterminate(
                  opt_anchorIdOrEl,
                  'Stage 2/2: Uploading "' + (prep.originalFilename || 'file') + '" directly to Google Drive...'
                );
              }
              var previewUrl = '';
              if (typeof window.URL !== 'undefined' && typeof window.URL.createObjectURL === 'function' && prep.blob) {
                try { previewUrl = window.URL.createObjectURL(prep.blob); } catch (ignorePreviewErr) {}
              }
              resolve({
                originalFilename: prep.originalFilename || fileObj.name || 'upload.bin',
                mimeType: prep.mimeType || fileObj.type || 'application/octet-stream',
                sizeBytes: prep.sizeBytes || (prep.blob && prep.blob.size) || fileObj.size,
                dataBase64: window.PB_DRIVE.registerPendingBlob(prep.blob),
                _directFileBlob: prep.blob,
                _alreadyCompressed: true,
                localPreviewUrl: previewUrl
              });
            })
            .catch(function (prepErr) {
              if (opt_anchorIdOrEl) PBUploadProgress.completeAndHide(opt_anchorIdOrEl);
              reject({
                code: 'ERR_FILE_INVALID',
                message: (prepErr && prepErr.message) || 'Failed to prepare/compress file in browser.'
              });
            });
          return;
        }

        maybeOptimizeUploadImage(fileObj).then(function (effectiveBlob) {
          var effectiveMime =
            String(fileObj.type || effectiveBlob.type || '').trim() ||
            (/\.pdf$/i.test(fileObj.name || '') ? 'application/pdf' : '');

          if (typeof effectiveBlob.arrayBuffer === 'function' && typeof window.btoa === 'function') {
            if (opt_anchorIdOrEl) {
              PBUploadProgress.updateStage1Determinate(opt_anchorIdOrEl, 65, fileObj.name);
            }
            effectiveBlob
              .arrayBuffer()
              .then(function (buf) {
                if (opt_anchorIdOrEl) {
                  PBUploadProgress.updateStage1Determinate(opt_anchorIdOrEl, 100, fileObj.name);
                  PBUploadProgress.updateStage2Indeterminate(
                    opt_anchorIdOrEl,
                    'Stage 2/2: Uploading "' +
                      (fileObj.name || 'file') +
                      '" to secure Google Drive storage...'
                  );
                }
                resolve({
                  originalFilename: fileObj.name || 'upload.bin',
                  mimeType: effectiveMime,
                  sizeBytes: effectiveBlob.size || fileObj.size,
                  dataBase64: arrayBufferToBase64Fast(buf)
                });
              })
              .catch(function () {
                reject({
                  code: 'ERR_FILE_INVALID',
                  message: 'Browser could not read the selected file bytes.'
                });
              });
            return;
          }

          var reader = new FileReader();
          reader.onprogress = function (evt) {
            if (evt && evt.lengthComputable && opt_anchorIdOrEl) {
              var pct = Math.round((evt.loaded / evt.total) * 100);
              PBUploadProgress.updateStage1Determinate(opt_anchorIdOrEl, pct, fileObj.name);
            }
          };
          reader.onload = function () {
            if (opt_anchorIdOrEl) {
              PBUploadProgress.updateStage1Determinate(opt_anchorIdOrEl, 100, fileObj.name);
              PBUploadProgress.updateStage2Indeterminate(
                opt_anchorIdOrEl,
                'Stage 2/2: Uploading "' +
                  (fileObj.name || 'file') +
                  '" to secure Google Drive storage and recording...'
              );
            }
            var resStr = String(reader.result || '');
            var commaIdx = resStr.indexOf(',');
            var rawB64 = commaIdx !== -1 ? resStr.slice(commaIdx + 1) : resStr;
            resolve({
              originalFilename: fileObj.name || 'upload.bin',
              mimeType: effectiveMime,
              sizeBytes: effectiveBlob.size || fileObj.size,
              dataBase64: rawB64
            });
          };
          reader.onerror = function () {
            if (opt_anchorIdOrEl) {
              PBUploadProgress.completeAndHide(opt_anchorIdOrEl);
            }
            reject({
              code: 'ERR_FILE_INVALID',
              message: 'Browser FileReader could not read the selected file.'
            });
          };
          reader.readAsDataURL(effectiveBlob);
        });
      });
    }

    function renderPrivateImagePreviewStep8(containerId, fileId, courseId, captionText, opt_options) {
      var box = document.getElementById(containerId);
      if (!box) {
        return;
      }
      while (box.firstChild) {
        box.removeChild(box.firstChild);
      }
      var cleanId = String(fileId || '').trim();
      if (!/^fil_[a-z0-9_-]{4,64}$/i.test(cleanId)) {
        box.classList.add('hidden');
        return;
      }
      box.classList.remove('hidden');

      var opts = opt_options || {};
      var isBanner =
        opts.variant === 'banner' || containerId === 'student-course-cover-banner';

      var stage = document.createElement('div');
      stage.className = 'pb-blur-up-stage is-uploading' + (isBanner ? ' is-banner' : '');

      var statusSpan = document.createElement('div');
      statusSpan.className = 'pb-blur-up-caption';
      statusSpan.textContent = 'Loading image preview...';
      stage.appendChild(statusSpan);
      box.appendChild(stage);

      PBObjectUrlManager.fetchAndCreateObjectUrl(cleanId, courseId || '')
        .then(function (entry) {
          while (stage.firstChild) {
            stage.removeChild(stage.firstChild);
          }
          var img = document.createElement('img');
          img.className = 'pb-blur-up-img';
          img.alt = captionText || 'Authorized Image';
          img.referrerPolicy = 'no-referrer';
          img.onload = function () {
            stage.classList.remove('is-uploading');
            setTimeout(function () {
              img.classList.add('is-sharp');
            }, 30);
          };
          PBObjectUrlManager.attachDriveImageFallback(img, entry);
          img.src = entry.objectUrl;
          setTimeout(function () {
            stage.classList.remove('is-uploading');
            img.classList.add('is-sharp');
          }, 120);
          stage.appendChild(img);

          if (opts.showCaption === true && opts.caption) {
            var meta = document.createElement('div');
            meta.className = 'pb-blur-up-caption';
            meta.textContent = String(opts.caption);
            stage.appendChild(meta);
          }
        })
        .catch(function (err) {
          stage.classList.remove('is-uploading');
          statusSpan.style.color = 'var(--color-danger-text)';
          statusSpan.textContent =
            'Preview unavailable (' + (err.code || 'ERR') + '): ' + (err.message || '');
        });
    }

    var PB_EXAM_PAPER_PDF_MARKER = '[PB_EXAM_PAPER_PDF]';
    var PB_ANSWER_SHEET_PDF_PREFIX = '[PB_ANSWER_SHEET_PDF:';

    function extractExamPdfAttachmentsFromRichText(richTextDoc) {
      var res = {
        examPaperPdf: null,
        answerSheetPdf: null,
        plainText: ''
      };
      if (!richTextDoc) return res;
      if (typeof richTextDoc === 'string') {
        res.plainText = richTextDoc;
        return res;
      }
      var blocks = Array.isArray(richTextDoc.blocks) ? richTextDoc.blocks : [];
      var textParts = [];
      for (var i = 0; i < blocks.length; i++) {
        var b = blocks[i];
        if (!b || typeof b !== 'object') continue;
        if (b.type === 'pdf_attachment' && b.fileId) {
          var t = String(b.title || '').trim();
          if (t.indexOf(PB_EXAM_PAPER_PDF_MARKER) === 0) {
            res.examPaperPdf = {
              fileId: String(b.fileId).trim(),
              filename: t.slice(PB_EXAM_PAPER_PDF_MARKER.length).trim() || 'Exam Paper.pdf'
            };
            continue;
          }
          if (t.indexOf(PB_ANSWER_SHEET_PDF_PREFIX) === 0) {
            var closeIdx = t.indexOf(']');
            var policy = 'AFTER_SUBMIT';
            var fName = 'Answer Sheet.pdf';
            if (closeIdx !== -1) {
              var rawPol = t.slice(PB_ANSWER_SHEET_PDF_PREFIX.length, closeIdx).trim().toUpperCase();
              if (rawPol === 'WITH_KEY' || rawPol === 'AFTER_SUBMIT' || rawPol === 'ALWAYS') {
                policy = rawPol;
              }
              fName = t.slice(closeIdx + 1).trim() || fName;
            }
            res.answerSheetPdf = {
              fileId: String(b.fileId).trim(),
              filename: fName,
              policy: policy
            };
            continue;
          }
        }
        if (Array.isArray(b.spans)) {
          var spanText = b.spans
            .map(function (sp) {
              return sp && sp.text !== undefined && sp.text !== null ? String(sp.text) : '';
            })
            .join('');
          if (spanText.trim()) {
            textParts.push(spanText);
          }
        } else if (typeof b.text === 'string' && b.text.trim()) {
          textParts.push(b.text);
        }
      }
      res.plainText = textParts.join('\n\n');
      return res;
    }

    function stripExamPdfMarkersFromRichText(richTextDoc) {
      if (!richTextDoc || typeof richTextDoc === 'string') {
        return richTextDoc;
      }
      var blocks = Array.isArray(richTextDoc.blocks) ? richTextDoc.blocks : [];
      var filtered = [];
      for (var i = 0; i < blocks.length; i++) {
        var b = blocks[i];
        if (b && b.type === 'pdf_attachment') {
          var t = String(b.title || '').trim();
          if (t.indexOf(PB_EXAM_PAPER_PDF_MARKER) === 0 || t.indexOf(PB_ANSWER_SHEET_PDF_PREFIX) === 0) {
            continue;
          }
        }
        filtered.push(b);
      }
      if (filtered.length === 0) return '';
      return {
        schemaVersion: richTextDoc.schemaVersion || richTextDoc.format || 'pb-richtext-v1',
        blocks: filtered
      };
    }

    function composeExamInstructionsRichTextWithPdfs(plainText, examPaperPdf, answerSheetPdf) {
      var txt = String(plainText || '').trim();
      var blocks = [];
      if (txt) {
        var paras = txt.split(/\n{2,}/);
        for (var i = 0; i < paras.length; i++) {
          var seg = paras[i].trim();
          if (seg) {
            blocks.push({ type: 'paragraph', spans: [{ text: seg }] });
          }
        }
      }
      if (examPaperPdf && examPaperPdf.fileId && /^fil_[a-z0-9_-]{4,64}$/i.test(examPaperPdf.fileId)) {
        blocks.push({
          type: 'pdf_attachment',
          fileId: examPaperPdf.fileId,
          title: PB_EXAM_PAPER_PDF_MARKER + ' ' + String(examPaperPdf.filename || 'Exam Paper.pdf').slice(0, 150)
        });
      }
      if (answerSheetPdf && answerSheetPdf.fileId && /^fil_[a-z0-9_-]{4,64}$/i.test(answerSheetPdf.fileId)) {
        var safePol =
          answerSheetPdf.policy === 'WITH_KEY' || answerSheetPdf.policy === 'ALWAYS'
            ? answerSheetPdf.policy
            : 'AFTER_SUBMIT';
        blocks.push({
          type: 'pdf_attachment',
          fileId: answerSheetPdf.fileId,
          title:
            PB_ANSWER_SHEET_PDF_PREFIX +
            safePol +
            '] ' +
            String(answerSheetPdf.filename || 'Answer Sheet.pdf').slice(0, 140)
        });
      }
      if (blocks.length === 0) return '';
      return { schemaVersion: 'pb-richtext-v1', blocks: blocks };
    }

    function canStudentViewExamAnswerSheetPdf(answerSheetPdf, ctx) {
      if (!answerSheetPdf || !answerSheetPdf.fileId) return false;
      var c = ctx || {};
      if (Boolean(c.isAdminPreview) && isCurrentSessionAdminUser()) return true;
      var policy = String(answerSheetPdf.policy || 'AFTER_SUBMIT').toUpperCase();
      if (policy === 'ALWAYS') return true;
      if (policy === 'AFTER_SUBMIT') return Boolean(c.hasSubmittedAttempt);
      if (policy === 'WITH_KEY') return Boolean(c.explanationsReleased);
      return false;
    }

    function closeInAppPdfViewerModal() {
      closeModalDialog('modal-pb-pdf-viewer');
    }

    function openInAppPdfViewerModal(entry, opt_opts) {
      if (!entry || !entry.objectUrl) return;
      var modalEl = document.getElementById('modal-pb-pdf-viewer');
      if (!modalEl) return;
      var allowDownload = !(opt_opts && opt_opts.allowDownload === false);
      if (activeModalId && activeModalId !== 'modal-pb-pdf-viewer') {
        pbPdfViewerReturnModalId = activeModalId;
      }
      var titleEl = document.getElementById('pb-pdf-viewer-title');
      var metaEl = document.getElementById('pb-pdf-viewer-meta');
      var openTabLink = document.getElementById('link-pb-pdf-viewer-open-tab');
      var downloadLink = document.getElementById('link-pb-pdf-viewer-download');
      var iframeEl = document.getElementById('iframe-pb-pdf-viewer');
      var safeFilename = String(entry.originalFilename || 'document.pdf').trim();
      var sizeKb = entry.sizeBytes ? Math.max(1, Math.round(Number(entry.sizeBytes) / 1024)) : 0;

      if (titleEl) {
        titleEl.textContent = safeFilename || 'Document Preview';
      }
      if (metaEl) {
        metaEl.textContent =
          (sizeKb ? String(sizeKb) + ' KB • ' : '') +
          String(entry.mimeType || 'application/pdf') +
          (entry.mechanism ? ' (' + String(entry.mechanism) + ')' : '') +
          (allowDownload ? '' : ' • View Only (Download Disabled)');
      }
      if (openTabLink) {
        openTabLink.classList.toggle('hidden', !allowDownload);
        if (allowDownload) {
          openTabLink.href = entry.objectUrl;
        } else {
          openTabLink.removeAttribute('href');
        }
      }
      if (downloadLink) {
        downloadLink.classList.toggle('hidden', !allowDownload);
        if (allowDownload) {
          downloadLink.href = entry.objectUrl;
          downloadLink.setAttribute('download', safeFilename || 'document.pdf');
        } else {
          downloadLink.removeAttribute('href');
          downloadLink.removeAttribute('download');
        }
      }
      if (iframeEl) {
        iframeEl.src = allowDownload
          ? entry.objectUrl
          : entry.objectUrl + '#toolbar=0&navpanes=0';
      }
      openModalDialog('modal-pb-pdf-viewer', 'btn-pb-pdf-viewer-close');
    }

    var pbImageZoomCurrentPct = 100;

    function applyImageZoomPercent(pctVal) {
      var zoomImg = document.getElementById('img-pb-image-zoom-target');
      var pctLbl = document.getElementById('pb-image-zoom-pct-label');
      if (!zoomImg) return;
      if (pctVal === 'fit') {
        pbImageZoomCurrentPct = 100;
        zoomImg.style.width = 'auto';
        zoomImg.style.maxWidth = '100%';
        zoomImg.style.maxHeight = '66dvh';
        if (pctLbl) pctLbl.textContent = 'Fit';
        return;
      }
      var cleanPct = Math.min(250, Math.max(40, Math.round(Number(pctVal) || 100)));
      pbImageZoomCurrentPct = cleanPct;
      zoomImg.style.maxWidth = 'none';
      zoomImg.style.maxHeight = 'none';
      zoomImg.style.width = cleanPct + '%';
      if (pctLbl) pctLbl.textContent = cleanPct + '%';
    }

    function closeInAppImageZoomModal() {
      closeModalDialog('modal-pb-image-zoom');
    }

    function openInAppImageZoomModal(entryOrFileId, opt_courseId, opt_altOrTitle) {
      var modalEl = document.getElementById('modal-pb-image-zoom');
      if (!modalEl) return;
      if (activeModalId && activeModalId !== 'modal-pb-image-zoom') {
        pbPdfViewerReturnModalId = activeModalId;
      }
      var titleEl = document.getElementById('pb-image-zoom-title');
      var metaEl = document.getElementById('pb-image-zoom-meta');
      var zoomImg = document.getElementById('img-pb-image-zoom-target');
      var dlLink = document.getElementById('link-pb-image-zoom-download');

      function applyEntryToZoomModal(entry) {
        if (!entry || !entry.objectUrl) return;
        var safeTitle = String(
          opt_altOrTitle || entry.originalFilename || 'Question Diagram'
        ).trim();
        var sizeKb = entry.sizeBytes ? Math.max(1, Math.round(Number(entry.sizeBytes) / 1024)) : 0;
        if (titleEl) titleEl.textContent = safeTitle;
        if (metaEl) {
          metaEl.textContent =
            (sizeKb ? String(sizeKb) + ' KB • ' : '') +
            String(entry.mimeType || 'image/png') +
            ' • Use +/- or presets to inspect details';
        }
        if (zoomImg) {
          zoomImg.referrerPolicy = 'no-referrer';
          PBObjectUrlManager.attachDriveImageFallback(zoomImg, entry);
          zoomImg.src = entry.objectUrl;
          zoomImg.alt = safeTitle;
        }
        if (dlLink) {
          dlLink.href = entry.objectUrl;
          dlLink.setAttribute('download', entry.originalFilename || 'diagram.png');
        }
        applyImageZoomPercent('fit');
        openModalDialog('modal-pb-image-zoom', 'btn-pb-image-zoom-close');
      }

      if (entryOrFileId && typeof entryOrFileId === 'object' && entryOrFileId.objectUrl) {
        applyEntryToZoomModal(entryOrFileId);
        return;
      }
      var fid = String(entryOrFileId || '').trim();
      if (!fid) return;
      if (currentQBankLocalImagePreviewDataUrlByIdPhase2 && currentQBankLocalImagePreviewDataUrlByIdPhase2[fid]) {
        applyEntryToZoomModal({
          objectUrl: currentQBankLocalImagePreviewDataUrlByIdPhase2[fid],
          originalFilename: opt_altOrTitle || (fid + '.png'),
          mimeType: 'image/*'
        });
        return;
      }
      PBObjectUrlManager.fetchAndCreateObjectUrl(fid, opt_courseId || '', { skipRevokeCheck: true })
        .then(function (fetched) {
          if (fetched && fetched.objectUrl) {
            currentQBankLocalImagePreviewDataUrlByIdPhase2[fid] = fetched.objectUrl;
            applyEntryToZoomModal(fetched);
          }
        })
        .catch(function (err) {
          if (typeof PBNotify === 'object' && PBNotify) {
            PBNotify.toast('warning', 'Image Preview Notice', (err && err.message) || 'Could not load image.');
          }
        });
    }

    var PBSpreadsheetTableImporter = (function () {
      var MAX_TABLE_ROWS = 40;
      var MAX_TABLE_COLS = 12;

      function readU16LE(view, off) {
        return view.getUint16(off, true);
      }
      function readU32LE(view, off) {
        return view.getUint32(off, true);
      }

      function decodeUtf8Bytes(uint8Arr) {
        if (typeof TextDecoder === 'function') {
          return new TextDecoder('utf-8', { fatal: false }).decode(uint8Arr);
        }
        var out = '';
        for (var i = 0; i < uint8Arr.length; i++) {
          out += String.fromCharCode(uint8Arr[i]);
        }
        try {
          return decodeURIComponent(escape(out));
        } catch (e) {
          return out;
        }
      }

      function unzipEntriesFromBuffer(arrayBuffer) {
        var bytes = new Uint8Array(arrayBuffer);
        var view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
        var eocdOffset = -1;
        var minOffset = Math.max(0, bytes.length - 65558);
        for (var p = bytes.length - 22; p >= minOffset; p--) {
          if (readU32LE(view, p) === 0x06054b50) {
            eocdOffset = p;
            break;
          }
        }
        if (eocdOffset === -1) {
          return Promise.reject(new Error('Invalid .xlsx archive: ZIP End-of-Central-Directory not found.'));
        }
        var cdOffset = readU32LE(view, eocdOffset + 16);
        var cdEntries = readU16LE(view, eocdOffset + 10);
        var entries = {};
        var cursor = cdOffset;
        var tasks = [];

        for (var idx = 0; idx < cdEntries && cursor + 46 <= bytes.length; idx++) {
          if (readU32LE(view, cursor) !== 0x02014b50) break;
          var compMethod = readU16LE(view, cursor + 10);
          var compSize = readU32LE(view, cursor + 20);
          var fnameLen = readU16LE(view, cursor + 28);
          var extraLen = readU16LE(view, cursor + 30);
          var commentLen = readU16LE(view, cursor + 32);
          var localHdrOffset = readU32LE(view, cursor + 42);
          var fname = decodeUtf8Bytes(bytes.subarray(cursor + 46, cursor + 46 + fnameLen)).replace(/^\/+/, '');
          cursor += 46 + fnameLen + extraLen + commentLen;

          if (!fname || /\/$/.test(fname)) continue;
          if (localHdrOffset + 30 > bytes.length || readU32LE(view, localHdrOffset) !== 0x04034b50) {
            continue;
          }
          var lNameLen = readU16LE(view, localHdrOffset + 26);
          var lExtraLen = readU16LE(view, localHdrOffset + 28);
          var dataStart = localHdrOffset + 30 + lNameLen + lExtraLen;
          var sliceEnd = Math.min(bytes.length, dataStart + compSize);
          var rawSlice = bytes.subarray(dataStart, sliceEnd);

          (function (entryName, method, compressedBytes) {
            if (method === 0) {
              entries[entryName] = compressedBytes;
            } else if (method === 8) {
              if (typeof DecompressionStream !== 'function') {
                tasks.push(Promise.reject(new Error('This browser does not support DecompressionStream for compressed .xlsx files. Try .csv or Google Sheets import.')));
                return;
              }
              var stream = new Blob([compressedBytes]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
              tasks.push(
                new Response(stream).arrayBuffer().then(function (decBuf) {
                  entries[entryName] = new Uint8Array(decBuf);
                })
              );
            }
          })(fname, compMethod, rawSlice);
        }

        return Promise.all(tasks).then(function () {
          return entries;
        });
      }

      function colLettersToZeroIndex(refStr) {
        var m = String(refStr || '').match(/^([A-Z]+)/i);
        if (!m) return -1;
        var letters = m[1].toUpperCase();
        var col = 0;
        for (var i = 0; i < letters.length; i++) {
          col = col * 26 + (letters.charCodeAt(i) - 64);
        }
        return col - 1;
      }

      function normalizeGridResult(rawGrid, meta) {
        var useHeader = !(meta && meta.useFirstRowAsHeader === false);
        var caption = String((meta && meta.caption) || '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, 240);
        var cleanGrid = [];
        var maxUsedCols = 0;
        var origRowCount = Array.isArray(rawGrid) ? rawGrid.length : 0;
        var origColCount = 0;

        for (var r = 0; r < rawGrid.length; r++) {
          var rowSrc = Array.isArray(rawGrid[r]) ? rawGrid[r] : [];
          if (rowSrc.length > origColCount) origColCount = rowSrc.length;
          var cleanRow = [];
          var hasVal = false;
          for (var c = 0; c < Math.min(MAX_TABLE_COLS, rowSrc.length); c++) {
            var val = String(rowSrc[c] === null || rowSrc[c] === undefined ? '' : rowSrc[c])
              .replace(/[\r\n\t]+/g, ' ')
              .trim()
              .slice(0, 300);
            cleanRow.push(val);
            if (val) {
              hasVal = true;
              if (c + 1 > maxUsedCols) maxUsedCols = c + 1;
            }
          }
          if (hasVal || r === 0) {
            cleanGrid.push(cleanRow);
          }
        }

        while (cleanGrid.length > 1) {
          var tail = cleanGrid[cleanGrid.length - 1];
          var tailHas = tail.some(function (x) { return Boolean(x); });
          if (!tailHas) cleanGrid.pop();
          else break;
        }
        if (maxUsedCols < 1) maxUsedCols = Math.max(1, Math.min(MAX_TABLE_COLS, origColCount || 1));
        for (var pr = 0; pr < cleanGrid.length; pr++) {
          while (cleanGrid[pr].length < maxUsedCols) cleanGrid[pr].push('');
          if (cleanGrid[pr].length > maxUsedCols) cleanGrid[pr] = cleanGrid[pr].slice(0, maxUsedCols);
        }

        var rowCap = useHeader ? MAX_TABLE_ROWS + 1 : MAX_TABLE_ROWS;
        var truncated = origRowCount > rowCap || origColCount > MAX_TABLE_COLS;
        cleanGrid = cleanGrid.slice(0, rowCap);

        var headers = [];
        var rows = [];
        if (useHeader && cleanGrid.length >= 2) {
          headers = cleanGrid[0].map(function (h) { return String(h || '').slice(0, 200); });
          rows = cleanGrid.slice(1, MAX_TABLE_ROWS + 1);
        } else {
          rows = cleanGrid.slice(0, MAX_TABLE_ROWS);
        }
        if (rows.length === 0) {
          rows = [new Array(maxUsedCols + 1).join(',').split(',').map(function () { return ''; })];
        }

        return {
          caption: caption,
          headers: headers,
          rows: rows,
          sheetNames: (meta && meta.sheetNames) || [],
          activeSheetName: (meta && meta.activeSheetName) || '',
          totalRows: origRowCount,
          totalCols: origColCount,
          truncated: truncated
        };
      }

      function parseDelimitedText(rawText, meta) {
        var str = String(rawText || '').replace(/^\uFEFF/, '');
        var lines = str.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
        var tabCount = (lines.slice(0, 2000).match(/\t/g) || []).length;
        var commaCount = (lines.slice(0, 2000).match(/,/g) || []).length;
        var semiCount = (lines.slice(0, 2000).match(/;/g) || []).length;
        var delim = tabCount > 0 ? '\t' : (commaCount >= semiCount ? ',' : ';');

        var grid = [];
        var row = [];
        var field = '';
        var inQuotes = false;

        for (var i = 0; i < lines.length; i++) {
          var ch = lines.charAt(i);
          if (inQuotes) {
            if (ch === '"') {
              if (lines.charAt(i + 1) === '"') {
                field += '"';
                i++;
              } else {
                inQuotes = false;
              }
            } else {
              field += ch;
            }
          } else {
            if (ch === '"' && field.length === 0) {
              inQuotes = true;
            } else if (ch === delim) {
              row.push(field);
              field = '';
            } else if (ch === '\n') {
              row.push(field);
              grid.push(row);
              row = [];
              field = '';
            } else {
              field += ch;
            }
          }
        }
        if (field.length > 0 || row.length > 0) {
          row.push(field);
          grid.push(row);
        }
        return normalizeGridResult(grid, meta);
      }

      function parseXmlText(bytes) {
        var parser = new DOMParser();
        return parser.parseFromString(decodeUtf8Bytes(bytes), 'text/xml');
      }

      function getSharedStringsFromZip(entries) {
        var key = Object.keys(entries).find(function (k) { return /^xl\/sharedStrings\.xml$/i.test(k); });
        if (!key) return [];
        var xmlDoc = parseXmlText(entries[key]);
        var siNodes = xmlDoc.getElementsByTagName('si');
        var out = [];
        for (var i = 0; i < siNodes.length; i++) {
          var tNodes = siNodes[i].getElementsByTagName('t');
          var parts = [];
          for (var j = 0; j < tNodes.length; j++) {
            parts.push(tNodes[j].textContent || '');
          }
          out.push(parts.join(''));
        }
        return out;
      }

      function getWorkbookSheetsFromZip(entries) {
        var wbKey = Object.keys(entries).find(function (k) { return /^xl\/workbook\.xml$/i.test(k); });
        var relsKey = Object.keys(entries).find(function (k) { return /^xl\/_rels\/workbook\.xml\.rels$/i.test(k); });
        var relMap = {};
        if (relsKey) {
          var relDoc = parseXmlText(entries[relsKey]);
          var rels = relDoc.getElementsByTagName('Relationship');
          for (var i = 0; i < rels.length; i++) {
            var rid = rels[i].getAttribute('Id') || '';
            var target = rels[i].getAttribute('Target') || '';
            if (rid && target) {
              target = target.replace(/^\/+/, '');
              if (target.indexOf('xl/') !== 0) target = 'xl/' + target.replace(/^\.\//, '');
              relMap[rid] = target;
            }
          }
        }
        var sheets = [];
        if (wbKey) {
          var wbDoc = parseXmlText(entries[wbKey]);
          var shNodes = wbDoc.getElementsByTagName('sheet');
          for (var s = 0; s < shNodes.length; s++) {
            var name = shNodes[s].getAttribute('name') || ('Sheet ' + (s + 1));
            var rId = shNodes[s].getAttribute('r:id') || shNodes[s].getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships', 'id') || '';
            var path = relMap[rId] || ('xl/worksheets/sheet' + (s + 1) + '.xml');
            if (entries[path]) {
              sheets.push({ name: name, path: path });
            }
          }
        }
        if (sheets.length === 0) {
          var fallbackPaths = Object.keys(entries).filter(function (k) {
            return /^xl\/worksheets\/sheet\d+\.xml$/i.test(k);
          }).sort();
          for (var f = 0; f < fallbackPaths.length; f++) {
            sheets.push({ name: 'Sheet ' + (f + 1), path: fallbackPaths[f] });
          }
        }
        return sheets;
      }

      function parseXlsxWorksheetGrid(entries, sheetPath, sharedStrings) {
        var wsBytes = entries[sheetPath];
        if (!wsBytes) throw new Error('Worksheet XML not found: ' + sheetPath);
        var wsDoc = parseXmlText(wsBytes);
        var rowNodes = wsDoc.getElementsByTagName('row');
        var grid = [];
        var expectedRowIdx = 0;

        for (var r = 0; r < rowNodes.length && grid.length < MAX_TABLE_ROWS + 5; r++) {
          var rowNumAttr = Number(rowNodes[r].getAttribute('r') || (expectedRowIdx + 1));
          while (expectedRowIdx + 1 < rowNumAttr && grid.length < MAX_TABLE_ROWS + 5) {
            grid.push([]);
            expectedRowIdx++;
          }
          var rowArr = [];
          var cells = rowNodes[r].getElementsByTagName('c');
          for (var c = 0; c < cells.length; c++) {
            var cell = cells[c];
            var ref = cell.getAttribute('r') || '';
            var colIdx = colLettersToZeroIndex(ref);
            if (colIdx < 0) colIdx = rowArr.length;
            if (colIdx >= MAX_TABLE_COLS + 4) continue;
            while (rowArr.length <= colIdx) rowArr.push('');

            var cType = cell.getAttribute('t') || '';
            var valText = '';
            if (cType === 'inlineStr') {
              var isT = cell.getElementsByTagName('t');
              var isParts = [];
              for (var k = 0; k < isT.length; k++) isParts.push(isT[k].textContent || '');
              valText = isParts.join('');
            } else {
              var vNode = cell.getElementsByTagName('v')[0];
              var rawVal = vNode ? (vNode.textContent || '') : '';
              if (cType === 's') {
                var sIdx = Number(rawVal);
                valText = isFinite(sIdx) && sharedStrings[sIdx] !== undefined ? sharedStrings[sIdx] : rawVal;
              } else if (cType === 'b') {
                valText = rawVal === '1' ? 'TRUE' : 'FALSE';
              } else {
                valText = rawVal;
              }
            }
            rowArr[colIdx] = valText;
          }
          grid.push(rowArr);
          expectedRowIdx++;
        }
        return grid;
      }

      function parseXlsxFile(fileOrBuffer, opts) {
        var o = opts || {};
        var fname = (fileOrBuffer && fileOrBuffer.name) || o.filename || 'Spreadsheet.xlsx';
        var bufPromise = fileOrBuffer && typeof fileOrBuffer.arrayBuffer === 'function'
          ? fileOrBuffer.arrayBuffer()
          : Promise.resolve(fileOrBuffer);
        return bufPromise.then(unzipEntriesFromBuffer).then(function (entries) {
          var sheets = getWorkbookSheetsFromZip(entries);
          if (sheets.length === 0) {
            throw new Error('No readable worksheets were found inside "' + fname + '".');
          }
          var sharedStrings = getSharedStringsFromZip(entries);
          var sheetNames = sheets.map(function (s) { return s.name; });
          var targetSheet = sheets[0];
          if (o.sheetName) {
            var found = sheets.find(function (s) { return s.name === o.sheetName; });
            if (found) targetSheet = found;
          }
          var grid = parseXlsxWorksheetGrid(entries, targetSheet.path, sharedStrings);
          var baseCap = String(fname).replace(/\.xlsx$/i, '');
          var res = normalizeGridResult(grid, {
            useFirstRowAsHeader: o.useFirstRowAsHeader !== false,
            caption: baseCap + (sheets.length > 1 ? ' (' + targetSheet.name + ')' : ''),
            sheetNames: sheetNames,
            activeSheetName: targetSheet.name
          });
          res._cachedXlsx = { entries: entries, sheets: sheets, sharedStrings: sharedStrings, filename: fname };
          return res;
        });
      }

      function parseGsheetSource(urlOrIdOrFileText, opts) {
        var o = opts || {};
        var raw = String(urlOrIdOrFileText || '').trim();
        var docId = '';
        var docUrl = '';
        var parsedJsonName = '';

        if (raw.charAt(0) === '{') {
          try {
            var gObj = JSON.parse(raw);
            docId = String(gObj.doc_id || gObj.spreadsheetId || gObj.id || '').trim();
            docUrl = String(gObj.url || '').trim();
            parsedJsonName = String(gObj.title || '').trim();
          } catch (e) {}
        }
        if (!docId) {
          var m =
            raw.match(/\/spreadsheets\/d\/([A-Za-z0-9_-]{10,120})/) ||
            raw.match(/[?&]id=([A-Za-z0-9_-]{10,120})/) ||
            (/^[A-Za-z0-9_-]{16,120}$/.test(raw) ? [raw, raw] : null);
          if (m && m[1]) {
            docId = m[1];
          }
        }
        if (!docId && !docUrl) {
          return Promise.reject(new Error('Could not find a valid Google Sheet ID or URL inside the .gsheet file or input.'));
        }

        return rpcCallEnvelope('admin.spreadsheet.parseGsheet', {
          spreadsheetId: docId,
          url: docUrl || raw,
          sheetName: o.sheetName || '',
          useFirstRowAsHeader: o.useFirstRowAsHeader !== false
        })
          .then(function (env) {
            var d = env.data || {};
            return {
              caption: d.caption || parsedJsonName || d.title || 'Google Sheet Table',
              headers: Array.isArray(d.headers) ? d.headers : [],
              rows: Array.isArray(d.rows) ? d.rows : [['']],
              sheetNames: Array.isArray(d.sheetNames) ? d.sheetNames : [],
              activeSheetName: d.activeSheetName || '',
              totalRows: d.totalRows || (d.rows ? d.rows.length : 0),
              totalCols: d.totalCols || (d.headers ? d.headers.length : 0),
              truncated: Boolean(d.truncated),
              _gsheetSource: { spreadsheetId: docId, url: docUrl || raw }
            };
          })
          .catch(function (rpcErr) {
            var msg = String((rpcErr && rpcErr.message) || '');
            var isUnregistered =
              (rpcErr && rpcErr.code === 'ERR_UNKNOWN_ACTION') ||
              msg.indexOf('Unknown') !== -1 ||
              msg.indexOf('parseGsheet') !== -1;
            if (!isUnregistered || !docId) {
              throw rpcErr;
            }
            var csvUrl = 'https://docs.google.com/spreadsheets/d/' + encodeURIComponent(docId) + '/export?format=csv';
            return fetch(csvUrl)
              .then(function (resp) {
                if (!resp.ok) {
                  throw new Error('HTTP ' + resp.status);
                }
                return resp.text();
              })
              .then(function (csvText) {
                var parsed = parseDelimitedText(csvText, {
                  useFirstRowAsHeader: o.useFirstRowAsHeader !== false,
                  caption: parsedJsonName || 'Google Sheet Table'
                });
                parsed._gsheetSource = { spreadsheetId: docId, url: docUrl || raw };
                return parsed;
              })
              .catch(function () {
                throw new Error(
                  'To import private .gsheet files directly, redeploy Google Apps Script with the updated Code.gs and CourseService.gs — OR download the Google Sheet as .xlsx / .csv and import it here.'
                );
              });
          });
      }

      return Object.freeze({
        MAX_ROWS: MAX_TABLE_ROWS,
        MAX_COLS: MAX_TABLE_COLS,
        parseXlsxFile: parseXlsxFile,
        parseDelimitedText: parseDelimitedText,
        parseGsheetSource: parseGsheetSource,
        normalizeGridResult: normalizeGridResult,
        switchCachedXlsxSheet: function (cachedXlsx, sheetName, useHeader) {
          var target = cachedXlsx.sheets.find(function (s) { return s.name === sheetName; }) || cachedXlsx.sheets[0];
          var grid = parseXlsxWorksheetGrid(cachedXlsx.entries, target.path, cachedXlsx.sharedStrings);
          var baseCap = String(cachedXlsx.filename || 'Spreadsheet').replace(/\.xlsx$/i, '');
          var res = normalizeGridResult(grid, {
            useFirstRowAsHeader: useHeader !== false,
            caption: baseCap + (cachedXlsx.sheets.length > 1 ? ' (' + target.name + ')' : ''),
            sheetNames: cachedXlsx.sheets.map(function (s) { return s.name; }),
            activeSheetName: target.name
          });
          res._cachedXlsx = cachedXlsx;
          return res;
        }
      });
    })();

    var pbTableEditorSession = {
      onSaveCallback: null,
      useFirstRowAsHeader: true,
      headers: ['Parameter', 'Control', 'Treatment'],
      rows: [
        ['Rate (umol/min)', '0.42', '1.18'],
        ['pH', '7.0', '7.2']
      ],
      caption: '',
      cachedXlsx: null,
      gsheetSource: null
    };

    function syncTableEditorModalControls() {
      var capInp = document.getElementById('input-pb-table-caption');
      var hdrChk = document.getElementById('chk-pb-table-first-row-header');
      if (capInp) capInp.value = pbTableEditorSession.caption || '';
      if (hdrChk) hdrChk.checked = Boolean(pbTableEditorSession.useFirstRowAsHeader);
      renderTableEditorGridDom();
    }

    function renderTableEditorGridDom() {
      var host = document.getElementById('pb-table-grid-editor-host');
      var dimBadge = document.getElementById('pb-table-dim-badge');
      if (!host) return;
      while (host.firstChild) host.removeChild(host.firstChild);

      var rows = pbTableEditorSession.rows;
      var headers = pbTableEditorSession.headers;
      var colCount = Math.max(
        1,
        pbTableEditorSession.useFirstRowAsHeader && headers.length > 0
          ? headers.length
          : (rows[0] ? rows[0].length : 1)
      );

      for (var r = 0; r < rows.length; r++) {
        while (rows[r].length < colCount) rows[r].push('');
        if (rows[r].length > colCount) rows[r] = rows[r].slice(0, colCount);
      }
      if (pbTableEditorSession.useFirstRowAsHeader) {
        while (headers.length < colCount) headers.push('Header ' + (headers.length + 1));
        if (headers.length > colCount) headers = pbTableEditorSession.headers = headers.slice(0, colCount);
      }

      if (dimBadge) {
        dimBadge.textContent =
          colCount + ' cols \u00D7 ' + rows.length + ' data rows' +
          (pbTableEditorSession.useFirstRowAsHeader ? ' (+ header)' : '');
      }

      var tbl = document.createElement('table');
      tbl.className = 'pb-table-grid-editor';

      if (pbTableEditorSession.useFirstRowAsHeader) {
        var thead = document.createElement('thead');
        var hTr = document.createElement('tr');
        var corner = document.createElement('th');
        corner.className = 'pb-table-row-idx-col';
        corner.textContent = 'Hdr';
        hTr.appendChild(corner);

        for (var hc = 0; hc < colCount; hc++) {
          (function (colIdx) {
            var th = document.createElement('th');
            var inp = document.createElement('input');
            inp.type = 'text';
            inp.maxLength = 200;
            inp.className = 'pb-table-grid-input is-header-cell';
            inp.value = headers[colIdx] || '';
            inp.placeholder = 'Col ' + (colIdx + 1);
            inp.setAttribute('aria-label', 'Header column ' + (colIdx + 1));
            inp.addEventListener('input', function () {
              headers[colIdx] = inp.value;
            });
            th.appendChild(inp);
            hTr.appendChild(th);
          })(hc);
        }
        thead.appendChild(hTr);
        tbl.appendChild(thead);
      }

      var tbody = document.createElement('tbody');
      for (var ri = 0; ri < rows.length; ri++) {
        (function (rowIdx) {
          var tr = document.createElement('tr');
          var idxTd = document.createElement('td');
          idxTd.className = 'pb-table-row-idx-col';
          idxTd.textContent = String(rowIdx + 1);
          tr.appendChild(idxTd);

          for (var ci = 0; ci < colCount; ci++) {
            (function (cIdx) {
              var td = document.createElement('td');
              var cInp = document.createElement('input');
              cInp.type = 'text';
              cInp.maxLength = 300;
              cInp.className = 'pb-table-grid-input';
              cInp.value = rows[rowIdx][cIdx] || '';
              cInp.setAttribute('aria-label', 'Row ' + (rowIdx + 1) + ' Column ' + (cIdx + 1));
              cInp.addEventListener('input', function () {
                rows[rowIdx][cIdx] = cInp.value;
              });
              td.appendChild(cInp);
              tr.appendChild(td);
            })(ci);
          }
          tbody.appendChild(tr);
        })(ri);
      }
      tbl.appendChild(tbody);
      host.appendChild(tbl);
    }

    function applyImportedTablePayloadToModal(parsedTable, sourceLabel) {
      if (!parsedTable) return;
      var hasHdr = Array.isArray(parsedTable.headers) && parsedTable.headers.length > 0;
      pbTableEditorSession.useFirstRowAsHeader = hasHdr;
      pbTableEditorSession.headers = hasHdr ? parsedTable.headers.slice() : [];
      pbTableEditorSession.rows =
        Array.isArray(parsedTable.rows) && parsedTable.rows.length > 0
          ? parsedTable.rows.map(function (r) { return Array.isArray(r) ? r.slice() : []; })
          : [['']];
      pbTableEditorSession.caption = parsedTable.caption || pbTableEditorSession.caption || '';
      pbTableEditorSession.cachedXlsx = parsedTable._cachedXlsx || null;
      pbTableEditorSession.gsheetSource = parsedTable._gsheetSource || null;

      var pickerWrap = document.getElementById('pb-table-sheet-picker-wrap');
      var pickerSel = document.getElementById('select-pb-table-sheet-name');
      var names = Array.isArray(parsedTable.sheetNames) ? parsedTable.sheetNames : [];
      if (pickerWrap && pickerSel) {
        while (pickerSel.firstChild) pickerSel.removeChild(pickerSel.firstChild);
        if (names.length > 1) {
          names.forEach(function (nm) {
            var opt = document.createElement('option');
            opt.value = nm;
            opt.textContent = nm;
            if (nm === parsedTable.activeSheetName) opt.selected = true;
            pickerSel.appendChild(opt);
          });
          pickerWrap.classList.remove('hidden');
        } else {
          pickerWrap.classList.add('hidden');
        }
      }

      var st = document.getElementById('pb-table-import-status');
      if (st) {
        var note =
          (sourceLabel ? sourceLabel + ': ' : '') +
          'Loaded ' +
          pbTableEditorSession.rows.length +
          ' data row(s)' +
          (hasHdr ? ' + header row' : '') +
          (parsedTable.activeSheetName ? ' from "' + parsedTable.activeSheetName + '"' : '') +
          '.';
        if (parsedTable.truncated) {
          note += ' Note: Large spreadsheets are capped at 40 data rows \u00D7 12 columns to fit exam cards.';
        }
        st.textContent = note;
        st.style.color = '#0F766E';
      }
      syncTableEditorModalControls();
    }

    function openQuestionTableEditorModal(initialTableBlock, onApplyFn) {
      if (activeModalId && activeModalId !== 'modal-pb-table-editor') {
        pbPdfViewerReturnModalId = activeModalId;
      }
      pbTableEditorSession.onSaveCallback = typeof onApplyFn === 'function' ? onApplyFn : null;
      pbTableEditorSession.cachedXlsx = null;
      pbTableEditorSession.gsheetSource = null;

      if (initialTableBlock && initialTableBlock.type === 'table') {
        var hasH = Array.isArray(initialTableBlock.headers) && initialTableBlock.headers.length > 0;
        pbTableEditorSession.useFirstRowAsHeader = hasH;
        pbTableEditorSession.headers = hasH ? initialTableBlock.headers.slice() : [];
        pbTableEditorSession.rows =
          Array.isArray(initialTableBlock.rows) && initialTableBlock.rows.length > 0
            ? initialTableBlock.rows.map(function (r) { return Array.isArray(r) ? r.slice() : []; })
            : [['', '', ''], ['', '', '']];
        pbTableEditorSession.caption = initialTableBlock.caption || '';
      } else {
        pbTableEditorSession.useFirstRowAsHeader = true;
        pbTableEditorSession.headers = ['Column 1', 'Column 2', 'Column 3'];
        pbTableEditorSession.rows = [
          ['', '', ''],
          ['', '', ''],
          ['', '', '']
        ];
        pbTableEditorSession.caption = '';
      }

      var fileInp = document.getElementById('input-pb-table-import-file');
      var urlInp = document.getElementById('input-pb-table-gsheet-url');
      var pasteDrawer = document.getElementById('pb-table-paste-drawer');
      var pasteTxt = document.getElementById('textarea-pb-table-paste');
      var pickerWrap = document.getElementById('pb-table-sheet-picker-wrap');
      var st = document.getElementById('pb-table-import-status');
      if (fileInp) fileInp.value = '';
      if (urlInp) urlInp.value = '';
      if (pasteDrawer) pasteDrawer.classList.add('hidden');
      if (pasteTxt) pasteTxt.value = '';
      if (pickerWrap) pickerWrap.classList.add('hidden');
      if (st) {
        st.textContent = 'Ready: edit cells below or upload .xlsx, .gsheet, or .csv to auto-convert into a table.';
        st.style.color = 'var(--color-text-muted)';
      }

      syncTableEditorModalControls();
      openModalDialog('modal-pb-table-editor', 'input-pb-table-caption');
    }

    function bindQuestionTableEditorModalEvents() {
      var closeBtn = document.getElementById('btn-pb-table-editor-close');
      var cancelBtn = document.getElementById('btn-pb-table-editor-cancel');
      var saveBtn = document.getElementById('btn-pb-table-save');
      var backdrop = document.getElementById('modal-pb-table-editor');
      if (backdrop && backdrop.dataset && backdrop.dataset.boundModal === '1') return;
      if (backdrop && backdrop.dataset) backdrop.dataset.boundModal = '1';

      function closeTbl() {
        closeModalDialog('modal-pb-table-editor');
      }
      if (closeBtn) closeBtn.addEventListener('click', closeTbl);
      if (cancelBtn) cancelBtn.addEventListener('click', closeTbl);
      if (backdrop) {
        backdrop.addEventListener('click', function (evt) {
          if (evt && evt.target === backdrop) closeTbl();
        });
      }

      var zoomOutBtn = document.getElementById('btn-pb-image-zoom-out');
      var zoomInBtn = document.getElementById('btn-pb-image-zoom-in');
      var zoomCloseBtn = document.getElementById('btn-pb-image-zoom-close');
      var zoomBackdrop = document.getElementById('modal-pb-image-zoom');
      if (zoomOutBtn) zoomOutBtn.addEventListener('click', function () { applyImageZoomPercent(pbImageZoomCurrentPct - 25); });
      if (zoomInBtn) zoomInBtn.addEventListener('click', function () { applyImageZoomPercent(pbImageZoomCurrentPct + 25); });
      if (zoomCloseBtn) zoomCloseBtn.addEventListener('click', closeInAppImageZoomModal);
      if (zoomBackdrop) {
        zoomBackdrop.addEventListener('click', function (evt) {
          if (evt && evt.target === zoomBackdrop) closeInAppImageZoomModal();
        });
        var presetBtns = zoomBackdrop.querySelectorAll('[data-pb-zoom-preset]');
        for (var pIdx = 0; pIdx < presetBtns.length; pIdx++) {
          (function (btn) {
            btn.addEventListener('click', function () {
              applyImageZoomPercent(btn.getAttribute('data-pb-zoom-preset'));
            });
          })(presetBtns[pIdx]);
        }
      }

      var capInp = document.getElementById('input-pb-table-caption');
      if (capInp) {
        capInp.addEventListener('input', function () {
          pbTableEditorSession.caption = capInp.value;
        });
      }
      var hdrChk = document.getElementById('chk-pb-table-first-row-header');
      if (hdrChk) {
        hdrChk.addEventListener('change', function () {
          var nextUse = Boolean(hdrChk.checked);
          if (nextUse === pbTableEditorSession.useFirstRowAsHeader) return;
          if (nextUse) {
            if (pbTableEditorSession.rows.length >= 2) {
              pbTableEditorSession.headers = pbTableEditorSession.rows.shift().slice();
            } else {
              var cLen = pbTableEditorSession.rows[0] ? pbTableEditorSession.rows[0].length : 3;
              pbTableEditorSession.headers = [];
              for (var i = 0; i < cLen; i++) pbTableEditorSession.headers.push('Column ' + (i + 1));
            }
          } else if (pbTableEditorSession.headers.length > 0) {
            pbTableEditorSession.rows.unshift(pbTableEditorSession.headers.slice());
            pbTableEditorSession.headers = [];
          }
          pbTableEditorSession.useFirstRowAsHeader = nextUse;
          renderTableEditorGridDom();
        });
      }

      var addRowBtn = document.getElementById('btn-pb-table-add-row');
      var delRowBtn = document.getElementById('btn-pb-table-del-row');
      var addColBtn = document.getElementById('btn-pb-table-add-col');
      var delColBtn = document.getElementById('btn-pb-table-del-col');
      if (addRowBtn) {
        addRowBtn.addEventListener('click', function () {
          if (pbTableEditorSession.rows.length >= 40) {
            PBNotify.toast('info', 'Row Limit', 'Tables support up to 40 data rows.');
            return;
          }
          var cols = pbTableEditorSession.useFirstRowAsHeader && pbTableEditorSession.headers.length > 0
            ? pbTableEditorSession.headers.length
            : (pbTableEditorSession.rows[0] ? pbTableEditorSession.rows[0].length : 3);
          pbTableEditorSession.rows.push(new Array(cols + 1).join(',').split(',').map(function () { return ''; }));
          renderTableEditorGridDom();
        });
      }
      if (delRowBtn) {
        delRowBtn.addEventListener('click', function () {
          if (pbTableEditorSession.rows.length <= 1) return;
          pbTableEditorSession.rows.pop();
          renderTableEditorGridDom();
        });
      }
      if (addColBtn) {
        addColBtn.addEventListener('click', function () {
          var curCols = pbTableEditorSession.useFirstRowAsHeader && pbTableEditorSession.headers.length > 0
            ? pbTableEditorSession.headers.length
            : (pbTableEditorSession.rows[0] ? pbTableEditorSession.rows[0].length : 1);
          if (curCols >= 12) {
            PBNotify.toast('info', 'Column Limit', 'Tables support up to 12 columns.');
            return;
          }
          if (pbTableEditorSession.useFirstRowAsHeader) {
            pbTableEditorSession.headers.push('Col ' + (curCols + 1));
          }
          for (var r = 0; r < pbTableEditorSession.rows.length; r++) {
            pbTableEditorSession.rows[r].push('');
          }
          renderTableEditorGridDom();
        });
      }
      if (delColBtn) {
        delColBtn.addEventListener('click', function () {
          var curCols = pbTableEditorSession.useFirstRowAsHeader && pbTableEditorSession.headers.length > 0
            ? pbTableEditorSession.headers.length
            : (pbTableEditorSession.rows[0] ? pbTableEditorSession.rows[0].length : 1);
          if (curCols <= 1) return;
          if (pbTableEditorSession.useFirstRowAsHeader && pbTableEditorSession.headers.length > 1) {
            pbTableEditorSession.headers.pop();
          }
          for (var r = 0; r < pbTableEditorSession.rows.length; r++) {
            pbTableEditorSession.rows[r].pop();
          }
          renderTableEditorGridDom();
        });
      }

      var fileInp = document.getElementById('input-pb-table-import-file');
      var impFileBtn = document.getElementById('btn-pb-table-import-file');
      function handleTableFileChosen(fileObj) {
        if (!fileObj) return;
        var st = document.getElementById('pb-table-import-status');
        if (st) {
          st.textContent = 'Reading "' + fileObj.name + '"...';
          st.style.color = '#0F766E';
        }
        var lowerName = String(fileObj.name || '').toLowerCase();
        var hdrChkEl = document.getElementById('chk-pb-table-first-row-header');
        var useHeader = hdrChkEl ? Boolean(hdrChkEl.checked) : true;
        var workPromise;
        if (/\.xlsx$/.test(lowerName)) {
          workPromise = PBSpreadsheetTableImporter.parseXlsxFile(fileObj, {
            useFirstRowAsHeader: useHeader,
            filename: fileObj.name
          });
        } else if (/\.gsheet$/.test(lowerName)) {
          workPromise = fileObj.text().then(function (txt) {
            return PBSpreadsheetTableImporter.parseGsheetSource(txt, {
              useFirstRowAsHeader: useHeader
            });
          });
        } else if (/\.(csv|tsv|txt)$/.test(lowerName)) {
          workPromise = fileObj.text().then(function (txt) {
            return PBSpreadsheetTableImporter.parseDelimitedText(txt, {
              useFirstRowAsHeader: useHeader,
              caption: String(fileObj.name || '').replace(/\.(csv|tsv|txt)$/i, '')
            });
          });
        } else if (/\.xls$/.test(lowerName)) {
          workPromise = Promise.reject(new Error('Legacy binary .xls format is not supported in browser. Save as .xlsx or .csv and re-import.'));
        } else {
          workPromise = Promise.reject(new Error('Unsupported file extension. Upload .xlsx, .gsheet, .csv, or .tsv.'));
        }
        workPromise
          .then(function (parsed) {
            applyImportedTablePayloadToModal(parsed, fileObj.name);
          })
          .catch(function (err) {
            if (st) {
              st.textContent = (err && err.message) || 'Failed to parse spreadsheet file.';
              st.style.color = '#B91C1C';
            }
          });
      }
      if (fileInp) {
        fileInp.addEventListener('change', function () {
          if (fileInp.files && fileInp.files[0]) handleTableFileChosen(fileInp.files[0]);
        });
      }
      if (impFileBtn) {
        impFileBtn.addEventListener('click', function () {
          if (fileInp && fileInp.files && fileInp.files[0]) {
            handleTableFileChosen(fileInp.files[0]);
          } else if (fileInp) {
            fileInp.click();
          }
        });
      }

      var fetchSheetBtn = document.getElementById('btn-pb-table-gsheet-fetch');
      if (fetchSheetBtn) {
        fetchSheetBtn.addEventListener('click', function () {
          var urlVal = ((document.getElementById('input-pb-table-gsheet-url') || {}).value || '').trim();
          var hdrChkEl = document.getElementById('chk-pb-table-first-row-header');
          var useHeader = hdrChkEl ? Boolean(hdrChkEl.checked) : true;
          var st = document.getElementById('pb-table-import-status');
          if (!urlVal) {
            if (st) {
              st.textContent = 'Enter a Google Sheets URL or Spreadsheet ID first.';
              st.style.color = '#B91C1C';
            }
            return;
          }
          runButtonWithLoadingState(fetchSheetBtn, 'Importing...', function () {
            return PBSpreadsheetTableImporter.parseGsheetSource(urlVal, {
              useFirstRowAsHeader: useHeader
            })
              .then(function (parsed) {
                applyImportedTablePayloadToModal(parsed, 'Google Sheets');
              })
              .catch(function (err) {
                if (st) {
                  st.textContent = (err && err.message) || 'Unable to import Google Sheet.';
                  st.style.color = '#B91C1C';
                }
              });
          });
        });
      }

      var sheetSel = document.getElementById('select-pb-table-sheet-name');
      if (sheetSel) {
        sheetSel.addEventListener('change', function () {
          var hdrChkEl = document.getElementById('chk-pb-table-first-row-header');
          var useHeader = hdrChkEl ? Boolean(hdrChkEl.checked) : true;
          var chosen = sheetSel.value;
          if (pbTableEditorSession.cachedXlsx) {
            var sw = PBSpreadsheetTableImporter.switchCachedXlsxSheet(
              pbTableEditorSession.cachedXlsx,
              chosen,
              useHeader
            );
            applyImportedTablePayloadToModal(sw, pbTableEditorSession.cachedXlsx.filename);
          } else if (pbTableEditorSession.gsheetSource) {
            PBSpreadsheetTableImporter.parseGsheetSource(
              pbTableEditorSession.gsheetSource.url || pbTableEditorSession.gsheetSource.spreadsheetId,
              { sheetName: chosen, useFirstRowAsHeader: useHeader }
            )
              .then(function (parsed) {
                applyImportedTablePayloadToModal(parsed, 'Google Sheets');
              })
              .catch(function (err) {
                var st = document.getElementById('pb-table-import-status');
                if (st) {
                  st.textContent = (err && err.message) || 'Failed to switch worksheet.';
                  st.style.color = '#B91C1C';
                }
              });
          }
        });
      }

      var togglePasteBtn = document.getElementById('btn-pb-table-toggle-paste');
      var pasteDrawer = document.getElementById('pb-table-paste-drawer');
      if (togglePasteBtn && pasteDrawer) {
        togglePasteBtn.addEventListener('click', function () {
          pasteDrawer.classList.toggle('hidden');
        });
      }
      var applyPasteBtn = document.getElementById('btn-pb-table-apply-paste');
      if (applyPasteBtn) {
        applyPasteBtn.addEventListener('click', function () {
          var rawPaste = ((document.getElementById('textarea-pb-table-paste') || {}).value || '');
          var hdrChkEl = document.getElementById('chk-pb-table-first-row-header');
          var useHeader = hdrChkEl ? Boolean(hdrChkEl.checked) : true;
          if (!rawPaste.trim()) return;
          var parsed = PBSpreadsheetTableImporter.parseDelimitedText(rawPaste, {
            useFirstRowAsHeader: useHeader,
            caption: pbTableEditorSession.caption || ''
          });
          applyImportedTablePayloadToModal(parsed, 'Pasted Grid');
          if (pasteDrawer) pasteDrawer.classList.add('hidden');
        });
      }

      if (saveBtn) {
        saveBtn.addEventListener('click', function () {
          var captionTxt = ((document.getElementById('input-pb-table-caption') || {}).value || '').trim().slice(0, 240);
          var outBlock = {
            type: 'table',
            caption: captionTxt,
            headers: pbTableEditorSession.useFirstRowAsHeader
              ? pbTableEditorSession.headers.map(function (h) { return String(h || '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, 200); })
              : [],
            rows: pbTableEditorSession.rows.map(function (r) {
              return r.map(function (c) { return String(c || '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, 300); });
            })
          };
          var cb = pbTableEditorSession.onSaveCallback;
          closeTbl();
          if (typeof cb === 'function') cb(outBlock);
        });
      }
    }

    function uploadQuestionStemAttachmentFile(fileObj, kind, courseId) {
      var isPdf = kind === 'pdf';
      return readBrowserFileAsBase64Step8(fileObj).then(function (fData) {
        var primaryPurpose = isPdf ? 'QUESTION_PDF' : 'QUESTION_IMAGE';
        return rpcCallEnvelope('admin.uploadFile', {
          purpose: primaryPurpose,
          originalFilename: fData.originalFilename,
          mimeType: fData.mimeType,
          dataBase64: fData.dataBase64
        })
          .catch(function (err) {
            var errMsg = String((err && err.message) || '');
            if (isPdf && (errMsg.indexOf('Allowed purposes') !== -1 || errMsg.indexOf('QUESTION_PDF') !== -1)) {
              return rpcCallEnvelope('admin.uploadFile', {
                purpose: 'EXPLANATION_ATTACHMENT',
                originalFilename: fData.originalFilename,
                mimeType: fData.mimeType,
                dataBase64: fData.dataBase64
              });
            }
            throw err;
          })
          .then(function (env) {
            var fid = env.data && env.data.file && env.data.file.fileId;
            if (!fid) throw new Error('Upload succeeded without returning fileId.');
            if (typeof PBObjectUrlManager.seedCacheFromBase64 === 'function') {
              PBObjectUrlManager.seedCacheFromBase64(
                fid,
                fData.dataBase64,
                fData.mimeType,
                fData.originalFilename,
                courseId || '',
                fData._directFileBlob || null
              );
            }
            if (!isPdf) {
              if (fData.localPreviewUrl) {
                currentQBankLocalImagePreviewDataUrlByIdPhase2[fid] = fData.localPreviewUrl;
              } else if (String(fData.dataBase64 || '').indexOf('__PB_DIRECT_BLOB__:') !== 0) {
                currentQBankLocalImagePreviewDataUrlByIdPhase2[fid] =
                  'data:' + fData.mimeType + ';base64,' + fData.dataBase64;
              }
            }
            return {
              fileId: fid,
              originalFilename: fData.originalFilename || fileObj.name || (isPdf ? 'Attachment.pdf' : 'Diagram.png'),
              mimeType: fData.mimeType
            };
          });
      });
    }

    function renderQuestionRichMediaTray(hostEl, mediaBlocks, opts) {
      if (!hostEl) return;
      clearChildren(hostEl);
      var list = Array.isArray(mediaBlocks) ? mediaBlocks : [];
      var o = opts || {};
      var courseId = o.courseId || '';

      function commitList(nextList) {
        if (typeof o.onUpdate === 'function') {
          o.onUpdate(nextList);
        }
      }

      if (list.length === 0) return;

      var wrap = document.createElement('div');
      wrap.className = 'pb-q-media-tray';

      for (var i = 0; i < list.length; i++) {
        (function (blk, idx) {
          if (!blk || typeof blk !== 'object') return;
          if (blk.type !== 'image_attachment' && blk.type !== 'pdf_attachment' && blk.type !== 'table') {
            return;
          }
          var card = document.createElement('div');
          card.className = 'pb-q-media-block-card';

          var hdr = document.createElement('div');
          hdr.className = 'pb-q-media-block-header';

          var badge = document.createElement('span');
          badge.className = 'badge badge-ok';
          if (blk.type === 'image_attachment') {
            badge.textContent = 'Image Diagram • ' + (blk.widthPct || 100) + '%';
          } else if (blk.type === 'pdf_attachment') {
            badge.textContent =
              'Embedded PDF • ' +
              (blk.widthPct || 100) +
              '% × ' +
              (blk.heightPx || 420) +
              'px • ' +
              (blk.allowDownload === false ? 'View Only (No Download)' : 'Downloadable');
          } else {
            var rLen = Array.isArray(blk.rows) ? blk.rows.length : 0;
            var cLen = Array.isArray(blk.headers) && blk.headers.length > 0
              ? blk.headers.length
              : (Array.isArray(blk.rows) && blk.rows[0] ? blk.rows[0].length : 0);
            badge.textContent = 'Data Table • ' + cLen + ' cols × ' + rLen + ' rows';
          }
          hdr.appendChild(badge);

          var ctrls = document.createElement('div');
          ctrls.className = 'pb-q-media-block-controls';

          if (blk.type === 'image_attachment' || blk.type === 'pdf_attachment') {
            var widthPresets = blk.type === 'image_attachment' ? [25, 50, 75, 100] : [50, 75, 100];
            widthPresets.forEach(function (wp) {
              var wb = document.createElement('button');
              wb.type = 'button';
              var curW = blk.widthPct || 100;
              wb.className = 'btn btn-outline btn-sm pb-q-media-ctrl-btn' + (curW === wp ? ' is-active' : '');
              wb.textContent = wp + '%';
              wb.title = 'Set width to ' + wp + '%';
              wb.addEventListener('click', function () {
                var next = list.slice();
                next[idx] = Object.assign({}, blk, { widthPct: wp });
                commitList(next);
              });
              ctrls.appendChild(wb);
            });
          }

          if (blk.type === 'pdf_attachment') {
            [
              { label: 'Compact', px: 280 },
              { label: 'Medium', px: 420 },
              { label: 'Tall', px: 620 }
            ].forEach(function (hp) {
              var hb = document.createElement('button');
              hb.type = 'button';
              var curH = blk.heightPx || 420;
              hb.className = 'btn btn-outline btn-sm pb-q-media-ctrl-btn' + (curH === hp.px ? ' is-active' : '');
              hb.textContent = hp.label;
              hb.title = 'Set embedded PDF height to ' + hp.px + 'px';
              hb.addEventListener('click', function () {
                var next = list.slice();
                next[idx] = Object.assign({}, blk, {
                  displayMode: 'embed',
                  heightPx: hp.px
                });
                commitList(next);
              });
              ctrls.appendChild(hb);
            });

            var allowPdfDl = blk.allowDownload !== false;
            var dlPermBtn = document.createElement('button');
            dlPermBtn.type = 'button';
            dlPermBtn.className =
              'btn btn-outline btn-sm pb-q-media-ctrl-btn pb-pdf-dl-toggle-btn ' +
              (allowPdfDl ? 'is-allowed' : 'is-locked');
            setElementVectorIconLabel(
              dlPermBtn,
              allowPdfDl ? 'download' : 'shield-lock',
              allowPdfDl ? 'Download: Allowed' : 'View Only (No Download)',
              'pb-icon-xs'
            );
            dlPermBtn.title = allowPdfDl
              ? 'Students can download this embedded PDF. Click to set View Only.'
              : 'View Only: students can view/zoom in-app but cannot download. Click to allow downloads.';
            dlPermBtn.addEventListener('click', function () {
              var next = list.slice();
              next[idx] = Object.assign({}, blk, { allowDownload: !allowPdfDl });
              commitList(next);
            });
            ctrls.appendChild(dlPermBtn);

            var zPdfBtn = document.createElement('button');
            zPdfBtn.type = 'button';
            zPdfBtn.className = 'btn btn-outline btn-sm pb-q-media-ctrl-btn';
            setElementVectorIconLabel(zPdfBtn, 'zoom-in', 'Zoom Modal', 'pb-icon-xs');
            zPdfBtn.addEventListener('click', function () {
              openOrDownloadExamPdfWithNotice(
                zPdfBtn,
                blk.fileId,
                courseId,
                true,
                'Zoom Modal',
                { allowDownload: blk.allowDownload !== false }
              );
            });
            ctrls.appendChild(zPdfBtn);
          }

          if (blk.type === 'image_attachment') {
            var zImgBtn = document.createElement('button');
            zImgBtn.type = 'button';
            zImgBtn.className = 'btn btn-outline btn-sm pb-q-media-ctrl-btn';
            setElementVectorIconLabel(zImgBtn, 'zoom-in', 'Zoom', 'pb-icon-xs');
            zImgBtn.addEventListener('click', function () {
              openInAppImageZoomModal(blk.fileId, courseId, blk.altText || blk.caption || 'Question Diagram');
            });
            ctrls.appendChild(zImgBtn);
          }

          if (blk.type === 'table') {
            var editTblBtn = document.createElement('button');
            editTblBtn.type = 'button';
            editTblBtn.className = 'btn btn-secondary btn-sm pb-q-media-ctrl-btn';
            setElementVectorIconLabel(editTblBtn, 'table', 'Edit / Re-import Table', 'pb-icon-xs');
            editTblBtn.addEventListener('click', function () {
              openQuestionTableEditorModal(blk, function (updatedTbl) {
                var next = list.slice();
                next[idx] = updatedTbl;
                commitList(next);
              });
            });
            ctrls.appendChild(editTblBtn);
          }

          if (idx > 0) {
            var upB = document.createElement('button');
            upB.type = 'button';
            upB.className = 'btn btn-outline btn-sm pb-q-media-ctrl-btn';
            setElementVectorIconLabel(upB, 'arrow-up', '', 'pb-icon-xs');
            upB.setAttribute('aria-label', 'Move media item up');
            upB.title = 'Move Up';
            upB.addEventListener('click', function () {
              var next = list.slice();
              var tmp = next[idx - 1];
              next[idx - 1] = next[idx];
              next[idx] = tmp;
              commitList(next);
            });
            ctrls.appendChild(upB);
          }
          if (idx < list.length - 1) {
            var dnB = document.createElement('button');
            dnB.type = 'button';
            dnB.className = 'btn btn-outline btn-sm pb-q-media-ctrl-btn';
            setElementVectorIconLabel(dnB, 'arrow-down', '', 'pb-icon-xs');
            dnB.setAttribute('aria-label', 'Move media item down');
            dnB.title = 'Move Down';
            dnB.addEventListener('click', function () {
              var next = list.slice();
              var tmp = next[idx + 1];
              next[idx + 1] = next[idx];
              next[idx] = tmp;
              commitList(next);
            });
            ctrls.appendChild(dnB);
          }

          var rmB = document.createElement('button');
          rmB.type = 'button';
          rmB.className = 'btn btn-outline btn-sm pb-q-media-ctrl-btn';
          rmB.textContent = 'Remove';
          rmB.addEventListener('click', function () {
            var next = list.slice();
            next.splice(idx, 1);
            commitList(next);
          });
          ctrls.appendChild(rmB);

          hdr.appendChild(ctrls);
          card.appendChild(hdr);

          var previewBox = document.createElement('div');
          renderRichTextDocumentToDom(
            previewBox,
            { schemaVersion: 'pb-richtext-v1', blocks: [blk] },
            courseId
          );
          card.appendChild(previewBox);
          wrap.appendChild(card);
        })(list[i], i);
      }

      hostEl.appendChild(wrap);
    }

    function openOrDownloadExamPdfWithNotice(btnEl, fileId, courseId, openInNewTab, defaultLabel, opt_viewerOpts) {
      if (!fileId) return;
      var allowDownload = !(opt_viewerOpts && opt_viewerOpts.allowDownload === false);
      if (!openInNewTab && !allowDownload) {
        if (typeof PBNotify === 'object' && PBNotify) {
          PBNotify.toast('warning', 'View Only PDF', 'Downloading is disabled for this embedded PDF.');
        }
        return;
      }
      var origChildren = btnEl ? Array.prototype.slice.call(btnEl.childNodes || []) : [];
      var origText = defaultLabel || (btnEl ? btnEl.textContent : 'Open PDF');
      function restoreBtnContent() {
        if (!btnEl) return;
        btnEl.disabled = false;
        while (btnEl.firstChild) btnEl.removeChild(btnEl.firstChild);
        if (origChildren.length > 0) {
          for (var ci = 0; ci < origChildren.length; ci++) {
            btnEl.appendChild(origChildren[ci]);
          }
        } else {
          btnEl.textContent = origText;
        }
      }
      if (btnEl) {
        btnEl.disabled = true;
        btnEl.textContent = openInNewTab ? 'Opening PDF...' : 'Downloading PDF...';
      }
      var actionPromise = openInNewTab
        ? PBObjectUrlManager.fetchAndCreateObjectUrl(fileId, courseId || '', {
            skipRevokeCheck: true
          }).then(function (entry) {
            if (document.getElementById('modal-pb-pdf-viewer')) {
              openInAppPdfViewerModal(entry, { allowDownload: allowDownload });
              return entry;
            }
            if (!allowDownload) {
              throw new Error('View-only PDF viewer is unavailable.');
            }
            return PBObjectUrlManager.triggerAuthorizedDownload(fileId, courseId || '', true);
          })
        : PBObjectUrlManager.triggerAuthorizedDownload(fileId, courseId || '', false);

      actionPromise
        .then(function () {
          restoreBtnContent();
        })
        .catch(function (err) {
          restoreBtnContent();
          var msg = String((err && err.message) || 'Could not open PDF.');
          if (err && err.code === 'ERR_FORBIDDEN_RESOURCE' && msg.indexOf('not actively referenced') !== -1) {
            msg =
              'Student PDF download for Mock Tests requires updating Google Apps Script backend files from OneDrive\\PPB\\Web\\DriveService.gs and Code.gs.';
          }
          if (typeof PBNotify === 'object' && PBNotify) {
            PBNotify.toast('warning', 'PDF Access Notice', msg);
          } else {
            showUiErrorBanner({
              code: (err && err.code) || 'ERR_PDF_ACCESS',
              action: 'file.getContent',
              message: msg
            });
          }
        });
    }

    function renderStudentExamPdfResourcePanel(hostEl, instructionsRichText, ctx) {
      if (!hostEl) return;
      while (hostEl.firstChild) hostEl.removeChild(hostEl.firstChild);
      var parsed = extractExamPdfAttachmentsFromRichText(instructionsRichText);
      var paper = parsed.examPaperPdf;
      var ans = parsed.answerSheetPdf;
      if (!paper && !ans) {
        hostEl.classList.add('hidden');
        return;
      }
      hostEl.classList.remove('hidden');

      var head = document.createElement('div');
      head.className = 'pb-student-pdf-resources-head';
      head.textContent = 'Mock Test Papers & Answer Sheet (PDF)';
      hostEl.appendChild(head);

      var row = document.createElement('div');
      row.className = 'pb-student-pdf-resources-actions';
      var c = ctx || {};
      var courseId = c.courseId || '';

      if (paper && paper.fileId) {
        var openPaperBtn = document.createElement('button');
        openPaperBtn.type = 'button';
        openPaperBtn.className = 'btn btn-primary btn-sm';
        openPaperBtn.textContent = 'Open Exam Paper (PDF)';
        openPaperBtn.addEventListener('click', function () {
          openOrDownloadExamPdfWithNotice(openPaperBtn, paper.fileId, courseId, true, 'Open Exam Paper (PDF)');
        });
        row.appendChild(openPaperBtn);

        var dlPaperBtn = document.createElement('button');
        dlPaperBtn.type = 'button';
        dlPaperBtn.className = 'btn btn-outline btn-sm';
        dlPaperBtn.textContent = 'Download Exam Paper';
        dlPaperBtn.addEventListener('click', function () {
          openOrDownloadExamPdfWithNotice(dlPaperBtn, paper.fileId, courseId, false, 'Download Exam Paper');
        });
        row.appendChild(dlPaperBtn);
      }

      if (ans && ans.fileId) {
        if (canStudentViewExamAnswerSheetPdf(ans, c)) {
          var openAnsBtn = document.createElement('button');
          openAnsBtn.type = 'button';
          openAnsBtn.className = 'btn btn-secondary btn-sm';
          openAnsBtn.textContent = 'Open Answer Sheet (PDF)';
          openAnsBtn.addEventListener('click', function () {
            openOrDownloadExamPdfWithNotice(openAnsBtn, ans.fileId, courseId, true, 'Open Answer Sheet (PDF)');
          });
          row.appendChild(openAnsBtn);

          var dlAnsBtn = document.createElement('button');
          dlAnsBtn.type = 'button';
          dlAnsBtn.className = 'btn btn-outline btn-sm';
          dlAnsBtn.textContent = 'Download Answer Sheet';
          dlAnsBtn.addEventListener('click', function () {
            openOrDownloadExamPdfWithNotice(dlAnsBtn, ans.fileId, courseId, false, 'Download Answer Sheet');
          });
          row.appendChild(dlAnsBtn);
        } else {
          var lockPill = document.createElement('span');
          lockPill.className = 'pb-pdf-lock-pill';
          lockPill.textContent =
            ans.policy === 'WITH_KEY'
              ? 'Answer Sheet (PDF): Unlocks when official answer key is released'
              : 'Answer Sheet (PDF): Unlocks after you submit this Mock Test';
          row.appendChild(lockPill);
        }
      }

      hostEl.appendChild(row);
    }

    function setExamPdfEditorSlotState(cfg, fileId, filename, policy) {
      var idEl = document.getElementById(cfg.fileIdInputId);
      var nameEl = document.getElementById(cfg.filenameInputId);
      var statusEl = document.getElementById(cfg.statusElId);
      var openBtn = document.getElementById(cfg.openBtnId);
      var removeBtn = document.getElementById(cfg.removeBtnId);
      var policySel = cfg.policySelectId ? document.getElementById(cfg.policySelectId) : null;
      var cleanId = String(fileId || '').trim();
      var cleanName = String(filename || '').trim();
      if (idEl) idEl.value = cleanId;
      if (nameEl) nameEl.value = cleanName;
      if (policySel && policy) policySel.value = policy;
      if (statusEl) {
        if (cleanId) {
          statusEl.textContent = 'Attached: ' + (cleanName || cleanId) + ' (' + cleanId + ')';
          statusEl.classList.add('is-attached');
        } else {
          statusEl.textContent = cfg.emptyText || 'No PDF attached.';
          statusEl.classList.remove('is-attached');
        }
      }
      if (openBtn) openBtn.classList.toggle('hidden', !cleanId);
      if (removeBtn) removeBtn.classList.toggle('hidden', !cleanId);
    }

    function readExamPdfEditorSlotState(cfg) {
      var idEl = document.getElementById(cfg.fileIdInputId);
      var nameEl = document.getElementById(cfg.filenameInputId);
      var policySel = cfg.policySelectId ? document.getElementById(cfg.policySelectId) : null;
      var fid = idEl ? String(idEl.value || '').trim() : '';
      if (!fid) return null;
      return {
        fileId: fid,
        filename: (nameEl ? String(nameEl.value || '').trim() : '') || cfg.defaultName || 'document.pdf',
        policy: policySel ? String(policySel.value || 'AFTER_SUBMIT').toUpperCase() : 'AFTER_SUBMIT'
      };
    }

    function bindAdminExamPdfSlotControls(cfg) {
      var uploadBtn = document.getElementById(cfg.uploadBtnId);
      var fileInp = document.getElementById(cfg.fileInputId);
      var openBtn = document.getElementById(cfg.openBtnId);
      var removeBtn = document.getElementById(cfg.removeBtnId);
      if (uploadBtn && !(uploadBtn.dataset && uploadBtn.dataset.boundPdfSlot)) {
        if (uploadBtn.dataset) uploadBtn.dataset.boundPdfSlot = '1';
        uploadBtn.addEventListener('click', function () {
          var fileObj = fileInp && fileInp.files && fileInp.files[0];
          if (!fileObj) {
            setText(cfg.statusElId, 'Please choose a PDF file (.pdf) before clicking Upload PDF.');
            return;
          }
          var nameLower = String(fileObj.name || '').toLowerCase();
          var mimeLower = String(fileObj.type || '').toLowerCase();
          if (mimeLower && mimeLower !== 'application/pdf' && !nameLower.endsWith('.pdf')) {
            setText(cfg.statusElId, 'Only valid PDF documents (.pdf) are allowed.');
            return;
          }
          setText(cfg.statusElId, 'Uploading "' + (fileObj.name || 'document.pdf') + '"...');
          runButtonWithLoadingState(uploadBtn, 'Uploading...', function () {
            var uploadedBase64 = '';
            var uploadedBlob = null;
            var uploadedName = fileObj.name || cfg.defaultName || 'document.pdf';
            return readBrowserFileAsBase64Step8(fileObj, cfg.fileInputId)
              .then(function (fData) {
                uploadedBase64 = (fData && fData.dataBase64) || '';
                uploadedBlob = (fData && fData._directFileBlob) || null;
                uploadedName = (fData && fData.originalFilename) || uploadedName;
                return rpcCallEnvelope('admin.uploadFile', {
                  purpose: 'PDF_ATTACHMENT',
                  originalFilename: uploadedName,
                  mimeType: 'application/pdf',
                  dataBase64: uploadedBase64
                });
              })
              .then(function (env) {
                PBUploadProgress.completeAndHide(cfg.fileInputId);
                var uploaded = (env && env.data && env.data.file) || {};
                var finalName = uploaded.originalFilename || uploadedName || cfg.defaultName;
                if (
                  uploaded.fileId &&
                  (uploadedBase64 || uploadedBlob) &&
                  typeof PBObjectUrlManager === 'object' &&
                  PBObjectUrlManager &&
                  typeof PBObjectUrlManager.seedCacheFromBase64 === 'function'
                ) {
                  PBObjectUrlManager.seedCacheFromBase64(
                    uploaded.fileId,
                    uploadedBase64,
                    'application/pdf',
                    finalName,
                    '',
                    uploadedBlob
                  );
                }
                var policySel = cfg.policySelectId ? document.getElementById(cfg.policySelectId) : null;
                setExamPdfEditorSlotState(
                  cfg,
                  uploaded.fileId || '',
                  finalName,
                  policySel ? policySel.value : 'AFTER_SUBMIT'
                );
                if (fileInp) fileInp.value = '';
                PBNotify.toast('success', 'PDF Uploaded', (finalName || 'PDF') + ' attached. Save or Publish to persist.');
              })
              .catch(function (err) {
                PBUploadProgress.completeAndHide(cfg.fileInputId);
                setText(cfg.statusElId, 'Upload failed (' + ((err && err.code) || 'ERR') + '): ' + ((err && err.message) || ''));
              });
          });
        });
      }
      if (openBtn && !(openBtn.dataset && openBtn.dataset.boundPdfOpen)) {
        if (openBtn.dataset) openBtn.dataset.boundPdfOpen = '1';
        openBtn.addEventListener('click', function () {
          var fid = ((document.getElementById(cfg.fileIdInputId) || {}).value || '').trim();
          openOrDownloadExamPdfWithNotice(openBtn, fid, '', true, 'Open PDF');
        });
      }
      if (removeBtn && !(removeBtn.dataset && removeBtn.dataset.boundPdfRem)) {
        if (removeBtn.dataset) removeBtn.dataset.boundPdfRem = '1';
        removeBtn.addEventListener('click', function () {
          setExamPdfEditorSlotState(cfg, '', '', 'AFTER_SUBMIT');
          if (fileInp) fileInp.value = '';
        });
      }
    }

