    function renderRichTextDocumentToDom(containerEl, richTextDoc, opt_courseId, opt_renderOpts) {
      if (!containerEl) {
        return;
      }
      var renderOpts = opt_renderOpts && typeof opt_renderOpts === 'object' ? opt_renderOpts : {};
      clearChildren(containerEl);

      var effectiveCourseId =
        opt_courseId ||
        currentStudentCourseId ||
        (currentSelectedCourseDetail &&
          currentSelectedCourseDetail.course &&
          currentSelectedCourseDetail.course.courseId) ||
        '';
      var doc = cloneRichTextDocSafe(richTextDoc);
      var blocks = Array.isArray(doc.blocks) ? doc.blocks : [];

      function buildSpanDomNode(span) {
        var s = span && typeof span === 'object' ? span : { text: '' };
        var textVal = s.text === null || s.text === undefined ? '' : String(s.text);
        var classes = [];
        if (s.bold === true) {
          classes.push('pb-rt-bold');
        }
        if (s.italic === true) {
          classes.push('pb-rt-italic');
        }
        if (s.underline === true) {
          classes.push('pb-rt-underline');
        }
        var sz = s.size || 'base';
        if (sz === 'sm' || sz === 'base' || sz === 'lg' || sz === 'xl') {
          classes.push('pb-rt-size-' + sz);
        }

        var el = null;
        if (s.link && isSafeRichTextHref(s.link)) {
          el = document.createElement('a');
          var cleanHref = s.link.trim();
          el.setAttribute('href', cleanHref);
          if (cleanHref.toLowerCase().indexOf('mailto:') === 0) {
            el.setAttribute('target', '_top');
          } else {
            el.setAttribute('target', '_blank');
            el.setAttribute('rel', 'noopener noreferrer');
          }
          classes.push('pb-rt-link');
        } else {
          el = document.createElement('span');
        }

        if (s.sup === true && !s.link) {
          el = document.createElement('sup');
          classes.push('pb-rt-sup');
        } else if (s.sub === true && !s.link) {
          el = document.createElement('sub');
          classes.push('pb-rt-sub');
        }
        if (classes.length > 0) {
          el.className = classes.join(' ');
        }
        if (!s.link && !s.sup && !s.sub && typeof renderFormattedBiologyUnitDom === 'function') {
          renderFormattedBiologyUnitDom(el, textVal);
        } else {
          el.textContent = textVal;
        }
        return el;
      }

      var renderedAnyContent = false;
      for (var b = 0; b < blocks.length; b++) {
        var blk = blocks[b];
        if (!blk || typeof blk !== 'object') {
          continue;
        }
        if (blk.type === 'paragraph') {
          var p = document.createElement('p');
          var spans = Array.isArray(blk.spans) && blk.spans.length > 0 ? blk.spans : [{ text: '' }];
          for (var i = 0; i < spans.length; i++) {
            if (spans[i] && spans[i].text) {
              renderedAnyContent = true;
            }
            p.appendChild(buildSpanDomNode(spans[i]));
          }
          containerEl.appendChild(p);
        } else if (blk.type === 'table' && Array.isArray(blk.rows)) {
          renderedAnyContent = true;
          var tblWrap = document.createElement('div');
          tblWrap.className = 'table-responsive pb-rt-table-wrap';
          tblWrap.style.marginBottom = '10px';
          var tblEl = document.createElement('table');
          tblEl.className = 'data-table pb-rt-table';
          if (blk.caption) {
            var capEl = document.createElement('caption');
            capEl.style.captionSide = 'top';
            capEl.style.textAlign = 'left';
            capEl.style.fontWeight = '700';
            capEl.style.fontSize = '0.84rem';
            capEl.style.marginBottom = '6px';
            capEl.style.color = 'var(--color-brand-deep)';
            capEl.textContent = blk.caption;
            tblEl.appendChild(capEl);
          }
          if (Array.isArray(blk.headers) && blk.headers.length > 0) {
            var thead = document.createElement('thead');
            var hTr = document.createElement('tr');
            for (var hi = 0; hi < blk.headers.length; hi++) {
              var th = document.createElement('th');
              th.scope = 'col';
              th.textContent = String(blk.headers[hi] || '');
              hTr.appendChild(th);
            }
            thead.appendChild(hTr);
            tblEl.appendChild(thead);
          }
          var tbody = document.createElement('tbody');
          for (var ri = 0; ri < blk.rows.length; ri++) {
            var rArr = Array.isArray(blk.rows[ri]) ? blk.rows[ri] : [];
            var rTr = document.createElement('tr');
            for (var ci = 0; ci < rArr.length; ci++) {
              var td = document.createElement('td');
              td.textContent = String(rArr[ci] !== undefined && rArr[ci] !== null ? rArr[ci] : '');
              rTr.appendChild(td);
            }
            tbody.appendChild(rTr);
          }
          tblEl.appendChild(tbody);
          tblWrap.appendChild(tblEl);
          containerEl.appendChild(tblWrap);
        } else if (blk.type === 'bullet_list' || blk.type === 'ordered_list') {
          var listEl = document.createElement(blk.type === 'ordered_list' ? 'ol' : 'ul');
          var items = Array.isArray(blk.items) ? blk.items : [];
          for (var m = 0; m < items.length; m++) {
            var li = document.createElement('li');
            var itemSpans =
              items[m] && Array.isArray(items[m].spans) && items[m].spans.length > 0
                ? items[m].spans
                : [{ text: '' }];
            for (var isIdx = 0; isIdx < itemSpans.length; isIdx++) {
              if (itemSpans[isIdx] && itemSpans[isIdx].text) {
                renderedAnyContent = true;
              }
              li.appendChild(buildSpanDomNode(itemSpans[isIdx]));
            }
            listEl.appendChild(li);
          }
          containerEl.appendChild(listEl);
        } else if (blk.type === 'image_attachment' && blk.fileId) {
          renderedAnyContent = true;
          (function (imgBlock) {
            var fig = document.createElement('figure');
            fig.className = 'pb-rt-attachment-figure';
            if (imgBlock.widthPct && Number(imgBlock.widthPct) > 0) {
              var wPct = Math.min(100, Math.max(20, Math.round(Number(imgBlock.widthPct))));
              fig.classList.add('has-custom-width');
              fig.style.width = wPct + '%';
            }

            var badge = document.createElement('span');
            badge.className = 'badge badge-ok';
            badge.style.marginBottom = '6px';
            badge.textContent = 'Loading image...';
            fig.appendChild(badge);

            var imgEl = document.createElement('img');
            imgEl.className = 'pb-rt-attachment-img is-zoomable hidden';
            imgEl.alt = imgBlock.altText || imgBlock.caption || 'Question illustration';
            imgEl.referrerPolicy = 'no-referrer';
            if (fig.classList.contains('has-custom-width')) {
              imgEl.style.width = '100%';
            }
            fig.appendChild(imgEl);

            if (imgBlock.caption && !/\.(png|jpe?g|webp|gif|svg|bmp)$/i.test(String(imgBlock.caption).trim())) {
              var cap = document.createElement('figcaption');
              cap.className = 'pb-rt-attachment-caption';
              cap.textContent = imgBlock.caption;
              fig.appendChild(cap);
            }
            var actionBar = document.createElement('div');
            actionBar.className = 'pb-rt-figure-actions';
            var zoomBtn = document.createElement('button');
            zoomBtn.type = 'button';
            zoomBtn.className = 'btn btn-outline btn-sm';
            setElementVectorIconLabel(zoomBtn, 'zoom-in', 'Zoom / Inspect Image', 'pb-icon-xs');
            var fetchedEntryRef = null;
            function openThisImageZoom() {
              openInAppImageZoomModal(
                fetchedEntryRef || imgBlock.fileId,
                effectiveCourseId,
                imgBlock.altText || imgBlock.caption || 'Question Image'
              );
            }
            zoomBtn.addEventListener('click', openThisImageZoom);
            imgEl.addEventListener('click', openThisImageZoom);
            actionBar.appendChild(zoomBtn);
            fig.appendChild(actionBar);

            PBObjectUrlManager.fetchAndCreateObjectUrl(imgBlock.fileId, effectiveCourseId)
              .then(function (entry) {
                fetchedEntryRef = entry;
                PBObjectUrlManager.attachDriveImageFallback(imgEl, entry, function () {
                  if (badge) {
                    badge.className = 'badge badge-incomplete';
                    badge.textContent = 'Image Unavailable (Check Drive permissions or config)';
                  }
                });
                imgEl.src = entry.objectUrl;
                imgEl.classList.remove('hidden');
                if (badge && badge.parentNode) {
                  badge.parentNode.removeChild(badge);
                }
              })
              .catch(function (err) {
                badge.className = 'badge badge-incomplete';
                badge.textContent =
                  'Image Protected / Unavailable (' + (err.code || 'ERR') + ')';
              });

            containerEl.appendChild(fig);
          })(blk);
        } else if (blk.type === 'pdf_attachment' && blk.fileId) {
          var blkTitleCheck = String(blk.title || '').trim();
          if (
            blkTitleCheck.indexOf('[PB_EXAM_PAPER_PDF]') === 0 ||
            blkTitleCheck.indexOf('[PB_ANSWER_SHEET_PDF:') === 0
          ) {
            continue;
          }
          renderedAnyContent = true;
          (function (pdfBlock) {
            var allowPdfDownload = pdfBlock.allowDownload !== false;
            var isEmbeddedPdf =
              String(pdfBlock.displayMode || '').toLowerCase() === 'embed' ||
              Boolean(pdfBlock.heightPx) ||
              Boolean(pdfBlock.widthPct) ||
              Boolean(
                renderOpts.defaultEmbedPdf &&
                  String(pdfBlock.displayMode || '').toLowerCase() !== 'card'
              );
            if (isEmbeddedPdf) {
              var embedBox = document.createElement('div');
              embedBox.className = 'pb-rt-pdf-embed-box' + (allowPdfDownload ? '' : ' is-view-only');
              if (!allowPdfDownload) {
                embedBox.addEventListener('contextmenu', function (ev) {
                  ev.preventDefault();
                });
              }
              var pWidth = pdfBlock.widthPct
                ? Math.min(100, Math.max(30, Math.round(Number(pdfBlock.widthPct))))
                : 100;
              var pHeight = pdfBlock.heightPx
                ? Math.min(900, Math.max(180, Math.round(Number(pdfBlock.heightPx))))
                : 420;
              if (pWidth < 100) {
                embedBox.classList.add('has-custom-width');
                embedBox.style.width = pWidth + '%';
              }

              var bar = document.createElement('div');
              bar.className = 'pb-rt-pdf-embed-toolbar';
              var titleGrp = document.createElement('div');
              titleGrp.className = 'pb-rt-pdf-embed-title-group';
              var pBadge = document.createElement('span');
              pBadge.className = 'badge badge-ok';
              pBadge.textContent = 'PDF';
              titleGrp.appendChild(pBadge);
              var pTitle = document.createElement('span');
              pTitle.className = 'pb-rt-pdf-embed-title';
              pTitle.textContent = pdfBlock.title || pdfBlock.filename || 'Attached PDF Document';
              titleGrp.appendChild(pTitle);
              if (!allowPdfDownload) {
                var voPill = document.createElement('span');
                voPill.className = 'pb-pdf-viewonly-pill';
                voPill.appendChild(PBIcons.create('shield-lock', 'pb-icon-xs'));
                var voTxt = document.createElement('span');
                voTxt.textContent = 'View Only';
                voPill.appendChild(voTxt);
                titleGrp.appendChild(voPill);
              }
              bar.appendChild(titleGrp);

              var actGrp = document.createElement('div');
              actGrp.className = 'pb-rt-pdf-embed-actions';

              var curHeightPx = pHeight;
              var zoomModalBtn = document.createElement('button');
              zoomModalBtn.type = 'button';
              zoomModalBtn.className = 'btn btn-secondary btn-sm';
              setElementVectorIconLabel(zoomModalBtn, 'zoom-in', 'Zoom / Full View', 'pb-icon-xs');
              zoomModalBtn.addEventListener('click', function () {
                openOrDownloadExamPdfWithNotice(
                  zoomModalBtn,
                  pdfBlock.fileId,
                  effectiveCourseId,
                  true,
                  'Zoom / Full View',
                  { allowDownload: allowPdfDownload }
                );
              });
              actGrp.appendChild(zoomModalBtn);

              var fitHeightBtn = document.createElement('button');
              fitHeightBtn.type = 'button';
              fitHeightBtn.className = 'btn btn-outline btn-sm';
              fitHeightBtn.textContent = curHeightPx > 500 ? 'Compact View' : 'Expand View';
              actGrp.appendChild(fitHeightBtn);

              if (allowPdfDownload) {
                var dlPdfBtn = document.createElement('button');
                dlPdfBtn.type = 'button';
                dlPdfBtn.className = 'btn btn-outline btn-sm';
                setElementVectorIconLabel(dlPdfBtn, 'download', 'Download', 'pb-icon-xs');
                dlPdfBtn.addEventListener('click', function () {
                  openOrDownloadExamPdfWithNotice(
                    dlPdfBtn,
                    pdfBlock.fileId,
                    effectiveCourseId,
                    false,
                    'Download',
                    { allowDownload: true }
                  );
                });
                actGrp.appendChild(dlPdfBtn);
              }
              bar.appendChild(actGrp);
              embedBox.appendChild(bar);

              var frameWrap = document.createElement('div');
              frameWrap.className = 'pb-rt-pdf-embed-frame-wrap';
              var loadingLbl = document.createElement('div');
              loadingLbl.className = 'pb-rt-pdf-embed-loading';
              loadingLbl.textContent = 'Loading embedded PDF object...';
              frameWrap.appendChild(loadingLbl);

              var pdfFrame = null;
              function mountEmbeddedPdfFrame() {
                if (pdfFrame && pdfFrame.parentNode === frameWrap) {
                  return;
                }
                loadingLbl.textContent = 'Loading embedded PDF object...';
                loadingLbl.classList.remove('hidden');
                pdfFrame = document.createElement('iframe');
                pdfFrame.className = 'pb-rt-pdf-embed-frame hidden';
                pdfFrame.style.height = curHeightPx + 'px';
                pdfFrame.setAttribute('loading', 'lazy');
                pdfFrame.title = pdfBlock.title || 'Embedded Question PDF';
                frameWrap.appendChild(pdfFrame);

                PBObjectUrlManager.fetchAndCreateObjectUrl(pdfBlock.fileId, effectiveCourseId, {
                  skipRevokeCheck: true
                })
                  .then(function (entry) {
                    if (entry && entry.objectUrl && pdfFrame && pdfFrame.parentNode === frameWrap) {
                      pdfFrame.src = allowPdfDownload
                        ? entry.objectUrl
                        : entry.objectUrl + '#toolbar=0&navpanes=0';
                      pdfFrame.classList.remove('hidden');
                      loadingLbl.classList.add('hidden');
                    }
                  })
                  .catch(function (err) {
                    loadingLbl.textContent = allowPdfDownload
                      ? 'Unable to embed PDF (' + ((err && err.code) || 'ERR') + '). Use Download or Zoom above.'
                      : 'Unable to embed PDF (' + ((err && err.code) || 'ERR') + '). Use Zoom / Full View above.';
                    loadingLbl.classList.remove('hidden');
                  });
              }
              frameWrap._pbPdfMountFn = mountEmbeddedPdfFrame;

              fitHeightBtn.addEventListener('click', function () {
                curHeightPx = curHeightPx > 500 ? 320 : 580;
                if (pdfFrame) {
                  pdfFrame.style.height = curHeightPx + 'px';
                }
                fitHeightBtn.textContent = curHeightPx > 500 ? 'Compact View' : 'Expand View';
              });

              embedBox.appendChild(frameWrap);
              containerEl.appendChild(embedBox);
              mountEmbeddedPdfFrame();
              return;
            }

            var card = document.createElement('div');
            card.className = 'pb-rt-pdf-attachment-card';

            var infoDiv = document.createElement('div');
            var pdfBadge = document.createElement('span');
            pdfBadge.className = 'badge badge-ok';
            pdfBadge.textContent = allowPdfDownload ? 'Private PDF Attachment' : 'Private View-Only PDF';
            infoDiv.appendChild(pdfBadge);

            var titleStrong = document.createElement('div');
            titleStrong.style.fontWeight = '700';
            titleStrong.style.marginTop = '4px';
            titleStrong.style.color = 'var(--color-brand-deep)';
            titleStrong.textContent =
              pdfBlock.title || pdfBlock.filename || pdfBlock.fileId;
            infoDiv.appendChild(titleStrong);

            var idNote = document.createElement('div');
            idNote.style.fontSize = '0.78rem';
            idNote.style.color = 'var(--color-text-muted)';
            idNote.textContent = allowPdfDownload
              ? 'Protected Course Document • Ready for authorized viewing'
              : 'View Only Document • Download disabled by instructor';
            idNote.title = 'File ID: ' + (pdfBlock.fileId || '');
            infoDiv.appendChild(idNote);
            card.appendChild(infoDiv);

            var btnGroup = document.createElement('div');
            btnGroup.style.display = 'flex';
            btnGroup.style.gap = '6px';
            btnGroup.style.flexWrap = 'wrap';

            var viewModalBtn = document.createElement('button');
            viewModalBtn.type = 'button';
            viewModalBtn.className = 'btn btn-secondary btn-sm';
            viewModalBtn.textContent = 'View / Zoom PDF';
            viewModalBtn.addEventListener('click', function () {
              openOrDownloadExamPdfWithNotice(
                viewModalBtn,
                pdfBlock.fileId,
                effectiveCourseId,
                true,
                'View / Zoom PDF',
                { allowDownload: allowPdfDownload }
              );
            });
            btnGroup.appendChild(viewModalBtn);

            if (allowPdfDownload) {
              var dlBtn = document.createElement('button');
              dlBtn.type = 'button';
              dlBtn.className = 'btn btn-primary btn-sm';
              dlBtn.textContent = 'Download PDF';
              dlBtn.addEventListener('click', function () {
                dlBtn.disabled = true;
                dlBtn.textContent = 'Authorizing PDF...';
                PBObjectUrlManager.triggerAuthorizedDownload(
                  pdfBlock.fileId,
                  effectiveCourseId,
                  false
                )
                  .then(function () {
                    dlBtn.disabled = false;
                    dlBtn.textContent = 'Download PDF (Ready)';
                  })
                  .catch(function (err) {
                    dlBtn.disabled = false;
                    dlBtn.textContent = 'Download PDF';
                    showUiErrorBanner(err);
                  });
              });
              btnGroup.appendChild(dlBtn);
            }

            card.appendChild(btnGroup);
            containerEl.appendChild(card);
          })(blk);
        }
      }

      var currentChildCount = containerEl.childNodes ? containerEl.childNodes.length : (containerEl.children ? containerEl.children.length : 0);
      if (!renderedAnyContent && currentChildCount <= 1) {
        var placeholder = document.createElement('p');
        placeholder.className = 'pb-rt-empty';
        placeholder.style.color = 'var(--color-text-muted)';
        placeholder.style.fontStyle = 'italic';
        placeholder.textContent = 'No content recorded yet.';
        while (containerEl.firstChild) {
          containerEl.removeChild(containerEl.firstChild);
        }
        containerEl.appendChild(placeholder);
      }
    }

