    function forceRestoreLoadingButton(btnOrId) {
      var btnEl =
        typeof btnOrId === 'string'
          ? document.getElementById(btnOrId)
          : btnOrId;
      if (!btnEl) return;
      if (typeof btnEl._pbLoadingRestore === 'function') {
        btnEl._pbLoadingRestore();
        return;
      }
      if (btnEl.dataset) delete btnEl.dataset.pbBusy;
      btnEl.disabled = false;
      btnEl.classList.remove('is-btn-loading');
      btnEl.removeAttribute('aria-busy');
    }

    function runButtonWithLoadingState(btnEl, busyLabel, promiseFactory) {
      if (!btnEl) {
        return Promise.resolve().then(promiseFactory);
      }
      if (btnEl.dataset && btnEl.dataset.pbBusy === '1') {
        return Promise.resolve();
      }
      var savedFragment = document.createDocumentFragment();
      for (var cIdx = 0; cIdx < btnEl.childNodes.length; cIdx++) {
        savedFragment.appendChild(btnEl.childNodes[cIdx].cloneNode(true));
      }
      var origDisabled = Boolean(btnEl.disabled);
      if (btnEl.dataset) btnEl.dataset.pbBusy = '1';
      btnEl.disabled = true;
      btnEl.classList.add('is-btn-loading');
      btnEl.setAttribute('aria-busy', 'true');
      if (busyLabel) {
        btnEl.textContent = busyLabel;
      }
      var restored = false;
      function restore() {
        if (restored) return;
        restored = true;
        if (btnEl._pbLoadingRestore === restore) {
          delete btnEl._pbLoadingRestore;
        }
        if (btnEl.dataset) delete btnEl.dataset.pbBusy;
        btnEl.disabled = origDisabled;
        btnEl.classList.remove('is-btn-loading');
        btnEl.removeAttribute('aria-busy');
        if (busyLabel) {
          while (btnEl.firstChild) btnEl.removeChild(btnEl.firstChild);
          btnEl.appendChild(savedFragment.cloneNode(true));
        }
      }
      btnEl._pbLoadingRestore = restore;
      var p;
      try {
        p = Promise.resolve().then(promiseFactory);
      } catch (syncErr) {
        restore();
        return Promise.reject(syncErr);
      }
      return p.then(
        function (res) {
          restore();
          return res;
        },
        function (err) {
          restore();
          throw err;
        }
      );
    }

    function renderDirectImageElementIntoStage(stageOrId, fileId, courseId, altText) {
      var stage = typeof stageOrId === 'string' ? document.getElementById(stageOrId) : stageOrId;
      if (!stage) return;
      clearChildren(stage);
      var cleanId = String(fileId || '').trim();
      if (!cleanId) return;

      if (currentQBankLocalImagePreviewDataUrlByIdPhase2 && currentQBankLocalImagePreviewDataUrlByIdPhase2[cleanId]) {
        stage.classList.remove('pb-img-stage-loading');
        var localImg = document.createElement('img');
        localImg.className = 'pb-actual-image-preview is-zoomable';
        localImg.src = currentQBankLocalImagePreviewDataUrlByIdPhase2[cleanId];
        localImg.alt = altText || ('Diagram ' + cleanId);
        localImg.title = 'Click to Zoom / Inspect Diagram';
        localImg.addEventListener('click', function () {
          openInAppImageZoomModal(cleanId, courseId || '', localImg.alt);
        });
        stage.appendChild(localImg);
        return;
      }

      stage.classList.add('pb-img-stage-loading');
      var skel = document.createElement('div');
      skel.className = 'pb-skeleton-line';
      skel.style.width = '86%';
      skel.style.height = '82%';
      skel.style.borderRadius = '10px';
      stage.appendChild(skel);

      PBObjectUrlManager.fetchAndCreateObjectUrl(cleanId, courseId || '')
        .then(function (entry) {
          stage.classList.remove('pb-img-stage-loading');
          clearChildren(stage);
          if (entry && entry.objectUrl) {
            currentQBankLocalImagePreviewDataUrlByIdPhase2[cleanId] = entry.objectUrl;
            var img = document.createElement('img');
            img.className = 'pb-actual-image-preview is-zoomable';
            img.src = entry.objectUrl;
            img.alt = altText || entry.originalFilename || ('Diagram ' + cleanId);
            img.title = 'Click to Zoom / Inspect Diagram';
            img.addEventListener('click', function () {
              openInAppImageZoomModal(entry, courseId || '', img.alt);
            });
            stage.appendChild(img);
          }
        })
        .catch(function () {
          stage.classList.remove('pb-img-stage-loading');
          clearChildren(stage);
          var fallbackSvg =
            'data:image/svg+xml;utf8,' +
            encodeURIComponent(
              '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 180"><rect width="320" height="180" rx="12" fill="#ECFEFF"/><circle cx="160" cy="76" r="34" fill="#CCFBF1" stroke="#0D9488" stroke-width="3"/><path d="M144 76h32M160 60v32" stroke="#0F766E" stroke-width="3" stroke-linecap="round"/><text x="160" y="142" text-anchor="middle" font-family="sans-serif" font-size="13" font-weight="700" fill="#0F766E">Biology Diagram (' +
                cleanId.replace(/[^A-Za-z0-9_-]/g, '') +
                ')</text></svg>'
            );
          var fbImg = document.createElement('img');
          fbImg.className = 'pb-actual-image-preview';
          fbImg.src = fallbackSvg;
          fbImg.alt = altText || ('Diagram ' + cleanId);
          stage.appendChild(fbImg);
        });
    }

    function parseClientImageFileIdsListPhase2(rawVal) {
      if (Array.isArray(rawVal)) {
        return rawVal
          .map(function (x) { return String(x || '').trim(); })
          .filter(Boolean)
          .slice(0, 8);
      }
      var str = String(rawVal || '').trim();
      if (!str) return [];
      var parts = str.split(',');
      var out = [];
      var seen = {};
      for (var i = 0; i < parts.length && out.length < 8; i++) {
        var id = String(parts[i] || '').trim();
        if (id && !seen[id]) {
          seen[id] = true;
          out.push(id);
        }
      }
      return out;
    }

    function formatFriendlyEnumStatus(rawVal) {
      var k = String(rawVal || '').trim().toUpperCase();
      var map = {
        SUBMITTED: 'Submitted',
        IN_PROGRESS: 'In Progress',
        EXPIRED_SUBMITTED: 'Submitted (Time Expired)',
        INVALIDATED_COPY_POLICY: 'Voided (Copy Policy)',
        GRADED: 'Graded',
        REGRADED: 'Regraded',
        AUTO_GRADED_PENDING_MANUAL: 'Pending Manual Review',
        MANUAL_REVIEW_PENDING: 'Pending Review',
        UNGRADED: 'Ungraded',
        PUBLISHED: 'Published',
        DRAFT: 'Draft',
        WITHHELD: 'Withheld',
        ARCHIVED: 'Archived',
        CORRECT: 'Correct',
        PARTIAL: 'Partial Credit',
        INCORRECT: 'Incorrect',
        UNANSWERED: 'Unanswered',
        CHECKED: 'Checked',
        AWAITING_VERIFICATION: 'Awaiting Verification',
        APPROVING: 'Verifying',
        PAID: 'Paid',
        REJECTED: 'Rejected',
        EASY: 'Easy',
        MEDIUM: 'Medium',
        HARD: 'Hard',
        OLYMPIAD: 'Olympiad',
        ASSIGNED: 'Assigned',
        REVOKED: 'Revoked',
        EXPIRED: 'Expired',
        SENT: 'Sent',
        PENDING_ATTEMPT: 'Pending',
        FAILED: 'Failed'
      };
      return map[k] || (k ? k.replace(/_/g, ' ') : '-');
    }

    function formatQuestionTypeDisplayLabel(qType, opt_compact, opt_optionCount) {
      var k = String(qType || 'SINGLE_CHOICE').trim().toUpperCase();
      var optN = Number(opt_optionCount || 0);
      if (opt_compact) {
        if (k === 'SINGLE_CHOICE') {
          return optN > 0 ? 'MC (' + optN + ' Opts)' : 'Multiple Choice';
        }
        var compactMap = {
          COMPLEX_MULTIPLE_CHOICE: 'Complex MC',
          MULTIPLE_SELECT: 'Multi-Select',
          TRUE_FALSE: 'True / False',
          NUMERIC_RESPONSE: 'Numeric',
          SHORT_ANSWER: 'Short Answer',
          WRITTEN_RESPONSE: 'Written'
        };
        return compactMap[k] || k.replace(/_/g, ' ');
      }
      if (k === 'SINGLE_CHOICE') {
        return optN > 0 ? 'Multiple Choice (' + optN + ' Opts)' : 'Multiple Choice';
      }
      var map = {
        COMPLEX_MULTIPLE_CHOICE: 'Complex MC (Yes/No)',
        MULTIPLE_SELECT: 'Multiple Select',
        TRUE_FALSE: 'True / False',
        NUMERIC_RESPONSE: 'Numeric Response',
        SHORT_ANSWER: 'Short Answer',
        WRITTEN_RESPONSE: 'Written Response'
      };
      return map[k] || k.replace(/_/g, ' ');
    }

    function renderComplexMultipleChoiceStatementsDom(containerEl, q, currentDecisionsMap, onChangeDecision, opt_courseId) {
      if (!containerEl) return;
      while (containerEl.firstChild) containerEl.removeChild(containerEl.firstChild);

      var opts = Array.isArray(q && q.options) ? q.options : [];
      var decMap = currentDecisionsMap && typeof currentDecisionsMap === 'object' ? currentDecisionsMap : {};

      var list = document.createElement('div');
      list.className = 'pb-complex-mc-card-list';

      for (var i = 0; i < opts.length; i++) {
        (function (opt, idx) {
          var curVal = String(decMap[opt.optionId] || '').toUpperCase();
          var row = document.createElement('div');
          row.className = 'pb-complex-mc-row' + (curVal === 'YES' || curVal === 'NO' ? ' is-decided' : '');

          var stmtWrap = document.createElement('div');
          stmtWrap.className = 'pb-complex-mc-stmt-wrap';

          var numEl = document.createElement('span');
          numEl.className = 'pb-complex-mc-num';
          numEl.textContent = String(opt.displayLabel || idx + 1) + '.';
          stmtWrap.appendChild(numEl);

          var bodyEl = document.createElement('div');
          bodyEl.className = 'pb-complex-mc-stmt-body pb-rt-rendered';
          renderRichTextDocumentToDom(bodyEl, opt.contentRichText || opt.text || '', opt_courseId || '', {
            defaultEmbedPdf: true
          });
          stmtWrap.appendChild(bodyEl);
          row.appendChild(stmtWrap);

          var tg = document.createElement('div');
          tg.className = 'pb-complex-mc-toggle-group';
          tg.setAttribute('role', 'group');
          tg.setAttribute('aria-label', 'Sub-statement ' + (idx + 1));

          var yesBtn = document.createElement('button');
          yesBtn.type = 'button';
          yesBtn.className = 'pb-complex-mc-toggle-pill is-yes' + (curVal === 'YES' ? ' is-selected' : '');
          yesBtn.textContent = 'Yes';
          yesBtn.setAttribute('aria-pressed', curVal === 'YES' ? 'true' : 'false');
          yesBtn.addEventListener('click', function () {
            if (typeof onChangeDecision === 'function') {
              onChangeDecision(opt.optionId, 'YES', opt, idx);
            }
          });
          tg.appendChild(yesBtn);

          var noBtn = document.createElement('button');
          noBtn.type = 'button';
          noBtn.className = 'pb-complex-mc-toggle-pill is-no' + (curVal === 'NO' ? ' is-selected' : '');
          noBtn.textContent = 'No';
          noBtn.setAttribute('aria-pressed', curVal === 'NO' ? 'true' : 'false');
          noBtn.addEventListener('click', function () {
            if (typeof onChangeDecision === 'function') {
              onChangeDecision(opt.optionId, 'NO', opt, idx);
            }
          });
          tg.appendChild(noBtn);

          row.appendChild(tg);
          list.appendChild(row);
        })(opts[i], i);
      }

      containerEl.appendChild(list);
    }

    function formatStudentResponseSummaryText(respPayload, opt_question, opt_emptyFallback) {
      var p = respPayload && typeof respPayload === 'object' ? respPayload : {};
      var opts = opt_question && Array.isArray(opt_question.options) ? opt_question.options : [];
      function resolveOptionReadableLabel(optionIdVal) {
        var targetId = String(optionIdVal || '').trim();
        if (!targetId) return '';
        for (var j = 0; j < opts.length; j++) {
          var o = opts[j] || {};
          var oid = o.optionId || o.option_id || '';
          if (oid === targetId) {
            var lbl = o.displayLabel || o.optionKey || String.fromCharCode(65 + j);
            var txt = o.plainTextSummary || o.text || '';
            if (!txt && o.contentRichText && typeof extractRichTextPlainSummarySafe === 'function') {
              txt = extractRichTextPlainSummarySafe(o.contentRichText);
            }
            return txt ? lbl + '. ' + txt : 'Choice ' + lbl;
          }
        }
        return 'Selected Choice';
      }
      if (p.statementDecisions && typeof p.statementDecisions === 'object') {
        var parts = [];
        if (opts.length > 0) {
          for (var i = 0; i < opts.length; i++) {
            var oid = opts[i].optionId || opts[i].option_id || '';
            var dVal = String(p.statementDecisions[oid] || '').toUpperCase();
            parts.push((i + 1) + ': ' + (dVal === 'YES' ? 'Yes' : dVal === 'NO' ? 'No' : '-'));
          }
        } else {
          var keys = Object.keys(p.statementDecisions);
          for (var k = 0; k < keys.length; k++) {
            var dk = String(p.statementDecisions[keys[k]] || '').toUpperCase();
            parts.push((k + 1) + ': ' + (dk === 'YES' ? 'Yes' : dk === 'NO' ? 'No' : '-'));
          }
        }
        if (parts.length > 0) return parts.join(' | ');
      }
      if (p.selectedOptionId) {
        return resolveOptionReadableLabel(p.selectedOptionId);
      }
      if (Array.isArray(p.selectedOptionIds) && p.selectedOptionIds.length > 0) {
        return p.selectedOptionIds.map(resolveOptionReadableLabel).join('; ');
      }
      return (
        p.textResponse ||
        p.numericText ||
        (opt_emptyFallback !== undefined ? opt_emptyFallback : '(No answer submitted)')
      );
    }

    function renderFormattedBiologyUnitDom(containerEl, rawUnit, opt_trim) {
      if (!containerEl) return;
      while (containerEl.firstChild) containerEl.removeChild(containerEl.firstChild);
      var txt = rawUnit === null || rawUnit === undefined ? '' : String(rawUnit);
      if (opt_trim) txt = txt.trim();
      if (!txt) return;

      txt = txt
        .replace(/\bumol\b/g, '\u00B5mol')
        .replace(/\bug\b/g, '\u00B5g')
        .replace(/\buL\b/g, '\u00B5L')
        .replace(/\buM\b/g, '\u00B5M')
        .replace(/\bum\b/g, '\u00B5m');

      var tokenRe = /\b(CO2|O2|H2O|N2|NH3|CH4)\b|\b(mg|ug|\u00B5g|g|kg|mmol|umol|\u00B5mol|mol|mL|uL|\u00B5L|L|mm|cm|dm|m|km|s|min|h|hr|d|yr)(?:-(\d+)|\^(-?\d+))|\b(mm|cm|dm|m|km)([23])\b/g;
      var lastIdx = 0;
      var m;
      while ((m = tokenRe.exec(txt)) !== null) {
        if (m.index > lastIdx) {
          containerEl.appendChild(document.createTextNode(txt.slice(lastIdx, m.index)));
        }
        if (m[1]) {
          var chem = m[1];
          for (var ci = 0; ci < chem.length; ci++) {
            var ch = chem.charAt(ci);
            if (ch >= '0' && ch <= '9') {
              var subEl = document.createElement('sub');
              subEl.textContent = ch;
              containerEl.appendChild(subEl);
            } else {
              containerEl.appendChild(document.createTextNode(ch));
            }
          }
        } else if (m[2]) {
          containerEl.appendChild(document.createTextNode(m[2]));
          var supTxt = m[3] ? '\u2212' + m[3] : String(m[4] || '').replace(/^-/, '\u2212');
          var supEl = document.createElement('sup');
          supEl.textContent = supTxt;
          containerEl.appendChild(supEl);
        } else if (m[5]) {
          containerEl.appendChild(document.createTextNode(m[5]));
          var areaSup = document.createElement('sup');
          areaSup.textContent = m[6];
          containerEl.appendChild(areaSup);
        }
        lastIdx = tokenRe.lastIndex;
      }
      if (lastIdx < txt.length) {
        containerEl.appendChild(document.createTextNode(txt.slice(lastIdx)));
      }
    }

    function resolveChoiceOptionPresentation(qType, opt, oIdx) {
      var isTrueFalse = qType === 'TRUE_FALSE';
      var rawKey = String((opt && (opt.displayLabel || opt.optionKey)) || '').trim();
      var rawKeyUpper = rawKey.toUpperCase();
      var tfBool = null;
      if (isTrueFalse) {
        tfBool = rawKeyUpper === 'FALSE' || rawKeyUpper === 'F' ? false : rawKeyUpper === 'TRUE' || rawKeyUpper === 'T' ? true : oIdx === 0;
      }
      var keyText = isTrueFalse
        ? (tfBool ? 'T' : 'F')
        : (rawKey || String.fromCharCode(65 + (Number(oIdx) || 0)));

      return {
        isTrueFalse: isTrueFalse,
        tfSemantic: isTrueFalse ? (tfBool ? 'true' : 'false') : '',
        keyText: keyText,
        canonicalTfText: isTrueFalse ? (tfBool ? 'True' : 'False') : ''
      };
    }

    var qbankWordStatePhase2 = {
      toolbarMounted: false,
      stemEditor: null,
      expEditor: null,
      optionEditors: {},
      optionDocs: {}
    };

    function mountQBankWordEditorOnControl(controlId, editorKey, isStem, placeholder, isSingleLine) {
      var origEl = document.getElementById(controlId);
      if (!origEl || !origEl.parentNode) return null;
      var existing =
        editorKey === 'stem'
          ? qbankWordStatePhase2.stemEditor
          : editorKey === 'explanation'
          ? qbankWordStatePhase2.expEditor
          : qbankWordStatePhase2.optionEditors[editorKey];
      if (existing && existing.element && existing.element.parentNode === origEl.parentNode) {
        return existing;
      }
      if (origEl.hasAttribute('required')) {
        origEl.removeAttribute('required');
      }
      origEl.classList.add('hidden');
      var ed = PBWordRichEditor.createInput({
        isStem: Boolean(isStem),
        isSingleLine: Boolean(isSingleLine),
        placeholder: placeholder || '',
        initialValue: origEl.value || '',
        ariaLabel: origEl.getAttribute('aria-label') || placeholder || editorKey,
        onChange: function (doc, plainTxt) {
          origEl.value = plainTxt;
          if (editorKey !== 'stem' && editorKey !== 'explanation') {
            qbankWordStatePhase2.optionDocs[editorKey] = doc;
          }
        },
        onMediaChange: function () {
          if (editorKey === 'stem') {
            renderQBankStemRichMediaTrayPhase2();
          }
        }
      });
      if (isSingleLine) {
        ed.element.style.flex = '1';
      }
      origEl.parentNode.insertBefore(ed.element, origEl.nextSibling);
      if (editorKey === 'stem') {
        qbankWordStatePhase2.stemEditor = ed;
        renderQBankStemRichMediaTrayPhase2();
      } else if (editorKey === 'explanation') qbankWordStatePhase2.expEditor = ed;
      else qbankWordStatePhase2.optionEditors[editorKey] = ed;
      return ed;
    }

    function renderQBankStemRichMediaTrayPhase2() {
      var host = document.getElementById('qbank-stem-rich-media-tray');
      var ed = qbankWordStatePhase2.stemEditor;
      if (!host || !ed) return;
      while (host.firstChild) host.removeChild(host.firstChild);

      var bar = document.createElement('div');
      bar.style.display = 'flex';
      bar.style.alignItems = 'center';
      bar.style.gap = '6px';
      bar.style.flexWrap = 'wrap';

      var imgInp = document.createElement('input');
      imgInp.type = 'file';
      imgInp.accept = 'image/png,image/jpeg,image/webp,image/gif';
      imgInp.className = 'hidden';
      var imgBtn = document.createElement('button');
      imgBtn.type = 'button';
      imgBtn.className = 'btn btn-outline btn-sm';
      setElementVectorIconLabel(imgBtn, 'image', 'Add Diagram', 'pb-icon-xs');
      imgBtn.addEventListener('click', function () { imgInp.click(); });
      imgInp.addEventListener('change', function () {
        var f = imgInp.files && imgInp.files[0];
        if (!f) return;
        runButtonWithLoadingState(imgBtn, 'Uploading...', function () {
          return uploadQuestionStemAttachmentFile(f, 'image', '').then(function (res) {
            ed.addMediaBlock({
              type: 'image_attachment',
              fileId: res.fileId,
              altText: String(res.originalFilename || 'Question diagram').replace(/\.[^.]+$/, ''),
              caption: '',
              widthPct: 75
            });
            imgInp.value = '';
            PBNotify.toast('success', 'Image Embedded', 'Added resizable diagram ' + res.fileId + ' to stem.');
          });
        });
      });

      var pdfInp = document.createElement('input');
      pdfInp.type = 'file';
      pdfInp.accept = 'application/pdf,.pdf';
      pdfInp.className = 'hidden';
      var pdfBtn = document.createElement('button');
      pdfBtn.type = 'button';
      pdfBtn.className = 'btn btn-outline btn-sm';
      setElementVectorIconLabel(pdfBtn, 'file-pdf', 'Embed PDF', 'pb-icon-xs');
      var qPdfAllowDlToggle = createPdfDownloadTogglePill(true);
      pdfBtn.addEventListener('click', function () { pdfInp.click(); });
      pdfInp.addEventListener('change', function () {
        var f = pdfInp.files && pdfInp.files[0];
        if (!f) return;
        runButtonWithLoadingState(pdfBtn, 'Uploading PDF...', function () {
          return uploadQuestionStemAttachmentFile(f, 'pdf', '').then(function (res) {
            var allowDl = qPdfAllowDlToggle.isAllowed();
            ed.addMediaBlock({
              type: 'pdf_attachment',
              fileId: res.fileId,
              title: res.originalFilename || 'Question PDF Reference.pdf',
              displayMode: 'embed',
              widthPct: 100,
              heightPx: 420,
              allowDownload: allowDl
            });
            pdfInp.value = '';
            PBNotify.toast(
              'success',
              'PDF Embedded',
              'Attached embedded PDF ' + res.fileId + (allowDl ? ' (Downloadable).' : ' (View Only / No Download).')
            );
          });
        });
      });

      var tblBtn = document.createElement('button');
      tblBtn.type = 'button';
      tblBtn.className = 'btn btn-outline btn-sm';
      setElementVectorIconLabel(tblBtn, 'table', 'Add Table (.xlsx / .gsheet)', 'pb-icon-xs');
      tblBtn.addEventListener('click', function () {
        openQuestionTableEditorModal(null, function (tblBlock) {
          ed.addMediaBlock(tblBlock);
          PBNotify.toast('success', 'Table Added', 'Embedded structured table into question stem.');
        });
      });

      bar.appendChild(imgInp);
      bar.appendChild(imgBtn);
      bar.appendChild(pdfInp);
      bar.appendChild(pdfBtn);
      bar.appendChild(qPdfAllowDlToggle.element);
      bar.appendChild(tblBtn);
      host.appendChild(bar);

      var listHost = document.createElement('div');
      host.appendChild(listHost);
      renderQuestionRichMediaTray(listHost, ed.getMediaBlocks(), {
        courseId: '',
        onUpdate: function (nextBlocks) {
          ed.setMediaBlocks(nextBlocks);
        }
      });
    }

    function ensureAllQBankWordEditorsMountedPhase2() {
      var qEditorForm = document.getElementById('form-admin-question-editor');
      var dockEl = document.getElementById('qbank-word-toolbar-dock');
      if (dockEl && !qbankWordStatePhase2.toolbarMounted) {
        PBWordRichEditor.renderToolbarInto(dockEl, qEditorForm || document.body);
        qbankWordStatePhase2.toolbarMounted = true;
      }
      mountQBankWordEditorOnControl(
        'textarea-qbank-stem',
        'stem',
        true,
        'Enter biology question stem (Ctrl+B/I/U, Ctrl+= Subscript, Ctrl+Shift+= Superscript, \\beta- for β-)...',
        false
      );
      mountQBankWordEditorOnControl(
        'textarea-qbank-explanation',
        'explanation',
        false,
        'Explain the biological mechanism behind the answer (supports Sub/Sup & Greek)...',
        false
      );
      for (var i = 0; i < 10; i++) {
        var inp = document.getElementById('input-qbank-opt-text-' + i);
        if (inp) {
          mountQBankWordEditorOnControl(
            'input-qbank-opt-text-' + i,
            'opt_' + i,
            false,
            'Option ' + String.fromCharCode(65 + i) + ' text (Ctrl+= Sub, Ctrl+Shift+= Sup, \\beta-)...',
            true
          );
        }
      }
    }

    function updateQBankOptionsCountBadgePhase2() {
      var badge = document.getElementById('qbank-options-count-badge');
      var typeSel = document.getElementById('select-qbank-type');
      var qType = typeSel ? typeSel.value : 'SINGLE_CHOICE';
      if (!badge) return;
      if (qType === 'TRUE_FALSE') {
        badge.textContent = '2 Choices (True / False)';
      } else if (qType === 'COMPLEX_MULTIPLE_CHOICE') {
        badge.textContent = String(currentQBankActiveOptionCountPhase2) + ' Sub-Statements (Yes / No)';
      } else {
        var lastLetter = String.fromCharCode(64 + Math.max(2, currentQBankActiveOptionCountPhase2));
        badge.textContent = String(currentQBankActiveOptionCountPhase2) + ' Choices (A–' + lastLetter + ')';
      }
    }

    function setQBankOptionRowCountPhase2(targetCount) {
      var count = Math.min(10, Math.max(2, Number(targetCount) || 5));
      currentQBankActiveOptionCountPhase2 = count;

      // Toggle visibility of rows 2 and 3 (C and D) if count < 4
      for (var baseIdx = 0; baseIdx < 4; baseIdx++) {
        var chkEl = document.getElementById('chk-qbank-opt-correct-' + baseIdx);
        var rowEl = chkEl && chkEl.parentNode ? chkEl.parentNode : null;
        if (rowEl && rowEl.classList) {
          rowEl.classList.toggle('hidden', baseIdx >= count);
        }
      }

      var extraHost = document.getElementById('qbank-extra-options-container');
      if (extraHost) {
        // Preserve existing values in extra rows before rebuilding
        var savedExtra = {};
        for (var k = 4; k < 10; k++) {
          var exTxt = document.getElementById('input-qbank-opt-text-' + k);
          var exChk = document.getElementById('chk-qbank-opt-correct-' + k);
          var exPin = document.getElementById('select-qbank-opt-pin-' + k);
          var exEd = qbankWordStatePhase2.optionEditors['opt_' + k];
          if (exTxt || exChk || exPin) {
            savedExtra[k] = {
              text: exTxt ? exTxt.value : '',
              doc: exEd ? exEd.getValueDoc() : qbankWordStatePhase2.optionDocs['opt_' + k] || null,
              checked: Boolean(exChk && exChk.checked),
              pin: exPin ? exPin.value : 'NONE'
            };
          }
          delete qbankWordStatePhase2.optionEditors['opt_' + k];
        }
        clearChildren(extraHost);
        for (var idx = 4; idx < count; idx++) {
          (function (optIndex) {
            var letter = String.fromCharCode(65 + optIndex);
            var row = document.createElement('div');
            row.className = 'qbank-option-edit-row';
            row.style.display = 'flex';
            row.style.gap = '8px';
            row.style.alignItems = 'center';

            var chk = document.createElement('input');
            chk.type = 'checkbox';
            chk.id = 'chk-qbank-opt-correct-' + optIndex;
            chk.setAttribute('aria-label', 'Option ' + letter + ' is correct');
            if (savedExtra[optIndex]) chk.checked = savedExtra[optIndex].checked;
            row.appendChild(chk);

            var strong = document.createElement('strong');
            strong.style.minWidth = '22px';
            strong.textContent = letter + '.';
            row.appendChild(strong);

            var inp = document.createElement('input');
            inp.type = 'text';
            inp.className = 'form-input';
            inp.id = 'input-qbank-opt-text-' + optIndex;
            inp.placeholder = 'Option ' + letter + ' text';
            inp.style.flex = '1';
            if (savedExtra[optIndex]) inp.value = savedExtra[optIndex].text;
            row.appendChild(inp);

            var sel = document.createElement('select');
            sel.className = 'form-input';
            sel.id = 'select-qbank-opt-pin-' + optIndex;
            sel.style.width = '110px';
            sel.style.fontSize = '0.78rem';
            var pins = [
              { v: 'NONE', l: 'Shuffle OK' },
              { v: 'LAST', l: 'Pin Last' },
              { v: 'FIXED', l: 'Pin Fixed' }
            ];
            for (var p = 0; p < pins.length; p++) {
              var o = document.createElement('option');
              o.value = pins[p].v;
              o.textContent = pins[p].l;
              sel.appendChild(o);
            }
            if (savedExtra[optIndex]) sel.value = savedExtra[optIndex].pin;
            row.appendChild(sel);

            var rmBtn = document.createElement('button');
            rmBtn.type = 'button';
            rmBtn.className = 'btn btn-outline btn-sm';
            rmBtn.textContent = 'Remove';
            rmBtn.setAttribute('aria-label', 'Remove Option ' + letter);
            rmBtn.addEventListener('click', function () {
              removeSpecificQBankOptionRowPhase2(optIndex);
            });
            row.appendChild(rmBtn);

            extraHost.appendChild(row);
            var mountedEd = mountQBankWordEditorOnControl(
              'input-qbank-opt-text-' + optIndex,
              'opt_' + optIndex,
              false,
              'Option ' + letter + ' text (Ctrl+= Sub, Ctrl+Shift+= Sup)...',
              true
            );
            if (mountedEd && savedExtra[optIndex] && savedExtra[optIndex].doc) {
              mountedEd.setValue(savedExtra[optIndex].doc);
              qbankWordStatePhase2.optionDocs['opt_' + optIndex] = savedExtra[optIndex].doc;
            }
          })(idx);
        }
      }
      ensureAllQBankWordEditorsMountedPhase2();
      updateQBankOptionsCountBadgePhase2();
    }

    function removeSpecificQBankOptionRowPhase2(removeIdx) {
      if (currentQBankActiveOptionCountPhase2 <= 2) return;
      var allVals = [];
      for (var i = 0; i < currentQBankActiveOptionCountPhase2; i++) {
        if (i === removeIdx) continue;
        var tEl = document.getElementById('input-qbank-opt-text-' + i);
        var cEl = document.getElementById('chk-qbank-opt-correct-' + i);
        var pEl = document.getElementById('select-qbank-opt-pin-' + i);
        var edEl = qbankWordStatePhase2.optionEditors['opt_' + i];
        allVals.push({
          text: tEl ? tEl.value : '',
          doc: edEl ? edEl.getValueDoc() : qbankWordStatePhase2.optionDocs['opt_' + i] || null,
          checked: Boolean(cEl && cEl.checked),
          pin: pEl ? pEl.value : 'NONE'
        });
      }
      setQBankOptionRowCountPhase2(allVals.length);
      for (var j = 0; j < allVals.length; j++) {
        var tEl2 = document.getElementById('input-qbank-opt-text-' + j);
        var cEl2 = document.getElementById('chk-qbank-opt-correct-' + j);
        var pEl2 = document.getElementById('select-qbank-opt-pin-' + j);
        var edEl2 = qbankWordStatePhase2.optionEditors['opt_' + j];
        if (tEl2) tEl2.value = allVals[j].text;
        if (edEl2) edEl2.setValue(allVals[j].doc || allVals[j].text);
        if (cEl2) cEl2.checked = allVals[j].checked;
        if (pEl2) pEl2.value = allVals[j].pin;
      }
    }

