    function populateAdminExamEditorForEditPhase3(examDto) {
      resetAdminExamEditorFormPhase3();
      if (!examDto) return;
      var idEl = document.getElementById('input-exam-editor-id');
      var verEl = document.getElementById('input-exam-editor-expected-version');
      if (idEl) idEl.value = examDto.examSetId || '';
      if (verEl) verEl.value = String(examDto.version || 1);
      setText(
        'exam-editor-mode-badge',
        'Edit Exam (' + (examDto.status || 'DRAFT') + ' | Latest v' + (examDto.latestVersionNo || 1) + ')'
      );
      setText('exam-editor-heading', 'Edit Examination Set: ' + (examDto.examCode || ''));

      var codeEl = document.getElementById('input-exam-editor-code');
      var titleEl = document.getElementById('input-exam-editor-title');
      var crsEl = document.getElementById('select-exam-editor-course');
      var modeEl = document.getElementById('select-exam-editor-mode');
      var durEl = document.getElementById('input-exam-editor-duration');
      var maxAttEl = document.getElementById('input-exam-editor-max-attempts');
      var openEl = document.getElementById('input-exam-editor-open-at');
      var closeEl = document.getElementById('input-exam-editor-close-at');
      var scPolEl = document.getElementById('select-exam-editor-score-policy');
      var exPolEl = document.getElementById('select-exam-editor-explanation-policy');
      var aggEl = document.getElementById('select-exam-editor-aggregation');
      var passEl = document.getElementById('input-exam-editor-pass-pct');
      var rqEl = document.getElementById('chk-exam-editor-rand-questions');
      var roEl = document.getElementById('chk-exam-editor-rand-options');
      var pfEl = document.getElementById('chk-exam-editor-practice-feedback');
      var descEl = document.getElementById('textarea-exam-editor-description');
      var instEl = document.getElementById('textarea-exam-editor-instructions');

      if (codeEl) codeEl.value = examDto.examCode || '';
      if (titleEl) titleEl.value = examDto.title || '';
      if (crsEl) crsEl.value = examDto.courseId || '';
      if (modeEl) modeEl.value = examDto.examMode || 'MOCK_EXAM';
      if (durEl) durEl.value = String(examDto.durationMinutes || 0);
      var resolvedEditorMaxAtt =
        examDto.maxAttempts !== undefined && examDto.maxAttempts !== null
          ? Number(examDto.maxAttempts)
          : examDto.examMode === 'PRACTICE'
          ? 0
          : 1;
      if (maxAttEl) maxAttEl.value = String(resolvedEditorMaxAtt);
      var edAttPolEdit = document.getElementById('select-exam-editor-attempt-policy');
      if (edAttPolEdit && edAttPolEdit.dataset) edAttPolEdit.dataset.userTouched = '1';
      syncExamAttemptPolicyPairFromCount(
        'select-exam-editor-attempt-policy',
        'input-exam-editor-max-attempts',
        'wrap-exam-editor-attempt-pair',
        resolvedEditorMaxAtt
      );
      if (openEl) openEl.value = examDto.openAtUtc || '';
      if (closeEl) closeEl.value = examDto.closeAtUtc || '';
      if (scPolEl) scPolEl.value = examDto.scoreReleasePolicy || 'MANUAL_ADMIN';
      if (exPolEl) exPolEl.value = examDto.explanationReleasePolicy || 'WITH_SCORE';
      if (aggEl) aggEl.value = examDto.aggregationRule || 'BEST_PUBLISHED';
      if (passEl) passEl.value = String(examDto.passThresholdPct || 60);
      if (rqEl) rqEl.checked = Boolean(examDto.randomizeQuestions);
      if (roEl) roEl.checked = Boolean(examDto.randomizeOptions);
      if (pfEl) pfEl.checked = Boolean(examDto.allowPerQuestionPracticeFeedback);
      var parsedEdPdf =
        typeof extractExamPdfAttachmentsFromRichText === 'function'
          ? extractExamPdfAttachmentsFromRichText(examDto.instructionsRichText || examDto.descriptionRichText)
          : { examPaperPdf: null, answerSheetPdf: null, plainText: '' };
      if (descEl) descEl.value = examDto.descriptionPlainText || '';
      if (instEl) {
        instEl.value =
          parsedEdPdf.plainText ||
          examDto.instructionsPlainText ||
          '';
      }
      if (typeof setExamPdfEditorSlotState === 'function') {
        if (parsedEdPdf.examPaperPdf) {
          setExamPdfEditorSlotState(EDITOR_PAPER_PDF_CFG, parsedEdPdf.examPaperPdf.fileId, parsedEdPdf.examPaperPdf.filename);
        } else {
          setExamPdfEditorSlotState(EDITOR_PAPER_PDF_CFG, '', '');
        }
        if (parsedEdPdf.answerSheetPdf) {
          setExamPdfEditorSlotState(
            EDITOR_ANSWER_PDF_CFG,
            parsedEdPdf.answerSheetPdf.fileId,
            parsedEdPdf.answerSheetPdf.filename,
            parsedEdPdf.answerSheetPdf.policy || 'AFTER_SUBMIT'
          );
        } else {
          setExamPdfEditorSlotState(EDITOR_ANSWER_PDF_CFG, '', '', 'AFTER_SUBMIT');
        }
      }

      var selectedMap = {};
      if (Array.isArray(examDto.sections) && examDto.sections.length > 0) {
        var s0 = examDto.sections[0];
        var sec1TitleEl = document.getElementById('input-exam-sec1-title');
        var sec1ModeEl = document.getElementById('select-exam-sec1-mode');
        var sec1DrawEl = document.getElementById('input-exam-sec1-pool-draw');
        if (sec1TitleEl) sec1TitleEl.value = s0.title || 'Part I';
        if (sec1ModeEl) sec1ModeEl.value = s0.selectionMode || 'FIXED_ITEMS';
        if (sec1DrawEl) sec1DrawEl.value = String(s0.poolDrawCount || 1);
        for (var si = 0; si < examDto.sections.length; si++) {
          var sec = examDto.sections[si];
          var items = Array.isArray(sec.items) ? sec.items : [];
          for (var k = 0; k < items.length; k++) {
            selectedMap[items[k].questionId] = true;
          }
        }
      }
      renderExamBuilderQuestionChecklistPhase3(selectedMap);
    }

    function populateAdminExamAssignSetSelectorPhase3(selectedExamSetId) {
      var sel = document.getElementById('select-exam-assign-exam-set');
      if (!sel) return;
      var list = Array.isArray(currentAdminExamsListPhase3) ? currentAdminExamsListPhase3 : [];
      var curVal = selectedExamSetId || sel.value || '';
      while (sel.firstChild) sel.removeChild(sel.firstChild);

      var placeholder = document.createElement('option');
      placeholder.value = '';
      placeholder.textContent =
        list.length === 0
          ? '-- No Exam Sets Found (Create an Exam First) --'
          : '-- Select Examination / Mock Test --';
      sel.appendChild(placeholder);

      for (var i = 0; i < list.length; i++) {
        var ex = list[i];
        if (!ex || !ex.examSetId) continue;
        var opt = document.createElement('option');
        opt.value = ex.examSetId;
        opt.textContent =
          '[' + (ex.examCode || ex.examSetId) + '] ' + (ex.title || 'Untitled Exam') + ' (' + (ex.status || 'DRAFT') + ')';
        sel.appendChild(opt);
      }
      if (curVal) sel.value = curVal;
      if (!sel.value && list.length > 0 && list[0] && list[0].examSetId) {
        sel.value = list[0].examSetId;
      }
    }

    function applyExamDtoToAssignmentsModalDomPhase3(examDto) {
      var ex = examDto || {};
      var idInp = document.getElementById('input-exam-assign-exam-id');
      if (idInp) idInp.value = ex.examSetId || '';
      var setSel = document.getElementById('select-exam-assign-exam-set');
      if (setSel && ex.examSetId) setSel.value = ex.examSetId;
      setText('exam-assign-code-badge', ex.examCode || 'EXAM');
      setText(
        'exam-assign-heading',
        ex.examSetId
          ? 'Assignments & Accommodations: ' + (ex.title || ex.examCode || '')
          : 'Assignments & Accommodations'
      );
      setText('exam-assign-status-text', '');

      var crsSel = document.getElementById('select-exam-assign-course');
      if (crsSel && ex.courseId) crsSel.value = ex.courseId;

      var tbody = document.getElementById('admin-exam-assignments-tbody');
      if (tbody) {
        while (tbody.firstChild) tbody.removeChild(tbody.firstChild);
        var asgList = Array.isArray(ex.assignments) ? ex.assignments : [];
        if (asgList.length === 0) {
          var trEmpty = document.createElement('tr');
          var tdEmpty = document.createElement('td');
          tdEmpty.colSpan = 6;
          tdEmpty.style.textAlign = 'center';
          tdEmpty.style.color = 'var(--color-text-muted)';
          tdEmpty.textContent = ex.examSetId
            ? 'No explicit assignment or accommodation records yet.'
            : 'Select an Examination / Mock Test above to view or create assignments.';
          trEmpty.appendChild(tdEmpty);
          tbody.appendChild(trEmpty);
        } else {
          for (var i = 0; i < asgList.length; i++) {
            var a = asgList[i];
            var tr = document.createElement('tr');

            var tdTarget = document.createElement('td');
            tdTarget.textContent =
              a.targetType === 'COURSE'
                ? 'Course: ' + (a.courseCode || a.courseId)
                : 'Student: ' + (a.studentFullName || a.studentUsername || a.studentUserId);
            tr.appendChild(tdTarget);

            var tdStatus = document.createElement('td');
            var stBadge = document.createElement('span');
            stBadge.className = a.assignmentStatus === 'ASSIGNED' ? 'badge badge-ok' : 'badge badge-danger';
            stBadge.textContent =
              typeof formatFriendlyEnumStatus === 'function'
                ? formatFriendlyEnumStatus(a.assignmentStatus)
                : a.assignmentStatus;
            tdStatus.appendChild(stBadge);
            tr.appendChild(tdStatus);

            var tdTime = document.createElement('td');
            tdTime.textContent = a.extraTimeMinutes > 0 ? '+' + a.extraTimeMinutes + ' mins' : 'Standard';
            tr.appendChild(tdTime);

            var tdAtt = document.createElement('td');
            tdAtt.textContent = a.extraAttemptsGranted > 0 ? '+' + a.extraAttemptsGranted + ' attempts' : 'Standard';
            tr.appendChild(tdAtt);

            var tdDead = document.createElement('td');
            tdDead.textContent = a.overrideDeadlineUtc || 'Default Window';
            tr.appendChild(tdDead);

            var tdNote = document.createElement('td');
            tdNote.textContent = a.accommodationReason || '-';
            tr.appendChild(tdNote);

            tbody.appendChild(tr);
          }
        }
      }
    }

    function openAdminExamAssignmentsFromHeaderPhase3() {
      populateAdminExamBuilderCourseAndStudentDropdownsPhase3();
      var ensureExams =
        Array.isArray(currentAdminExamsListPhase3) && currentAdminExamsListPhase3.length > 0
          ? Promise.resolve(currentAdminExamsListPhase3)
          : rpcCallEnvelope('admin.exams.list', {})
              .then(function (env) {
                var list = (env && env.data && env.data.exams) || [];
                currentAdminExamsListPhase3 = list;
                return list;
              })
              .catch(function () {
                return currentAdminExamsListPhase3 || [];
              });

      return ensureExams.then(function (list) {
        var editingId =
          ((document.getElementById('input-forms-exam-id') || {}).value || '').trim() ||
          ((document.getElementById('input-exam-editor-id') || {}).value || '').trim() ||
          ((document.getElementById('input-exam-assign-exam-id') || {}).value || '').trim();
        populateAdminExamAssignSetSelectorPhase3(editingId);
        var setSel = document.getElementById('select-exam-assign-exam-set');
        var chosenId = (setSel && setSel.value) || editingId || '';
        var chosenDto = null;
        for (var i = 0; i < list.length; i++) {
          if (list[i] && list[i].examSetId === chosenId) {
            chosenDto = list[i];
            break;
          }
        }
        applyExamDtoToAssignmentsModalDomPhase3(chosenDto || list[0] || {});
        if (typeof PBAdminActionModal === 'object' && PBAdminActionModal) {
          PBAdminActionModal.open('admin-exam-assign-modal-card', 'Student Assignments & Time Accommodations');
        }
      });
    }

    function openAdminExamAssignmentsModalPhase3(examDto) {
      populateAdminExamBuilderCourseAndStudentDropdownsPhase3();
      populateAdminExamAssignSetSelectorPhase3((examDto && examDto.examSetId) || '');
      applyExamDtoToAssignmentsModalDomPhase3(examDto || {});

      if (typeof PBAdminActionModal === 'object' && PBAdminActionModal) {
        PBAdminActionModal.open('admin-exam-assign-modal-card', 'Student Assignments & Time Accommodations');
      }
    }

    function renderAdminExamsTablePhase3(bundle) {
      var data = bundle || {};
      var exams = Array.isArray(data.exams) ? data.exams : [];
      currentAdminExamsListPhase3 = exams;

      var summary = data.summary || {};
      var bySt = summary.countsByStatus || {};
      setText('admin-exams-total-badge', String(summary.totalExams || exams.length) + ' Exam Sets');
      setText('admin-exams-published-badge', String(bySt.PUBLISHED || 0) + ' Published');
      setText('admin-exams-draft-badge', String(bySt.DRAFT || 0) + ' Draft');

      var tbody = document.getElementById('admin-exams-table-tbody');
      if (!tbody) return;
      while (tbody.firstChild) tbody.removeChild(tbody.firstChild);

      if (exams.length === 0) {
        var trE = document.createElement('tr');
        var tdE = document.createElement('td');
        tdE.colSpan = 6;
        tdE.style.textAlign = 'center';
        tdE.style.color = 'var(--color-text-muted)';
        tdE.textContent =
          'No examination sets match the current filter. Click "Seed 3 Sample Biology Exam Sets" or "+ Create Examination Set".';
        trE.appendChild(tdE);
        tbody.appendChild(trE);
        return;
      }

      for (var i = 0; i < exams.length; i++) {
        (function (ex) {
          var tr = document.createElement('tr');

          var tdTitle = document.createElement('td');
          tdTitle.className = 'pb-table-primary-col';
          tdTitle.appendChild(
            createTablePrimaryIdentityDom({
              code: ex.examCode,
              title: ex.title,
              description: ex.descriptionPlainText || '',
              descOptions: { clampThreshold: 84 }
            })
          );
          tr.appendChild(tdTitle);

          var tdMode = document.createElement('td');
          var modeStack = document.createElement('div');
          modeStack.className = 'pb-table-item-stack';
          var mBadge = document.createElement('span');
          mBadge.className =
            ex.examMode === 'PRACTICE'
              ? 'badge pb-exam-badge-practice'
              : ex.examMode === 'MOCK_EXAM'
              ? 'badge pb-exam-badge-mock'
              : 'badge pb-exam-badge-assigned';
          mBadge.style.whiteSpace = 'nowrap';
          var compactModeLabel =
            ex.examMode === 'PRACTICE'
              ? 'Practice Quiz'
              : ex.examMode === 'MOCK_EXAM'
              ? 'Timed Mock'
              : 'Assigned Exam';
          mBadge.textContent = compactModeLabel;
          mBadge.title = ex.examModeLabel || compactModeLabel;
          modeStack.appendChild(mBadge);
          var crsDiv = document.createElement('div');
          crsDiv.style.fontSize = '0.77rem';
          crsDiv.style.color = 'var(--color-text-secondary)';
          crsDiv.style.overflow = 'hidden';
          crsDiv.style.textOverflow = 'ellipsis';
          crsDiv.style.maxWidth = '128px';
          crsDiv.style.whiteSpace = 'nowrap';
          var fullCourseLbl = ex.courseCode ? ex.courseCode + ' — ' + ex.courseTitle : 'Multi-Course';
          crsDiv.textContent = ex.courseCode ? ex.courseCode + (ex.courseTitle ? ' · ' + ex.courseTitle : '') : 'Multi-Course';
          crsDiv.title = fullCourseLbl;
          modeStack.appendChild(crsDiv);
          tdMode.appendChild(modeStack);
          tr.appendChild(tdMode);

          var tdStruct = document.createElement('td');
          var structWrap = document.createElement('div');
          structWrap.className = 'pb-table-stat-group';
          var secSt = document.createElement('span');
          secSt.className = 'pb-table-stat-chip';
          var effectiveSecCount =
            Number(ex.sectionCount) > 0
              ? Number(ex.sectionCount)
              : Number(ex.totalQuestionsCount || 0) > 0
              ? 1
              : 0;
          secSt.textContent = String(effectiveSecCount) + ' sec · ' + String(ex.totalQuestionsCount || 0) + ' Qs';
          var ptsSt = document.createElement('span');
          ptsSt.className = 'pb-table-stat-chip';
          ptsSt.textContent = ex.maxPointsDisplay || '0 pts';
          structWrap.appendChild(secSt);
          structWrap.appendChild(ptsSt);
          tdStruct.appendChild(structWrap);
          tr.appendChild(tdStruct);

          var tdTime = document.createElement('td');
          var durDiv = document.createElement('div');
          durDiv.style.fontSize = '0.84rem';
          durDiv.textContent = ex.durationLabel || 'Untimed';
          tdTime.appendChild(durDiv);
          var attBadge = document.createElement('span');
          var maxA = Number(ex.maxAttempts);
          if (maxA === 0 || ex.allowedAttempts === 'UNLIMITED') {
            attBadge.className = 'badge pb-cat-attempt-unlimited';
            attBadge.textContent = 'Unlimited';
            attBadge.title = 'Unlimited Retakes';
          } else if (maxA === 1) {
            attBadge.className = 'badge pb-cat-attempt-single';
            attBadge.textContent = '1 Attempt';
            attBadge.title = 'Single Attempt (1)';
          } else {
            attBadge.className = 'badge pb-cat-attempt-multi';
            attBadge.textContent = String(maxA || 1) + ' Attempts';
            attBadge.title = 'Multiple (' + String(maxA || 1) + ' Attempts)';
          }
          attBadge.style.marginTop = '4px';
          tdTime.appendChild(attBadge);
          tr.appendChild(tdTime);

          var tdStatus = document.createElement('td');
          var stBadge = document.createElement('span');
          stBadge.className =
            ex.status === 'PUBLISHED'
              ? 'badge badge-ok'
              : ex.status === 'DRAFT'
              ? 'badge badge-warning'
              : 'badge';
          stBadge.textContent = ex.status + (ex.activeVersionNo ? ' (v' + ex.activeVersionNo + ')' : '');
          tdStatus.appendChild(stBadge);

          if (ex.validationReport) {
            var valDiv = document.createElement('div');
            valDiv.style.fontSize = '0.75rem';
            valDiv.style.marginTop = '4px';
            var blockingCount = Array.isArray(ex.validationReport.blockingErrors)
              ? ex.validationReport.blockingErrors.length
              : 0;
            var warningCount = Array.isArray(ex.validationReport.warnings)
              ? ex.validationReport.warnings.length
              : 0;
            if (blockingCount > 0) {
              valDiv.style.color = 'var(--color-danger-text)';
              valDiv.textContent = blockingCount + ' blocking issue(s)';
            } else if (warningCount > 0) {
              valDiv.style.color = '#8A4B08';
              valDiv.textContent = 'Valid (' + warningCount + ' warning(s))';
            } else {
              valDiv.style.color = 'var(--color-brand-primary)';
              valDiv.textContent = 'Ready / Verified';
            }
            tdStatus.appendChild(valDiv);
          }
          tr.appendChild(tdStatus);

          var tdAct = document.createElement('td');
          var btnWrap = document.createElement('div');
          btnWrap.className = 'pb-table-actions-grid';

          var editBtn = document.createElement('button');
          editBtn.type = 'button';
          editBtn.className = 'btn btn-secondary btn-sm pb-action-full';
          setBtnVectorIcon(editBtn, 'edit', 'Edit', 'Edit exam in Form Builder');
          editBtn.addEventListener('click', function () {
            if (typeof openFormsExamBuilderWithExam === 'function') {
              openFormsExamBuilderWithExam(ex);
            } else {
              populateAdminExamEditorForEditPhase3(ex);
              if (typeof PBAdminActionModal === 'object' && PBAdminActionModal) {
                PBAdminActionModal.open('admin-exam-editor-card', 'Create / Edit Examination Set & Section Builder');
              }
            }
          });
          btnWrap.appendChild(editBtn);

          var prevBtn = document.createElement('button');
          prevBtn.type = 'button';
          prevBtn.className = 'btn btn-outline btn-sm';
          setBtnVectorIcon(prevBtn, 'preview', 'Preview', 'Preview examination set');
          prevBtn.addEventListener('click', function () {
            runButtonWithLoadingState(prevBtn, 'Loading Preview...', function () {
              return openStudentExamInstructionsModalPhase3(ex.examSetId, true);
            });
          });
          btnWrap.appendChild(prevBtn);

          var pubBtn = document.createElement('button');
          pubBtn.type = 'button';
          pubBtn.className = 'btn btn-primary btn-sm';
          setBtnVectorIcon(
            pubBtn,
            'check',
            ex.status === 'PUBLISHED' ? 'Republish' : 'Publish',
            ex.status === 'PUBLISHED' ? 'Republish exam set' : 'Publish exam set'
          );
          pubBtn.addEventListener('click', function () {
            runButtonWithLoadingState(pubBtn, 'Publishing...', function () {
              setText('admin-exams-status-banner', 'Validating and publishing ' + ex.examCode + '...');
              return rpcCallEnvelope('admin.exams.publish', { examSetId: ex.examSetId })
                .then(function (env) {
                  renderAdminExamsTablePhase3(env.data);
                  setText('admin-exams-status-banner', 'Published ' + ex.examCode + ' successfully.');
                  PBNotify.toast('success', 'Examination Published', ex.title + ' is now live for assigned students.');
                })
                .catch(function (err) {
                  setText('admin-exams-status-banner', 'Publish blocked: ' + ((err && err.message) || 'Validation failed'));
                  PBNotify.toast('danger', 'Publication Blocked', (err && err.message) || 'Validation failed.');
                });
            });
          });
          btnWrap.appendChild(pubBtn);

          var asgBtn = document.createElement('button');
          asgBtn.type = 'button';
          asgBtn.className = 'btn btn-outline btn-sm';
          setBtnVectorIcon(
            asgBtn,
            'users',
            'Assign (' + (Array.isArray(ex.assignments) ? ex.assignments.length : 0) + ')',
            'Manage student assignments'
          );
          asgBtn.addEventListener('click', function () {
            openAdminExamAssignmentsModalPhase3(ex);
          });
          btnWrap.appendChild(asgBtn);

          var delExamBtn = document.createElement('button');
          delExamBtn.type = 'button';
          delExamBtn.className = 'btn btn-outline btn-sm pb-btn-danger-outline';
          setBtnVectorIcon(delExamBtn, 'trash', 'Delete', 'Delete question set and all contained questions');
          delExamBtn.addEventListener('click', function () {
            var qCnt = Number(ex.totalQuestionsCount || ex.questionCount || 0);
            var setTitle = ex.title || ex.examCode || ex.examSetId;
            PBConfirmModal.run({
              badgeText: 'Confirm Question Set Deletion',
              title: 'Delete Question Set & Contained Questions?',
              targetLabel: 'Question Set (' + String(qCnt) + ' question(s))',
              targetDetail: setTitle,
              message:
                'Permanently delete question set "' +
                setTitle +
                '" and ALL ' +
                String(qCnt) +
                ' question(s) contained inside it? This cannot be undone.',
              confirmText: 'Delete Question Set',
              loadingText: 'Deleting Set...',
              onConfirm: function () {
                return rpcCallEnvelope('admin.exams.delete', { examSetId: ex.examSetId }).then(function (env) {
                  renderAdminExamsTablePhase3(env.data);
                  invalidateQBankClientCachePhase2();
                  if (typeof loadQuestionBankListPhase2 === 'function') {
                    loadQuestionBankListPhase2();
                  }
                  if (typeof loadAdminCoursesAndAssessmentsStep7 === 'function') {
                    loadAdminCoursesAndAssessmentsStep7();
                  }
                  setText('admin-exams-status-banner', 'Deleted question set "' + (ex.title || ex.examCode) + '" and its contained questions.');
                  PBNotify.toast('success', 'Question Set Deleted', 'Removed set and its contained questions.');
                });
              }
            });
          });
          btnWrap.appendChild(delExamBtn);

          var anlBtn = document.createElement('button');
          anlBtn.type = 'button';
          anlBtn.className = 'btn btn-outline btn-sm';
          setBtnVectorIcon(anlBtn, 'chart', 'Analytics', 'Analytics & regrade');
          anlBtn.addEventListener('click', function () {
            openAdminExamRegradeAndAnalyticsModalPhase7(ex);
          });
          btnWrap.appendChild(anlBtn);

          tdAct.appendChild(btnWrap);
          tr.appendChild(tdAct);
          tbody.appendChild(tr);
        })(exams[i]);
      }
    }

    function loadAdminExamSetsPhase3() {
      populateAdminExamBuilderCourseAndStudentDropdownsPhase3();
      var sInp = document.getElementById('input-admin-exams-search');
      var crsSel = document.getElementById('select-admin-exams-course-filter');
      var modSel = document.getElementById('select-admin-exams-mode-filter');
      var stSel = document.getElementById('select-admin-exams-status-filter');

      var payload = {
        search: sInp ? sInp.value : '',
        courseId: crsSel ? crsSel.value : 'ALL',
        examMode: modSel ? modSel.value : 'ALL',
        status: stSel ? stSel.value : 'ALL'
      };
      setText('admin-exams-status-banner', 'Loading examination sets...');
      return rpcCallEnvelope('admin.exams.list', payload)
        .then(function (env) {
          setText('admin-exams-status-banner', '');
          renderAdminExamsTablePhase3(env.data);
          return env.data;
        })
        .catch(function (err) {
          setText('admin-exams-status-banner', 'Error loading exams: ' + ((err && err.message) || 'Failed'));
        });
    }

    // Student Course Examination Catalog & Instructions Modal Controller
    function formatFriendlyExamBadgeText(raw) {
      var s = String(raw || '').trim().toUpperCase();
      var map = {
        AVAILABLE: 'Open Now',
        IN_PROGRESS_RESUMABLE: 'In Progress',
        IN_PROGRESS: 'In Progress',
        UPCOMING: 'Upcoming',
        CLOSED: 'Closed',
        NOT_STARTED: 'Not Started',
        COMPLETED: 'Completed',
        SUBMITTED: 'Submitted',
        GRADED: 'Graded',
        PUBLISHED: 'Score Released'
      };
      return map[s] || s.replace(/_/g, ' ');
    }

    function createExamMetricBoxDom(label, value) {
      var box = document.createElement('div');
      box.className = 'pb-exam-meta-box';
      var lbl = document.createElement('span');
      lbl.className = 'pb-exam-meta-label';
      lbl.textContent = label;
      var val = document.createElement('span');
      val.className = 'pb-exam-meta-val';
      val.textContent = value;
      box.appendChild(lbl);
      box.appendChild(val);
      return box;
    }

    function renderStudentCourseExamCatalogCardsPhase3(catalogBundle) {
      var data = catalogBundle || {};
      var exams = Array.isArray(data.exams) ? data.exams : [];
      currentStudentCourseExamsCatalogPhase3 = exams;

      var pracCount = 0;
      for (var p = 0; p < exams.length; p++) {
        if (exams[p] && exams[p].examMode === 'PRACTICE') pracCount++;
      }

      setText(
        'student-course-exams-count-badge',
        String(exams.length) +
          (exams.length === 1 ? ' Assessment' : ' Assessments') +
          (pracCount > 0 ? ' (' + pracCount + ' Practice)' : '')
      );
      setText('student-course-stat-exams', String(exams.length));

      var emptyBox = document.getElementById('student-course-exams-empty');
      var gridEl = document.getElementById('student-course-exams-grid');
      var quickTabsEl = document.getElementById('student-exam-mode-quick-tabs');
      var filterFormEl = document.getElementById('form-student-exam-catalog-filter');
      var sInpEl = document.getElementById('input-student-exam-search');
      var mSelEl = document.getElementById('select-student-exam-mode-filter');
      var aSelEl = document.getElementById('select-student-exam-availability-filter');
      var cSelEl = document.getElementById('select-student-exam-completion-filter');
      var hasActiveCatalogFilter = Boolean(
        (sInpEl && sInpEl.value.trim()) ||
          (mSelEl && mSelEl.value !== 'ALL') ||
          (aSelEl && aSelEl.value !== 'ALL') ||
          (cSelEl && cSelEl.value !== 'ALL')
      );
      if (quickTabsEl) {
        quickTabsEl.classList.toggle('hidden', exams.length === 0 && !hasActiveCatalogFilter);
      }
      if (filterFormEl) {
        filterFormEl.classList.toggle('hidden', exams.length === 0 && !hasActiveCatalogFilter);
      }
      if (!gridEl) return;

      while (gridEl.firstChild) gridEl.removeChild(gridEl.firstChild);

      if (exams.length === 0) {
        if (emptyBox) emptyBox.classList.remove('hidden');
        gridEl.classList.add('hidden');
        return;
      }

      if (emptyBox) emptyBox.classList.add('hidden');
      gridEl.classList.remove('hidden');

      for (var i = 0; i < exams.length; i++) {
        (function (exam) {
          var isPractice = exam.examMode === 'PRACTICE';
          var isMock = exam.examMode === 'MOCK_EXAM';

          var card = document.createElement('article');
          card.className =
            'pb-exam-set-card ' +
            (isPractice
              ? 'is-practice-quiz'
              : isMock
              ? 'is-mock-exam'
              : 'is-assigned-exam');

          var headerWrap = document.createElement('div');
          headerWrap.className = 'pb-exam-set-card-header';

          // Top Badges Row (Format Badge on Left, Status Badges on Right)
          var topRow = document.createElement('div');
          topRow.className = 'pb-exam-set-card-top';

          var leftBadges = document.createElement('div');
          leftBadges.style.display = 'flex';
          leftBadges.style.alignItems = 'center';
          leftBadges.style.gap = '6px';
          leftBadges.style.flexWrap = 'wrap';

          var modeBadge = document.createElement('span');
          modeBadge.className =
            'badge ' +
            (isPractice
              ? 'pb-exam-badge-practice'
              : isMock
              ? 'pb-exam-badge-mock'
              : 'pb-exam-badge-assigned');
          modeBadge.textContent = isPractice
            ? 'Practice Quiz'
            : isMock
            ? 'Timed Mock Exam'
            : 'Assigned Assessment';
          leftBadges.appendChild(modeBadge);

          var attemptPolicyBadge = document.createElement('span');
          var isUnlimCard =
            exam.allowedAttempts === 'UNLIMITED' ||
            exam.allowedAttemptsDisplay === 'Unlimited' ||
            Number(exam.allowedAttempts) === 0;
          if (isUnlimCard) {
            attemptPolicyBadge.className = 'badge pb-cat-attempt-unlimited';
            attemptPolicyBadge.textContent = 'Unlimited Retakes';
          } else if (Number(exam.allowedAttempts) === 1) {
            attemptPolicyBadge.className = 'badge pb-cat-attempt-single';
            attemptPolicyBadge.textContent = 'Single Attempt';
          } else {
            attemptPolicyBadge.className = 'badge pb-cat-attempt-multi';
            attemptPolicyBadge.textContent =
              String(exam.allowedAttempts || 2) + ' Attempts Max';
          }
          leftBadges.appendChild(attemptPolicyBadge);

          var rightBadges = document.createElement('div');
          rightBadges.style.display = 'flex';
          rightBadges.style.alignItems = 'center';
          rightBadges.style.gap = '6px';
          rightBadges.style.flexWrap = 'wrap';

          var availBadge = document.createElement('span');
          availBadge.className =
            exam.availabilityState === 'AVAILABLE' || exam.availabilityState === 'IN_PROGRESS_RESUMABLE'
              ? 'badge badge-ok'
              : exam.availabilityState === 'UPCOMING'
              ? 'badge badge-warning'
              : 'badge badge-incomplete';
          availBadge.textContent = formatFriendlyExamBadgeText(exam.availabilityState);
          rightBadges.appendChild(availBadge);

          var compBadge = document.createElement('span');
          compBadge.className =
            exam.completionState === 'COMPLETED'
              ? 'badge badge-ok'
              : exam.completionState === 'IN_PROGRESS'
              ? 'badge badge-warning'
              : 'badge';
          compBadge.textContent = formatFriendlyExamBadgeText(exam.completionState);
          rightBadges.appendChild(compBadge);

          topRow.appendChild(leftBadges);
          topRow.appendChild(rightBadges);
          headerWrap.appendChild(topRow);

          // Code Subtitle & Title
          var codeLabel = document.createElement('div');
          codeLabel.className = 'pb-exam-set-code';
          codeLabel.textContent =
            (exam.examCode || 'BIO-QUIZ') +
            (isPractice
              ? ' • Self-Paced Practice & Answer Key'
              : isMock
              ? ' • Timed Mock Examination'
              : ' • Assigned Course Assessment');
          headerWrap.appendChild(codeLabel);

          var titleH3 = document.createElement('h3');
          titleH3.className = 'pb-exam-set-title';
          titleH3.textContent = exam.title || 'Biology Practice Quiz';
          headerWrap.appendChild(titleH3);

          if (exam.descriptionPlainText) {
            var exDescDom = createCollapsibleDescriptionDom(exam.descriptionPlainText, {
              clampThreshold: 100,
              stopPropagation: true
            });
            if (exDescDom) {
              exDescDom.classList.add('pb-exam-set-desc');
              headerWrap.appendChild(exDescDom);
            }
          }

          card.appendChild(headerWrap);

          // Uniform 2x2 Metric Grid (Questions, Total Score, Time Limit, Attempts)
          var metaGrid = document.createElement('div');
          metaGrid.className = 'pb-exam-set-meta-grid';

          metaGrid.appendChild(
            createExamMetricBoxDom(
              'Questions',
              String(exam.questionCount || 0) +
                (exam.questionCount === 1 ? ' Question' : ' Questions')
            )
          );
          metaGrid.appendChild(
            createExamMetricBoxDom('Total Score', exam.maxPointsDisplay || '0 pts')
          );
          metaGrid.appendChild(
            createExamMetricBoxDom(
              'Time Limit',
              exam.durationLabel || (isPractice ? 'Untimed (Self-Paced)' : 'Untimed')
            )
          );
          metaGrid.appendChild(
            createExamMetricBoxDom(
              'Attempts',
              String(exam.attemptsUsed || 0) + ' / ' + (exam.allowedAttemptsDisplay || 'Unlimited')
            )
          );

          card.appendChild(metaGrid);

          // Clean Schedule & Feedback Box
          var schedBox = document.createElement('div');
          schedBox.className = 'pb-exam-set-schedule-box';

          var openLabel =
            !exam.openAtBangkok || exam.openAtBangkok === 'Immediate'
              ? 'Open Anytime'
              : 'Opens ' + exam.openAtBangkok;
          var closeLabel =
            !exam.closeAtBangkok || exam.closeAtBangkok === 'No Deadline'
              ? 'No Closing Deadline'
              : 'Closes ' + exam.closeAtBangkok;
          var winLine = document.createElement('div');
          winLine.textContent = 'Schedule: ' + openLabel + '  •  ' + closeLabel;
          schedBox.appendChild(winLine);

          if (isPractice) {
            var pracLine = document.createElement('div');
            pracLine.style.color = '#065F46';
            pracLine.style.fontWeight = '600';
            pracLine.style.display = 'flex';
            pracLine.style.alignItems = 'center';
            pracLine.style.gap = '6px';
            setElementVectorIconLabel(
              pracLine,
              'check',
              exam.allowPerQuestionPracticeFeedback
                ? 'Instant per-question answer check & explanations enabled'
                : 'Full answer key & explanations available upon submission',
              'pb-icon-xs'
            );
            schedBox.appendChild(pracLine);
          }
          card.appendChild(schedBox);

          // Published Score Banner (if released) or Clean Attempt Summary
          if (exam.publishedScoreSummary) {
            var scoreBar = document.createElement('div');
            scoreBar.className = 'pb-assessment-inline-score-banner';
            scoreBar.textContent =
              'Latest Score: ' +
              exam.publishedScoreSummary.scoreDisplay +
              ' (' +
              exam.publishedScoreSummary.percentageFormatted +
              ')';
            card.appendChild(scoreBar);
          } else if (exam.attemptsUsed > 0) {
            var holdNote = document.createElement('div');
            holdNote.style.fontSize = '0.8rem';
            holdNote.style.fontWeight = '600';
            holdNote.style.color = 'var(--color-text-secondary)';
            holdNote.textContent =
              'Progress: ' +
              (exam.attemptStatusSummary || 'Submitted') +
              '  •  ' +
              (exam.publicationStatusSummary || 'Awaiting Score Release');
            card.appendChild(holdNote);
          }

          var cardPdfParsed =
            typeof extractExamPdfAttachmentsFromRichText === 'function'
              ? extractExamPdfAttachmentsFromRichText(exam.instructionsRichText)
              : { examPaperPdf: null, answerSheetPdf: null };
          if (cardPdfParsed.examPaperPdf || cardPdfParsed.answerSheetPdf) {
            var pdfStrip = document.createElement('div');
            pdfStrip.className = 'pb-exam-card-pdf-strip';
            if (cardPdfParsed.examPaperPdf) {
              var paperChip = document.createElement('span');
              paperChip.className = 'badge badge-ok';
              paperChip.textContent = 'Exam Paper PDF';
              pdfStrip.appendChild(paperChip);
            }
            if (cardPdfParsed.answerSheetPdf) {
              var ansChip = document.createElement('span');
              ansChip.className = 'badge';
              ansChip.style.background = '#ECFEFF';
              ansChip.style.color = '#0E7490';
              ansChip.textContent = canStudentViewExamAnswerSheetPdf(cardPdfParsed.answerSheetPdf, {
                isAdminPreview: isCurrentSessionAdminUser(),
                hasSubmittedAttempt:
                  (exam.attemptsUsed || 0) > 0 && !exam.canResumeAttempt,
                explanationsReleased:
                  Boolean(exam.canViewPublishedResult) || Boolean(exam.publishedScoreSummary)
              })
                ? 'Answer Sheet PDF Ready'
                : 'Answer Sheet PDF Included';
              pdfStrip.appendChild(ansChip);
            }
            card.appendChild(pdfStrip);
          }

          // Footer Action Buttons
          var footerRow = document.createElement('div');
          footerRow.className = 'pb-exam-set-footer';

          var actBtn = document.createElement('button');
          actBtn.type = 'button';
          actBtn.className =
            exam.canStartNewAttempt || exam.canResumeAttempt
              ? 'btn btn-primary btn-sm'
              : 'btn btn-secondary btn-sm';

          var defaultCta = isPractice
            ? exam.canResumeAttempt
              ? 'Resume Practice Quiz'
              : exam.attemptsUsed > 0
              ? 'Retake Practice Quiz'
              : 'Start Practice Quiz'
            : exam.primaryActionLabel || 'View Instructions & Start';

          actBtn.textContent =
            exam.primaryActionType === 'VIEW_RESULT' && exam.canViewPublishedResult
              ? 'Review Score & Answer Key'
              : defaultCta;

          actBtn.addEventListener('click', function () {
            runButtonWithLoadingState(actBtn, 'Loading...', function () {
              if (exam.primaryActionType === 'VIEW_RESULT' && exam.canViewPublishedResult) {
                return openStudentPublishedExamResultModalPhase7(exam.examSetId, '');
              }
              var isAdmViewer = isCurrentSessionAdminUser();
              return openStudentExamInstructionsModalPhase3(exam.examSetId, isAdmViewer);
            });
          });
          footerRow.appendChild(actBtn);

          if (
            exam.canViewPublishedResult &&
            exam.primaryActionType !== 'VIEW_RESULT' &&
            (exam.canStartNewAttempt || exam.canResumeAttempt)
          ) {
            var revBtn = document.createElement('button');
            revBtn.type = 'button';
            revBtn.className = 'btn btn-outline btn-sm';
            revBtn.textContent = 'View Past Result';
            revBtn.addEventListener('click', function () {
              runButtonWithLoadingState(revBtn, 'Opening...', function () {
                return openStudentPublishedExamResultModalPhase7(exam.examSetId, '');
              });
            });
            footerRow.appendChild(revBtn);
          }

          card.appendChild(footerRow);
          gridEl.appendChild(card);
        })(exams[i]);
      }

      if (typeof PBObjectUrlManager === 'object' && PBObjectUrlManager && typeof PBObjectUrlManager.prefetchFiles === 'function') {
        var prefetchQueue = [];
        for (var pfIdx = 0; pfIdx < exams.length; pfIdx++) {
          var pfExam = exams[pfIdx];
          if (!pfExam || !pfExam.instructionsRichText) continue;
          var pfParsed = extractExamPdfAttachmentsFromRichText(pfExam.instructionsRichText);
          if (pfParsed.examPaperPdf && pfParsed.examPaperPdf.fileId) {
            prefetchQueue.push({
              fileId: pfParsed.examPaperPdf.fileId,
              courseId: pfExam.courseId || ''
            });
          }
        }
        if (prefetchQueue.length > 0) {
          PBObjectUrlManager.prefetchFiles(prefetchQueue);
        }
      }
    }

    function loadStudentCourseExamsCatalogPhase3(opt_courseId) {
      var targetCourseId = opt_courseId || currentStudentCourseId || '';
      if (!targetCourseId) return Promise.resolve(null);

      var sInp = document.getElementById('input-student-exam-search');
      var mSel = document.getElementById('select-student-exam-mode-filter');
      var aSel = document.getElementById('select-student-exam-availability-filter');
      var cSel = document.getElementById('select-student-exam-completion-filter');

      var payload = {
        courseId: targetCourseId,
        search: sInp ? sInp.value : '',
        modeFilter: mSel ? mSel.value : 'ALL',
        availabilityFilter: aSel ? aSel.value : 'ALL',
        completionFilter: cSel ? cSel.value : 'ALL',
        adminPreview: Boolean(currentStudentCourseFromAdminPreview) && isCurrentSessionAdminUser()
      };

      return rpcCallEnvelope('exams.list', payload)
        .then(function (env) {
          renderStudentCourseExamCatalogCardsPhase3(env.data);
          return env.data;
        })
        .catch(function (err) {
          setText(
            'student-course-exams-empty-text',
            'Unable to load examination catalog: ' + ((err && err.message) || 'Error')
          );
        });
    }

    function buildFallbackAdminPreviewInstructionsBundle(examSetId) {
      if (!isCurrentSessionAdminUser()) return null;
      var found = null;
      if (Array.isArray(currentAdminExamsListPhase3)) {
        for (var i = 0; i < currentAdminExamsListPhase3.length; i++) {
          if (currentAdminExamsListPhase3[i] && currentAdminExamsListPhase3[i].examSetId === examSetId) {
            found = currentAdminExamsListPhase3[i];
            break;
          }
        }
      }
      if (!found) return null;
      var secs = Array.isArray(found.sections) ? found.sections : [];
      var secOverview = [];
      for (var s = 0; s < secs.length; s++) {
        var sitems = Array.isArray(secs[s].items) ? secs[s].items : [];
        secOverview.push({
          title: secs[s].title || 'Part ' + (s + 1),
          selectionMode: secs[s].selectionMode || 'FIXED_ITEMS',
          selectionModeLabel:
            secs[s].selectionMode === 'QUESTION_POOL'
              ? 'Random Pool (' + (secs[s].poolDrawCount || sitems.length) + ' drawn)'
              : 'All Questions in Order',
          sectionQuestionsCount: sitems.length,
          sectionMaxPointsDisplay: found.maxPointsDisplay || (sitems.length * 2) + ' pts'
        });
      }
      return {
        exam: {
          examSetId: found.examSetId,
          examCode: found.examCode || 'DRAFT-EXAM',
          title: found.title || 'Untitled Exam',
          courseId: found.courseId || '',
          courseCode: found.courseCode || '',
          courseTitle: found.courseTitle || '',
          examMode: found.examMode || 'MOCK_EXAM',
          examModeLabel: found.examModeLabel || found.examMode || 'Examination',
          availabilityState: found.status || 'DRAFT',
          questionCount: found.questionCount || (secs[0] && secs[0].items ? secs[0].items.length : 0),
          sectionCount: secs.length || 1,
          maxPointsDisplay: found.maxPointsDisplay || '0 pts',
          durationMinutes: Number(found.durationMinutes || 0),
          effectiveDurationMinutes: Number(found.durationMinutes || 0),
          durationLabel: Number(found.durationMinutes || 0) > 0 ? found.durationMinutes + ' min' : 'Untimed',
          attemptsUsed: 0,
          allowedAttemptsDisplay: Number(found.maxAttempts || 0) === 0 ? 'Unlimited' : String(found.maxAttempts || 1),
          aggregationRule: found.aggregationRule || 'BEST_PUBLISHED',
          openAtBangkok: found.openAtBangkok || 'Immediate',
          closeAtBangkok: found.closeAtBangkok || 'No Deadline',
          scoreReleasePolicy: found.scoreReleasePolicy || 'IMMEDIATE_AUTO',
          explanationReleasePolicy: found.explanationReleasePolicy || 'WITH_SCORE',
          allowPerQuestionPracticeFeedback: Boolean(found.allowPerQuestionPracticeFeedback),
          instructionsRichText: found.instructionsRichText || found.descriptionRichText || '',
          sectionsOverview: secOverview,
          sections: secs,
          canStartNewAttempt: true,
          canResumeAttempt: false,
          _isAdminPreview: true
        },
        rulesChecklist: [
          'Administrator Preview Mode: You can test-drive all questions, options, and instant answer checks without affecting student records.',
          'Time Limit: ' + (Number(found.durationMinutes || 0) > 0 ? found.durationMinutes + ' minutes' : 'Untimed (Self-Paced)')
        ],
        integrityPolicy: {
          copyPolicyEnabled: Boolean(found.copyPolicyEnabled !== false),
          policyVersion: 'pb-exam-integrity-v1'
        }
      };
    }

    var activeExamInstructionsReqToken = 0;

    function openStudentExamInstructionsModalPhase3(examSetId, opt_isAdminPreview) {
      var modal = document.getElementById('modal-student-exam-instructions');
      if (!modal) return Promise.resolve(null);
      var reqToken = ++activeExamInstructionsReqToken;
      openModalDialog('modal-student-exam-instructions', 'btn-exam-inst-header-close');
      if (!modal.dataset.boundBackdropClick) {
        modal.dataset.boundBackdropClick = '1';
        modal.addEventListener('click', function (evt) {
          if (evt.target === modal) {
            closeStudentExamInstructionsModalPhase3();
          }
        });
      }

      var isAdminPrev = Boolean(opt_isAdminPreview) && isCurrentSessionAdminUser();
      currentSelectedInstructionExamPhase3 = null;
      var loadOverlay = document.getElementById('exam-inst-loading-overlay');
      if (loadOverlay) loadOverlay.classList.remove('hidden');
      var startBtnInit = document.getElementById('btn-exam-inst-start-attempt');
      if (startBtnInit) {
        startBtnInit.disabled = true;
        startBtnInit.classList.remove('is-btn-loading');
        startBtnInit.textContent = 'Verifying Session...';
      }
      var closeBtnFooter = document.getElementById('btn-exam-inst-close');
      if (closeBtnFooter) {
        closeBtnFooter.textContent = isAdminPrev ? 'Close Preview' : 'Back to Course Catalog';
      }
      var availBadgeInit = document.getElementById('exam-inst-availability-badge');
      if (availBadgeInit) {
        availBadgeInit.classList.remove('is-preview');
        availBadgeInit.textContent = 'CHECKING...';
      }
      setText('exam-inst-mode-badge', 'Assessment');
      setText('exam-inst-code-badge', 'LOADING');
      setText('exam-inst-title', 'Loading Examination Instructions...');
      setText('exam-inst-course-label', '');
      setText('exam-inst-status-title', 'Verifying Session');
      setText('exam-inst-status-message', 'Verifying your session role and fetching official assessment rules...');
      setText('exam-inst-question-count', 'Loading...');
      setText('exam-inst-max-points', 'Loading...');
      setText('exam-inst-duration', 'Loading...');
      setText('exam-inst-attempts', 'Loading...');
      setText('exam-inst-window', 'Loading...');
      setText('exam-inst-release-policy', 'Loading...');
      renderModalSkeletonBlock('exam-inst-richtext-body', 1);
      renderTableSkeletonRows('exam-inst-sections-tbody', 4, 2);

      function formatFriendlyPolicyLabel(raw) {
        var s = String(raw || '').trim().toUpperCase();
        var map = {
          IMMEDIATE_AUTO: 'Instant Auto-Release',
          MANUAL_ADMIN: 'Instructor Review',
          AFTER_CLOSE: 'After Closing Deadline',
          SCHEDULED: 'Scheduled Release',
          WITH_SCORE: 'Included with Score',
          NEVER: 'Score Only',
          BEST_PUBLISHED: 'Highest Score',
          LATEST_PUBLISHED: 'Latest Attempt',
          FIRST_PUBLISHED: 'First Attempt',
          FIXED_ITEMS: 'All Questions in Order',
          QUESTION_POOL: 'Random Question Pool',
          PRACTICE: 'Practice Quiz',
          MOCK_EXAM: 'Timed Mock Examination',
          ASSIGNED_ASSESSMENT: 'Assigned Assessment'
        };
        if (map[s]) return map[s];
        return String(raw || '-')
          .replace(/\b1 questions\b/gi, '1 question')
          .replace(/\b1 candidates\b/gi, '1 candidate')
          .replace(/\b1 items\b/gi, '1 item')
          .replace(/_/g, ' ');
      }

      function humanizeRuleLine(line) {
        return String(line || '')
          .replace(/\bIMMEDIATE_AUTO\b/g, 'Instant Auto-Release')
          .replace(/\bMANUAL_ADMIN\b/g, 'Instructor Review')
          .replace(/\bAFTER_CLOSE\b/g, 'After Closing Deadline')
          .replace(/\bWITH_SCORE\b/g, 'Included with Score')
          .replace(/\bBEST_PUBLISHED\b/g, 'Highest Score')
          .replace(/\bLATEST_PUBLISHED\b/g, 'Latest Attempt')
          .replace(/\bFIRST_PUBLISHED\b/g, 'First Attempt')
          .replace(/\b1 questions\b/gi, '1 question')
          .replace(/\b1 sections\b/gi, '1 section');
      }

      function renderInstKeyValueStackDom(elId, rows) {
        var host = document.getElementById(elId);
        if (!host) return;
        while (host.firstChild) host.removeChild(host.firstChild);
        var stack = document.createElement('div');
        stack.className = 'pb-inst-kv-stack';
        for (var i = 0; i < rows.length; i++) {
          var row = document.createElement('div');
          row.className = 'pb-inst-kv-row';
          var kSpan = document.createElement('span');
          kSpan.className = 'pb-inst-kv-key';
          kSpan.textContent = rows[i].label;
          var vSpan = document.createElement('span');
          vSpan.className = 'pb-inst-kv-val';
          vSpan.textContent = rows[i].value;
          row.appendChild(kSpan);
          row.appendChild(vSpan);
          stack.appendChild(row);
        }
        host.appendChild(stack);
      }

      function applyInstructionsBundleToModal(data) {
        var ex = (data && data.exam) || {};
        var effectiveAdminPrev =
          isCurrentSessionAdminUser() &&
          Boolean(isAdminPrev || ex._isAdminPreview || currentStudentCourseFromAdminPreview);
        ex._isAdminPreview = effectiveAdminPrev;
        currentSelectedInstructionExamPhase3 = ex;

        if (closeBtnFooter) {
          closeBtnFooter.textContent = effectiveAdminPrev ? 'Close Preview' : 'Back to Course Catalog';
        }

        var modeClass = ex.examMode === 'PRACTICE'
          ? 'is-mode-practice'
          : ex.examMode === 'MOCK_EXAM'
          ? 'is-mode-mock'
          : 'is-mode-assigned';
        var dialogEl = document.getElementById('exam-inst-popup-dialog');
        if (dialogEl) {
          dialogEl.classList.remove('is-mode-practice', 'is-mode-mock', 'is-mode-assigned');
          dialogEl.classList.add(modeClass);
        }

        setText(
          'exam-inst-mode-badge',
          ex.examModeLabel ? formatFriendlyPolicyLabel(ex.examModeLabel) : formatFriendlyPolicyLabel(ex.examMode || 'Assigned Assessment')
        );
        var instModeBadgeEl = document.getElementById('exam-inst-mode-badge');
        if (instModeBadgeEl) {
          instModeBadgeEl.className =
            'badge ' +
            (ex.examMode === 'PRACTICE'
              ? 'pb-exam-badge-practice'
              : ex.examMode === 'MOCK_EXAM'
              ? 'pb-exam-badge-mock'
              : 'pb-exam-badge-assigned');
        }
        setText('exam-inst-code-badge', ex.examCode || 'ASSESSMENT');
        var availBadgeEl = document.getElementById('exam-inst-availability-badge');
        setText(
          'exam-inst-availability-badge',
          effectiveAdminPrev ? 'ADMIN PREVIEW' : formatFriendlyExamBadgeText(ex.availabilityState || 'AVAILABLE')
        );
        if (availBadgeEl) {
          availBadgeEl.classList.toggle('is-preview', effectiveAdminPrev);
        }
        setText('exam-inst-title', ex.title || 'Assessment Overview & Instructions');
        setText(
          'exam-inst-course-label',
          ex.courseCode ? ex.courseCode + ' — ' + ex.courseTitle : 'Assigned Biology Assessment'
        );

        var qCnt = Number(ex.questionCount || 0);
        var sCnt = Number(ex.sectionCount || 1);
        setText(
          'exam-inst-question-count',
          qCnt + (qCnt === 1 ? ' Question' : ' Questions') + ' • ' + sCnt + (sCnt === 1 ? ' Section' : ' Sections')
        );
        setText('exam-inst-max-points', ex.maxPointsDisplay || '0 pts');
        setText(
          'exam-inst-duration',
          (ex.durationLabel || 'Untimed (Self-Paced)') +
            (ex.hasTimeAccommodation ? ' (+' + ex.extraTimeMinutes + 'm Accommodation)' : '')
        );
        setText(
          'exam-inst-attempts',
          effectiveAdminPrev
            ? 'Unlimited Preview (' + (ex.allowedAttemptsDisplay || '1') + ' for Students)'
            : String(ex.attemptsUsed || 0) + ' used of ' + (ex.allowedAttemptsDisplay || '1')
        );
        var openTxt =
          !ex.openAtBangkok || ex.openAtBangkok === 'Immediate' || ex.openAtBangkok === 'Immediately Available'
            ? 'Open Anytime'
            : ex.openAtBangkok;
        var closeTxt =
          !ex.closeAtBangkok || ex.closeAtBangkok === 'No Deadline' || ex.closeAtBangkok === 'No Closing Deadline'
            ? 'No Deadline'
            : ex.closeAtBangkok;
        renderInstKeyValueStackDom('exam-inst-window', [
          { label: 'Opens:', value: openTxt },
          { label: 'Closes:', value: closeTxt }
        ]);
        renderInstKeyValueStackDom('exam-inst-release-policy', [
          { label: 'Score:', value: formatFriendlyPolicyLabel(ex.scoreReleasePolicy || 'IMMEDIATE_AUTO') },
          { label: 'Key:', value: formatFriendlyPolicyLabel(ex.explanationReleasePolicy || 'WITH_SCORE') }
        ]);

        renderRichTextDocumentToDom(
          document.getElementById('exam-inst-richtext-body'),
          stripExamPdfMarkersFromRichText(
            ex.instructionsRichText ||
              ex.descriptionRichText ||
              'Complete all questions carefully before submitting your responses.'
          ),
          ex.courseId
        );
        renderStudentExamPdfResourcePanel(
          document.getElementById('exam-inst-pdf-box'),
          ex.instructionsRichText,
          {
            courseId: ex.courseId,
            isAdminPreview: effectiveAdminPrev,
            hasSubmittedAttempt: (ex.attemptsUsed || 0) > 0 && !ex.canResumeAttempt,
            explanationsReleased:
              Boolean(ex.canViewPublishedResult) || Boolean(ex.publishedScoreSummary)
          }
        );

        var secCardWrap = document.getElementById('exam-inst-sections-card');
        var secTbody = document.getElementById('exam-inst-sections-tbody');
        var secs = Array.isArray(ex.sectionsOverview) ? ex.sectionsOverview : [];
        if (secCardWrap) {
          secCardWrap.classList.toggle('hidden', secs.length === 0);
        }
        if (secTbody) {
          while (secTbody.firstChild) secTbody.removeChild(secTbody.firstChild);
          for (var s = 0; s < secs.length; s++) {
            var tr = document.createElement('tr');
            var td1 = document.createElement('td');
            td1.textContent = (s + 1) + '. ' + secs[s].title;
            tr.appendChild(td1);

            var td2 = document.createElement('td');
            td2.textContent = formatFriendlyPolicyLabel(secs[s].selectionModeLabel || secs[s].selectionMode);
            tr.appendChild(td2);

            var td3 = document.createElement('td');
            td3.className = 'pb-inst-col-num';
            td3.textContent = String(secs[s].sectionQuestionsCount || 0);
            tr.appendChild(td3);

            var td4 = document.createElement('td');
            td4.className = 'pb-inst-col-num';
            td4.textContent = secs[s].sectionMaxPointsDisplay || '0 pts';
            tr.appendChild(td4);

            secTbody.appendChild(tr);
          }
        }

        var rulesCardWrap = document.getElementById('exam-inst-guidelines-card');
        var rulesUl = document.getElementById('exam-inst-rules-list');
        var rules = Array.isArray(data.rulesChecklist) ? data.rulesChecklist : [];
        if (rulesCardWrap) {
          rulesCardWrap.classList.toggle('hidden', rules.length === 0);
        }
        if (rulesUl) {
          while (rulesUl.firstChild) rulesUl.removeChild(rulesUl.firstChild);
          for (var r = 0; r < rules.length; r++) {
            var li = document.createElement('li');
            li.className = 'pb-inst-rule-item';
            var cleanLine = humanizeRuleLine(rules[r]);
            var colonIdx = cleanLine.indexOf(':');
            if (colonIdx > 0 && colonIdx < 48) {
              var pref = document.createElement('strong');
              pref.className = 'pb-inst-rule-prefix';
              pref.textContent = cleanLine.slice(0, colonIdx + 1) + ' ';
              li.appendChild(pref);
              li.appendChild(document.createTextNode(cleanLine.slice(colonIdx + 1).trim()));
            } else {
              li.textContent = cleanLine;
            }
            rulesUl.appendChild(li);
          }
        }

        if (typeof populatePreExamIntegrityDisclosurePhaseC === 'function') {
          populatePreExamIntegrityDisclosurePhaseC(ex, data.integrityPolicy || ex.integrityPolicy || null);
        }

        var ackWrap = document.getElementById('exam-inst-integrity-ack-wrap');
        if (ackWrap) {
          ackWrap.classList.toggle('hidden', effectiveAdminPrev);
        }
        var ackChk = document.getElementById('chk-exam-inst-integrity-ack');
        if (effectiveAdminPrev && ackChk) {
          ackChk.checked = true;
        }

        var startBtn = document.getElementById('btn-exam-inst-start-attempt');
        if (startBtn) {
          startBtn.classList.remove('is-btn-loading');
          if (effectiveAdminPrev) {
            startBtn.disabled = false;
            setBtnVectorIcon(
              startBtn,
              'play',
              'Open Full Preview Page',
              'Open the interactive examination preview page directly'
            );
            setText('exam-inst-status-title', 'Administrator Preview Ready');
            setText(
              'exam-inst-status-message',
              'Review the exam rules and metadata above, or click "Open Full Preview Page" to test-drive all questions interactively.'
            );
            setText(
              'exam-inst-footer-note',
              'Admin Preview Mode: interactive test-drive does not affect student records.'
            );
          } else if (ex.canResumeAttempt) {
            startBtn.disabled = false;
            startBtn.textContent = ex.examMode === 'PRACTICE' ? 'Resume Practice Quiz' : 'Resume Active Attempt';
            setText('exam-inst-status-title', 'Active Attempt Available');
            setText(
              'exam-inst-status-message',
              'You have an active attempt in progress. Clicking Resume will restore your saved responses.'
            );
            setText(
              'exam-inst-footer-note',
              'Resuming restores your previously saved responses and remaining timer.'
            );
          } else if (ex.canStartNewAttempt) {
            startBtn.disabled = false;
            startBtn.textContent =
              ex.examMode === 'PRACTICE'
                ? ex.attemptsUsed > 0
                  ? 'Start Practice Retake'
                  : 'Start Practice Quiz'
                : ex.attemptsUsed > 0
                ? 'Start Retake Attempt'
                : 'Start Examination';
            setText('exam-inst-status-title', 'Readiness Check');
            setText(
              'exam-inst-status-message',
              'You are ready to begin. Your timer starts only after you click Start.'
            );
            setText(
              'exam-inst-footer-note',
              'Your timer only begins once you start an attempt.'
            );
          } else {
            startBtn.disabled = true;
            startBtn.textContent = 'Not Available (' + formatFriendlyExamBadgeText(ex.availabilityState || 'CLOSED') + ')';
            setText('exam-inst-status-title', 'Unavailable');
            setText(
              'exam-inst-status-message',
              'This assessment cannot be started right now because its status is ' + formatFriendlyExamBadgeText(ex.availabilityState || 'CLOSED') + '.'
            );
            setText(
              'exam-inst-footer-note',
              'Attempt entry is currently locked under the schedule or attempt limit above.'
            );
          }
        }
        var loadOverlayDone = document.getElementById('exam-inst-loading-overlay');
        if (loadOverlayDone) loadOverlayDone.classList.add('hidden');
      }

      return rpcCallEnvelope(
        'exams.getInstructions',
        {
          examSetId: examSetId,
          adminPreview: isAdminPrev
        },
        { suppressErrorBanner: isAdminPrev, forceRefresh: isAdminPrev }
      )
        .then(function (env) {
          if (reqToken !== activeExamInstructionsReqToken) return;
          applyInstructionsBundleToModal(env.data || {});
        })
        .catch(function (err) {
          if (reqToken !== activeExamInstructionsReqToken) return;
          if (isAdminPrev && isCurrentSessionAdminUser()) {
            var fallback = buildFallbackAdminPreviewInstructionsBundle(examSetId);
            if (fallback) {
              applyInstructionsBundleToModal(fallback);
              return;
            }
          }
          var loadOverlayErr = document.getElementById('exam-inst-loading-overlay');
          if (loadOverlayErr) loadOverlayErr.classList.add('hidden');
          var startBtnErr = document.getElementById('btn-exam-inst-start-attempt');
          if (startBtnErr) {
            startBtnErr.disabled = true;
            startBtnErr.classList.remove('is-btn-loading');
            startBtnErr.textContent = 'Unavailable';
          }
          setText('exam-inst-title', 'Unable to Load Instructions');
          setText('exam-inst-status-message', (err && err.message) || 'Error loading examination rules.');
        });
    }

    function restoreFormsPreviewButtonsState() {
      forceRestoreLoadingButton('btn-forms-preview-exam');
      forceRestoreLoadingButton('btn-forms-preview-exam-bottom');
    }

    function closeStudentExamInstructionsModalPhase3() {
      activeExamInstructionsReqToken++;
      var loadOverlay = document.getElementById('exam-inst-loading-overlay');
      if (loadOverlay) loadOverlay.classList.add('hidden');
      currentSelectedInstructionExamPhase3 = null;
      closeModalDialog('modal-student-exam-instructions');
      restoreFormsPreviewButtonsState();
    }


    // ========================================================================
    // EXAM PHASE 4: CLIENT ATTEMPT ENGINE, SERVER-SYNCED COUNTDOWN CLOCK,
    // MULTI-TAB LEASE GUARD & QUOTA-SAFE DEBOUNCED BATCH AUTOSAVE
    // ========================================================================
    window.PBExamAutosaveEngine = (function () {
      var DEBOUNCE_MS = 2500;
      var state = {
        attempt: null,
        exam: null,
        sections: [],
        items: [],
        itemsById: {},
        localResponsesByItemId: {},
        pendingDirtyByItemId: {},
        flagsByItemId: {},
        clientRevisionCounter: 0,
        serverTimeOffsetMs: 0,
        saveState: 'IDLE',
        lastSavedAtBangkok: '',
        lastSaveError: '',
        inFlightSavePromise: null,
        needsFollowUpFlush: false,
        debounceTimerId: null,
        countdownIntervalId: null,
        onStateChangeCallback: null
      };

      function notifyListeners() {
        if (typeof state.onStateChangeCallback === 'function') {
          try {
            state.onStateChangeCallback(getSnapshot());
          } catch (ignoreErr) {}
        }
      }

      function getStorageKey(userId, attemptId) {
        if (!userId || !attemptId) return '';
        return 'pb_exam_draft_v1_' + String(userId) + '_' + String(attemptId);
      }

      function readLocalDraftSafe(userId, attemptId) {
        var key = getStorageKey(userId, attemptId);
        if (!key) return null;
        try {
          if (typeof window !== 'undefined' && window.localStorage) {
            var raw = window.localStorage.getItem(key);
            if (raw) {
              var parsed = JSON.parse(raw);
              if (parsed && parsed.attemptId === attemptId && parsed.userId === userId) {
                return parsed;
              }
            }
          }
        } catch (ignoreStorageErr) {}
        return null;
      }

      function writeLocalDraftSafe() {
        if (!state.attempt) return;
        var key = getStorageKey(state.attempt.studentUserId, state.attempt.attemptId);
        if (!key) return;
        try {
          if (typeof window !== 'undefined' && window.localStorage) {
            var dirtyKeys = Object.keys(state.pendingDirtyByItemId);
            if (dirtyKeys.length === 0) {
              window.localStorage.removeItem(key);
              return;
            }
            var payload = {
              userId: state.attempt.studentUserId,
              attemptId: state.attempt.attemptId,
              examSetId: state.attempt.examSetId,
              clientRevisionCounter: state.clientRevisionCounter,
              savedAtLocalMs: Date.now(),
              pendingDirtyByItemId: state.pendingDirtyByItemId
            };
            window.localStorage.setItem(key, JSON.stringify(payload));
          }
        } catch (ignoreStorageErr) {}
      }

      function clearLocalDraft(userId, attemptId) {
        var uId = userId || (state.attempt && state.attempt.studentUserId) || '';
        var aId = attemptId || (state.attempt && state.attempt.attemptId) || '';
        var key = getStorageKey(uId, aId);
        if (!key) return;
        try {
          if (typeof window !== 'undefined' && window.localStorage) {
            window.localStorage.removeItem(key);
          }
        } catch (ignoreStorageErr) {}
      }

      function computeIsResponseNonEmpty(responsePayload) {
        var p = responsePayload && typeof responsePayload === 'object' ? responsePayload : {};
        if (p.selectedOptionId && String(p.selectedOptionId).trim()) return true;
        if (Array.isArray(p.selectedOptionIds) && p.selectedOptionIds.length > 0) return true;
        if (p.statementDecisions && typeof p.statementDecisions === 'object') {
          var decKeys = Object.keys(p.statementDecisions);
          for (var i = 0; i < decKeys.length; i++) {
            var v = String(p.statementDecisions[decKeys[i]] || '').toUpperCase();
            if (v === 'YES' || v === 'NO') return true;
          }
        }
        if (p.numericText !== undefined && p.numericText !== null && String(p.numericText).trim() !== '') return true;
        if (p.textResponse !== undefined && p.textResponse !== null && String(p.textResponse).trim() !== '') return true;
        return false;
      }

      function syncServerClockOffset(serverNowUtc) {
        if (!serverNowUtc) return;
        var srvMs = Date.parse(serverNowUtc);
        if (!isNaN(srvMs)) {
          state.serverTimeOffsetMs = srvMs - Date.now();
        }
      }

      function getAuthoritativeNowMs() {
        return Date.now() + state.serverTimeOffsetMs;
      }

      function getRemainingSeconds() {
        if (!state.attempt) {
          return null;
        }
        var deadlineStr = state.attempt.effectiveDeadlineUtc || state.attempt.serverDeadlineUtc || '';
        if (!deadlineStr) {
          return null;
        }
        var deadMs = Date.parse(deadlineStr);
        if (isNaN(deadMs)) return null;
        return Math.max(0, Math.floor((deadMs - getAuthoritativeNowMs()) / 1000));
      }

      function loadFromWorkspaceBundle(bundle) {
        if (!bundle || !bundle.attempt) return null;
        if (state.debounceTimerId) {
          clearTimeout(state.debounceTimerId);
          state.debounceTimerId = null;
        }

        syncServerClockOffset(bundle.serverNowUtc);
        state.attempt = bundle.attempt;
        if (
          !state.attempt.effectiveDeadlineUtc &&
          !state.attempt.serverDeadlineUtc &&
          typeof state.attempt.remainingSeconds === 'number' &&
          state.attempt.remainingSeconds > 0
        ) {
          state.attempt.effectiveDeadlineUtc = new Date(
            getAuthoritativeNowMs() + state.attempt.remainingSeconds * 1000
          ).toISOString();
        }
        state.exam = bundle.exam || {};
        state.sections = Array.isArray(bundle.sections) ? bundle.sections : [];
        state.items = Array.isArray(bundle.items) ? bundle.items : [];
        state.itemsById = {};
        state.localResponsesByItemId = {};
        state.pendingDirtyByItemId = {};
        state.flagsByItemId = {};
        state.lastSavedAtBangkok = bundle.attempt.lastSavedAtBangkok || '';
        state.lastSaveError = '';

        var maxRev = Number(bundle.attempt.latestRevisionNo) || 0;
        var savedMap = bundle.savedResponsesByItemId || {};

        for (var i = 0; i < state.items.length; i++) {
          var it = state.items[i];
          state.itemsById[it.attemptItemId] = it;
          state.flagsByItemId[it.attemptItemId] = Boolean(it.isFlagged);

          var srvResp = savedMap[it.attemptItemId] || it.savedResponse || null;
          if (srvResp) {
            var cRev = Number(srvResp.clientRevisionNo) || 0;
            if (cRev > maxRev) maxRev = cRev;
            state.localResponsesByItemId[it.attemptItemId] = {
              attemptItemId: it.attemptItemId,
              responsePayload: srvResp.responsePayload || {},
              isAnsweredLocal: Boolean(srvResp.isAnswered),
              isSavedOnServer: true,
              clientRevisionNo: cRev,
              serverRevisionNo: Number(srvResp.serverRevisionNo) || 0,
              savedAtBangkok: srvResp.savedAtBangkok || ''
            };
          } else {
            state.localResponsesByItemId[it.attemptItemId] = {
              attemptItemId: it.attemptItemId,
              responsePayload: {},
              isAnsweredLocal: false,
              isSavedOnServer: false,
              clientRevisionNo: 0,
              serverRevisionNo: 0,
              savedAtBangkok: ''
            };
          }
        }

        state.clientRevisionCounter = maxRev;
        state.saveState = 'SAVED';

        // Recover any unsynced local draft for this exact user + attempt
        var recoveredDraft = readLocalDraftSafe(
          state.attempt.studentUserId,
          state.attempt.attemptId
        );
        if (recoveredDraft && recoveredDraft.pendingDirtyByItemId) {
          var dKeys = Object.keys(recoveredDraft.pendingDirtyByItemId);
          var recoveredCount = 0;
          for (var dk = 0; dk < dKeys.length; dk++) {
            var itemId = dKeys[dk];
            var dEntry = recoveredDraft.pendingDirtyByItemId[itemId];
            var curEntry = state.localResponsesByItemId[itemId];
            if (
              dEntry &&
              curEntry &&
              Number(dEntry.clientRevisionNo) > Number(curEntry.clientRevisionNo)
            ) {
              if (Number(dEntry.clientRevisionNo) > state.clientRevisionCounter) {
                state.clientRevisionCounter = Number(dEntry.clientRevisionNo);
              }
              state.pendingDirtyByItemId[itemId] = dEntry;
              state.localResponsesByItemId[itemId] = {
                attemptItemId: itemId,
                responsePayload: dEntry.responsePayload || {},
                isAnsweredLocal: computeIsResponseNonEmpty(dEntry.responsePayload),
                isSavedOnServer: false,
                clientRevisionNo: Number(dEntry.clientRevisionNo),
                serverRevisionNo: curEntry.serverRevisionNo,
                savedAtBangkok: curEntry.savedAtBangkok
              };
              recoveredCount += 1;
            }
          }
          if (recoveredCount > 0) {
            state.saveState = 'UNSAVED_CHANGES';
          }
        }

        notifyListeners();
        return getSnapshot();
      }

      function queueResponseChange(attemptItemId, responsePayload, opt_flushImmediately) {
        if (!state.attempt || !state.itemsById[attemptItemId]) {
          return null;
        }
        state.clientRevisionCounter += 1;
        var revNo = state.clientRevisionCounter;
        var isAns = computeIsResponseNonEmpty(responsePayload);
        var isPreviewMode = Boolean(state.attempt && state.attempt._isAdminPreview);

        state.localResponsesByItemId[attemptItemId] = {
          attemptItemId: attemptItemId,
          responsePayload: responsePayload || {},
          isAnsweredLocal: isAns,
          isSavedOnServer: isPreviewMode ? true : false,
          clientRevisionNo: revNo,
          serverRevisionNo:
            (state.localResponsesByItemId[attemptItemId] &&
              state.localResponsesByItemId[attemptItemId].serverRevisionNo) ||
            (isPreviewMode ? revNo : 0),
          savedAtBangkok:
            isPreviewMode
              ? 'Preview Ready'
              : ((state.localResponsesByItemId[attemptItemId] &&
                  state.localResponsesByItemId[attemptItemId].savedAtBangkok) ||
                '')
        };

        if (isPreviewMode) {
          delete state.pendingDirtyByItemId[attemptItemId];
          state.saveState = 'SAVED';
          notifyListeners();
          return Promise.resolve(getSnapshot());
        }

        state.pendingDirtyByItemId[attemptItemId] = {
          attemptItemId: attemptItemId,
          responsePayload: responsePayload || {},
          clientRevisionNo: revNo,
          queuedAtMs: Date.now()
        };

        state.saveState = 'UNSAVED_CHANGES';
        writeLocalDraftSafe();
        notifyListeners();

        if (state.debounceTimerId) {
          clearTimeout(state.debounceTimerId);
          state.debounceTimerId = null;
        }

        if (opt_flushImmediately) {
          return flushPendingSaves(false);
        }

        state.debounceTimerId = setTimeout(function () {
          state.debounceTimerId = null;
          flushPendingSaves(false);
        }, DEBOUNCE_MS);

        return Promise.resolve(getSnapshot());
      }

      function flushPendingSaves(opt_forceTakeoverLease) {
        if (state.debounceTimerId) {
          clearTimeout(state.debounceTimerId);
          state.debounceTimerId = null;
        }
        if (!state.attempt) {
          return Promise.resolve(getSnapshot());
        }

        if (state.attempt._isAdminPreview) {
          var prevDirtyIds = Object.keys(state.pendingDirtyByItemId);
          for (var p = 0; p < prevDirtyIds.length; p++) {
            var pid = prevDirtyIds[p];
            delete state.pendingDirtyByItemId[pid];
            if (state.localResponsesByItemId[pid]) {
              state.localResponsesByItemId[pid].isSavedOnServer = Boolean(
                state.localResponsesByItemId[pid].isAnsweredLocal
              );
              state.localResponsesByItemId[pid].savedAtBangkok = 'Preview Mode';
            }
          }
          state.saveState = 'SAVED';
          state.lastSavedAtBangkok = 'Preview Mode';
          notifyListeners();
          return Promise.resolve(getSnapshot());
        }

        var dirtyIds = Object.keys(state.pendingDirtyByItemId);
        if (dirtyIds.length === 0) {
          return Promise.resolve(getSnapshot());
        }

        if (state.inFlightSavePromise) {
          state.needsFollowUpFlush = true;
          return state.inFlightSavePromise;
        }

        var batchEntries = [];
        var maxBatchRev = state.clientRevisionCounter;
        for (var i = 0; i < dirtyIds.length; i++) {
          var d = state.pendingDirtyByItemId[dirtyIds[i]];
          batchEntries.push({
            attemptItemId: d.attemptItemId,
            responsePayload: d.responsePayload,
            clientRevisionNo: d.clientRevisionNo
          });
        }

        state.saveState = 'SAVING';
        state.lastSaveError = '';
        notifyListeners();

        var rpcPayload = {
          attemptId: state.attempt.attemptId,
          leaseToken: state.attempt.leaseToken,
          forceTakeoverLease: Boolean(opt_forceTakeoverLease),
          clientRevisionNo: maxBatchRev,
          responses: batchEntries
        };

        state.inFlightSavePromise = rpcCallEnvelope('exams.saveResponses', rpcPayload)
          .then(function (env) {
            state.inFlightSavePromise = null;
            var res = env.data || {};
            syncServerClockOffset(res.serverNowUtc);
            if (res.leaseToken && state.attempt) {
              state.attempt.leaseToken = res.leaseToken;
            }
            state.lastSavedAtBangkok = res.lastSavedAtBangkok || state.lastSavedAtBangkok;

            var statuses = Array.isArray(res.itemSaveStatuses) ? res.itemSaveStatuses : [];
            for (var s = 0; s < statuses.length; s++) {
              var st = statuses[s];
              var itemId = st.attemptItemId;
              var pendingNow = state.pendingDirtyByItemId[itemId];
              // Only clear pending dirty entry if the student did not edit that item again while RPC was in flight
              if (pendingNow && Number(pendingNow.clientRevisionNo) <= Number(st.clientRevisionNo)) {
                delete state.pendingDirtyByItemId[itemId];
                if (state.localResponsesByItemId[itemId]) {
                  state.localResponsesByItemId[itemId].isSavedOnServer = Boolean(st.isAnswered);
                  state.localResponsesByItemId[itemId].serverRevisionNo = Number(st.serverRevisionNo) || 0;
                  state.localResponsesByItemId[itemId].savedAtBangkok =
                    st.savedAtBangkok || res.lastSavedAtBangkok || '';
                }
              }
            }

            writeLocalDraftSafe();
            var remainingDirty = Object.keys(state.pendingDirtyByItemId).length;
            state.saveState = remainingDirty > 0 ? 'UNSAVED_CHANGES' : 'SAVED';
            notifyListeners();

            if (state.needsFollowUpFlush || remainingDirty > 0) {
              state.needsFollowUpFlush = false;
              return flushPendingSaves(false);
            }
            return getSnapshot();
          })
          .catch(function (err) {
            state.inFlightSavePromise = null;
            var code = (err && err.code) || 'ERR';
            state.lastSaveError = (err && err.message) || 'Failed to save responses.';
            if (code === 'ERR_EXAM_LEASE_CONFLICT') {
              state.saveState = 'LEASE_CONFLICT';
            } else if (code === 'ERR_EXAM_DEADLINE_EXPIRED') {
              state.saveState = 'DEADLINE_EXPIRED';
              if (state.attempt) {
                state.attempt.attemptStatus = 'EXPIRED_SUBMITTED';
              }
            } else {
              state.saveState = 'SAVE_FAILED';
            }
            writeLocalDraftSafe();
            notifyListeners();
            throw err;
          });

        return state.inFlightSavePromise;
      }

      function toggleItemFlag(attemptItemId, opt_explicitFlagBoolean) {
        if (!state.attempt || !state.itemsById[attemptItemId]) {
          return Promise.resolve(null);
        }
        var nextFlag =
          opt_explicitFlagBoolean !== undefined
            ? Boolean(opt_explicitFlagBoolean)
            : !state.flagsByItemId[attemptItemId];
        state.flagsByItemId[attemptItemId] = nextFlag;
        state.itemsById[attemptItemId].isFlagged = nextFlag;
        notifyListeners();

        if (state.attempt._isAdminPreview) {
          return Promise.resolve({ flaggedCount: getSnapshot().flaggedCount });
        }

        return rpcCallEnvelope('exams.saveFlags', {
          attemptId: state.attempt.attemptId,
          leaseToken: state.attempt.leaseToken,
          flags: [{ attemptItemId: attemptItemId, isFlagged: nextFlag }]
        }).then(function (env) {
          var res = env.data || {};
          if (state.attempt && res.flaggedCount !== undefined) {
            state.attempt.flaggedCount = Number(res.flaggedCount) || 0;
          }
          state.lastSavedAtBangkok = res.lastSavedAtBangkok || state.lastSavedAtBangkok;
          notifyListeners();
          return res;
        });
      }

      function getSnapshot() {
        var answeredLocalCount = 0;
        var answeredServerCount = 0;
        var flaggedCount = 0;
        var keys = Object.keys(state.localResponsesByItemId);
        for (var i = 0; i < keys.length; i++) {
          var r = state.localResponsesByItemId[keys[i]];
          if (r.isAnsweredLocal) answeredLocalCount += 1;
          if (r.isSavedOnServer && r.isAnsweredLocal) answeredServerCount += 1;
        }
        var fKeys = Object.keys(state.flagsByItemId);
        for (var j = 0; j < fKeys.length; j++) {
          if (state.flagsByItemId[fKeys[j]]) flaggedCount += 1;
        }
        return {
          attempt: state.attempt,
          exam: state.exam,
          sections: state.sections,
          items: state.items,
          localResponsesByItemId: state.localResponsesByItemId,
          pendingDirtyCount: Object.keys(state.pendingDirtyByItemId).length,
          flagsByItemId: state.flagsByItemId,
          answeredLocalCount: answeredLocalCount,
          answeredServerCount: answeredServerCount,
          unansweredCount: Math.max(0, state.items.length - answeredLocalCount),
          flaggedCount: flaggedCount,
          remainingSeconds: getRemainingSeconds(),
          saveState: state.saveState,
          lastSavedAtBangkok: state.lastSavedAtBangkok,
          lastSaveError: state.lastSaveError,
          clientRevisionCounter: state.clientRevisionCounter
        };
      }

      function reset() {
        if (state.debounceTimerId) {
          clearTimeout(state.debounceTimerId);
          state.debounceTimerId = null;
        }
        if (state.countdownIntervalId) {
          clearInterval(state.countdownIntervalId);
          state.countdownIntervalId = null;
        }
        state.attempt = null;
        state.exam = null;
        state.sections = [];
        state.items = [];
        state.itemsById = {};
        state.localResponsesByItemId = {};
        state.pendingDirtyByItemId = {};
        state.flagsByItemId = {};
        state.clientRevisionCounter = 0;
        state.serverTimeOffsetMs = 0;
        state.saveState = 'IDLE';
        state.lastSavedAtBangkok = '';
        state.lastSaveError = '';
        state.inFlightSavePromise = null;
        state.needsFollowUpFlush = false;
        state.onStateChangeCallback = null;
      }

      return {
        loadFromWorkspaceBundle: loadFromWorkspaceBundle,
        queueResponseChange: queueResponseChange,
        flushPendingSaves: flushPendingSaves,
        toggleItemFlag: toggleItemFlag,
        getRemainingSeconds: getRemainingSeconds,
        getSnapshot: getSnapshot,
        clearLocalDraft: clearLocalDraft,
        getStorageKey: getStorageKey,
        reset: reset,
        setOnStateChange: function (fn) {
          state.onStateChangeCallback = fn;
        }
      };
    })();

    function launchAdminInteractiveExamWorkspacePreview(examDto) {
      if (!isCurrentSessionAdminUser()) {
        return Promise.reject(new Error('Administrator session required.'));
      }
      var startBtn = document.getElementById('btn-exam-inst-start-attempt');
      if (startBtn) {
        startBtn.disabled = true;
        startBtn.classList.add('is-btn-loading');
        startBtn.textContent = 'Building Interactive Question Preview...';
      }

      var ensureQuestionsLoaded = rpcCallEnvelope(
        'admin.questions.list',
        { page: 1, limit: 200, includePrivate: true },
        { suppressErrorBanner: true, forceRefresh: true }
      )
        .then(function (env) {
          var d = env.data || {};
          currentQBankQuestionsPhase2 = Array.isArray(d.questions) ? d.questions : [];
          return currentQBankQuestionsPhase2;
        })
        .catch(function () {
          return currentQBankQuestionsPhase2 || [];
        });

      var ensureExamsLoaded = rpcCallEnvelope('admin.exams.list', {}, { suppressErrorBanner: true, forceRefresh: true })
        .then(function (env) {
          var d = env.data || {};
          currentAdminExamsListPhase3 = Array.isArray(d.exams) ? d.exams : [];
          if (examDto && examDto.examSetId) {
            for (var fei = 0; fei < currentAdminExamsListPhase3.length; fei++) {
              var freshEx = currentAdminExamsListPhase3[fei];
              if (freshEx && freshEx.examSetId === examDto.examSetId) {
                var alreadyHasPreviewSections =
                  Boolean(examDto._isAdminPreview) &&
                  Array.isArray(examDto.sections) &&
                  examDto.sections.length > 0;
                if (!alreadyHasPreviewSections && Array.isArray(freshEx.sections) && freshEx.sections.length > 0) {
                  examDto.sections = freshEx.sections;
                  if (freshEx.title) examDto.title = freshEx.title;
                  if (freshEx.description !== undefined) examDto.description = freshEx.description;
                  if (freshEx.durationMinutes !== undefined) examDto.durationMinutes = freshEx.durationMinutes;
                  if (freshEx.examVersionId) examDto.examVersionId = freshEx.examVersionId;
                  if (freshEx.updatedAt) examDto.updatedAt = freshEx.updatedAt;
                }
                break;
              }
            }
          }
          return currentAdminExamsListPhase3;
        })
        .catch(function () {
          return currentAdminExamsListPhase3 || [];
        });

      return Promise.all([ensureQuestionsLoaded, ensureExamsLoaded]).then(function () {
        var adminExam = null;
        if (Array.isArray(currentAdminExamsListPhase3)) {
          for (var i = 0; i < currentAdminExamsListPhase3.length; i++) {
            if (currentAdminExamsListPhase3[i] && currentAdminExamsListPhase3[i].examSetId === examDto.examSetId) {
              adminExam = currentAdminExamsListPhase3[i];
              break;
            }
          }
        }
        var qById = {};
        if (Array.isArray(currentQBankQuestionsPhase2)) {
          for (var q = 0; q < currentQBankQuestionsPhase2.length; q++) {
            var qb = currentQBankQuestionsPhase2[q];
            if (qb && qb.questionId) qById[qb.questionId] = qb;
          }
        }

        var secs =
          (examDto && examDto._isAdminPreview && Array.isArray(examDto.sections) && examDto.sections.length > 0
            ? examDto.sections
            : null) ||
          (adminExam && Array.isArray(adminExam.sections) && adminExam.sections) ||
          examDto.sections ||
          [];
        var previewItems = [];
        var dispNum = 1;
        for (var s = 0; s < secs.length; s++) {
          var sec = secs[s] || {};
          var secItems = Array.isArray(sec.items) ? sec.items : [];
          for (var it = 0; it < secItems.length; it++) {
            var itemObj = secItems[it] || {};
            var qId = itemObj.questionId || itemObj.question_id || '';
            var targetQvId = itemObj.questionVersionId || itemObj.question_version_id || '';
            var prevQ = itemObj.question || itemObj.questionPreview || null;
            var bankQ = qById[qId] || null;
            var fullQ = {};
            if (prevQ && prevQ.questionId && (!targetQvId || !prevQ.questionVersionId || prevQ.questionVersionId === targetQvId)) {
              fullQ = prevQ;
              if (bankQ && (!targetQvId || bankQ.questionVersionId === targetQvId) && Array.isArray(bankQ.options) && bankQ.options.length > 0 && (!Array.isArray(prevQ.options) || prevQ.options.length === 0)) {
                fullQ = bankQ;
              }
            } else if (bankQ && (!targetQvId || bankQ.questionVersionId === targetQvId)) {
              fullQ = bankQ;
            } else {
              fullQ = prevQ || bankQ || {};
            }
            if (fullQ && fullQ.privateGradingData) {
              var fullQPriv = fullQ.privateGradingData;
              if (!fullQ.explanationRichText && fullQPriv.explanationRichText) {
                fullQ = Object.assign({}, fullQ, { explanationRichText: fullQPriv.explanationRichText });
              }
              if (!fullQ.gradingSpec && fullQPriv.gradingSpec) {
                fullQ = Object.assign({}, fullQ, { gradingSpec: fullQPriv.gradingSpec });
              }
            }
            var rawOpts = Array.isArray(fullQ.options) ? fullQ.options : [];
            var mappedOpts = [];
            for (var o = 0; o < rawOpts.length; o++) {
              mappedOpts.push({
                optionId: rawOpts[o].optionId || 'opt_' + (o + 1),
                optionKey: rawOpts[o].optionKey || (fullQ.questionType === 'COMPLEX_MULTIPLE_CHOICE' ? 'S' + (o + 1) : String.fromCharCode(65 + o)),
                displayLabel:
                  fullQ.questionType === 'COMPLEX_MULTIPLE_CHOICE'
                    ? String(o + 1)
                    : rawOpts[o].optionKey || String.fromCharCode(65 + o),
                contentRichText: rawOpts[o].contentRichText || rawOpts[o].text || '',
                isCorrect: Boolean(rawOpts[o].isCorrect)
              });
            }
            var resolvedPts =
              secItems[it].points !== undefined && secItems[it].points !== null && secItems[it].points !== ''
                ? Number(secItems[it].points)
                : secItems[it].pointsBp !== undefined && secItems[it].pointsBp !== null
                ? Number(secItems[it].pointsBp) / 100
                : fullQ.defaultPoints !== undefined && fullQ.defaultPoints !== null && fullQ.defaultPoints !== ''
                ? Number(fullQ.defaultPoints)
                : fullQ.defaultPointsBp !== undefined && fullQ.defaultPointsBp !== null
                ? Number(fullQ.defaultPointsBp) / 100
                : 2.4;
            var isFreePrevItem =
              Boolean(secItems[it] && secItems[it].isFreeQuestion) ||
              Boolean(fullQ && fullQ.isFreeQuestion) ||
              resolvedPts === 0 ||
              String((secItems[it] && secItems[it].pointsDisplay) || '').toLowerCase().indexOf('free') !== -1;
            var pts = isFreePrevItem
              ? 0
              : (isFinite(resolvedPts) && resolvedPts >= 0 ? Math.round(resolvedPts * 100) / 100 : 2.4);
            var resolvedNegPts =
              secItems[it].negativePoints !== undefined && secItems[it].negativePoints !== null && secItems[it].negativePoints !== ''
                ? Number(secItems[it].negativePoints)
                : secItems[it].negativePointsBp !== undefined && secItems[it].negativePointsBp !== null
                ? Number(secItems[it].negativePointsBp) / 100
                : fullQ.negativePoints !== undefined && fullQ.negativePoints !== null && fullQ.negativePoints !== ''
                ? Number(fullQ.negativePoints)
                : fullQ.negativePointsBp !== undefined && fullQ.negativePointsBp !== null
                ? Number(fullQ.negativePointsBp) / 100
                : 0;
            var negPts = isFreePrevItem ? 0 : (isFinite(resolvedNegPts) && resolvedNegPts > 0 ? Math.round(resolvedNegPts * 100) / 100 : 0);
            previewItems.push({
              attemptItemId: 'prev_item_' + dispNum,
              displayNumber: dispNum,
              sectionTitle: sec.title || 'Part I',
              isFreeQuestion: isFreePrevItem,
              pointsBp: Math.round(pts * 100),
              pointsDisplay: isFreePrevItem ? 'Free Question' : (pts + (pts === 1 ? ' pt' : ' pts')),
              negativePointsBp: Math.round(negPts * 100),
              negativePointsDisplay: negPts + (negPts === 1 ? ' pt' : ' pts'),
              isFlagged: false,
              question: {
                questionId: qId || 'q_prev_' + dispNum,
                questionCode: fullQ.questionCode || 'Q-' + dispNum,
                title: fullQ.title || 'Question ' + dispNum,
                questionType: fullQ.questionType || 'SINGLE_CHOICE',
                stemRichText: fullQ.stemRichText || fullQ.title || 'Sample question stem',
                imageFileId: fullQ.imageFileId || '',
                imageFileIds: fullQ.imageFileIds || [],
                imageAltText: fullQ.imageAltText || '',
                selectionInstruction:
                  fullQ.questionType === 'COMPLEX_MULTIPLE_CHOICE'
                    ? 'Complex Multiple Choice: Evaluate each sub-statement and select "Yes" or "No".'
                    : fullQ.questionType === 'MULTIPLE_SELECT'
                    ? 'Select all correct answers.'
                    : fullQ.questionType === 'NUMERIC_RESPONSE'
                    ? 'Enter your numeric response below.'
                    : fullQ.questionType === 'SHORT_ANSWER' || fullQ.questionType === 'WRITTEN_RESPONSE'
                    ? 'Type your answer below.'
                    : 'Select the single best answer.',
                options: mappedOpts,
                explanationRichText: fullQ.explanationRichText || 'Review the biological concept in your course notes.',
                acceptedAnswers: fullQ.acceptedAnswers || [],
                numericTarget: fullQ.numericTarget,
                numericTolerance: fullQ.numericTolerance,
                unitLabel: fullQ.unitLabel || ''
              }
            });
            dispNum++;
          }
        }

        if (previewItems.length === 0) {
          previewItems.push({
            attemptItemId: 'prev_item_1',
            displayNumber: 1,
            sectionTitle: 'Part I',
            pointsBp: 200,
            pointsDisplay: '2 pts',
            negativePointsBp: 0,
            negativePointsDisplay: '0 pts',
            isFlagged: false,
            question: {
              questionId: 'q_prev_1',
              questionCode: 'PREVIEW-01',
              title: 'Sample Preview Question',
              questionType: 'SINGLE_CHOICE',
              stemRichText: 'No questions have been linked to this exam section yet. Add question cards in the Exam Builder to preview them here.',
              selectionInstruction: 'Select the single best answer.',
              options: [
                { optionId: 'opt_1', optionKey: 'A', displayLabel: 'A', contentRichText: 'Sample Option A', isCorrect: true },
                { optionId: 'opt_2', optionKey: 'B', displayLabel: 'B', contentRichText: 'Sample Option B', isCorrect: false }
              ],
              explanationRichText: 'This is a sample preview explanation.'
            }
          });
        }

        var durMin = Number((adminExam && adminExam.durationMinutes) || examDto.effectiveDurationMinutes || examDto.durationMinutes || 0);
        var nowMs = Date.now();
        var deadlineUtc = durMin > 0 ? new Date(nowMs + durMin * 60 * 1000).toISOString() : '';

        var previewBundle = {
          serverNowUtc: new Date(nowMs).toISOString(),
          attempt: {
            attemptId: 'ADMIN-PREVIEW-' + (examDto.examCode || 'EXAM'),
            examSetId: examDto.examSetId,
            courseId: (adminExam && adminExam.courseId) || examDto.courseId || '',
            studentUserId: (currentSessionMeta && currentSessionMeta.user && currentSessionMeta.user.user_id) || 'admin',
            attemptNumber: 1,
            attemptStatus: 'IN_PROGRESS',
            leaseToken: 'preview_lease',
            effectiveDeadlineUtc: deadlineUtc,
            effectiveDeadlineBangkok: durMin > 0 ? durMin + ' min preview timer' : 'Untimed Preview',
            lastSavedAtBangkok: 'Preview Mode',
            latestRevisionNo: 1,
            _isAdminPreview: true
          },
          exam: {
            examSetId: examDto.examSetId,
            examCode: (adminExam && adminExam.examCode) || examDto.examCode || 'PREVIEW',
            title: ((adminExam && adminExam.title) || examDto.title || 'Exam') + ' (Admin Preview)',
            examMode: (adminExam && adminExam.examMode) || examDto.examMode || 'PRACTICE',
            examModeLabel: 'Admin Preview • ' + ((adminExam && adminExam.examModeLabel) || examDto.examModeLabel || 'Exam'),
            allowPerQuestionPracticeFeedback: true,
            navigationMode: 'FREE'
          },
          sections: secs,
          items: previewItems,
          savedResponsesByItemId: {},
          integrityPolicy: {
            copyPolicyEnabled: false
          }
        };

        if (startBtn) {
          startBtn.disabled = false;
          startBtn.classList.remove('is-btn-loading');
          startBtn.textContent = 'Launch Interactive Question Preview';
        }
        closeStudentExamInstructionsModalPhase3();
        if (typeof PBAdminActionModal === 'object' && PBAdminActionModal) {
          PBAdminActionModal.close();
        }
        openStudentExamWorkspacePhase5(previewBundle);
        PBNotify.toast(
          'info',
          'Admin Exam Preview Active',
          'You are previewing "' + (examDto.title || 'Exam') + '". Click "Check Answer" on any question or "Exit Preview" when done.'
        );
        return previewBundle;
      }).catch(function (prevErr) {
        if (startBtn) {
          startBtn.disabled = false;
          startBtn.classList.remove('is-btn-loading');
          startBtn.textContent = 'Launch Interactive Question Preview';
        }
        PBNotify.toast(
          'danger',
          'Preview Launch Failed',
          (prevErr && prevErr.message) || 'Could not launch interactive question preview.'
        );
        return null;
      });
    }

    function handleStartOrResumeExamAttemptPhase4(examDto) {
      if (!examDto || !examDto.examSetId) return Promise.resolve(null);
      if (examDto._isAdminPreview) {
        if (!isCurrentSessionAdminUser()) {
          examDto._isAdminPreview = false;
        } else {
          return launchAdminInteractiveExamWorkspacePreview(examDto);
        }
      }
      var action = examDto.canResumeAttempt && examDto.activeAttemptId
        ? 'exams.getAttempt'
        : 'exams.startAttempt';
      var isResume = Boolean(examDto.canResumeAttempt && examDto.activeAttemptId);
      var intPol = examDto.integrityPolicy || null;
      var ackChk = document.getElementById('chk-exam-inst-integrity-ack');
      if (!isResume && intPol && intPol.copyPolicyEnabled && ackChk && !ackChk.checked) {
        PBNotify.toast(
          'warning',
          'Policy Acknowledgment Required',
          'Please check the box acknowledging the Copy-Restriction and Examination-Integrity Policy before starting.'
        );
        ackChk.focus();
        return Promise.resolve(null);
      }
      var startBtn = document.getElementById('btn-exam-inst-start-attempt');
      if (startBtn) {
        startBtn.disabled = true;
        startBtn.classList.add('is-btn-loading');
        startBtn.textContent = 'Authorizing Attempt & Deadline...';
      }
      var payload = isResume
        ? { attemptId: examDto.activeAttemptId, acquireLease: true }
        : {
            examSetId: examDto.examSetId,
            idempotencyKey: 'start_' + examDto.examSetId + '_' + (Number(examDto.attemptsUsed || 0) + 1),
            requireIntegrityPolicyAck: Boolean(intPol && intPol.copyPolicyEnabled),
            policyAcknowledged: Boolean(!intPol || !intPol.copyPolicyEnabled || !ackChk || ackChk.checked),
            policyVersion: (intPol && intPol.policyVersion) || 'pb-exam-integrity-v1'
          };

      return rpcCallEnvelope(action, payload)
        .then(function (env) {
          var bundle = env.data || {};
          var snapshot = window.PBExamAutosaveEngine.loadFromWorkspaceBundle(bundle);
          closeStudentExamInstructionsModalPhase3();
          loadStudentCourseExamsCatalogPhase3(examDto.courseId || currentStudentCourseId);

          if (typeof openStudentExamWorkspacePhase5 === 'function') {
            openStudentExamWorkspacePhase5(bundle);
          } else {
            var qLen = bundle.items ? bundle.items.length : 0;
            PBNotify.toast(
              'success',
              bundle.resumedExistingAttempt || bundle.idempotentReplay
                ? 'Attempt Restored'
                : 'Attempt Started',
              'Attempt #' +
                (bundle.attempt && bundle.attempt.attemptNumber) +
                ' initialized (' +
                qLen +
                (qLen === 1 ? ' question' : ' questions') +
                '). Server deadline: ' +
                ((bundle.attempt && bundle.attempt.effectiveDeadlineBangkok) || 'Untimed')
            );
          }
          return snapshot;
        })
        .catch(function (err) {
          if (startBtn) {
            startBtn.disabled = false;
            startBtn.textContent = examDto.canResumeAttempt
              ? 'Resume Active Attempt'
              : 'Start Authorized Attempt';
          }
          setText(
            'exam-inst-status-message',
            'Unable to start attempt: ' + ((err && err.message) || 'Error')
          );
          PBNotify.toast('danger', 'Attempt Start Blocked', (err && err.message) || 'Failed to start attempt.');
        });
    }

    // ========================================================================
    // DEDICATED EXAMS & QUIZZES STUDIO + GOOGLE FORMS STYLE EXAM BUILDER
    // ========================================================================
    var isExamStudioModeActive = false;
    var currentExamStudioTab = 'builder';
    var formsBuilderQuestionCards = [];
    var formsBuilderCardSeq = 1;

    function updateNavbarActiveForExamStudio(inExamStudio) {
      var navBtns = document.querySelectorAll('[data-nav-view]');
      for (var j = 0; j < navBtns.length; j++) {
        var btn = navBtns[j];
        var tv = btn.getAttribute('data-nav-view');
        if (tv === 'admin-exams') {
          btn.classList.toggle('is-active', Boolean(inExamStudio));
          if (inExamStudio) btn.setAttribute('aria-current', 'page');
          else btn.removeAttribute('aria-current');
        } else if (tv === 'admin') {
          btn.classList.toggle('is-active', !inExamStudio);
          if (!inExamStudio) btn.setAttribute('aria-current', 'page');
          else btn.removeAttribute('aria-current');
        }
      }
    }

    function enterAdminExamsStudioMode(opt_studioTab) {
      isExamStudioModeActive = true;
      var adminHeader = document.getElementById('admin-header-overview-card');
      var studioHeader = document.getElementById('admin-exams-studio-header-card');
      if (adminHeader) adminHeader.classList.add('hidden');
      if (studioHeader) studioHeader.classList.remove('hidden');
      updateNavbarActiveForExamStudio(true);
      switchAdminExamStudioTab(opt_studioTab || currentExamStudioTab || 'builder');
    }

    function exitAdminExamsStudioMode(opt_force, opt_opts) {
      var opts = opt_opts && typeof opt_opts === 'object' ? opt_opts : {};
      if (!isExamStudioModeActive && !opt_force) return;
      isExamStudioModeActive = false;
      currentExamStudioTab = 'builder';
      if (typeof PBEnhancedSelect === 'object' && PBEnhancedSelect) {
        PBEnhancedSelect.closeActive(true, false);
      }
      var adminHeader = document.getElementById('admin-header-overview-card');
      var studioHeader = document.getElementById('admin-exams-studio-header-card');
      if (adminHeader) adminHeader.classList.remove('hidden');
      if (studioHeader) studioHeader.classList.add('hidden');
      var studioTabBtns = document.querySelectorAll('[data-exam-studio-tab]');
      for (var st = 0; st < studioTabBtns.length; st++) {
        var stb = studioTabBtns[st];
        var isBuilderBtn = stb.getAttribute('data-exam-studio-tab') === 'builder';
        stb.classList.toggle('is-active', isBuilderBtn);
        stb.setAttribute('aria-selected', isBuilderBtn ? 'true' : 'false');
      }
      if (typeof closeFormsExamBuilderToCatalog === 'function') {
        closeFormsExamBuilderToCatalog({ skipSubTabSync: true });
      }
      if (typeof switchAdminExamCreationSubCategory === 'function') {
        switchAdminExamCreationSubCategory('sets', { skipDataLoad: true });
      }
      var destTab = opts.targetAdminTab;
      if (!destTab) {
        if (
          currentAdminTab === 'exam-creation' ||
          currentAdminTab === 'exam-integrity' ||
          currentAdminTab === 'assessments' ||
          !currentAdminTab
        ) {
          destTab = 'settings';
        } else {
          destTab = currentAdminTab;
        }
      }
      if (opts.skipDataLoad) {
        currentAdminTab = destTab;
        var tabDefs = [
          { key: 'settings', btnId: 'btn-admin-tab-settings', panelId: 'admin-panel-settings' },
          { key: 'users', btnId: 'btn-admin-tab-users', panelId: 'admin-panel-users' },
          { key: 'courses', btnId: 'btn-admin-tab-courses', panelId: 'admin-panel-courses' },
          { key: 'announcements', btnId: 'btn-admin-tab-announcements', panelId: 'admin-panel-announcements' },
          { key: 'assessments', btnId: 'btn-admin-tab-assessments', panelId: 'admin-panel-assessments' },
          { key: 'exam-creation', btnId: 'btn-admin-tab-exam-creation', panelId: 'admin-panel-exam-creation' },
          { key: 'exam-integrity', btnId: 'btn-admin-tab-exam-integrity', panelId: 'admin-panel-exam-integrity' },
          { key: 'overview', btnId: 'btn-admin-tab-overview', panelId: 'admin-panel-overview' },
          { key: 'unavailability', btnId: 'btn-admin-tab-unavailability', panelId: 'admin-panel-unavailability' }
        ];
        for (var ti = 0; ti < tabDefs.length; ti++) {
          var td = tabDefs[ti];
          var isMatch = td.key === currentAdminTab;
          var tBtn = document.getElementById(td.btnId);
          var tPanel = document.getElementById(td.panelId);
          if (tBtn) {
            tBtn.classList.toggle('is-active', isMatch);
            tBtn.setAttribute('aria-selected', isMatch ? 'true' : 'false');
          }
          if (tPanel) {
            tPanel.classList.toggle('hidden', !isMatch);
          }
        }
      } else {
        switchAdminSubTab(destTab, true, false);
      }
      updateNavbarActiveForExamStudio(false);
    }

    function switchAdminExamStudioTab(studioTab) {
      if (typeof PBEnhancedSelect === 'object' && PBEnhancedSelect) {
        PBEnhancedSelect.closeActive(true, false);
      }
      currentExamStudioTab = studioTab || 'builder';
      var tabIds = [
        { k: 'builder', id: 'btn-exam-studio-tab-builder' },
        { k: 'grading', id: 'btn-exam-studio-tab-grading' },
        { k: 'integrity', id: 'btn-exam-studio-tab-integrity' },
        { k: 'qbank', id: 'btn-exam-studio-tab-qbank' }
      ];
      for (var i = 0; i < tabIds.length; i++) {
        var b = document.getElementById(tabIds[i].id);
        var active = tabIds[i].k === currentExamStudioTab;
        if (b) {
          b.classList.toggle('is-active', active);
          b.setAttribute('aria-selected', active ? 'true' : 'false');
        }
      }

      // Hide the old sub-category header card inside admin-panel-exam-creation when in Studio mode
      var creationPanel = document.getElementById('admin-panel-exam-creation');
      if (creationPanel && creationPanel.firstElementChild && creationPanel.firstElementChild.querySelector('#admin-exam-creation-subnav')) {
        creationPanel.firstElementChild.classList.toggle('hidden', isExamStudioModeActive);
      }

      if (currentExamStudioTab === 'builder') {
        switchAdminSubTab('exam-creation', true, false);
        switchAdminExamCreationSubCategory('sets');
      } else if (currentExamStudioTab === 'qbank') {
        closeFormsExamBuilderToCatalog({ skipSubTabSync: true });
        switchAdminSubTab('exam-creation', true, false);
        switchAdminExamCreationSubCategory('qbank');
      } else if (currentExamStudioTab === 'grading') {
        closeFormsExamBuilderToCatalog({ skipSubTabSync: true });
        switchAdminSubTab('assessments', true, false);
        switchAdminAssessmentsSubCategory('attempts');
      } else if (currentExamStudioTab === 'integrity') {
        closeFormsExamBuilderToCatalog({ skipSubTabSync: true });
        switchAdminSubTab('exam-integrity', true, false);
      }
      updateNavbarActiveForExamStudio(isExamStudioModeActive);
      if (typeof PBPortalRouter === 'object' && PBPortalRouter && isExamStudioModeActive && currentActiveViewName === 'admin') {
        PBPortalRouter.syncHashForCurrentState(false);
      }
    }

    var activeFormsBlueprintSectionId = 'PART_1';
    var formsWordToolbarMounted = false;
    var formsStickyResizeBound = false;

    function syncFormsStickyToolbarOffset() {
      var hdr = document.querySelector('.site-header');
      var ws = document.getElementById('pb-forms-builder-workspace');
      if (hdr && ws && ws.style) {
        var h = Math.max(58, Math.ceil(hdr.getBoundingClientRect().height || 64));
        ws.style.setProperty('--pb-sticky-toolbar-top', h + 'px');
      }
    }

    function resolveBlueprintSectionIdFromLabel(rawLabel) {
      var s = String(rawLabel || '').trim();
      if (!s) return 'PART_1';
      for (var i = 0; i < PB_ALEVEL_66_BIO_BLUEPRINT.sections.length; i++) {
        var sec = PB_ALEVEL_66_BIO_BLUEPRINT.sections[i];
        if (s === sec.id || s.indexOf(sec.title) !== -1 || s.indexOf('Part ' + (i + 1)) !== -1 || s.indexOf('\u0E2A\u0E48\u0E27\u0E19\u0E17\u0E35\u0E48 ' + (i + 1)) !== -1) {
          return sec.id;
        }
      }
      return 'PART_1';
    }

    function getBlueprintSectionById(secId) {
      for (var i = 0; i < PB_ALEVEL_66_BIO_BLUEPRINT.sections.length; i++) {
        if (PB_ALEVEL_66_BIO_BLUEPRINT.sections[i].id === secId) {
          return PB_ALEVEL_66_BIO_BLUEPRINT.sections[i];
        }
      }
      return PB_ALEVEL_66_BIO_BLUEPRINT.sections[0];
    }

    var activeFormsToolbarCardId = '';

    function ensureFormsWordToolbarMounted() {
      syncFormsStickyToolbarOffset();
      if (!formsStickyResizeBound && typeof window !== 'undefined') {
        formsStickyResizeBound = true;
        window.addEventListener('resize', syncFormsStickyToolbarOffset);
      }
      var dockEl = document.getElementById('pb-forms-word-toolbar-dock');
      var canvasEl = document.getElementById('pb-forms-questions-container');
      if (dockEl && !formsWordToolbarMounted) {
        PBWordRichEditor.renderToolbarInto(dockEl, canvasEl || document.getElementById('pb-forms-builder-workspace'));
        formsWordToolbarMounted = true;
      }
      if (dockEl && !document.getElementById('pb-forms-word-toolbar-home-anchor') && dockEl.parentNode) {
        var homeAnchor = document.createElement('div');
        homeAnchor.id = 'pb-forms-word-toolbar-home-anchor';
        homeAnchor.style.display = 'none';
        dockEl.parentNode.insertBefore(homeAnchor, dockEl);
      }
    }

    function rescueFormsWordToolbarToHome() {
      var dockEl = document.getElementById('pb-forms-word-toolbar-dock');
      var anchorEl = document.getElementById('pb-forms-word-toolbar-home-anchor');
      if (dockEl && anchorEl && anchorEl.parentNode && dockEl.parentNode !== anchorEl.parentNode) {
        anchorEl.parentNode.insertBefore(dockEl, anchorEl.nextSibling);
      }
      if (dockEl) dockEl.classList.remove('is-floating-card-bar');
    }

    function moveFormsWordToolbarAboveCard(cardElOrId, opt_skipScrollCompensate) {
      ensureFormsWordToolbarMounted();
      var dockEl = document.getElementById('pb-forms-word-toolbar-dock');
      var container = document.getElementById('pb-forms-questions-container');
      if (!dockEl || !container) return;
      var cardEl = typeof cardElOrId === 'string'
        ? container.querySelector('.pb-forms-q-card[data-forms-card-id="' + cardElOrId + '"]')
        : cardElOrId;
      if (!cardEl || cardEl.parentNode !== container) return;
      var cid = cardEl.getAttribute('data-forms-card-id') || '';
      if (activeFormsToolbarCardId === cid && dockEl.parentNode === container && dockEl.nextElementSibling === cardEl) {
        dockEl.classList.add('is-floating-card-bar');
        return;
      }
      var prevTop = !opt_skipScrollCompensate && typeof cardEl.getBoundingClientRect === 'function'
        ? cardEl.getBoundingClientRect().top
        : null;
      activeFormsToolbarCardId = cid;
      dockEl.classList.add('is-floating-card-bar');
      container.insertBefore(dockEl, cardEl);
      if (
        prevTop !== null &&
        typeof window !== 'undefined' &&
        typeof window.scrollBy === 'function' &&
        prevTop >= -200 &&
        prevTop <= (window.innerHeight || 900) + 200
      ) {
        var nextTop = cardEl.getBoundingClientRect().top;
        var delta = nextTop - prevTop;
        if (Math.abs(delta) > 1) {
          window.scrollBy(0, delta);
        }
      }
    }

    function createBlankFormsQuestionCardState(opt_overrides) {
      var ov = opt_overrides && typeof opt_overrides === 'object' ? opt_overrides : {};
      var qType = ov.questionType || 'SINGLE_CHOICE';
      var defaultOpts =
        qType === 'TRUE_FALSE'
          ? [
              { text: 'True', doc: plainTextToRichTextDocSafe('True'), isCorrect: true, pinPosition: 'FIXED' },
              { text: 'False', doc: plainTextToRichTextDocSafe('False'), isCorrect: false, pinPosition: 'FIXED' }
            ]
          : qType === 'COMPLEX_MULTIPLE_CHOICE'
          ? [
              { text: '', doc: createDefaultEmptyRichTextDoc(), isCorrect: true, pinPosition: 'FIXED' },
              { text: '', doc: createDefaultEmptyRichTextDoc(), isCorrect: false, pinPosition: 'FIXED' },
              { text: '', doc: createDefaultEmptyRichTextDoc(), isCorrect: true, pinPosition: 'FIXED' }
            ]
          : [
              { text: '', doc: createDefaultEmptyRichTextDoc(), isCorrect: true, pinPosition: 'NONE' },
              { text: '', doc: createDefaultEmptyRichTextDoc(), isCorrect: false, pinPosition: 'NONE' },
              { text: '', doc: createDefaultEmptyRichTextDoc(), isCorrect: false, pinPosition: 'NONE' },
              { text: '', doc: createDefaultEmptyRichTextDoc(), isCorrect: false, pinPosition: 'NONE' },
              { text: '', doc: createDefaultEmptyRichTextDoc(), isCorrect: false, pinPosition: 'NONE' }
            ];
      var fallbackDefaultPts =
        qType === 'COMPLEX_MULTIPLE_CHOICE'
          ? PB_ALEVEL_66_BIO_BLUEPRINT.complexMcDefaultPoints
          : PB_ALEVEL_66_BIO_BLUEPRINT.singleChoiceDefaultPoints;
      var parsedOvPts =
        ov.points !== undefined && ov.points !== null && ov.points !== ''
          ? Number(ov.points)
          : fallbackDefaultPts;
      var isFreeCard = Boolean(ov.isFreeQuestion) || (isFinite(parsedOvPts) && parsedOvPts === 0);
      var defaultPts = isFreeCard ? '0' : String(isFinite(parsedOvPts) && parsedOvPts > 0 ? parsedOvPts : fallbackDefaultPts);
      var stemDoc = ov.stemDoc
        ? cloneRichTextDocSafe(ov.stemDoc)
        : ov.stemRichText
        ? cloneRichTextDocSafe(ov.stemRichText)
        : plainTextToRichTextDocSafe(ov.stem !== undefined ? ov.stem : '');
      var expDoc = ov.explanationDoc
        ? cloneRichTextDocSafe(ov.explanationDoc)
        : ov.explanationRichText
        ? cloneRichTextDocSafe(ov.explanationRichText)
        : plainTextToRichTextDocSafe(ov.explanation || '');

      return {
        localId: 'fcard_' + (formsBuilderCardSeq++),
        questionId: ov.questionId || '',
        expectedVersion: ov.expectedVersion || '',
        questionCode: ov.questionCode || '',
        title: ov.title || '',
        questionType: qType,
        blueprintSection: ov.blueprintSection || activeFormsBlueprintSectionId || 'PART_1',
        stem: extractPlainTextFromRichTextDoc(stemDoc),
        stemDoc: stemDoc,
        isFreeQuestion: isFreeCard,
        points: defaultPts,
        _lastNonZeroPoints: isFreeCard ? String(fallbackDefaultPts) : defaultPts,
        negativePoints: ov.negativePoints !== undefined ? String(ov.negativePoints) : '0',
        difficulty: ov.difficulty || 'MEDIUM',
        topicTags: ov.topicTags || getBlueprintSectionById(ov.blueprintSection || activeFormsBlueprintSectionId || 'PART_1').title,
        options: Array.isArray(ov.options) && ov.options.length > 0 ? ov.options : defaultOpts,
        multiSelectRule: ov.multiSelectRule || 'EXACT_MATCH',
        numericTarget: ov.numericTarget !== undefined ? String(ov.numericTarget) : '0',
        numericTolerance: ov.numericTolerance !== undefined ? String(ov.numericTolerance) : '0',
        numericUnit: ov.numericUnit || '',
        shortAnswerMode: ov.shortAnswerMode || 'MANUAL',
        acceptedAnswers: ov.acceptedAnswers || '',
        sampleModelAnswer: ov.sampleModelAnswer || '',
        explanation: extractPlainTextFromRichTextDoc(expDoc),
        explanationDoc: expDoc,
        imageFileIds: Array.isArray(ov.imageFileIds) ? ov.imageFileIds.slice() : [],
        imageAltText: ov.imageAltText || '',
        isDirty: Boolean(ov.isDirty !== undefined ? ov.isDirty : !ov.questionId)
      };
    }

    function mapQuestionDtoToFormsCardState(qDto, opt_pointsDisplay, opt_negPointsDisplay, opt_sectionTitle) {
      if (!qDto) return createBlankFormsQuestionCardState();
      var qType = qDto.questionType || 'SINGLE_CHOICE';
      var opts = [];
      if (Array.isArray(qDto.options) && qDto.options.length > 0) {
        for (var i = 0; i < qDto.options.length; i++) {
          var o = qDto.options[i];
          var optDoc = o.contentRichText ? cloneRichTextDocSafe(o.contentRichText) : plainTextToRichTextDocSafe(o.plainText || o.text || '');
          opts.push({
            text: extractPlainTextFromRichTextDoc(optDoc) || o.plainText || '',
            doc: optDoc,
            isCorrect: Boolean(o.isCorrect),
            pinPosition: o.pinPosition || (qType === 'COMPLEX_MULTIPLE_CHOICE' ? 'FIXED' : 'NONE')
          });
        }
        if (qType !== 'COMPLEX_MULTIPLE_CHOICE') {
          var anyCorrect = opts.some(function (x) { return x.isCorrect; });
          if (!anyCorrect && opts.length > 0) opts[0].isCorrect = true;
        }
      }
      var privGrading = qDto.privateGradingData || {};
      var gSpec = qDto.gradingSpec || privGrading.gradingSpec || {};
      var fallbackPts = qType === 'COMPLEX_MULTIPLE_CHOICE' ? PB_ALEVEL_66_BIO_BLUEPRINT.complexMcDefaultPoints : PB_ALEVEL_66_BIO_BLUEPRINT.singleChoiceDefaultPoints;
      var parsedOptPts =
        opt_pointsDisplay !== undefined && opt_pointsDisplay !== null && opt_pointsDisplay !== ''
          ? parseFloat(String(opt_pointsDisplay))
          : NaN;
      var isFreeCard =
        Boolean(qDto.isFreeQuestion) ||
        Boolean(gSpec.isFreeQuestion) ||
        String(opt_pointsDisplay || '').toLowerCase().indexOf('free') !== -1 ||
        (!isNaN(parsedOptPts) && parsedOptPts === 0) ||
        (qDto.defaultPointsBp !== undefined && qDto.defaultPointsBp !== null && Number(qDto.defaultPointsBp) === 0);
      var pts = isFreeCard
        ? 0
        : (!isNaN(parsedOptPts) && parsedOptPts > 0
          ? parsedOptPts
          : ((qDto.defaultPointsBp !== undefined && qDto.defaultPointsBp !== null ? Number(qDto.defaultPointsBp) : Math.round(fallbackPts * 100)) / 100));
      var negPts = isFreeCard
        ? 0
        : (opt_negPointsDisplay !== undefined
          ? parseFloat(String(opt_negPointsDisplay)) || 0
          : (Number(qDto.negativePointsBp || 0) / 100));
      var imgIds = Array.isArray(qDto.imageFileIds) && qDto.imageFileIds.length > 0
        ? qDto.imageFileIds.slice()
        : (qDto.imageFileId ? [qDto.imageFileId] : []);
      var tagLabel = Array.isArray(qDto.topicTags) ? qDto.topicTags.join(', ') : '';
      var secGuess = resolveBlueprintSectionIdFromLabel(
        (tagLabel && tagLabel.trim()) ? tagLabel : (opt_sectionTitle || '')
      );
      var priv = qDto.privateGradingData || {};
      var expSource = priv.explanationRichText || qDto.explanationRichText || priv.explanationPlainText || qDto.explanationPlainText || '';

      return createBlankFormsQuestionCardState({
        questionId: qDto.questionId || '',
        expectedVersion: qDto.version || 1,
        questionCode: qDto.questionCode || '',
        title: qDto.title || '',
        questionType: qType,
        blueprintSection: secGuess,
        stemRichText: qDto.stemRichText || qDto.stemPlainText || '',
        isFreeQuestion: isFreeCard,
        points: pts,
        negativePoints: negPts,
        difficulty: qDto.difficulty || 'MEDIUM',
        topicTags: tagLabel && tagLabel.trim() ? tagLabel : getBlueprintSectionById(secGuess).title,
        options: opts,
        multiSelectRule: gSpec.multiSelectScoringRule || 'EXACT_MATCH',
        numericTarget: gSpec.targetValue !== undefined ? gSpec.targetValue : '0',
        numericTolerance: gSpec.toleranceValue !== undefined ? gSpec.toleranceValue : '0',
        numericUnit: qDto.unitLabel || '',
        shortAnswerMode: qDto.gradingMode || 'MANUAL',
        acceptedAnswers: Array.isArray(gSpec.acceptedAnswers) ? gSpec.acceptedAnswers.join('\n') : '',
        sampleModelAnswer: gSpec.sampleModelAnswer || '',
        explanationRichText: expSource,
        imageFileIds: imgIds,
        imageAltText: qDto.imageAltText || '',
        isDirty: false
      });
    }

    function updateFormsBuilderSummaryBadge() {
      var totalPts = 0;
      var count5Opt = 0;
      var countComplex = 0;
      var countFree = 0;
      var secCounts = {};
      for (var i = 0; i < formsBuilderQuestionCards.length; i++) {
        var c = formsBuilderQuestionCards[i];
        var p = parseFloat(c.points);
        if (c.isFreeQuestion || p === 0) {
          countFree++;
        } else if (isFinite(p) && p > 0) {
          totalPts += p;
        }
        if (c.questionType === 'SINGLE_CHOICE') count5Opt++;
        else if (c.questionType === 'COMPLEX_MULTIPLE_CHOICE') countComplex++;
        var sKey = c.blueprintSection || 'PART_1';
        secCounts[sKey] = (secCounts[sKey] || 0) + 1;
      }
      var count = formsBuilderQuestionCards.length;
      setText(
        'pb-forms-live-summary',
        count +
          (count === 1 ? ' Question' : ' Questions') +
          ' \u2022 ' +
          totalPts.toFixed(2) +
          ' pts' +
          (countFree > 0 ? ' (' + countFree + ' Free)' : '')
      );

      var p5El = document.getElementById('pb-alevel-count-5opt');
      if (p5El) {
        p5El.textContent = '5-Option MC: ' + count5Opt + ' / ' + PB_ALEVEL_66_BIO_BLUEPRINT.singleChoiceTargetCount;
        p5El.classList.toggle('is-target-met', count5Opt === PB_ALEVEL_66_BIO_BLUEPRINT.singleChoiceTargetCount);
      }
      var pCxEl = document.getElementById('pb-alevel-count-complex');
      if (pCxEl) {
        pCxEl.textContent = 'Complex MC (Yes/No): ' + countComplex + ' / ' + PB_ALEVEL_66_BIO_BLUEPRINT.complexMcTargetCount;
        pCxEl.classList.toggle('is-target-met', countComplex === PB_ALEVEL_66_BIO_BLUEPRINT.complexMcTargetCount);
      }
      var pScEl = document.getElementById('pb-alevel-score-total');
      if (pScEl) {
        pScEl.textContent = 'Total Score: ' + totalPts.toFixed(2) + ' / 100.00';
        pScEl.classList.toggle('is-target-met', Math.abs(totalPts - 100) < 0.01);
      }

      var stripEl = document.getElementById('pb-alevel-blueprint-sections');
      if (stripEl) {
        while (stripEl.firstChild) stripEl.removeChild(stripEl.firstChild);
        for (var s = 0; s < PB_ALEVEL_66_BIO_BLUEPRINT.sections.length; s++) {
          (function (sec) {
            var btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'pb-alevel-sec-pill' + (activeFormsBlueprintSectionId === sec.id ? ' is-active' : '');
            var cNum = secCounts[sec.id] || 0;
            btn.textContent = sec.shortLabel + ': ' + cNum + ' (' + sec.targetRangeText + ')';
            btn.title = sec.title + ' — Click to set as active section for new questions';
            btn.addEventListener('click', function () {
              activeFormsBlueprintSectionId = sec.id;
              updateFormsBuilderSummaryBadge();
            });
            stripEl.appendChild(btn);
          })(PB_ALEVEL_66_BIO_BLUEPRINT.sections[s]);
        }
      }
    }

    function renderFormsBuilderQuestionCards(opt_renderOpts) {
      var container = document.getElementById('pb-forms-questions-container');
      if (!container) return;
      var renderOpts = opt_renderOpts && typeof opt_renderOpts === 'object' ? opt_renderOpts : {};
      ensureFormsWordToolbarMounted();
      rescueFormsWordToolbarToHome();
      var prevScrollX = typeof window !== 'undefined' ? (window.scrollX || window.pageXOffset || 0) : 0;
      var prevScrollY = typeof window !== 'undefined' ? (window.scrollY || window.pageYOffset || 0) : 0;
      var prevHeight = container.offsetHeight || 0;
      if (prevHeight > 0) {
        container.style.minHeight = prevHeight + 'px';
      }
      var frag = document.createDocumentFragment();
      updateFormsBuilderSummaryBadge();

      for (var idx = 0; idx < formsBuilderQuestionCards.length; idx++) {
        (function (card, cardIndex) {
          var cardEl = document.createElement('div');
          cardEl.className = 'pb-forms-q-card';
          cardEl.setAttribute('data-forms-card-id', card.localId);
          cardEl.addEventListener('focusin', function () {
            moveFormsWordToolbarAboveCard(cardEl);
          });
          cardEl.addEventListener('mousedown', function () {
            moveFormsWordToolbarAboveCard(cardEl);
          });

          // 1. Card Top Bar: Question # Badge + Blueprint Section + Points + Free Toggle + Move/Duplicate/Delete
          var hdr = document.createElement('div');
          hdr.className = 'pb-forms-q-card-header';

          var leftHdr = document.createElement('div');
          leftHdr.style.display = 'flex';
          leftHdr.style.alignItems = 'center';
          leftHdr.style.gap = '8px';
          leftHdr.style.flexWrap = 'wrap';

          var numBdg = document.createElement('span');
          numBdg.className = 'pb-forms-q-num-badge';
          numBdg.textContent = 'Question ' + (cardIndex + 1);
          leftHdr.appendChild(numBdg);

          if (card.questionCode) {
            var codeTag = document.createElement('span');
            codeTag.className = 'badge';
            codeTag.style.fontSize = '0.73rem';
            codeTag.textContent = card.questionCode;
            leftHdr.appendChild(codeTag);
          }

          var secSel = document.createElement('select');
          secSel.className = 'form-input';
          secSel.style.width = 'auto';
          secSel.style.maxWidth = '265px';
          secSel.style.padding = '3px 8px';
          secSel.style.fontSize = '0.76rem';
          secSel.setAttribute('aria-label', 'A-Level Blueprint Section');
          for (var bs = 0; bs < PB_ALEVEL_66_BIO_BLUEPRINT.sections.length; bs++) {
            var bSec = PB_ALEVEL_66_BIO_BLUEPRINT.sections[bs];
            var bOpt = document.createElement('option');
            bOpt.value = bSec.id;
            bOpt.textContent = bSec.title;
            if ((card.blueprintSection || 'PART_1') === bSec.id) bOpt.selected = true;
            secSel.appendChild(bOpt);
          }
          secSel.addEventListener('change', function () {
            card.blueprintSection = secSel.value;
            card.topicTags = getBlueprintSectionById(secSel.value).title;
            markFormsCardDirty(card);
            updateFormsBuilderSummaryBadge();
          });
          leftHdr.appendChild(secSel);

          hdr.appendChild(leftHdr);

          var rightHdr = document.createElement('div');
          rightHdr.style.display = 'flex';
          rightHdr.style.alignItems = 'center';
          rightHdr.style.gap = '6px';
          rightHdr.style.flexWrap = 'wrap';

          var freeLbl = document.createElement('label');
          freeLbl.className = 'pb-forms-free-toggle-label';
          freeLbl.title = 'Free question: excluded from exam scoring and total points';
          var freeChk = document.createElement('input');
          freeChk.type = 'checkbox';
          freeChk.checked = Boolean(card.isFreeQuestion);
          freeLbl.appendChild(freeChk);
          var freeSpan = document.createElement('span');
          freeSpan.textContent = 'Free (0 pts)';
          freeLbl.appendChild(freeSpan);
          rightHdr.appendChild(freeLbl);

          var ptsLabel = document.createElement('label');
          ptsLabel.style.fontSize = '0.78rem';
          ptsLabel.style.fontWeight = '700';
          ptsLabel.style.color = 'var(--color-text-secondary)';
          ptsLabel.textContent = 'Points:';
          rightHdr.appendChild(ptsLabel);

          var ptsInp = document.createElement('input');
          ptsInp.type = 'number';
          ptsInp.className = 'form-input';
          ptsInp.min = '0';
          ptsInp.max = '100';
          ptsInp.step = '0.1';
          ptsInp.style.width = '76px';
          ptsInp.style.padding = '4px 8px';
          ptsInp.value = card.isFreeQuestion ? '0' : String(card.points !== undefined && card.points !== '' ? card.points : '2.4');
          ptsInp.disabled = Boolean(card.isFreeQuestion);

          freeChk.addEventListener('change', function () {
            if (freeChk.checked) {
              if (Number(card.points) > 0) card._lastNonZeroPoints = String(card.points);
              card.isFreeQuestion = true;
              card.points = '0';
              card.negativePoints = '0';
              ptsInp.value = '0';
              ptsInp.disabled = true;
            } else {
              card.isFreeQuestion = false;
              card.points = card._lastNonZeroPoints || '2.4';
              ptsInp.value = card.points;
              ptsInp.disabled = false;
            }
            markFormsCardDirty(card);
            updateFormsBuilderSummaryBadge();
          });

          ptsInp.addEventListener('input', function () {
            var rawVal = String(ptsInp.value || '').trim();
            var numVal = rawVal === '' ? NaN : Number(rawVal);
            if (!isNaN(numVal) && numVal === 0) {
              card.isFreeQuestion = true;
              card.points = '0';
              freeChk.checked = true;
            } else {
              card.isFreeQuestion = false;
              freeChk.checked = false;
              card.points = rawVal !== '' ? rawVal : '0';
              if (!isNaN(numVal) && numVal > 0) card._lastNonZeroPoints = String(numVal);
            }
            markFormsCardDirty(card);
            updateFormsBuilderSummaryBadge();
          });
          rightHdr.appendChild(ptsInp);

          var upBtn = document.createElement('button');
          upBtn.type = 'button';
          upBtn.className = 'btn btn-outline btn-sm';
          setElementVectorIconLabel(upBtn, 'arrow-up', '', 'pb-icon-xs');
          upBtn.setAttribute('aria-label', 'Move Question Up');
          upBtn.title = 'Move Question Up';
          upBtn.disabled = cardIndex === 0;
          upBtn.addEventListener('click', function () {
            if (cardIndex <= 0) return;
            var tmp = formsBuilderQuestionCards[cardIndex - 1];
            formsBuilderQuestionCards[cardIndex - 1] = formsBuilderQuestionCards[cardIndex];
            formsBuilderQuestionCards[cardIndex] = tmp;
            markFormsBuilderDirty();
            renderFormsBuilderQuestionCards({ restoreScroll: true, focusCardId: card.localId, skipScrollIntoView: true });
          });
          rightHdr.appendChild(upBtn);

          var dnBtn = document.createElement('button');
          dnBtn.type = 'button';
          dnBtn.className = 'btn btn-outline btn-sm';
          setElementVectorIconLabel(dnBtn, 'arrow-down', '', 'pb-icon-xs');
          dnBtn.setAttribute('aria-label', 'Move Question Down');
          dnBtn.title = 'Move Question Down';
          dnBtn.disabled = cardIndex === formsBuilderQuestionCards.length - 1;
          dnBtn.addEventListener('click', function () {
            if (cardIndex >= formsBuilderQuestionCards.length - 1) return;
            var tmp = formsBuilderQuestionCards[cardIndex + 1];
            formsBuilderQuestionCards[cardIndex + 1] = formsBuilderQuestionCards[cardIndex];
            formsBuilderQuestionCards[cardIndex] = tmp;
            markFormsBuilderDirty();
            renderFormsBuilderQuestionCards({ restoreScroll: true, focusCardId: card.localId, skipScrollIntoView: true });
          });
          rightHdr.appendChild(dnBtn);

          var dupBtn = document.createElement('button');
          dupBtn.type = 'button';
          dupBtn.className = 'btn btn-outline btn-sm';
          dupBtn.textContent = 'Duplicate';
          dupBtn.addEventListener('click', function () {
            var copyOpts = card.options.map(function (o) {
              return {
                text: o.text,
                doc: o.doc ? cloneRichTextDocSafe(o.doc) : plainTextToRichTextDocSafe(o.text),
                isCorrect: o.isCorrect,
                pinPosition: o.pinPosition
              };
            });
            var cloned = createBlankFormsQuestionCardState({
              questionType: card.questionType,
              blueprintSection: card.blueprintSection,
              stem: card.stem,
              stemDoc: card.stemDoc,
              isFreeQuestion: card.isFreeQuestion,
              points: card.points,
              negativePoints: card.negativePoints,
              difficulty: card.difficulty,
              topicTags: card.topicTags,
              options: copyOpts,
              numericTarget: card.numericTarget,
              numericTolerance: card.numericTolerance,
              numericUnit: card.numericUnit,
              shortAnswerMode: card.shortAnswerMode,
              acceptedAnswers: card.acceptedAnswers,
              sampleModelAnswer: card.sampleModelAnswer,
              explanation: card.explanation,
              explanationDoc: card.explanationDoc,
              imageFileIds: card.imageFileIds.slice(),
              imageAltText: card.imageAltText,
              isDirty: true
            });
            formsBuilderQuestionCards.splice(cardIndex + 1, 0, cloned);
            markFormsBuilderDirty();
            renderFormsBuilderQuestionCards({ focusCardId: cloned.localId, focusStem: true });
          });
          rightHdr.appendChild(dupBtn);

          var delBtn = document.createElement('button');
          delBtn.type = 'button';
          delBtn.className = 'btn btn-outline btn-sm';
          delBtn.style.color = '#DC2626';
          delBtn.textContent = 'Delete';
          delBtn.addEventListener('click', function () {
            if (formsBuilderQuestionCards.length <= 1) {
              PBNotify.toast('warning', 'Minimum 1 Question', 'An exam must have at least one question card.');
              return;
            }
            formsBuilderQuestionCards.splice(cardIndex, 1);
            markFormsBuilderDirty();
            renderFormsBuilderQuestionCards({ restoreScroll: true });
          });
          rightHdr.appendChild(delBtn);

          hdr.appendChild(rightHdr);
          cardEl.appendChild(hdr);

          // 2. Question Stem (Word-Style Inline Editor) + Question Type Selector Row
          var stemRow = document.createElement('div');
          stemRow.className = 'pb-forms-q-stem-row';

          var stemEd = PBWordRichEditor.createInput({
            isStem: true,
            isSingleLine: false,
            placeholder: 'Write question prompt here... (Ctrl+B/I/U, Ctrl+= Subscript, Ctrl+Shift+= Superscript, \\beta- for β-glycosidic)',
            initialValue: card.stemDoc || card.stem,
            ariaLabel: 'Question ' + (cardIndex + 1) + ' stem',
            onChange: function (doc, plainTxt) {
              card.stemDoc = doc;
              card.stem = plainTxt;
              markFormsCardDirty(card);
            }
          });
          stemRow.appendChild(stemEd.element);

          var typeSel = document.createElement('select');
          typeSel.className = 'form-input';
          var typeChoices = [
            { v: 'SINGLE_CHOICE', l: 'A-Level Multiple Choice (5 Opts)' },
            { v: 'COMPLEX_MULTIPLE_CHOICE', l: 'A-Level Complex MC (Yes / No)' },
            { v: 'MULTIPLE_SELECT', l: 'Checkboxes (Multi-Select)' },
            { v: 'TRUE_FALSE', l: 'True / False' },
            { v: 'NUMERIC_RESPONSE', l: 'Numeric Calculation' },
            { v: 'SHORT_ANSWER', l: 'Short Answer' },
            { v: 'WRITTEN_RESPONSE', l: 'Written Essay / Rubric' }
          ];
          for (var tc = 0; tc < typeChoices.length; tc++) {
            var topt = document.createElement('option');
            topt.value = typeChoices[tc].v;
            topt.textContent = typeChoices[tc].l;
            if (typeChoices[tc].v === card.questionType) topt.selected = true;
            typeSel.appendChild(topt);
          }
          typeSel.addEventListener('change', function () {
            card.questionType = typeSel.value;
            markFormsCardDirty(card);
            if (card.questionType === 'TRUE_FALSE') {
              card.options = [
                { text: 'True', doc: plainTextToRichTextDocSafe('True'), isCorrect: true, pinPosition: 'FIXED' },
                { text: 'False', doc: plainTextToRichTextDocSafe('False'), isCorrect: false, pinPosition: 'FIXED' }
              ];
            } else if (card.questionType === 'COMPLEX_MULTIPLE_CHOICE') {
              while (card.options.length < 3) {
                var sn = card.options.length + 1;
                card.options.push({
                  text: '',
                  doc: createDefaultEmptyRichTextDoc(),
                  isCorrect: sn % 2 === 1,
                  pinPosition: 'FIXED'
                });
              }
              if (card.options.length > 5) card.options = card.options.slice(0, 5);
              for (var cx = 0; cx < card.options.length; cx++) card.options[cx].pinPosition = 'FIXED';
              if (card.points === '2' || card.points === '2.4') card.points = '3.2';
            } else if (card.questionType === 'SINGLE_CHOICE' || card.questionType === 'MULTIPLE_SELECT') {
              while (card.options.length < 5) {
                card.options.push({
                  text: '',
                  doc: createDefaultEmptyRichTextDoc(),
                  isCorrect: card.options.length === 0,
                  pinPosition: 'NONE'
                });
              }
              if (card.questionType === 'SINGLE_CHOICE') {
                var foundOne = false;
                for (var oi = 0; oi < card.options.length; oi++) {
                  if (card.options[oi].isCorrect && !foundOne) {
                    foundOne = true;
                  } else {
                    card.options[oi].isCorrect = false;
                  }
                }
                if (!foundOne && card.options.length > 0) card.options[0].isCorrect = true;
                if (card.points === '2' || card.points === '3.2') card.points = '2.4';
              }
            }
            renderFormsBuilderQuestionCards({ restoreScroll: true, focusCardId: card.localId, skipScrollIntoView: true });
          });
          stemRow.appendChild(typeSel);
          cardEl.appendChild(stemRow);

          // 3. Diagram Preview & Embedded Media/Table Tray (Images, Embedded PDFs, Tables)
          var cardMediaHost = document.createElement('div');
          function syncCardRichMediaTray() {
            var blocks = stemEd.getMediaBlocks();
            renderQuestionRichMediaTray(cardMediaHost, blocks, {
              courseId: ((document.getElementById('select-forms-exam-course') || {}).value || '').trim(),
              onUpdate: function (nextList) {
                stemEd.setMediaBlocks(nextList);
                card.stemDoc = stemEd.getValueDoc();
                card.stem = extractPlainTextFromRichTextDoc(card.stemDoc);
                card.isDirty = true;
                syncCardRichMediaTray();
              }
            });
          }
          syncCardRichMediaTray();
          cardEl.appendChild(cardMediaHost);

          if (card.imageFileIds && card.imageFileIds.length > 0) {
            var imgBox = document.createElement('div');
            imgBox.style.padding = '10px 12px';
            imgBox.style.marginBottom = '10px';
            imgBox.style.background = '#F8FAFC';
            imgBox.style.borderRadius = '10px';
            imgBox.style.border = '1px solid #E2E8F0';

            var imgTop = document.createElement('div');
            imgTop.style.display = 'flex';
            imgTop.style.alignItems = 'center';
            imgTop.style.justifyContent = 'space-between';
            imgTop.style.gap = '6px';
            imgTop.style.flexWrap = 'wrap';
            imgTop.style.marginBottom = '8px';

            var imgLbl = document.createElement('strong');
            imgLbl.style.fontSize = '0.8rem';
            imgLbl.style.color = 'var(--color-brand-deep)';
            imgLbl.textContent = 'Attached Diagram(s): ' + card.imageFileIds.join(', ');
            imgTop.appendChild(imgLbl);

            var imgTopActions = document.createElement('div');
            imgTopActions.style.display = 'flex';
            imgTopActions.style.gap = '6px';
            var zoomDiagBtn = document.createElement('button');
            zoomDiagBtn.type = 'button';
            zoomDiagBtn.className = 'btn btn-outline btn-sm';
            setElementVectorIconLabel(zoomDiagBtn, 'zoom-in', 'Zoom Diagram', 'pb-icon-xs');
            zoomDiagBtn.addEventListener('click', function () {
              openInAppImageZoomModal(
                card.imageFileIds[0],
                ((document.getElementById('select-forms-exam-course') || {}).value || '').trim(),
                card.imageAltText || ('Question ' + (cardIndex + 1) + ' Diagram')
              );
            });
            imgTopActions.appendChild(zoomDiagBtn);

            var rmImgBtn = document.createElement('button');
            rmImgBtn.type = 'button';
            rmImgBtn.className = 'btn btn-outline btn-sm';
            rmImgBtn.textContent = 'Remove Diagram';
            rmImgBtn.addEventListener('click', function () {
              card.imageFileIds = [];
              card.isDirty = true;
              renderFormsBuilderQuestionCards({ restoreScroll: true, focusCardId: card.localId, skipScrollIntoView: true });
            });
            imgTopActions.appendChild(rmImgBtn);
            imgTop.appendChild(imgTopActions);
            imgBox.appendChild(imgTop);

            var gal = document.createElement('div');
            gal.className = 'pb-qbank-image-gallery';
            for (var im = 0; im < card.imageFileIds.length; im++) {
              var stg = document.createElement('div');
              stg.className = 'pb-qbank-image-thumb-stage';
              stg.style.maxWidth = '240px';
              gal.appendChild(stg);
              renderDirectImageElementIntoStage(stg, card.imageFileIds[im], '', card.imageAltText || 'Question diagram');
            }
            imgBox.appendChild(gal);
            cardEl.appendChild(imgBox);
          }

          // 4. Type-Specific Answer Area
          var qType = card.questionType;
          if (qType === 'COMPLEX_MULTIPLE_CHOICE') {
            var cmcHint = document.createElement('div');
            cmcHint.style.fontSize = '0.78rem';
            cmcHint.style.color = '#0F766E';
            cmcHint.style.fontWeight = '700';
            cmcHint.style.marginBottom = '6px';
            cmcHint.textContent = 'Complex Multiple Choice (Are these statements true?): Add 3–5 sub-statements and set each key to "Yes" or "No" (3/3 = 100%, 2/3 = 50%, <=1/3 = 0%).';
            cardEl.appendChild(cmcHint);

            var cmcList = document.createElement('div');
            cmcList.className = 'pb-complex-mc-card-list';

            for (var sIdx = 0; sIdx < card.options.length; sIdx++) {
              (function (stmtObj, statementIndex) {
                var row = document.createElement('div');
                row.className = 'pb-complex-mc-row is-decided';

                var stmtWrap = document.createElement('div');
                stmtWrap.className = 'pb-complex-mc-stmt-wrap';
                stmtWrap.style.alignItems = 'center';

                var numBadge = document.createElement('span');
                numBadge.className = 'pb-complex-mc-num';
                numBadge.textContent = (statementIndex + 1) + '.';
                stmtWrap.appendChild(numBadge);

                var stmtEd = PBWordRichEditor.createInput({
                  isSingleLine: true,
                  placeholder: 'Sub-statement ' + (statementIndex + 1) + ' (Ctrl+= Sub, Ctrl+Shift+= Sup, \\beta-)...',
                  initialValue: stmtObj.doc || stmtObj.text,
                  ariaLabel: 'Sub-statement ' + (statementIndex + 1),
                  onChange: function (doc, plainTxt) {
                    stmtObj.doc = doc;
                    stmtObj.text = plainTxt;
                    card.isDirty = true;
                  }
                });
                stmtWrap.appendChild(stmtEd.element);
                row.appendChild(stmtWrap);

                var tg = document.createElement('div');
                tg.className = 'pb-complex-mc-toggle-group';

                var yesKeyBtn = document.createElement('button');
                yesKeyBtn.type = 'button';
                yesKeyBtn.className = 'pb-complex-mc-toggle-pill is-yes' + (stmtObj.isCorrect ? ' is-selected' : '');
                yesKeyBtn.textContent = 'Key: Yes';
                yesKeyBtn.addEventListener('click', function () {
                  stmtObj.isCorrect = true;
                  yesKeyBtn.classList.add('is-selected');
                  noKeyBtn.classList.remove('is-selected');
                  markFormsCardDirty(card);
                });
                tg.appendChild(yesKeyBtn);

                var noKeyBtn = document.createElement('button');
                noKeyBtn.type = 'button';
                noKeyBtn.className = 'pb-complex-mc-toggle-pill is-no' + (!stmtObj.isCorrect ? ' is-selected' : '');
                noKeyBtn.textContent = 'Key: No';
                noKeyBtn.addEventListener('click', function () {
                  stmtObj.isCorrect = false;
                  noKeyBtn.classList.add('is-selected');
                  yesKeyBtn.classList.remove('is-selected');
                  markFormsCardDirty(card);
                });
                tg.appendChild(noKeyBtn);

                row.appendChild(tg);

                if (card.options.length > 3) {
                  var rmStBtn = document.createElement('button');
                  rmStBtn.type = 'button';
                  rmStBtn.className = 'btn btn-outline btn-sm';
                  rmStBtn.style.padding = '2px 7px';
                  rmStBtn.textContent = '\u00D7';
                  rmStBtn.title = 'Remove sub-statement';
                  rmStBtn.addEventListener('click', function () {
                    card.options.splice(statementIndex, 1);
                    card.isDirty = true;
                    renderFormsBuilderQuestionCards({ restoreScroll: true, focusCardId: card.localId, skipScrollIntoView: true });
                  });
                  row.appendChild(rmStBtn);
                }

                cmcList.appendChild(row);
              })(card.options[sIdx], sIdx);
            }
            cardEl.appendChild(cmcList);

            if (card.options.length < 5) {
              var addStmtBtn = document.createElement('button');
              addStmtBtn.type = 'button';
              addStmtBtn.className = 'btn btn-outline btn-sm';
              addStmtBtn.style.marginTop = '8px';
              addStmtBtn.textContent = '+ Add Sub-Statement (' + (card.options.length + 1) + ')';
              addStmtBtn.addEventListener('click', function () {
                card.options.push({
                  text: '',
                  doc: createDefaultEmptyRichTextDoc(),
                  isCorrect: true,
                  pinPosition: 'FIXED'
                });
                card.isDirty = true;
                renderFormsBuilderQuestionCards({ restoreScroll: true, focusCardId: card.localId, skipScrollIntoView: true });
              });
              cardEl.appendChild(addStmtBtn);
            }
          } else if (qType === 'SINGLE_CHOICE' || qType === 'MULTIPLE_SELECT' || qType === 'TRUE_FALSE') {
            var optHint = document.createElement('div');
            optHint.style.fontSize = '0.78rem';
            optHint.style.color = 'var(--color-text-secondary)';
            optHint.style.marginBottom = '4px';
            optHint.textContent =
              qType === 'MULTIPLE_SELECT'
                ? 'Check the box next to ALL correct answer choices (student selects all matching boxes):'
                : qType === 'SINGLE_CHOICE'
                ? 'Check 1 or more accepted correct answers (student picks one choice; any checked key earns full points):'
                : 'Select the radio button next to the correct answer:';
            cardEl.appendChild(optHint);

            var optList = document.createElement('div');
            optList.className = 'pb-forms-options-list';
            var optionRowRefs = [];

            function syncOptionKeyIndicatorsInCard() {
              for (var rIdx = 0; rIdx < optionRowRefs.length; rIdx++) {
                var ref = optionRowRefs[rIdx];
                var isCor = Boolean(ref.optObj && ref.optObj.isCorrect);
                ref.row.classList.toggle('is-correct-option', isCor);
                if (ref.selInp && ref.selInp.checked !== isCor) {
                  ref.selInp.checked = isCor;
                }
                if (isCor && !ref.corBadge) {
                  var corBadge = document.createElement('span');
                  corBadge.className = 'badge badge-ok pb-vec-icon-btn pb-forms-opt-correct-badge';
                  corBadge.style.fontSize = '0.7rem';
                  setElementVectorIconLabel(
                    corBadge,
                    'check',
                    qType === 'SINGLE_CHOICE' ? 'Accepted Key' : 'Correct Key',
                    'pb-icon-xs'
                  );
                  if (ref.rmOpt && ref.rmOpt.parentNode === ref.row) {
                    ref.row.insertBefore(corBadge, ref.rmOpt);
                  } else {
                    ref.row.appendChild(corBadge);
                  }
                  ref.corBadge = corBadge;
                } else if (!isCor && ref.corBadge) {
                  if (ref.corBadge.parentNode) {
                    ref.corBadge.parentNode.removeChild(ref.corBadge);
                  }
                  ref.corBadge = null;
                }
              }
            }

            for (var oIdx = 0; oIdx < card.options.length; oIdx++) {
              (function (optObj, optionIndex) {
                var row = document.createElement('div');
                row.className = 'pb-forms-option-row' + (optObj.isCorrect ? ' is-correct-option' : '');

                var selInp = document.createElement('input');
                selInp.type = (qType === 'MULTIPLE_SELECT' || qType === 'SINGLE_CHOICE') ? 'checkbox' : 'radio';
                selInp.name = 'forms_correct_' + card.localId;
                selInp.checked = Boolean(optObj.isCorrect);
                selInp.title = qType === 'SINGLE_CHOICE' ? 'Mark as accepted correct answer' : 'Mark as correct answer';
                selInp.addEventListener('change', function () {
                  if (qType === 'MULTIPLE_SELECT' || qType === 'SINGLE_CHOICE') {
                    if (qType === 'SINGLE_CHOICE' && !selInp.checked && !card.isFreeQuestion) {
                      var otherCorrect = card.options.some(function (optCandidate, idxCandidate) {
                        return idxCandidate !== optionIndex && optCandidate.isCorrect;
                      });
                      if (!otherCorrect) {
                        selInp.checked = true;
                        PBNotify.toast(
                          'warning',
                          'At Least 1 Correct Answer Needed',
                          'Keep at least one accepted answer checked, or enable "Free (0 pts)" above.'
                        );
                        return;
                      }
                    }
                    optObj.isCorrect = selInp.checked;
                  } else {
                    for (var k = 0; k < card.options.length; k++) {
                      card.options[k].isCorrect = k === optionIndex;
                    }
                  }
                  markFormsCardDirty(card);
                  syncOptionKeyIndicatorsInCard();
                  updateFormsBuilderSummaryBadge();
                });
                row.appendChild(selInp);

                var pill = document.createElement('span');
                pill.className = 'pb-forms-opt-key-pill';
                pill.textContent = qType === 'TRUE_FALSE' ? (optionIndex === 0 ? 'T' : 'F') : String.fromCharCode(65 + optionIndex);
                row.appendChild(pill);

                if (qType === 'TRUE_FALSE') {
                  var txtInp = document.createElement('input');
                  txtInp.type = 'text';
                  txtInp.className = 'pb-forms-opt-input';
                  txtInp.value = optObj.text;
                  txtInp.readOnly = true;
                  row.appendChild(txtInp);
                } else {
                  var optEd = PBWordRichEditor.createInput({
                    isSingleLine: true,
                    placeholder: 'Option ' + String.fromCharCode(65 + optionIndex) + ' (Ctrl+= Sub, Ctrl+Shift+= Sup, \\beta-)...',
                    initialValue: optObj.doc || optObj.text,
                    ariaLabel: 'Option ' + String.fromCharCode(65 + optionIndex),
                    onChange: function (doc, plainTxt) {
                      optObj.doc = doc;
                      optObj.text = plainTxt;
                      card.isDirty = true;
                    }
                  });
                  row.appendChild(optEd.element);
                }

                var corBadge = null;
                if (optObj.isCorrect) {
                  corBadge = document.createElement('span');
                  corBadge.className = 'badge badge-ok pb-vec-icon-btn pb-forms-opt-correct-badge';
                  corBadge.style.fontSize = '0.7rem';
                  setElementVectorIconLabel(
                    corBadge,
                    'check',
                    qType === 'SINGLE_CHOICE' ? 'Accepted Key' : 'Correct Key',
                    'pb-icon-xs'
                  );
                  row.appendChild(corBadge);
                }

                var rmOpt = null;
                if (qType !== 'TRUE_FALSE' && card.options.length > 2) {
                  rmOpt = document.createElement('button');
                  rmOpt.type = 'button';
                  rmOpt.className = 'btn btn-outline btn-sm';
                  rmOpt.style.padding = '2px 7px';
                  rmOpt.textContent = '\u00D7';
                  rmOpt.title = 'Remove this choice';
                  rmOpt.addEventListener('click', function () {
                    card.options.splice(optionIndex, 1);
                    if (!card.options.some(function (x) { return x.isCorrect; }) && card.options.length > 0) {
                      card.options[0].isCorrect = true;
                    }
                    markFormsCardDirty(card);
                    renderFormsBuilderQuestionCards({ restoreScroll: true, focusCardId: card.localId, skipScrollIntoView: true });
                  });
                  row.appendChild(rmOpt);
                }

                optionRowRefs.push({
                  row: row,
                  optObj: optObj,
                  selInp: selInp,
                  corBadge: corBadge,
                  rmOpt: rmOpt
                });
                optList.appendChild(row);
              })(card.options[oIdx], oIdx);
            }
            cardEl.appendChild(optList);

            if (qType !== 'TRUE_FALSE' && card.options.length < 10) {
              var addOptBtn = document.createElement('button');
              addOptBtn.type = 'button';
              addOptBtn.className = 'btn btn-outline btn-sm';
              addOptBtn.textContent = '+ Add Option (' + String.fromCharCode(65 + card.options.length) + ')';
              addOptBtn.addEventListener('click', function () {
                card.options.push({
                  text: '',
                  doc: createDefaultEmptyRichTextDoc(),
                  isCorrect: false,
                  pinPosition: 'NONE'
                });
                markFormsCardDirty(card);
                renderFormsBuilderQuestionCards({ restoreScroll: true, focusCardId: card.localId, skipScrollIntoView: true });
              });
              cardEl.appendChild(addOptBtn);
            }
          } else if (qType === 'NUMERIC_RESPONSE') {
            var numGrid = document.createElement('div');
            numGrid.className = 'form-grid-2col';
            numGrid.style.background = '#F0FDF4';
            numGrid.style.padding = '12px';
            numGrid.style.borderRadius = '10px';
            numGrid.style.border = '1px solid #BBF7D0';

            var tgWrap = document.createElement('div');
            tgWrap.className = 'form-group';
            tgWrap.style.margin = '0';
            var tgLbl = document.createElement('label');
            tgLbl.className = 'form-label';
            tgLbl.textContent = 'Correct Numeric Value *';
            var tgInp = document.createElement('input');
            tgInp.type = 'number';
            tgInp.step = 'any';
            tgInp.className = 'form-input';
            tgInp.value = card.numericTarget;
            tgInp.addEventListener('input', function () {
              card.numericTarget = tgInp.value;
              card.isDirty = true;
            });
            tgWrap.appendChild(tgLbl);
            tgWrap.appendChild(tgInp);
            numGrid.appendChild(tgWrap);

            var tolWrap = document.createElement('div');
            tolWrap.className = 'form-group';
            tolWrap.style.margin = '0';
            var tolLbl = document.createElement('label');
            tolLbl.className = 'form-label';
            tolLbl.textContent = 'Allowed Tolerance (\u00B1) & Unit';
            var tolRow = document.createElement('div');
            tolRow.style.display = 'flex';
            tolRow.style.gap = '6px';
            var tolInp = document.createElement('input');
            tolInp.type = 'number';
            tolInp.step = 'any';
            tolInp.className = 'form-input';
            tolInp.placeholder = '\u00B10';
            tolInp.value = card.numericTolerance;
            tolInp.addEventListener('input', function () {
              card.numericTolerance = tolInp.value;
              card.isDirty = true;
            });
            var unitInp = document.createElement('input');
            unitInp.type = 'text';
            unitInp.className = 'form-input';
            unitInp.placeholder = 'Unit (e.g. mM, \u00B0C)';
            unitInp.value = card.numericUnit;
            unitInp.addEventListener('input', function () {
              card.numericUnit = unitInp.value;
              card.isDirty = true;
            });
            tolRow.appendChild(tolInp);
            tolRow.appendChild(unitInp);
            tolWrap.appendChild(tolLbl);
            tolWrap.appendChild(tolRow);
            numGrid.appendChild(tolWrap);
            cardEl.appendChild(numGrid);
          } else if (qType === 'SHORT_ANSWER' || qType === 'WRITTEN_RESPONSE') {
            var saBox = document.createElement('div');
            saBox.style.background = '#F8FAFC';
            saBox.style.padding = '12px';
            saBox.style.borderRadius = '10px';
            saBox.style.border = '1px solid #E2E8F0';

            var saLbl = document.createElement('label');
            saLbl.className = 'form-label';
            saLbl.textContent =
              qType === 'SHORT_ANSWER'
                ? 'Accepted Auto-Match Answers (One per line, or leave blank for manual grading)'
                : 'Grading Rubric / Model Answer for Instructor Reference';
            var saTxt = document.createElement('textarea');
            saTxt.className = 'form-input';
            saTxt.rows = 2;
            saTxt.placeholder =
              qType === 'SHORT_ANSWER'
                ? 'e.g. Photolysis of water\nSplitting of H2O'
                : 'Key points required for full credit...';
            saTxt.value = qType === 'SHORT_ANSWER' ? card.acceptedAnswers : card.sampleModelAnswer;
            saTxt.addEventListener('input', function () {
              if (qType === 'SHORT_ANSWER') {
                card.acceptedAnswers = saTxt.value;
                card.shortAnswerMode = saTxt.value.trim() ? 'NORMALIZED_AUTO' : 'MANUAL';
              } else {
                card.sampleModelAnswer = saTxt.value;
              }
              card.isDirty = true;
            });
            saBox.appendChild(saLbl);
            saBox.appendChild(saTxt);
            cardEl.appendChild(saBox);
          }

          // 5. Card Footer: Answer Explanation + Diagram Upload + Optional Advanced Expander
          var ftr = document.createElement('div');
          ftr.className = 'pb-forms-q-footer';

          var expEd = PBWordRichEditor.createInput({
            isSingleLine: false,
            placeholder: 'Answer key explanation / rationale (Ctrl+= Sub, Ctrl+Shift+= Sup, \\beta-)...',
            initialValue: card.explanationDoc || card.explanation,
            ariaLabel: 'Question ' + (cardIndex + 1) + ' explanation',
            onChange: function (doc, plainTxt) {
              card.explanationDoc = doc;
              card.explanation = plainTxt;
              card.isDirty = true;
            }
          });
          expEd.element.style.flex = '1 1 260px';
          expEd.element.style.fontSize = '0.85rem';
          ftr.appendChild(expEd.element);

          var rightFtr = document.createElement('div');
          rightFtr.style.display = 'flex';
          rightFtr.style.alignItems = 'center';
          rightFtr.style.gap = '8px';
          rightFtr.style.flexWrap = 'wrap';

          var fileInp = document.createElement('input');
          fileInp.type = 'file';
          fileInp.accept = 'image/png,image/jpeg,image/webp,image/gif';
          fileInp.className = 'hidden';
          var upImgBtn = document.createElement('button');
          upImgBtn.type = 'button';
          upImgBtn.className = 'btn btn-outline btn-sm';
          setElementVectorIconLabel(upImgBtn, 'image', 'Add Diagram', 'pb-icon-xs');
          upImgBtn.addEventListener('click', function () {
            fileInp.click();
          });
          fileInp.addEventListener('change', function () {
            var f = fileInp.files && fileInp.files[0];
            if (!f) return;
            var assignedCrs = ((document.getElementById('select-forms-exam-course') || {}).value || '').trim();
            runButtonWithLoadingState(upImgBtn, 'Uploading...', function () {
              return uploadQuestionStemAttachmentFile(f, 'image', assignedCrs).then(function (res) {
                stemEd.addMediaBlock({
                  type: 'image_attachment',
                  fileId: res.fileId,
                  altText: String(res.originalFilename || ('Figure ' + (cardIndex + 1))).replace(/\.[^.]+$/, ''),
                  caption: '',
                  widthPct: 75
                });
                card.stemDoc = stemEd.getValueDoc();
                card.stem = extractPlainTextFromRichTextDoc(card.stemDoc);
                markFormsCardDirty(card);
                syncCardRichMediaTray();
                fileInp.value = '';
                PBNotify.toast('success', 'Diagram Embedded', 'Added resizable image ' + res.fileId + ' to Question ' + (cardIndex + 1) + '.');
              });
            });
          });
          rightFtr.appendChild(fileInp);
          rightFtr.appendChild(upImgBtn);

          var pdfFileInp = document.createElement('input');
          pdfFileInp.type = 'file';
          pdfFileInp.accept = 'application/pdf,.pdf';
          pdfFileInp.className = 'hidden';
          var upPdfBtn = document.createElement('button');
          upPdfBtn.type = 'button';
          upPdfBtn.className = 'btn btn-outline btn-sm';
          setElementVectorIconLabel(upPdfBtn, 'file-pdf', 'Embed PDF', 'pb-icon-xs');
          var existingCardMedia = typeof stemEd.getMediaBlocks === 'function' ? stemEd.getMediaBlocks() : [];
          var existingCardPdfs = existingCardMedia.filter(function (mb) { return mb && mb.type === 'pdf_attachment'; });
          var initialCardPdfAllowed = existingCardPdfs.length > 0 ? existingCardPdfs[existingCardPdfs.length - 1].allowDownload !== false : true;
          var fmPdfAllowDlToggle = createPdfDownloadTogglePill(initialCardPdfAllowed, function (allowed) {
            if (typeof stemEd.getMediaBlocks === 'function' && typeof stemEd.setMediaBlocks === 'function') {
              var curBlocks = stemEd.getMediaBlocks();
              var hadPdf = false;
              var updatedBlocks = curBlocks.map(function (mb) {
                if (mb && mb.type === 'pdf_attachment') {
                  hadPdf = true;
                  return Object.assign({}, mb, { allowDownload: allowed });
                }
                return mb;
              });
              if (hadPdf) {
                stemEd.setMediaBlocks(updatedBlocks);
                card.stemDoc = stemEd.getValueDoc();
                card.stem = extractPlainTextFromRichTextDoc(card.stemDoc);
                markFormsCardDirty(card);
                syncCardRichMediaTray();
              }
            }
          });
          upPdfBtn.addEventListener('click', function () {
            pdfFileInp.click();
          });
          pdfFileInp.addEventListener('change', function () {
            var f = pdfFileInp.files && pdfFileInp.files[0];
            if (!f) return;
            var assignedCrs = ((document.getElementById('select-forms-exam-course') || {}).value || '').trim();
            runButtonWithLoadingState(upPdfBtn, 'Uploading PDF...', function () {
              return uploadQuestionStemAttachmentFile(f, 'pdf', assignedCrs).then(function (res) {
                var allowDl = fmPdfAllowDlToggle.isAllowed();
                stemEd.addMediaBlock({
                  type: 'pdf_attachment',
                  fileId: res.fileId,
                  title: res.originalFilename || 'Attached PDF.pdf',
                  displayMode: 'embed',
                  widthPct: 100,
                  heightPx: 420,
                  allowDownload: allowDl
                });
                card.stemDoc = stemEd.getValueDoc();
                card.stem = extractPlainTextFromRichTextDoc(card.stemDoc);
                markFormsCardDirty(card);
                syncCardRichMediaTray();
                pdfFileInp.value = '';
                PBNotify.toast(
                  'success',
                  'PDF Embedded',
                  'Attached embedded PDF ' + res.fileId + ' to Question ' + (cardIndex + 1) + (allowDl ? ' (Downloadable).' : ' (View Only / No Download).')
                );
              });
            });
          });
          rightFtr.appendChild(pdfFileInp);
          rightFtr.appendChild(upPdfBtn);
          rightFtr.appendChild(fmPdfAllowDlToggle.element);

          var addTblBtn = document.createElement('button');
          addTblBtn.type = 'button';
          addTblBtn.className = 'btn btn-outline btn-sm';
          setElementVectorIconLabel(addTblBtn, 'table', 'Add Table (.xlsx / .gsheet)', 'pb-icon-xs');
          addTblBtn.addEventListener('click', function () {
            openQuestionTableEditorModal(null, function (tblBlock) {
              stemEd.addMediaBlock(tblBlock);
              card.stemDoc = stemEd.getValueDoc();
              card.stem = extractPlainTextFromRichTextDoc(card.stemDoc);
              markFormsCardDirty(card);
              syncCardRichMediaTray();
              PBNotify.toast('success', 'Table Added', 'Embedded data table into Question ' + (cardIndex + 1) + '.');
            });
          });
          rightFtr.appendChild(addTblBtn);

          ftr.appendChild(rightFtr);
          cardEl.appendChild(ftr);

          // Optional per-card Advanced Settings (Difficulty, Topic, Question Code)
          var advDetails = document.createElement('details');
          advDetails.style.marginTop = '8px';
          var advSum = document.createElement('summary');
          advSum.style.fontSize = '0.76rem';
          advSum.style.color = 'var(--color-text-muted)';
          advSum.style.cursor = 'pointer';
          advSum.textContent = 'More options (Difficulty, Topic Tag, Negative Marking, Question Code)';
          advDetails.appendChild(advSum);

          var advGrid = document.createElement('div');
          advGrid.className = 'form-grid-2col';
          advGrid.style.marginTop = '8px';
          advGrid.style.padding = '10px';
          advGrid.style.background = '#F8FAFC';
          advGrid.style.borderRadius = '8px';

          var difSel = document.createElement('select');
          difSel.className = 'form-input';
          ['EASY', 'MEDIUM', 'HARD', 'OLYMPIAD'].forEach(function (d) {
            var o = document.createElement('option');
            o.value = d;
            o.textContent = 'Difficulty: ' + d;
            if (card.difficulty === d) o.selected = true;
            difSel.appendChild(o);
          });
          difSel.addEventListener('change', function () {
            card.difficulty = difSel.value;
            markFormsCardDirty(card);
          });
          advGrid.appendChild(difSel);

          var topInp = document.createElement('input');
          topInp.type = 'text';
          topInp.className = 'form-input';
          topInp.placeholder = 'Topic tag (e.g. Photosynthesis, Genetics)';
          topInp.value = card.topicTags;
          topInp.addEventListener('input', function () {
            card.topicTags = topInp.value;
            card.isDirty = true;
          });
          advGrid.appendChild(topInp);

          advDetails.appendChild(advGrid);
          cardEl.appendChild(advDetails);

          frag.appendChild(cardEl);
        })(formsBuilderQuestionCards[idx], idx);
      }

      while (container.firstChild) container.removeChild(container.firstChild);
      container.appendChild(frag);

      var preferredCardId = renderOpts.focusCardId || activeFormsToolbarCardId || (formsBuilderQuestionCards[0] && formsBuilderQuestionCards[0].localId) || '';
      var targetCardEl = preferredCardId
        ? container.querySelector('.pb-forms-q-card[data-forms-card-id="' + preferredCardId + '"]')
        : container.querySelector('.pb-forms-q-card');
      if (!targetCardEl) {
        targetCardEl = container.querySelector('.pb-forms-q-card');
      }
      if (targetCardEl) {
        moveFormsWordToolbarAboveCard(targetCardEl, true);
      }

      if (renderOpts.focusCardId && targetCardEl && !renderOpts.skipScrollIntoView) {
        container.style.minHeight = '';
        try {
          targetCardEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        } catch (scrollErr) {}
        if (renderOpts.focusStem !== false) {
          var stemTarget = targetCardEl.querySelector('.pb-word-inline-editor.is-stem');
          if (stemTarget && typeof stemTarget.focus === 'function') {
            try {
              stemTarget.focus({ preventScroll: true });
            } catch (focusErr) {
              stemTarget.focus();
            }
          }
        }
      } else {
        if (renderOpts.restoreScroll !== false && typeof window !== 'undefined' && typeof window.scrollTo === 'function') {
          window.scrollTo(prevScrollX, prevScrollY);
        }
        container.style.minHeight = '';
      }
    }

    function enterFormsBuilderWorkspaceLayout() {
      if (typeof PBEnhancedSelect === 'object' && PBEnhancedSelect) {
        PBEnhancedSelect.closeActive(true, false);
      }
      var catalogCard = document.getElementById('admin-exam-builder-catalog-card');
      var qbankCard = document.getElementById('admin-question-bank-card');
      var workspace = document.getElementById('pb-forms-builder-workspace');
      if (catalogCard) catalogCard.classList.add('hidden');
      if (qbankCard) qbankCard.classList.add('hidden');
      if (isExamStudioModeActive) {
        currentExamStudioTab = 'builder';
        var studioTabs = [
          { id: 'btn-exam-studio-tab-builder', active: true },
          { id: 'btn-exam-studio-tab-grading', active: false },
          { id: 'btn-exam-studio-tab-integrity', active: false },
          { id: 'btn-exam-studio-tab-qbank', active: false }
        ];
        for (var st = 0; st < studioTabs.length; st++) {
          var sEl = document.getElementById(studioTabs[st].id);
          if (sEl) {
            sEl.classList.toggle('is-active', studioTabs[st].active);
            sEl.setAttribute('aria-selected', studioTabs[st].active ? 'true' : 'false');
          }
        }
        if (typeof switchAdminSubTab === 'function' && currentAdminTab !== 'exam-creation') {
          switchAdminSubTab('exam-creation', true, false);
        }
        var creationPanel = document.getElementById('admin-panel-exam-creation');
        if (creationPanel && creationPanel.firstElementChild && creationPanel.firstElementChild.querySelector('#admin-exam-creation-subnav')) {
          creationPanel.firstElementChild.classList.add('hidden');
        }
        if (typeof updateNavbarActiveForExamStudio === 'function') {
          updateNavbarActiveForExamStudio(true);
        }
      }
      var btnSets = document.getElementById('btn-exam-creation-subtab-sets');
      var btnQbank = document.getElementById('btn-exam-creation-subtab-qbank');
      if (btnSets) {
        btnSets.classList.add('is-active');
        btnSets.setAttribute('aria-selected', 'true');
      }
      if (btnQbank) {
        btnQbank.classList.remove('is-active');
        btnQbank.setAttribute('aria-selected', 'false');
      }
      if (workspace) workspace.classList.remove('hidden');
      syncFormsStickyToolbarOffset();
      if (typeof PBFloatingToc === 'object' && PBFloatingToc && typeof PBFloatingToc.syncForActiveView === 'function') {
        PBFloatingToc.syncForActiveView();
      }
    }

    var FORMS_AUTOSAVE_INTERVAL_MS = 60000;
    var formsBuilderAutoSaveIntervalId = null;
    var formsBuilderSaveInFlightPromise = null;
    var formsBuilderDirtySeq = 0;
    var formsBuilderLastSavedSeq = 0;
    var formsBuilderLastSavedSignature = '';
    var formsBuilderAutoSaveListenersBound = false;

    function isFormsBuilderWorkspaceVisible() {
      var ws = document.getElementById('pb-forms-builder-workspace');
      if (!ws || ws.classList.contains('hidden')) return false;
      var adminPortal = document.getElementById('view-admin');
      if (adminPortal && adminPortal.classList.contains('hidden')) return false;
      var creationPanel = document.getElementById('admin-panel-exam-creation');
      if (creationPanel && creationPanel.classList.contains('hidden')) return false;
      return true;
    }

    function setFormsAutoSaveStatusBadge(text, tone) {
      var el = document.getElementById('pb-forms-autosave-status');
      if (!el) return;
      el.textContent = text;
      if (tone === 'saving') {
        el.style.background = '#E0F2FE';
        el.style.color = '#0369A1';
      } else if (tone === 'saved') {
        el.style.background = '#DCFCE7';
        el.style.color = '#166534';
      } else if (tone === 'dirty') {
        el.style.background = '#FEF3C7';
        el.style.color = '#92400E';
      } else if (tone === 'warn') {
        el.style.background = '#FFEDD5';
        el.style.color = '#9A3412';
      } else {
        el.style.background = '#F1F5F9';
        el.style.color = '#475569';
      }
    }

    function formatFormsAutoSaveTimeHHMMSS() {
      try {
        return (
          new Intl.DateTimeFormat('en-GB', {
            timeZone: 'Asia/Bangkok',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            hour12: false
          }).format(new Date()) + ' ICT'
        );
      } catch (_e) {
        return new Date().toTimeString().slice(0, 8);
      }
    }

    function serializeFormsCardSnapshot(card) {
      if (!card) return '';
      try {
        return JSON.stringify({
          qId: card.questionId || '',
          qType: card.questionType || '',
          sec: card.blueprintSection || '',
          pts: String(card.points || ''),
          neg: String(card.negativePoints || ''),
          dif: card.difficulty || '',
          top: card.topicTags || '',
          stem: card.stem || '',
          stemDoc: card.stemDoc || null,
          opts: card.options || [],
          nt: card.numericTarget,
          to: card.numericTolerance,
          nu: card.numericUnit,
          sm: card.shortAnswerMode,
          aa: card.acceptedAnswers,
          sa: card.sampleModelAnswer,
          exp: card.explanation || '',
          expDoc: card.explanationDoc || null,
          imgs: card.imageFileIds || [],
          alt: card.imageAltText || ''
        });
      } catch (_e) {
        return String(card.stem || '') + ':' + String(card.points || '');
      }
    }

    function computeFormsBuilderStateSignature() {
      var readVal = function (id) {
        var el = document.getElementById(id);
        return el ? String(el.value || '') : '';
      };
      var headerSig = [
        readVal('input-forms-exam-id'),
        readVal('input-forms-exam-code'),
        readVal('input-forms-exam-title'),
        readVal('select-forms-exam-course'),
        readVal('textarea-forms-exam-description'),
        readVal('select-forms-exam-mode'),
        readVal('input-forms-exam-duration'),
        readVal('input-forms-exam-pass-pct'),
        readVal('input-forms-exam-attempts'),
        readVal('select-forms-exam-attempt-policy'),
        readVal('select-forms-score-policy'),
        readVal('select-forms-explanation-policy'),
        readVal('input-forms-open-at'),
        readVal('input-forms-close-at'),
        readVal('input-forms-sec-title'),
        readVal('select-forms-sec-mode')
      ].join('|');
      var cardSigs = Array.isArray(formsBuilderQuestionCards)
        ? formsBuilderQuestionCards.map(serializeFormsCardSnapshot).join('||')
        : '';
      return headerSig + '###' + cardSigs;
    }

    function markFormsBuilderDirty() {
      formsBuilderDirtySeq += 1;
      setFormsAutoSaveStatusBadge('Unsaved edits • Auto-saves every 1 min', 'dirty');
    }

    function markFormsCardDirty(card) {
      if (card) {
        card.isDirty = true;
        card._editSeq = (card._editSeq || 0) + 1;
      }
      markFormsBuilderDirty();
    }

    function saveFormsBuilderLocalBackup(reasonLabel) {
      try {
        if (typeof localStorage === 'undefined') return;
        var uid = (currentSessionMeta && currentSessionMeta.user && currentSessionMeta.user.userId) || 'admin';
        var examId = ((document.getElementById('input-forms-exam-id') || {}).value || '').trim() || 'new';
        var key = 'pb_forms_autosave_backup_v1_' + uid + '_' + examId;
        localStorage.setItem(
          key,
          JSON.stringify({
            savedAtIso: new Date().toISOString(),
            reason: String(reasonLabel || 'incomplete'),
            signature: computeFormsBuilderStateSignature(),
            examTitle: (document.getElementById('input-forms-exam-title') || {}).value || '',
            examCode: (document.getElementById('input-forms-exam-code') || {}).value || '',
            courseId: (document.getElementById('select-forms-exam-course') || {}).value || '',
            questionCount: Array.isArray(formsBuilderQuestionCards) ? formsBuilderQuestionCards.length : 0
          })
        );
      } catch (_e) {}
    }

    function bindFormsBuilderAutoSaveListenersOnce() {
      if (formsBuilderAutoSaveListenersBound) return;
      var ws = document.getElementById('pb-forms-builder-workspace');
      if (!ws) return;
      formsBuilderAutoSaveListenersBound = true;
      var handleWsMutation = function (ev) {
        var target = ev && ev.target;
        if (target && target.closest) {
          var cardEl = target.closest('[data-forms-card-id]');
          if (cardEl && Array.isArray(formsBuilderQuestionCards)) {
            var cid = cardEl.getAttribute('data-forms-card-id');
            for (var ci = 0; ci < formsBuilderQuestionCards.length; ci++) {
              if (formsBuilderQuestionCards[ci] && formsBuilderQuestionCards[ci].localId === cid) {
                formsBuilderQuestionCards[ci].isDirty = true;
                formsBuilderQuestionCards[ci]._editSeq = (formsBuilderQuestionCards[ci]._editSeq || 0) + 1;
                break;
              }
            }
          }
        }
        markFormsBuilderDirty();
      };
      ws.addEventListener('input', handleWsMutation);
      ws.addEventListener('change', handleWsMutation);
    }

    function stopFormsBuilderAutoSaveTimer() {
      if (formsBuilderAutoSaveIntervalId !== null) {
        clearInterval(formsBuilderAutoSaveIntervalId);
        formsBuilderAutoSaveIntervalId = null;
      }
    }

    function startFormsBuilderAutoSaveTimer() {
      stopFormsBuilderAutoSaveTimer();
      bindFormsBuilderAutoSaveListenersOnce();
      formsBuilderLastSavedSignature = computeFormsBuilderStateSignature();
      formsBuilderLastSavedSeq = formsBuilderDirtySeq;
      setFormsAutoSaveStatusBadge('Auto-save: Every 1 min', 'idle');
      formsBuilderAutoSaveIntervalId = setInterval(function () {
        if (!isFormsBuilderWorkspaceVisible()) {
          stopFormsBuilderAutoSaveTimer();
          return;
        }
        var role = currentSessionMeta && currentSessionMeta.user && currentSessionMeta.user.role;
        if (role !== 'ADMIN') {
          stopFormsBuilderAutoSaveTimer();
          return;
        }
        if (typeof handleFormsAutoSaveTick === 'function') {
          return handleFormsAutoSaveTick();
        }
      }, FORMS_AUTOSAVE_INTERVAL_MS);
    }

    function openFormsExamBuilderForNewExam() {
      restoreFormsPreviewButtonsState();
      populateAdminExamBuilderCourseAndStudentDropdownsPhase3();
      enterFormsBuilderWorkspaceLayout();

      var idEl = document.getElementById('input-forms-exam-id');
      var verEl = document.getElementById('input-forms-exam-version');
      var titleEl = document.getElementById('input-forms-exam-title');
      var descEl = document.getElementById('textarea-forms-exam-description');
      var codeEl = document.getElementById('input-forms-exam-code');
      var modeEl = document.getElementById('select-forms-exam-mode');
      var durEl = document.getElementById('input-forms-exam-duration');
      var passEl = document.getElementById('input-forms-exam-pass-pct');
      var attEl = document.getElementById('input-forms-exam-attempts');
      var scEl = document.getElementById('select-forms-score-policy');
      var exEl = document.getElementById('select-forms-explanation-policy');
      var openEl = document.getElementById('input-forms-open-at');
      var closeEl = document.getElementById('input-forms-close-at');
      var secTitleEl = document.getElementById('input-forms-sec-title');
      var secModeEl = document.getElementById('select-forms-sec-mode');
      var crsEl = document.getElementById('select-forms-exam-course');

      if (idEl) idEl.value = '';
      if (verEl) verEl.value = '';
      if (titleEl) titleEl.value = '';
      if (descEl) descEl.value = '';
      if (codeEl) codeEl.value = '';
      if (modeEl) modeEl.value = 'MOCK_EXAM';
      if (durEl) durEl.value = String(PB_ALEVEL_66_BIO_BLUEPRINT.examDurationMinutes);
      if (passEl) passEl.value = '60';
      if (attEl) attEl.value = '1';
      var fmAttPol = document.getElementById('select-forms-exam-attempt-policy');
      if (fmAttPol && fmAttPol.dataset) fmAttPol.dataset.userTouched = '';
      syncExamAttemptPolicyPairFromCount(
        'select-forms-exam-attempt-policy',
        'input-forms-exam-attempts',
        'wrap-forms-exam-attempt-pair',
        1
      );
      if (scEl) scEl.value = 'IMMEDIATE_AUTO';
      if (exEl) exEl.value = 'WITH_SCORE';
      if (openEl) openEl.value = '';
      if (closeEl) closeEl.value = '';
      activeFormsBlueprintSectionId = 'PART_1';
      if (secTitleEl) secTitleEl.value = PB_ALEVEL_66_BIO_BLUEPRINT.sections[0].title;
      if (secModeEl) secModeEl.value = 'FIXED_ITEMS';
      if (crsEl && !crsEl.value && crsEl.options.length > 1) {
        crsEl.selectedIndex = 1;
      }

      setText('pb-forms-status-badge', 'A-LEVEL 66 BIO FORMAT');
      var prog = document.getElementById('pb-forms-progress-banner');
      if (prog) prog.classList.add('hidden');
      if (typeof setExamPdfEditorSlotState === 'function') {
        setExamPdfEditorSlotState(FORMS_PAPER_PDF_CFG, '', '');
        setExamPdfEditorSlotState(FORMS_ANSWER_PDF_CFG, '', '', 'AFTER_SUBMIT');
      }

      ensureFormsWordToolbarMounted();
      formsBuilderQuestionCards = [createBlankFormsQuestionCardState()];
      renderFormsBuilderQuestionCards();
      formsBuilderDirtySeq = 0;
      formsBuilderLastSavedSeq = 0;
      startFormsBuilderAutoSaveTimer();
      if (titleEl) titleEl.focus();
    }

    function openFormsExamBuilderWithExam(examDto) {
      if (!examDto) {
        openFormsExamBuilderForNewExam();
        return;
      }
      restoreFormsPreviewButtonsState();
      populateAdminExamBuilderCourseAndStudentDropdownsPhase3();
      enterFormsBuilderWorkspaceLayout();

      var idEl = document.getElementById('input-forms-exam-id');
      var verEl = document.getElementById('input-forms-exam-version');
      var titleEl = document.getElementById('input-forms-exam-title');
      var descEl = document.getElementById('textarea-forms-exam-description');
      var codeEl = document.getElementById('input-forms-exam-code');
      var crsEl = document.getElementById('select-forms-exam-course');
      var modeEl = document.getElementById('select-forms-exam-mode');
      var durEl = document.getElementById('input-forms-exam-duration');
      var passEl = document.getElementById('input-forms-exam-pass-pct');
      var attEl = document.getElementById('input-forms-exam-attempts');
      var scEl = document.getElementById('select-forms-score-policy');
      var exEl = document.getElementById('select-forms-explanation-policy');
      var openEl = document.getElementById('input-forms-open-at');
      var closeEl = document.getElementById('input-forms-close-at');
      var rqEl = document.getElementById('chk-forms-rand-questions');
      var roEl = document.getElementById('chk-forms-rand-options');
      var pfEl = document.getElementById('chk-forms-practice-feedback');
      var secTitleEl = document.getElementById('input-forms-sec-title');
      var secModeEl = document.getElementById('select-forms-sec-mode');
      var secDrawEl = document.getElementById('input-forms-sec-pool-draw');

      if (idEl) idEl.value = examDto.examSetId || '';
      if (verEl) verEl.value = String(examDto.version || 1);
      if (titleEl) titleEl.value = examDto.title || '';
      var parsedFmPdf =
        typeof extractExamPdfAttachmentsFromRichText === 'function'
          ? extractExamPdfAttachmentsFromRichText(examDto.instructionsRichText || examDto.descriptionRichText)
          : { examPaperPdf: null, answerSheetPdf: null, plainText: '' };
      if (descEl) {
        descEl.value =
          parsedFmPdf.plainText ||
          examDto.descriptionPlainText ||
          examDto.instructionsPlainText ||
          '';
      }
      if (typeof setExamPdfEditorSlotState === 'function') {
        if (parsedFmPdf.examPaperPdf) {
          setExamPdfEditorSlotState(FORMS_PAPER_PDF_CFG, parsedFmPdf.examPaperPdf.fileId, parsedFmPdf.examPaperPdf.filename);
        } else {
          setExamPdfEditorSlotState(FORMS_PAPER_PDF_CFG, '', '');
        }
        if (parsedFmPdf.answerSheetPdf) {
          setExamPdfEditorSlotState(
            FORMS_ANSWER_PDF_CFG,
            parsedFmPdf.answerSheetPdf.fileId,
            parsedFmPdf.answerSheetPdf.filename,
            parsedFmPdf.answerSheetPdf.policy || 'AFTER_SUBMIT'
          );
        } else {
          setExamPdfEditorSlotState(FORMS_ANSWER_PDF_CFG, '', '', 'AFTER_SUBMIT');
        }
      }
      if (codeEl) codeEl.value = examDto.examCode || '';
      if (crsEl) crsEl.value = examDto.courseId || '';
      if (modeEl) modeEl.value = examDto.examMode || 'MOCK_EXAM';
      if (durEl) durEl.value = String(examDto.durationMinutes !== undefined ? examDto.durationMinutes : 45);
      if (passEl) passEl.value = String(examDto.passThresholdPct || 60);
      var resolvedFormsMaxAtt =
        examDto.maxAttempts !== undefined && examDto.maxAttempts !== null
          ? Number(examDto.maxAttempts)
          : examDto.examMode === 'PRACTICE'
          ? 0
          : 1;
      if (attEl) attEl.value = String(resolvedFormsMaxAtt);
      var fmAttPolEdit = document.getElementById('select-forms-exam-attempt-policy');
      if (fmAttPolEdit && fmAttPolEdit.dataset) fmAttPolEdit.dataset.userTouched = '1';
      syncExamAttemptPolicyPairFromCount(
        'select-forms-exam-attempt-policy',
        'input-forms-exam-attempts',
        'wrap-forms-exam-attempt-pair',
        resolvedFormsMaxAtt
      );
      if (scEl) scEl.value = examDto.scoreReleasePolicy || 'IMMEDIATE_AUTO';
      if (exEl) exEl.value = examDto.explanationReleasePolicy || 'WITH_SCORE';
      if (openEl) openEl.value = examDto.openAtUtc || '';
      if (closeEl) closeEl.value = examDto.closeAtUtc || '';
      if (rqEl) rqEl.checked = Boolean(examDto.randomizeQuestions);
      if (roEl) roEl.checked = Boolean(examDto.randomizeOptions);
      if (pfEl) pfEl.checked = Boolean(examDto.allowPerQuestionPracticeFeedback);

      setText(
        'pb-forms-status-badge',
        'EDITING: ' + (examDto.examCode || 'EXAM') + ' (' + (examDto.status || 'DRAFT') + ')'
      );

      // Build lookup map of full question DTOs (with private answer keys) from currentQBankQuestionsPhase2
      var qbankById = {};
      if (Array.isArray(currentQBankQuestionsPhase2)) {
        for (var q = 0; q < currentQBankQuestionsPhase2.length; q++) {
          qbankById[currentQBankQuestionsPhase2[q].questionId] = currentQBankQuestionsPhase2[q];
        }
      }

      var loadedCards = [];
      if (Array.isArray(examDto.sections) && examDto.sections.length > 0) {
        var s0 = examDto.sections[0];
        if (secTitleEl) secTitleEl.value = s0.title || 'Part I: Biology Questions';
        if (secModeEl) {
          secModeEl.value = s0.selectionMode || 'FIXED_ITEMS';
          if (secDrawEl) secDrawEl.classList.toggle('hidden', secModeEl.value !== 'QUESTION_POOL');
        }
        if (secDrawEl) secDrawEl.value = String(s0.poolDrawCount || 5);

        for (var si = 0; si < examDto.sections.length; si++) {
          var sec = examDto.sections[si];
          var items = Array.isArray(sec.items) ? sec.items : [];
          for (var k = 0; k < items.length; k++) {
            var it = items[k];
            var prevQ = it.questionPreview || null;
            var bankQ = qbankById[it.questionId] || null;
            var fullQ = null;
            if (prevQ && (!bankQ || (it.questionVersionId && prevQ.questionVersionId === it.questionVersionId && bankQ.questionVersionId !== it.questionVersionId))) {
              fullQ = prevQ;
            } else {
              fullQ = bankQ || prevQ || null;
            }
            loadedCards.push(
              mapQuestionDtoToFormsCardState(fullQ, it.pointsDisplay, it.negativePointsDisplay, sec.title)
            );
          }
        }
      }

      formsBuilderQuestionCards =
        loadedCards.length > 0 ? loadedCards : [createBlankFormsQuestionCardState()];
      renderFormsBuilderQuestionCards();

      // If Question Bank wasn't loaded yet, fetch it with includePrivate:true so correct answer keys populate accurately
      if (Object.keys(qbankById).length === 0) {
        loadAdminQuestionBankPhase2(1, true).then(function () {
          var freshMap = {};
          if (Array.isArray(currentQBankQuestionsPhase2)) {
            for (var fi = 0; fi < currentQBankQuestionsPhase2.length; fi++) {
              freshMap[currentQBankQuestionsPhase2[fi].questionId] = currentQBankQuestionsPhase2[fi];
            }
          }
          for (var ci = 0; ci < formsBuilderQuestionCards.length; ci++) {
            var c = formsBuilderQuestionCards[ci];
            if (c.questionId && freshMap[c.questionId] && !c.isDirty) {
              formsBuilderQuestionCards[ci] = mapQuestionDtoToFormsCardState(
                freshMap[c.questionId],
                c.points,
                c.negativePoints,
                getBlueprintSectionById(c.blueprintSection).title
              );
            }
          }
          renderFormsBuilderQuestionCards();
          formsBuilderDirtySeq = 0;
          formsBuilderLastSavedSeq = 0;
          startFormsBuilderAutoSaveTimer();
        });
      }
      formsBuilderDirtySeq = 0;
      formsBuilderLastSavedSeq = 0;
      startFormsBuilderAutoSaveTimer();
    }

    function closeFormsExamBuilderToCatalog(opt_opts) {
      stopFormsBuilderAutoSaveTimer();
      var opts = opt_opts && typeof opt_opts === 'object' ? opt_opts : {};
      restoreFormsPreviewButtonsState();
      if (typeof PBEnhancedSelect === 'object' && PBEnhancedSelect) {
        PBEnhancedSelect.closeActive(true, false);
      }
      var catalogCard = document.getElementById('admin-exam-builder-catalog-card');
      var qbankCard = document.getElementById('admin-question-bank-card');
      var workspace = document.getElementById('pb-forms-builder-workspace');
      if (workspace) {
        unloadEmbeddedPdfFramesInElement(workspace);
        workspace.classList.add('hidden');
      }
      if (!opts.skipSubTabSync) {
        if (catalogCard) catalogCard.classList.remove('hidden');
        if (qbankCard) qbankCard.classList.add('hidden');
        var btnSets = document.getElementById('btn-exam-creation-subtab-sets');
        var btnQbank = document.getElementById('btn-exam-creation-subtab-qbank');
        if (btnSets) {
          btnSets.classList.add('is-active');
          btnSets.setAttribute('aria-selected', 'true');
        }
        if (btnQbank) {
          btnQbank.classList.remove('is-active');
          btnQbank.setAttribute('aria-selected', 'false');
        }
      }
      if (typeof PBFloatingToc === 'object' && PBFloatingToc && typeof PBFloatingToc.syncForActiveView === 'function') {
        PBFloatingToc.syncForActiveView();
      }
    }

    function renderFormsImportBankDrawerList() {
      var listEl = document.getElementById('pb-forms-import-bank-list');
      if (!listEl) return;
      while (listEl.firstChild) listEl.removeChild(listEl.firstChild);

      var searchInp = document.getElementById('input-forms-import-search');
      var kw = searchInp ? searchInp.value.trim().toLowerCase() : '';
      var questions = Array.isArray(currentQBankQuestionsPhase2) ? currentQBankQuestionsPhase2 : [];

      var matches = questions.filter(function (q) {
        if (q.status === 'ARCHIVED') return false;
        if (!kw) return true;
        var cleanHayText =
          typeof stripInternalMediaMarkerTags === 'function'
            ? stripInternalMediaMarkerTags((q.title || '') + ' ' + (q.stemPlainText || ''))
            : (q.title || '') + ' ' + (q.stemPlainText || '');
        var hay = ((q.questionCode || '') + ' ' + cleanHayText).toLowerCase();
        return hay.indexOf(kw) !== -1;
      });

      if (matches.length === 0) {
        var emptyP = document.createElement('p');
        emptyP.style.margin = '6px 0';
        emptyP.style.fontSize = '0.84rem';
        emptyP.style.color = 'var(--color-text-muted)';
        emptyP.textContent = 'No matching questions found in the Question Bank.';
        listEl.appendChild(emptyP);
        return;
      }

      for (var i = 0; i < matches.length; i++) {
        (function (qDto) {
          var row = document.createElement('div');
          row.className = 'pb-forms-import-item';

          var info = document.createElement('div');
          info.style.fontSize = '0.85rem';
          var strong = document.createElement('strong');
          strong.style.color = 'var(--color-brand-deep)';
          strong.textContent = '[' + qDto.questionCode + '] ';
          info.appendChild(strong);
          var rawPreview = qDto.stemPlainText || qDto.title || '';
          var cleanPreview =
            typeof stripInternalMediaMarkerTags === 'function'
              ? stripInternalMediaMarkerTags(rawPreview)
              : rawPreview;
          var span = document.createElement('span');
          span.textContent = (cleanPreview || qDto.questionCode || 'Question').slice(0, 120);
          info.appendChild(span);
          row.appendChild(info);

          var addBtn = document.createElement('button');
          addBtn.type = 'button';
          addBtn.className = 'btn btn-secondary btn-sm';
          addBtn.textContent = '+ Add to Exam';
          addBtn.addEventListener('click', function () {
            formsBuilderQuestionCards.push(mapQuestionDtoToFormsCardState(qDto));
            renderFormsBuilderQuestionCards();
            PBNotify.toast('success', 'Question Added', 'Added ' + qDto.questionCode + ' to the form.');
          });
          row.appendChild(addBtn);
          listEl.appendChild(row);
        })(matches[i]);
      }
    }

    function setFormsBuilderProgressBanner(variant, title, body) {
      var banner = document.getElementById('pb-forms-progress-banner');
      if (!banner) return;
      if (variant === 'hidden') {
        banner.classList.add('hidden');
        return;
      }
      banner.className = 'banner banner-' + (variant || 'info');
      setText('pb-forms-progress-title', title || '');
      setText('pb-forms-progress-body', body || '');
      banner.classList.remove('hidden');
    }

    function saveAllFormsQuestionsAndBuildExamPayload(opt_opts) {
      var buildOpts = opt_opts && typeof opt_opts === 'object' ? opt_opts : {};
      var isSilentAutoSave = Boolean(buildOpts.isSilentAutoSave);
      var rejectFormsValidation = function (msg) {
        var vErr = new Error(msg);
        if (isSilentAutoSave) vErr.isAutoSaveIncomplete = true;
        return Promise.reject(vErr);
      };
      var examTitle = ((document.getElementById('input-forms-exam-title') || {}).value || '').trim();
      if (!examTitle || examTitle.length < 3) {
        return rejectFormsValidation('Please enter an Exam or Quiz Title (at least 3 characters) at the top of the form.');
      }
      var courseId = ((document.getElementById('select-forms-exam-course') || {}).value || '').trim();
      if (!courseId) {
        return rejectFormsValidation('Please select an Assigned Course for this exam.');
      }
      if (formsBuilderQuestionCards.length === 0) {
        return rejectFormsValidation('Please add at least one question card to the exam.');
      }

      var rawCode = ((document.getElementById('input-forms-exam-code') || {}).value || '').trim().toUpperCase();
      if (!rawCode) {
        var slug = examTitle
          .toUpperCase()
          .replace(/[^A-Z0-9]+/g, '-')
          .replace(/^-+|-+$/g, '')
          .slice(0, 14);
        var suffix = String(Date.now()).slice(-5);
        rawCode = 'BIO-' + (slug || 'EXAM') + '-' + suffix;
        var codeInp = document.getElementById('input-forms-exam-code');
        if (codeInp) codeInp.value = rawCode;
      }

      // Validate all cards upfront before making network calls
      for (var vIdx = 0; vIdx < formsBuilderQuestionCards.length; vIdx++) {
        var c = formsBuilderQuestionCards[vIdx];
        var qNum = vIdx + 1;
        var stemCleanTxt = extractCleanTextFromRichTextDoc(c.stemDoc || c.stem).trim();
        var stemChkTxt = extractPlainTextFromRichTextDoc(c.stemDoc || c.stem).trim();
        if (!stemChkTxt) {
          return rejectFormsValidation('Question ' + qNum + ' is missing its question prompt text.');
        }
        c.stem = stemCleanTxt || stemChkTxt;
        if (c.questionType === 'COMPLEX_MULTIPLE_CHOICE') {
          var nonEmptyStmts = c.options.filter(function (o) {
            return extractPlainTextFromRichTextDoc(o.doc || o.text).trim().length > 0;
          });
          if (nonEmptyStmts.length < 3 || nonEmptyStmts.length > 5) {
            return rejectFormsValidation('Question ' + qNum + ' (Complex MC) requires 3 to 5 non-empty sub-statements.');
          }
        } else if (c.questionType === 'SINGLE_CHOICE' || c.questionType === 'MULTIPLE_SELECT' || c.questionType === 'TRUE_FALSE') {
          var nonEmptyOpts = c.options.filter(function (o) {
            return extractPlainTextFromRichTextDoc(o.doc || o.text).trim().length > 0;
          });
          if (nonEmptyOpts.length < 2) {
            return rejectFormsValidation('Question ' + qNum + ' must have at least 2 non-empty answer choices.');
          }
          var correctCnt = nonEmptyOpts.filter(function (o) { return Boolean(o.isCorrect); }).length;
          if (correctCnt < 1) {
            return rejectFormsValidation('Question ' + qNum + ' must have a correct answer selected.');
          }
        }
      }

      var totalCards = formsBuilderQuestionCards.length;
      var dirtyQueue = [];
      for (var idx = 0; idx < totalCards; idx++) {
        if (!formsBuilderQuestionCards[idx].questionId || formsBuilderQuestionCards[idx].isDirty) {
          dirtyQueue.push({ card: formsBuilderQuestionCards[idx], cardIdx: idx });
        }
      }
      var totalDirty = dirtyQueue.length;
      var completedDirty = 0;

      function saveSingleFormsQuestionCard(card, cardIdx) {
        var qCode = String(card.questionCode || '').trim().toUpperCase();
        if (!qCode) {
          qCode = (rawCode.slice(0, 26) + '-Q' + String(cardIdx + 1) + '-' + String(Date.now()).slice(-4)).slice(0, 46);
        }
        var qTitle = String(card.title || '').trim();
        if (!qTitle) {
          var cleanStemForTitle = extractCleanTextFromRichTextDoc(card.stemDoc || card.stem);
          qTitle = String(cleanStemForTitle || 'Diagram / Rich Media Question ' + (cardIdx + 1))
            .replace(/\s+/g, ' ')
            .trim()
            .slice(0, 120);
        }

        var optionsPayload = [];
        if (
          card.questionType === 'SINGLE_CHOICE' ||
          card.questionType === 'COMPLEX_MULTIPLE_CHOICE' ||
          card.questionType === 'MULTIPLE_SELECT' ||
          card.questionType === 'TRUE_FALSE'
        ) {
          for (var oi = 0; oi < card.options.length; oi++) {
            var o = card.options[oi];
            var optDocObj = o.doc ? cloneRichTextDocSafe(o.doc) : plainTextToRichTextDocSafe(o.text || '');
            var txt = extractPlainTextFromRichTextDoc(optDocObj).trim();
            if (!txt) continue;
            optionsPayload.push({
              optionKey:
                card.questionType === 'TRUE_FALSE'
                  ? oi === 0
                    ? 'TRUE'
                    : 'FALSE'
                  : card.questionType === 'COMPLEX_MULTIPLE_CHOICE'
                  ? 'S' + (optionsPayload.length + 1)
                  : String.fromCharCode(65 + optionsPayload.length),
              text: txt,
              contentRichText: card.questionType === 'TRUE_FALSE' ? txt : optDocObj,
              isCorrect: Boolean(o.isCorrect),
              pinPosition: card.questionType === 'COMPLEX_MULTIPLE_CHOICE' ? 'FIXED' : (o.pinPosition || 'NONE')
            });
          }
        }

        var imgIds = Array.isArray(card.imageFileIds) ? card.imageFileIds : [];
        var altTxt = String(card.imageAltText || '').trim();
        var useVisualInterpFlag = false;
        if (imgIds.length > 0 && !altTxt) {
          altTxt = 'Attached figure ' + (cardIdx + 1);
          useVisualInterpFlag = true;
        }
        var stemDocPayload = card.stemDoc ? cloneRichTextDocSafe(card.stemDoc) : plainTextToRichTextDocSafe(card.stem);
        var expDocPayload = card.explanationDoc ? cloneRichTextDocSafe(card.explanationDoc) : plainTextToRichTextDocSafe(card.explanation || '');
        var expFinalPayload = extractPlainTextFromRichTextDoc(expDocPayload).trim() ? expDocPayload : '';

        var isFreeQCard = Boolean(card.isFreeQuestion) || (card.points !== undefined && card.points !== '' && Number(card.points) === 0);
        var defaultPtsStr = isFreeQCard
          ? '0'
          : String(
              card.points !== undefined && card.points !== null && String(card.points).trim() !== ''
                ? card.points
                : card.questionType === 'COMPLEX_MULTIPLE_CHOICE'
                ? '3.2'
                : '2.4'
            );
        var resolvedTopicTag = getBlueprintSectionById(card.blueprintSection || 'PART_1').title;
        if (!card.topicTags || PB_ALEVEL_66_BIO_BLUEPRINT.sections.some(function (sec) { return sec.title === card.topicTags; })) {
          card.topicTags = resolvedTopicTag;
        }
        var qPayload = {
          questionId: card.questionId || '',
          expectedVersion: card.expectedVersion ? Number(card.expectedVersion) : undefined,
          questionCode: qCode,
          title: qTitle,
          questionType: card.questionType,
          difficulty: card.difficulty || 'MEDIUM',
          isFreeQuestion: isFreeQCard,
          defaultPoints: defaultPtsStr,
          negativePoints: isFreeQCard ? '0' : String(card.negativePoints !== undefined && card.negativePoints !== '' ? card.negativePoints : '0'),
          topicTags: resolvedTopicTag,
          status: 'PUBLISHED',
          stimulusId: '',
          stemRichText: stemDocPayload,
          imageFileId: imgIds.join(','),
          imageFileIds: imgIds,
          imageAltText: altTxt,
          accessibleDesignFlag: useVisualInterpFlag ? 'VISUAL_INTERPRETATION_REQUIRED' : (card.accessibleDesignFlag || 'STANDARD_ALT'),
          options: optionsPayload,
          multiSelectScoringRule: card.multiSelectRule || 'EXACT_MATCH',
          unitLabel: card.numericUnit || '',
          numericSpec: {
            matchMode: 'EXACT_WITH_TOLERANCE',
            targetValue: String(card.numericTarget || '0'),
            toleranceType: 'ABSOLUTE',
            toleranceValue: String(card.numericTolerance || '0'),
            roundingDecimals: '',
            rangeMin: '',
            rangeMax: ''
          },
          gradingMode:
            card.questionType === 'WRITTEN_RESPONSE'
              ? 'MANUAL'
              : card.questionType === 'SHORT_ANSWER'
              ? card.acceptedAnswers && card.acceptedAnswers.trim()
                ? 'NORMALIZED_AUTO'
                : 'MANUAL'
              : 'AUTO',
          maxLengthChars: 1500,
          acceptedAnswers: card.acceptedAnswers || '',
          sampleModelAnswer: card.sampleModelAnswer || '',
          explanationRichText: expFinalPayload,
          referenceText: '',
          adminNotes: ''
        };

        var cardSnapshotAtStart = serializeFormsCardSnapshot(card);
        return rpcCallEnvelope('admin.questions.save', qPayload, {
          dedupeKey: 'admin.questions.save:' + (card.questionId || ('new_' + cardIdx + '_' + qCode)),
          suppressErrorBanner: isSilentAutoSave
        }).then(function (env) {
          var savedQ = env.data && env.data.question;
          if (savedQ && savedQ.questionId) {
            card.questionId = savedQ.questionId;
            card.questionVersionId = savedQ.questionVersionId || card.questionVersionId || '';
            card.expectedVersion = savedQ.version || 1;
            card.questionCode = savedQ.questionCode || qCode;
            card.title = savedQ.title || qTitle;
            if (serializeFormsCardSnapshot(card) === cardSnapshotAtStart) {
              card.isDirty = false;
            }
            if (Array.isArray(currentQBankQuestionsPhase2)) {
              var replacedInBank = false;
              for (var qi = 0; qi < currentQBankQuestionsPhase2.length; qi++) {
                if (currentQBankQuestionsPhase2[qi] && currentQBankQuestionsPhase2[qi].questionId === savedQ.questionId) {
                  currentQBankQuestionsPhase2[qi] = savedQ;
                  replacedInBank = true;
                  break;
                }
              }
              if (!replacedInBank) currentQBankQuestionsPhase2.unshift(savedQ);
            }
          }
          completedDirty++;
          if (totalDirty > 0) {
            if (isSilentAutoSave) {
              setFormsAutoSaveStatusBadge('Auto-saving (' + completedDirty + '/' + totalDirty + ')...', 'saving');
            } else {
              setFormsBuilderProgressBanner(
                'info',
                'Saving Questions (' + completedDirty + ' of ' + totalDirty + ')...',
                'Saved Q' + (cardIdx + 1) + ': ' + String(card.stem || qTitle).slice(0, 65)
              );
            }
          }
        });
      }

      var savePromise = Promise.resolve();
      if (totalDirty > 0) {
        if (isSilentAutoSave) {
          setFormsAutoSaveStatusBadge('Auto-saving ' + totalDirty + ' question(s)...', 'saving');
        } else {
          setFormsBuilderProgressBanner(
            'info',
            'Saving ' + totalDirty + ' Updated Question(s) in Parallel...',
            'Using concurrent request workers for faster Mock Test saving...'
          );
        }
        var nextCursor = 0;
        var workerCount = Math.min(3, totalDirty);
        var workers = [];
        function runWorker() {
          if (nextCursor >= totalDirty) return Promise.resolve();
          var job = dirtyQueue[nextCursor++];
          return saveSingleFormsQuestionCard(job.card, job.cardIdx).then(runWorker);
        }
        for (var w = 0; w < workerCount; w++) {
          workers.push(runWorker());
        }
        savePromise = Promise.all(workers);
      }

      return savePromise.then(function () {
        invalidateQBankClientCachePhase2();
        var examId = ((document.getElementById('input-forms-exam-id') || {}).value || '').trim();
        var examVer = ((document.getElementById('input-forms-exam-version') || {}).value || '').trim();
        var examMode = (document.getElementById('select-forms-exam-mode') || {}).value || 'MOCK_EXAM';
        var durVal = (document.getElementById('input-forms-exam-duration') || {}).value || '90';
        if (examMode === 'MOCK_EXAM' && Number(durVal) <= 0) {
          durVal = '90';
        }
        var descTxt = (document.getElementById('textarea-forms-exam-description') || {}).value || '';
        var secMode = (document.getElementById('select-forms-sec-mode') || {}).value || 'FIXED_ITEMS';

        // Group contiguous cards by blueprint section so card order never silently jumps when changing 1 question's category
        var sectionGroups = [];
        for (var i = 0; i < formsBuilderQuestionCards.length; i++) {
          var c = formsBuilderQuestionCards[i];
          var sId = c.blueprintSection || 'PART_1';
          var isFreeItCard = Boolean(c.isFreeQuestion) || (c.points !== undefined && c.points !== '' && Number(c.points) === 0);
          var ptsItemStr = isFreeItCard
            ? '0'
            : String(c.points !== undefined && c.points !== null && String(c.points).trim() !== '' ? c.points : '2.4');
          var itemPayload = {
            questionId: c.questionId,
            isFreeQuestion: isFreeItCard,
            points: ptsItemStr,
            negativePoints: isFreeItCard ? '0' : String(c.negativePoints !== undefined && c.negativePoints !== '' ? c.negativePoints : '0')
          };
          var lastGrp = sectionGroups.length > 0 ? sectionGroups[sectionGroups.length - 1] : null;
          if (!lastGrp || lastGrp.sectionId !== sId) {
            sectionGroups.push({
              sectionId: sId,
              title: getBlueprintSectionById(sId).title,
              items: [itemPayload]
            });
          } else {
            lastGrp.items.push(itemPayload);
          }
        }

        var builtSections = [];
        for (var sg = 0; sg < sectionGroups.length; sg++) {
          var grp = sectionGroups[sg];
          var pDraw = Number((document.getElementById('input-forms-sec-pool-draw') || {}).value || 1);
          if (secMode === 'QUESTION_POOL' && pDraw > grp.items.length) pDraw = grp.items.length;
          builtSections.push({
            title: grp.title,
            selectionMode: secMode,
            poolDrawCount: pDraw,
            items: grp.items
          });
        }
        if (builtSections.length > 0) {
          var secTitleField = document.getElementById('input-forms-sec-title');
          if (secTitleField) secTitleField.value = builtSections[0].title;
        }

        return {
          examSetId: examId,
          expectedVersion: examVer ? Number(examVer) : undefined,
          examCode: rawCode,
          title: examTitle,
          courseId: courseId,
          examMode: examMode,
          durationMinutes: String(durVal),
          maxAttempts: readExamAttemptPolicyCountValue(
            'select-forms-exam-attempt-policy',
            'input-forms-exam-attempts',
            examMode
          ),
          openAtUtc: (document.getElementById('input-forms-open-at') || {}).value || '',
          closeAtUtc: (document.getElementById('input-forms-close-at') || {}).value || '',
          scoreReleasePolicy: (document.getElementById('select-forms-score-policy') || {}).value || 'IMMEDIATE_AUTO',
          explanationReleasePolicy: (document.getElementById('select-forms-explanation-policy') || {}).value || 'WITH_SCORE',
          aggregationRule: 'BEST_PUBLISHED',
          passThresholdPct: (document.getElementById('input-forms-exam-pass-pct') || {}).value || '60',
          randomizeQuestions: Boolean((document.getElementById('chk-forms-rand-questions') || {}).checked),
          randomizeOptions: Boolean((document.getElementById('chk-forms-rand-options') || { checked: true }).checked),
          allowPerQuestionPracticeFeedback:
            examMode === 'PRACTICE' && Boolean((document.getElementById('chk-forms-practice-feedback') || {}).checked),
          copyPolicyEnabled: Boolean((document.getElementById('chk-forms-copy-policy') || { checked: true }).checked),
          descriptionRichText: descTxt,
          instructionsRichText: composeExamInstructionsRichTextWithPdfs(
            descTxt,
            readExamPdfEditorSlotState(FORMS_PAPER_PDF_CFG),
            readExamPdfEditorSlotState(FORMS_ANSWER_PDF_CFG)
          ),
          sections: builtSections
        };
      });
    }

    function formatFormsSaveErrorFriendly(err) {
      var msg = (err && err.message) || 'Failed to save exam.';
      if (msg.indexOf('Question type must be SINGLE_CHOICE') !== -1 && msg.indexOf('COMPLEX_MULTIPLE_CHOICE') === -1) {
        msg += ' — Note: Saving Complex Multiple Choice requires updating Google Apps Script from OneDrive\\PPB\\Web\\Code.gs and CourseService.gs.';
      }
      if (err && err.fieldErrors && typeof err.fieldErrors === 'object') {
        var feKeys = Object.keys(err.fieldErrors);
        if (feKeys.length > 0) {
          var feDetails = feKeys.map(function (k) {
            return k + ': ' + String(err.fieldErrors[k]);
          });
          msg += ' (' + feDetails.join(' | ') + ')';
        }
      }
      return msg;
    }

    function handleFormsAutoSaveTick() {
      if (!isFormsBuilderWorkspaceVisible()) {
        stopFormsBuilderAutoSaveTimer();
        return Promise.resolve(null);
      }
      var role = currentSessionMeta && currentSessionMeta.user && currentSessionMeta.user.role;
      if (role !== 'ADMIN') {
        stopFormsBuilderAutoSaveTimer();
        return Promise.resolve(null);
      }
      if (formsBuilderSaveInFlightPromise) {
        return formsBuilderSaveInFlightPromise;
      }
      var curSig = computeFormsBuilderStateSignature();
      if (curSig === formsBuilderLastSavedSignature && formsBuilderDirtySeq === formsBuilderLastSavedSeq) {
        return Promise.resolve(null);
      }
      return runFormsSaveDraftCore({ isAutoSave: true });
    }

    function runFormsSaveDraftCore(opts) {
      opts = opts && typeof opts === 'object' ? opts : {};
      var isAutoSave = Boolean(opts.isAutoSave);
      var triggerBtn = opts.triggerBtn || null;
      var sigAtStart = computeFormsBuilderStateSignature();
      var dirtySeqAtStart = formsBuilderDirtySeq;

      var executeSave = function () {
        if (isAutoSave) {
          setFormsAutoSaveStatusBadge('Auto-saving draft...', 'saving');
        }
        return saveAllFormsQuestionsAndBuildExamPayload({ isSilentAutoSave: isAutoSave })
          .then(function (examPayload) {
            if (!isAutoSave) {
              setFormsBuilderProgressBanner('info', 'Saving Exam Set...', 'Linking all questions into ' + examPayload.examCode + '...');
            }
            return rpcCallEnvelope('admin.exams.saveDraft', examPayload, { suppressErrorBanner: isAutoSave });
          })
          .then(function (env) {
            renderAdminExamsTablePhase3(env.data);
            var saved = env.data && env.data.exam;
            if (saved) {
              var idEl = document.getElementById('input-forms-exam-id');
              var verEl = document.getElementById('input-forms-exam-version');
              if (idEl) idEl.value = saved.examSetId || '';
              if (verEl) verEl.value = String(saved.version || 1);
              setText('pb-forms-status-badge', 'SAVED DRAFT: ' + (saved.examCode || ''));
            }
            var timeLabel = formatFormsAutoSaveTimeHHMMSS();
            if (isAutoSave) {
              var anyDirtyLeft = Array.isArray(formsBuilderQuestionCards) && formsBuilderQuestionCards.some(function (c) {
                return c && (!c.questionId || c.isDirty);
              });
              if (formsBuilderDirtySeq === dirtySeqAtStart && !anyDirtyLeft) {
                formsBuilderLastSavedSeq = formsBuilderDirtySeq;
                formsBuilderLastSavedSignature = computeFormsBuilderStateSignature();
                setFormsAutoSaveStatusBadge('Auto-saved at ' + timeLabel, 'saved');
              } else {
                formsBuilderLastSavedSeq = dirtySeqAtStart;
                formsBuilderLastSavedSignature = sigAtStart;
                setFormsAutoSaveStatusBadge('Auto-saved earlier • New edits pending', 'dirty');
              }
              return saved || null;
            }
            renderFormsBuilderQuestionCards();
            formsBuilderLastSavedSeq = formsBuilderDirtySeq;
            formsBuilderLastSavedSignature = computeFormsBuilderStateSignature();
            setFormsAutoSaveStatusBadge('Saved at ' + timeLabel, 'saved');
            setFormsBuilderProgressBanner(
              'success',
              'Exam Draft Saved!',
              'All questions and exam settings have been saved. Click "Publish Exam" when ready for students.'
            );
            PBNotify.toast('success', 'Exam Draft Saved', 'Saved ' + ((saved && saved.title) || 'exam') + ' with ' + formsBuilderQuestionCards.length + ' question(s).');
            return saved || null;
          })
          .catch(function (err) {
            if (isAutoSave) {
              var shortMsg = (err && err.message) ? String(err.message) : 'Pending fields';
              saveFormsBuilderLocalBackup(shortMsg);
              if (err && err.isAutoSaveIncomplete) {
                setFormsAutoSaveStatusBadge('Auto-save waiting: complete required fields', 'warn');
              } else {
                setFormsAutoSaveStatusBadge('Auto-save retry in 1 min (local backup kept)', 'warn');
              }
              return null;
            }
            var msg = formatFormsSaveErrorFriendly(err);
            setFormsBuilderProgressBanner('danger', 'Could Not Save Exam', msg);
            PBNotify.toast('danger', 'Save Error', msg);
          });
      };

      var priorInFlight = formsBuilderSaveInFlightPromise
        ? formsBuilderSaveInFlightPromise.catch(function () {})
        : Promise.resolve();

      var trackedPromise = !isAutoSave && triggerBtn
        ? runButtonWithLoadingState(triggerBtn, 'Saving Exam...', function () {
            return priorInFlight.then(executeSave);
          })
        : executeSave();

      var clearInFlight = function (val) {
        if (formsBuilderSaveInFlightPromise === wrapped) {
          formsBuilderSaveInFlightPromise = null;
        }
        return val;
      };
      var wrapped = trackedPromise.then(clearInFlight, function (err) {
        clearInFlight(null);
        throw err;
      });
      formsBuilderSaveInFlightPromise = wrapped;
      return wrapped;
    }

    function handleFormsSaveExamDraft(triggerBtn) {
      return runFormsSaveDraftCore({ isAutoSave: false, triggerBtn: triggerBtn });
    }

    function handleFormsPublishExamNow(triggerBtn) {
      var priorInFlight = formsBuilderSaveInFlightPromise
        ? formsBuilderSaveInFlightPromise.catch(function () {})
        : Promise.resolve();
      var pubPromise = runButtonWithLoadingState(triggerBtn, 'Publishing Exam...', function () {
        return priorInFlight
          .then(function () {
            return saveAllFormsQuestionsAndBuildExamPayload();
          })
          .then(function (examPayload) {
            setFormsBuilderProgressBanner('info', 'Validating & Publishing...', 'Saving exam structure and publishing live version...');
            return rpcCallEnvelope('admin.exams.saveDraft', examPayload);
          })
          .then(function (draftEnv) {
            var savedExam = draftEnv.data && draftEnv.data.exam;
            if (!savedExam || !savedExam.examSetId) {
              throw new Error('Could not resolve saved examSetId.');
            }
            return rpcCallEnvelope('admin.exams.publish', { examSetId: savedExam.examSetId });
          })
          .then(function (pubEnv) {
            renderAdminExamsTablePhase3(pubEnv.data);
            var pubExam = pubEnv.data && pubEnv.data.exam;
            if (pubExam) {
              var idEl = document.getElementById('input-forms-exam-id');
              var verEl = document.getElementById('input-forms-exam-version');
              if (idEl) idEl.value = pubExam.examSetId || '';
              if (verEl) verEl.value = String(pubExam.version || 1);
              setText('pb-forms-status-badge', 'PUBLISHED LIVE: ' + (pubExam.examCode || ''));
            }
            renderFormsBuilderQuestionCards();
            formsBuilderLastSavedSeq = formsBuilderDirtySeq;
            formsBuilderLastSavedSignature = computeFormsBuilderStateSignature();
            setFormsAutoSaveStatusBadge('Published at ' + formatFormsAutoSaveTimeHHMMSS(), 'saved');
            setFormsBuilderProgressBanner(
              'success',
              'Exam Published Live!',
              'Students enrolled in the assigned course can now take this exam.'
            );
            PBNotify.toast('success', 'Exam Published!', 'Your exam is now live for students.');
          })
          .catch(function (err) {
            var msg = formatFormsSaveErrorFriendly(err);
            setFormsBuilderProgressBanner('danger', 'Publication Blocked', msg);
            PBNotify.toast('danger', 'Publication Blocked', msg);
          });
      });
      formsBuilderSaveInFlightPromise = pubPromise;
      pubPromise.then(
        function () {
          if (formsBuilderSaveInFlightPromise === pubPromise) formsBuilderSaveInFlightPromise = null;
        },
        function () {
          if (formsBuilderSaveInFlightPromise === pubPromise) formsBuilderSaveInFlightPromise = null;
        }
      );
      return pubPromise;
    }

