      var heroCardFileInp = document.getElementById('input-admin-hero-card-file');
      if (heroCardFileInp) {
        heroCardFileInp.addEventListener('change', function () {
          var fObj = heroCardFileInp.files && heroCardFileInp.files[0];
          if (!fObj || !/^image\/(png|jpeg|webp|gif)$/i.test(fObj.type || '')) return;
          var slotSel = document.getElementById('select-admin-hero-card-slot');
          var slotVal = (slotSel && slotSel.value) || '1';
          var thumbImg = document.getElementById('admin-hero-card-thumb-img-' + slotVal);
          var thumbFb = document.getElementById('admin-hero-card-thumb-fallback-' + slotVal);
          if (typeof FileReader !== 'function' || !thumbImg) return;
          try {
            var rdr = new FileReader();
            rdr.onload = function (ev) {
              var dUrl = ev && ev.target ? String(ev.target.result || '') : '';
              if (!dUrl) return;
              thumbImg.classList.add('pb-blur-up-img');
              thumbImg.classList.remove('is-sharp', 'hidden');
              if (thumbFb) thumbFb.classList.add('hidden');
              thumbImg.src = dUrl;
              setTimeout(function () {
                thumbImg.classList.add('is-sharp');
              }, 90);
            };
            rdr.readAsDataURL(fObj);
          } catch (ignoreHeroPreviewErr) {}
        });
      }

